// Verificar disponibilidad de username
app.get('/api/auth/check-username', authLimiter, async (req, res) => {
  try {
    const { username } = req.query;
    
    if (!username || username.length < 3) {
      return res.json({ available: false, message: 'Usuario muy corto' });
    }
    
    // Buscar case-insensitive
    const localExists = await User.findOne({ 
      username: { $regex: new RegExp('^' + escapeRegex(username) + '$', 'i') } 
    });
    
    if (localExists) {
      return res.json({ available: false, message: 'Usuario ya registrado' });
    }
    
    try {
      const jgUser = await jugaygana.getUserInfoByName(username);
      if (jgUser) {
        return res.json({ 
          available: false, 
          message: 'Este nombre de usuario no está disponible. Intenta con otro nombre.'
        });
      }
    } catch (jgError) {
      logger.warn(`JUGAYGANA check failed: ${jgError.message}`);
    }
    
    res.json({ 
      available: true, 
      message: 'Usuario disponible'
    });
  } catch (error) {
    console.error('Error verificando username:', error);
    res.status(500).json({ available: false, message: 'Error del servidor' });
  }
});

// Endpoint para enviar CBU al chat
app.post('/api/admin/send-cbu', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const { userId } = req.body;
    const cbuConfig = await getConfig('cbu');
    
    if (!cbuConfig || !cbuConfig.number) {
      return res.status(400).json({ error: 'CBU no configurado' });
    }
    
    const timestamp = new Date();
    
    // 1. Mensaje completo con todos los datos
    const fullMessage = `💳 *Datos para transferir:*\n\n🏦 Banco: ${cbuConfig.bank}\n👤 Titular: ${cbuConfig.titular}\n🔢 CBU: ${cbuConfig.number}\n📱 Alias: ${cbuConfig.alias}\n\n✅ Una vez realizada la transferencia, envianos el comprobante por aquí.`;
    
    await Message.create({
      id: uuidv4(),
      senderId: req.user.userId,
      senderUsername: req.user.username,
      senderRole: 'admin',
      receiverId: userId,
      receiverRole: 'user',
      content: fullMessage,
      type: 'text',
      timestamp: timestamp,
      read: false
    });
    
    // 2. CBU solo para copiar y pegar
    await Message.create({
      id: uuidv4(),
      senderId: req.user.userId,
      senderUsername: req.user.username,
      senderRole: 'admin',
      receiverId: userId,
      receiverRole: 'user',
      content: cbuConfig.number,
      type: 'text',
      timestamp: new Date(Date.now() + 100),
      read: false
    });
    
    // Notificar al usuario por socket si está conectado
    const userSocket = connectedUsers.get(userId);
    if (userSocket) {
      userSocket.emit('new_message', {
        senderId: req.user.userId,
        senderUsername: req.user.username,
        content: fullMessage,
        timestamp: timestamp,
        type: 'text'
      });
      setTimeout(() => {
        userSocket.emit('new_message', {
          senderId: req.user.userId,
          senderUsername: req.user.username,
          content: cbuConfig.number,
          timestamp: new Date(),
          type: 'text'
        });
      }, 100);
    }
    
    res.json({ success: true, message: 'CBU enviado' });
  } catch (error) {
    console.error('Error enviando CBU:', error);
    res.status(500).json({ error: 'Error enviando CBU' });
  }
});

// Health check endpoint
app.get('/api/health', async (req, res) => {
  const mongoStates = { 0: 'disconnected', 1: 'connected', 2: 'connecting', 3: 'disconnecting' };
  const mongoState = mongoose.connection.readyState;
  const mongoOk = mongoState === 1;
  res.json({
    status: mongoOk ? 'ok' : 'degraded',
    mongo: mongoStates[mongoState] || 'unknown',
    env: {
      // Sólo flags booleanos — NO se exponen valores reales para no filtrar secrets.
      hasMongoUri: !!process.env.MONGODB_URI,
      hasJwtSecret: !!process.env.JWT_SECRET,
      hasJgApiUrl: !!process.env.JG_API_URL,
      hasRedisUrl: !!process.env.REDIS_URL,
      hasS3Bucket: !!process.env.S3_BUCKET,
      nodeEnv: process.env.NODE_ENV || 'development',
      debugLogin: process.env.DEBUG_LOGIN === '1'
    },
    uptime: Math.round(process.uptime()),
    timestamp: new Date().toISOString()
  });
});

// Endpoint opcional para subir imágenes a S3 (requiere configuración de AWS)
app.post('/api/upload/presigned-url', authMiddleware, async (req, res) => {
  try {
    if (!process.env.S3_BUCKET) {
      return res.status(501).json({ error: 'Upload a S3 no configurado. Usar envío por base64.' });
    }
    const { filename, contentType } = req.body;
    if (!filename || !contentType) {
      return res.status(400).json({ error: 'filename y contentType requeridos' });
    }
    const allowedTypes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
    if (!allowedTypes.includes(contentType)) {
      return res.status(400).json({ error: 'Tipo de archivo no permitido' });
    }
    const { S3Client, PutObjectCommand } = require('@aws-sdk/client-s3');
    const { getSignedUrl } = require('@aws-sdk/s3-request-presigner');
    const key = `chat-images/${req.user.userId}/${Date.now()}-${filename}`;
    const s3 = new S3Client({ region: process.env.AWS_REGION || 'us-east-1' });
    const command = new PutObjectCommand({
      Bucket: process.env.S3_BUCKET,
      Key: key,
      ContentType: contentType
    });
    const uploadUrl = await getSignedUrl(s3, command, { expiresIn: 300 });
    const publicUrl = `https://${process.env.S3_BUCKET}.s3.amazonaws.com/${key}`;
    res.json({ uploadUrl, publicUrl });
  } catch (error) {
    logger.error('Error generando presigned URL:', error.message);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// Registro de usuario
app.post('/api/auth/register', authLimiter, async (req, res) => {
  try {
    const { username, password, email, phone, referralCode, otpCode, campaignCode: bodyCampaignCode } = req.body;
    // Sanitizamos el campaignCode aca para tenerlo listo cuando creemos el
    // user. El front lo lee de localStorage (donde queda guardado al cargar
    // el home con ?c=<code>). Permitimos slug-style 2-60 chars; si no matchea
    // simplemente lo ignoramos (mejor null que basura).
    let campaignCode = null;
    if (bodyCampaignCode && typeof bodyCampaignCode === 'string') {
      const c = bodyCampaignCode.toLowerCase().trim();
      if (/^[a-z0-9_-]{2,60}$/.test(c)) campaignCode = c;
    }
    
    if (!username || !password) {
      return res.status(400).json({ error: 'Usuario y contraseña requeridos' });
    }

    if (_isVipUser(username)) {
      return res.status(403).json(VIP_BLOCK_RESPONSE);
    }

    if (password.length < 6) {
      return res.status(400).json({ error: 'La contraseña debe tener al menos 6 caracteres' });
    }

    if (!phone || phone.trim().length < 8) {
      return res.status(400).json({ error: 'El número de teléfono es obligatorio (mínimo 8 dígitos)' });
    }

    const normalizedPhone = phone.trim();

    // Validar y verificar OTP antes de crear la cuenta
    if (!otpCode) {
      return res.status(400).json({ error: 'Se requiere el código de verificación SMS' });
    }

    if (!validateInternationalPhone(normalizedPhone)) {
      return res.status(400).json({ error: 'Número de teléfono inválido. Usa formato internacional con código de país (ej: +5491155551234)' });
    }

    const otpResult = await verifyOTP(normalizedPhone, otpCode, 'register');
    if (!otpResult.valid) {
      return res.status(400).json({ error: otpResult.error || 'Código de verificación incorrecto o expirado' });
    }

    // Check if phone is already registered and verified (second line of defense)
    const existingPhoneUser = await User.findOne({ phone: normalizedPhone, phoneVerified: true }).lean();
    if (existingPhoneUser) {
      return res.status(400).json({ error: 'Este número de teléfono ya está registrado' });
    }
    
    // Buscar case-insensitive
    const existingUser = await User.findOne({ 
      username: { $regex: new RegExp('^' + escapeRegex(username) + '$', 'i') } 
    });
    
    if (existingUser) {
      return res.status(400).json({ error: 'El usuario ya existe' });
    }

    // Resolver código de referido si fue proporcionado
    const normalizedReferralCode = referralCode ? String(referralCode).toUpperCase().trim() : null;
    let referrer = null;
    if (normalizedReferralCode) {
      referrer = await User.findOne({ referralCode: normalizedReferralCode }).lean();
      if (!referrer) {
        logger.warn(`[Register] Código de referido inválido: ${normalizedReferralCode}`);
      }
    }
    
    // Crear usuario en JUGAYGANA PRIMERO
    let jgResult = null;
    try {
      jgResult = await jugaygana.syncUserToPlatform({
        username: username,
        password: password
      });
      
      if (!jgResult.success && !jgResult.alreadyExists) {
        return res.status(400).json({ error: 'No se pudo crear el usuario en JUGAYGANA: ' + (jgResult.error || 'Error desconocido') });
      }
      
      logger.info(`User created/linked in JUGAYGANA: ${username}`);
    } catch (jgError) {
      logger.error(`Error creating user in JUGAYGANA: ${jgError.message}`);
      return res.status(400).json({ error: 'Error al crear usuario en la plataforma. Intenta con otro nombre de usuario.' });
    }
    
    // Crear usuario localmente
    const userId = uuidv4();

    // Validar referido (evitar auto-referido).
    // BUG fix: el check viejo era `referrer.id !== userId`, pero userId es
    // un UUID recién generado — nunca puede igualar al UUID del referrer
    // (que ya existe en DB). El check siempre pasaba. Reemplazamos por
    // checks reales: mismo phone (mismo dueño con 2 cuentas) o mismo
    // username case-insensitive. El dedup por phone (línea ~1610) ya
    // bloquea registrar 2 cuentas con el mismo número, así que esto es
    // defense-in-depth.
    const referrerPhone = String(referrer && referrer.phone || '').trim();
    const referrerUsername = String(referrer && referrer.username || '').toLowerCase();
    const isValidReferral = !!(
      referrer
      && referrerPhone !== normalizedPhone
      && referrerUsername !== username.toLowerCase()
    );

    // Generar referralCode único para el nuevo usuario (con control de colisiones)
    let newReferralCode = null;
    for (let attempt = 0; attempt < 10; attempt++) {
      const candidate = generateReferralCode();
      const collision = await User.findOne({ referralCode: candidate }).lean();
      if (!collision) { newReferralCode = candidate; break; }
    }
    if (!newReferralCode) {
      logger.warn(`[Register] No se pudo generar un referralCode único para ${username} después de 10 intentos. El usuario se creará sin código.`);
    }
    
    const newUser = await User.create({
      id: userId,
      username,
      password: password,
      email: email || null,
      phone: normalizedPhone,
      phoneVerified: true,
      role: 'user',
      accountNumber: generateAccountNumber(),
      balance: jgResult.user?.balance || jgResult.user?.user_balance || 0,
      createdAt: new Date(),
      lastLogin: null,
      isActive: true,
      jugayganaUserId: jgResult.jugayganaUserId || jgResult.user?.user_id,
      jugayganaUsername: jgResult.jugayganaUsername || jgResult.user?.user_name,
      jugayganaSyncStatus: jgResult.alreadyExists ? 'linked' : 'synced',
      // Campos de referido
      referralCode: newReferralCode,
      referredByUserId: isValidReferral ? referrer.id : null,
      referredByCode: isValidReferral ? normalizedReferralCode : null,
      referredAt: isValidReferral ? new Date() : null,
      referralStatus: isValidReferral ? 'referred' : 'none',
      // Attribution de campaña (first-touch). Si vino de un link tipo
      // ?c=promo2k queda atado para el reporte del admin.
      campaignCode: campaignCode,
      campaignCodeAt: campaignCode ? new Date() : null
    });

    // Registrar evento de referido para trazabilidad
    if (isValidReferral) {
      try {
        await ReferralEvent.create({
          id: uuidv4(),
          referrerUserId: referrer.id,
          referrerUsername: referrer.username,
          referredUserId: userId,
          referredUsername: newUser.username,
          codeUsed: normalizedReferralCode,
          meta: { ip: req.ip || null, registeredAt: new Date() }
        });
        logger.info(`[Register] Referido registrado: ${newUser.username} referido por ${referrer.username} (código: ${normalizedReferralCode})`);
      } catch (refErr) {
        logger.error(`[Register] Error registrando evento de referido: ${refErr.message}`);
        // No interrumpir el flujo de registro
      }
    }
    
    // CORREGIDO: El mensaje de bienvenida se envía desde el cliente (app.js) con el formato actualizado incluyendo CBU
    // No enviamos mensaje de bienvenida desde el servidor para evitar duplicados y usar el formato correcto
    
    // Crear chat status
    await ChatStatus.create({
      userId: userId,
      username: username,
      status: 'open',
      category: 'cargas',
      lastMessageAt: new Date()
    });
    
    // 30 días: balance entre UX (no relogear seguido) y blast radius si
    // un token leakea desde localStorage del PWA via XSS o backup.
    const token = jwt.sign(
      { userId: newUser.id, username: newUser.username, role: newUser.role },
      JWT_SECRET,
      { expiresIn: '30d' }
    );
    
    res.status(201).json({
      message: 'Usuario creado exitosamente',
      token,
      user: {
        id: newUser.id,
        username: newUser.username,
        email: newUser.email,
        phone: newUser.phone,
        accountNumber: newUser.accountNumber,
        role: newUser.role,
        balance: newUser.balance,
        jugayganaLinked: true,
        needsPasswordChange: false,
        referralCode: newUser.referralCode,
        referredBy: isValidReferral ? referrer.username : null
      }
    });
  } catch (error) {
    logger.error(`Registration error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// Login
app.post('/api/auth/login', authLimiter, async (req, res) => {
  try {
    const { username, phone, password } = req.body;

    if (_isVipUser(username)) {
      return res.status(403).json(VIP_BLOCK_RESPONSE);
    }


    if ((!username && !phone) || !password) {
      return res.status(400).json({ error: 'Usuario o teléfono, y contraseña requeridos' });
    }
    
    logger.debug(`Login attempt for: ${username || phone}`);
    
    // Buscar usuario case-insensitive (para soportar usernames con mayúsculas/minúsculas)
    let user;
    let dbReadFailed = false;

    if (phone && !username) {
      // Phone-based login
      const normalizedPhone = phone.trim();
      try {
        user = await User.findOne({ phone: normalizedPhone, phoneVerified: true });
      } catch (dbErr) {
        logger.error(`[Login] MongoDB read failed for phone ${normalizedPhone}: ${dbErr.message}`);
        dbReadFailed = true;
      }
    } else {
      // Username-based login
      try {
        user = await User.findOne({ 
          username: { $regex: new RegExp('^' + escapeRegex(username) + '$', 'i') } 
        });
      } catch (dbErr) {
        logger.error(`[Login] MongoDB read failed for ${username}: ${dbErr.message}`);
        dbReadFailed = true;
      }
    }

    // Fallback admin sin Mongo: APAGADO por defecto. Es un by-pass total si
    // alguien tira Mongo abajo y conoce ADMIN_USERNAME/ADMIN_PASSWORD. Para
    // usarlo en una emergencia real, prendelo con ENABLE_FALLBACK_ADMIN_LOGIN=1
    // en la variable de entorno y apagalo apenas vuelva la DB.
    if (dbReadFailed) {
      if (process.env.ENABLE_FALLBACK_ADMIN_LOGIN !== '1') {
        return res.status(503).json({ error: 'Servicio temporalmente no disponible. Intenta más tarde.' });
      }
      const fallbackAdminUsername = process.env.ADMIN_USERNAME;
      const fallbackAdminPassword = process.env.ADMIN_PASSWORD;
      const isAdminFallback = fallbackAdminUsername && fallbackAdminPassword &&
        username === fallbackAdminUsername &&
        safeCompare(password, fallbackAdminPassword);
      if (!isAdminFallback) {
        return res.status(503).json({ error: 'Servicio temporalmente no disponible. Intenta más tarde.' });
      }
      const fallbackToken = jwt.sign(
        { userId: 'fallback-admin', username: fallbackAdminUsername, role: 'admin', tokenVersion: 0 },
        JWT_SECRET,
        { expiresIn: '4h' }
      );
      logger.warn(`[Login] FALLBACK ADMIN LOGIN USED (${fallbackAdminUsername}) - MongoDB unavailable. ENABLE_FALLBACK_ADMIN_LOGIN está prendido — APAGALO apenas vuelva la DB.`);
      return res.json({
        token: fallbackToken,
        user: { id: 'fallback-admin', username: fallbackAdminUsername, role: 'admin', balance: 0, needsPasswordChange: false }
      });
    }
    
    // Si no existe localmente, verificar en JUGAYGANA (solo para login por username)
    if (!user && username) {
      logger.debug(`User ${username} not found locally, checking JUGAYGANA...`);

      // En AWS suele haber problemas de conectividad o timeout hacia JUGAYGANA.
      // Si la llamada falla, NO queremos romper el login — degradamos a "user
      // not found" y devolvemos 401 normal.
      let jgUser = null;
      try {
        jgUser = await jugaygana.getUserInfoByName(username);
      } catch (jgErr) {
        logger.error(`[Login] JUGAYGANA lookup failed for ${username}: ${jgErr.message}`);
        // Si era un admin (no debería estar en JUGAYGANA), simplemente cae
        // como credenciales inválidas. Si era un user real importado, perdió
        // la chance de auto-creación esta vez — reintenta el próximo login.
      }

      if (jgUser) {
        logger.debug(`User found in JUGAYGANA, creating locally...`);
        
        const userId = uuidv4();
        
        user = await User.create({
          id: userId,
          username: jgUser.username,
          password: 'asd123',
          email: jgUser.email || null,
          phone: jgUser.phone || null,
          role: 'user',
          accountNumber: generateAccountNumber(),
          balance: jgUser.balance || 0,
          createdAt: new Date(),
          lastLogin: null,
          isActive: true,
          jugayganaUserId: jgUser.id,
          jugayganaUsername: jgUser.username,
          jugayganaSyncStatus: 'linked',
          source: 'jugaygana',
          tokenVersion: 0,
          // Auto-imported JUGAYGANA users start with the default password
          // "asd123"; force them to change it before they can use the app.
          mustChangePassword: true
        });
        
        // Crear chat status
        await ChatStatus.create({
          userId: userId,
          username: jgUser.username,
          status: 'open',
          category: 'cargas'
        });
        
        logger.info(`User ${username} auto-created from JUGAYGANA`);
      } else {
        return res.status(401).json({ error: 'Credenciales inválidas' });
      }
    } else if (!user) {
      return res.status(401).json({ error: 'Credenciales inválidas' });
    }
    
    // Convertir a objeto plano para acceder a los campos correctamente
    const userObj = user.toObject ? user.toObject() : user;
    
    // Usar 'id' si existe, sino usar '_id' como fallback
    const userId = userObj.id || userObj._id?.toString();
    
    logger.debug(`User found: ${userObj.username}, ID: ${userId}`);
    
    const loginIdentifier = username || phone;
    
    if (!userId) {
      logger.error(`User ${loginIdentifier} has no valid ID`);
      return res.status(500).json({ error: 'Error de configuración de usuario. Contacta al administrador.' });
    }
    
    if (!userObj.isActive) {
      return res.status(401).json({ error: 'Credenciales inválidas' });
    }

    // Reject login for blocked users before doing any further work.
    if (userObj.isBlocked === true) {
      return res.status(403).json({
        error: `Tu cuenta está bloqueada: ${userObj.blockReason || 'Contactá a soporte.'}`,
        code: 'USER_BLOCKED'
      });
    }
    
    // Verificar que el usuario tenga una contraseña válida
    if (!userObj.password) {
      logger.error(`User ${loginIdentifier} has no password configured`);
      return res.status(500).json({ error: 'Error de configuración de usuario. Contacta al administrador.' });
    }
    
    // Verificar si la contraseña almacenada es un hash bcrypt válido
    const isValidBcryptHash = userObj.password.startsWith('$2') || userObj.password.startsWith('$2a$') || userObj.password.startsWith('$2b$');
    if (!isValidBcryptHash) {
      logger.error(`User ${loginIdentifier} has password in invalid format`);
      return res.status(500).json({ error: 'Error de configuración de usuario. Contacta al administrador.' });
    }
    
    // Verificar si el usuario necesita cambiar la contraseña.
    // Admin roles (admin/depositor/withdrawer) are internal VIPCARGAS accounts and
    // must NEVER enter the mustChangePassword flow — even if their password is
    // "asd123". Only role=user is subject to this check.
    const isDefaultPassword = password === 'asd123';
    const needsPasswordChange = isAdminRole(userObj.role)
      ? false
      : ((!userObj.passwordChangedAt && userObj.source === 'jugaygana') || isDefaultPassword);
    
    let isValidPassword = false;
    
    try {
      isValidPassword = await bcrypt.compare(password, userObj.password);
    } catch (bcryptError) {
      logger.error(`Error comparing password for ${loginIdentifier}: ${bcryptError.message}`);
    }
    
    // Fallback SOLO para usuarios auto-importados desde JUGAYGANA que aún no cambiaron
    // su contraseña real (la inicial real es "asd123"). Para evitar backdoor:
    //  - Sólo aplica si source === 'jugaygana' Y nunca cambió contraseña.
    //  - Sólo aplica para role=user (admins nunca tienen contraparte en JUGAYGANA).
    //  - Valida que el hash almacenado realmente corresponda a "asd123";
    //    si la DB guarda otro hash, NO se acepta "asd123" como atajo.
    if (!isValidPassword && password === 'asd123' && !userObj.passwordChangedAt && userObj.source === 'jugaygana' && !isAdminRole(userObj.role)) {
      try {
        isValidPassword = await bcrypt.compare('asd123', userObj.password);
      } catch (bcryptError) {
        logger.error(`Error verifying JUGAYGANA default password: ${bcryptError.message}`);
      }
    }
    
    if (!isValidPassword) {
      logger.debug(`Wrong password for ${loginIdentifier}`);
      return res.status(401).json({ error: 'Credenciales inválidas' });
    }
    
    logger.info(`Login successful for ${loginIdentifier}`);
    
    // Actualizar lastLogin usando el modelo de Mongoose
    user.lastLogin = new Date();
    // Persist mustChangePassword only for non-admin roles. Admins are internal
    // VIPCARGAS accounts and are never blocked by the JUGAYGANA default-password
    // flow — even if their password happens to be "asd123".
    if (needsPasswordChange && !isAdminRole(user.role) && user.mustChangePassword !== true) {
      user.mustChangePassword = true;
    }
    // Self-heal: admins must NEVER carry mustChangePassword. If a stale flag
    // from before the role-isolation fix is still in DB, clear it on next login.
    if (isAdminRole(user.role) && user.mustChangePassword === true) {
      user.mustChangePassword = false;
      logger.info(`[login] Cleared stale mustChangePassword for admin ${user.username}`);
    }
    await user.save();
    
    // Token con expiración de 30 días para persistencia de sesión
    const token = jwt.sign(
      { userId: userId, username: userObj.username, role: userObj.role, tokenVersion: userObj.tokenVersion ?? 0 },
      JWT_SECRET,
      { expiresIn: '30d' }
    );
    
    // Intentar login en JUGAYGANA para obtener token de sesión (best-effort).
    // Admin roles have no counterpart in JUGAYGANA, so skip entirely.
    let jugayganaToken = null;
    if (!isAdminRole(userObj.role)) {
      try {
        const jgLogin = await jugayganaService.loginAsUser(userObj.username, password);
        if (jgLogin.success) {
          jugayganaToken = jgLogin.token;
          logger.info(`Token JUGAYGANA obtenido para: ${loginIdentifier}`);
        } else {
          logger.warn(`No se pudo obtener token JUGAYGANA para ${loginIdentifier}: ${jgLogin.error}`);
        }
      } catch (jgErr) {
        logger.warn(`Error obteniendo token JUGAYGANA para ${loginIdentifier}: ${jgErr.message}`);
      }
    }
    
    // Set an httpOnly admin session cookie for admin roles so that the server
    // can verify, on subsequent page requests, that the browser was genuinely
    // authenticated — not just checking localStorage (client-side only).
    // An httpOnly, SameSite=Strict, path-scoped cookie is the recommended
    // alternative to localStorage for session tokens: it is inaccessible to
    // JavaScript (XSS-safe) and is scoped to the admin path only.
    const adminRoles = ['admin', 'depositor', 'withdrawer', 'closings_viewer'];
    if (adminRoles.includes(userObj.role)) {
      // Set two httpOnly cookies: one for page access, one for API calls.
      // Neither can be read by client-side scripts (XSS-safe).
      // Incluir tokenVersion para que `Revocar todas las sesiones` invalide
      // este cookie también. Sin esto, después de un bump de tokenVersion el
      // localStorage token quedaba inválido pero el cookie httpOnly de 8h
      // sobrevivía hasta expiración natural.
      const adminCookieToken = jwt.sign(
        { userId: userId, username: userObj.username, role: userObj.role, tokenVersion: userObj.tokenVersion ?? 0 },
        JWT_SECRET,
        { expiresIn: '8h' }
      );
      res.setHeader('Set-Cookie', buildAdminSessionCookieHeaders(adminCookieToken));
    }

    res.json({
      message: 'Login exitoso',
      token,
      jugayganaToken,
      user: {
        id: userId,
        username: userObj.username,
        email: userObj.email,
        phone: userObj.phone || null,
        phoneVerified: userObj.phoneVerified || false,
        whatsapp: userObj.whatsapp || null,
        accountNumber: userObj.accountNumber,
        role: userObj.role,
        balance: userObj.balance,
        jugayganaLinked: !!userObj.jugayganaUserId,
        needsPasswordChange: needsPasswordChange,
        // Cambio de contraseña obligatorio deshabilitado por requerimiento.
        mustChangePassword: false
      }
    });
  } catch (error) {
    // Loggear stack completo para que en CloudWatch se vea la causa raíz.
    // El errorCode + name ayuda a identificar issues típicos en producción:
    //   MongooseError / MongoNetworkError → Mongo no llega
    //   JsonWebTokenError → JWT_SECRET malformado/faltante
    //   TypeError → bug del código
    logger.error(`[Login] ${error.name || 'Error'}: ${error.message}`, {
      stack: error.stack,
      code: error.code,
      name: error.name
    });
    res.status(500).json({
      error: 'Error del servidor',
      // El detalle del error sólo se incluye si DEBUG_LOGIN=1 en el env (no
      // exponer info sensible por default). Útil para diagnosticar en AWS.
      detail: process.env.DEBUG_LOGIN === '1' ? `${error.name}: ${error.message}` : undefined
    });
  }
});

// ============================================
// LOGIN SOLO-USUARIO (acceso simplificado a reembolsos)
// El usuario solo ingresa su username; si existe, se le devuelve un token
// con permisos limitados que sirve para consultar/reclamar reembolsos.
// Para entrar a la plataforma de juego sigue necesitando su contraseña real.
// ============================================
function pickLinePhoneForUsername(linesConfig, username) {
  if (!linesConfig || typeof linesConfig !== 'object') return null;
  const slots = Array.isArray(linesConfig.slots) ? linesConfig.slots : [];
  const defaultPhone = linesConfig.defaultPhone || null;
  const lower = String(username || '').toLowerCase();
  let bestMatch = null;
  for (const slot of slots) {
    if (!slot || !slot.prefix || !slot.phone) continue;
    const prefix = String(slot.prefix).toLowerCase().trim();
    if (!prefix) continue;
    if (lower.startsWith(prefix)) {
      if (!bestMatch || prefix.length > bestMatch.prefix.length) {
        bestMatch = { prefix, phone: String(slot.phone).trim() };
      }
    }
  }
  return bestMatch ? bestMatch.phone : defaultPhone;
}

// Devuelve toda la info necesaria para asignar línea por matcheo de
// prefijo. Diferencia entre match real (longest-prefix) y caída al
// general default. Es el pegamento entre pickLinePhoneForUsername y
// el persist al User: la versión "boba" devuelve solo el teléfono,
// esta devuelve también source + note + teamName.
//
// Retorna: { linePhone, lineTeamName, source, note } o null si no
// hay nada para asignar (ni match ni default).
function resolveLineByPrefixFallback(linesConfig, username) {
  if (!linesConfig || typeof linesConfig !== 'object') return null;
  const slots = Array.isArray(linesConfig.slots) ? linesConfig.slots : [];
  const defaultPhone = (linesConfig.defaultPhone || '').trim();
  const defaultTeamName = (linesConfig.defaultTeamName || '').trim();
  const lower = String(username || '').toLowerCase();
  let bestMatch = null;
  for (const slot of slots) {
    if (!slot || !slot.prefix || !slot.phone) continue;
    const prefix = String(slot.prefix).toLowerCase().trim();
    if (!prefix) continue;
    if (lower.startsWith(prefix)) {
      if (!bestMatch || prefix.length > bestMatch.prefix.length) {
        bestMatch = {
          prefix,
          phone: String(slot.phone).trim(),
          teamName: (slot.teamName || '').trim()
        };
      }
    }
  }
  if (bestMatch) {
    return {
      linePhone: bestMatch.phone,
      lineTeamName: bestMatch.teamName || null,
      source: 'prefix-fallback',
      note: `${bestMatch.prefix} → ${bestMatch.teamName || 'línea'} (${bestMatch.phone})`
    };
  }
  if (defaultPhone) {
    return {
      linePhone: defaultPhone,
      lineTeamName: defaultTeamName || null,
      source: 'general-default',
      note: `Sin prefijo coincidente → línea general${defaultTeamName ? ` (${defaultTeamName})` : ''}`
    };
  }
  return null;
}

// Normaliza username para matchear contra UserLineLookup.usernameNorm.
// Debe coincidir EXACTAMENTE con la normalización usada en el endpoint
// de import (server.js: _normalizeUsername).
function normalizeUsernameForLookup(raw) {
  if (!raw) return '';
  return String(raw)
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

// Busca en UserLineLookup la asignación pre-cargada para un username.
// Devuelve { linePhone, lineTeamName } o null si no está mapeado.
// Maneja errores silenciosamente (la asignación es best-effort).
async function pickLineFromLookup(username) {
  try {
    const norm = normalizeUsernameForLookup(username);
    if (!norm) return null;
    const entry = await UserLineLookup.findOne({ usernameNorm: norm })
      .select('linePhone lineTeamName')
      .lean();
    if (!entry) return null;
    return {
      linePhone: entry.linePhone || null,
      lineTeamName: entry.lineTeamName || null
    };
  } catch (err) {
    logger.warn(`[pickLineFromLookup] error: ${err.message}`);
    return null;
  }
}

// Mismo criterio que pickLinePhoneForUsername pero para el nombre del equipo.
// Lee el campo `teamName` del MISMO config 'userLinesByPrefix' (no creamos
// otra config porque conceptualmente es el mismo equipo: prefijo "ato" =
// numero "+54..." = nombre "Atomic"). Devuelve el teamName del prefijo mas
// largo que matchee, o '' si no matchea ninguno y no hay default.
function pickTeamNameForUsername(linesConfig, username) {
  if (!linesConfig || typeof linesConfig !== 'object') return '';
  const slots = Array.isArray(linesConfig.slots) ? linesConfig.slots : [];
  const defaultName = linesConfig.defaultTeamName || '';
  const lower = String(username || '').toLowerCase();
  let bestMatch = null;
  for (const slot of slots) {
    if (!slot || !slot.prefix) continue;
    const prefix = String(slot.prefix).toLowerCase().trim();
    if (!prefix) continue;
    const teamName = (slot.teamName ? String(slot.teamName) : '').trim();
    if (!teamName) continue;
    if (lower.startsWith(prefix)) {
      if (!bestMatch || prefix.length > bestMatch.prefix.length) {
        bestMatch = { prefix, teamName };
      }
    }
  }
  return bestMatch ? bestMatch.teamName : defaultName;
}

// Mismo criterio que pickLinePhoneForUsername pero para los links de comunidad.
// Usa la config 'userCommunitiesByPrefix' con shape:
//   { slots: [{prefix, link, link2?, label?, label2?}], defaultLink }.
// Retorna SOLO el link primario (string) para compat. Para obtener
// ambas comunidades del slot, usar pickCommunityBundleForUsername.
function pickCommunityLinkForUsername(communitiesConfig, username) {
  const b = pickCommunityBundleForUsername(communitiesConfig, username);
  return b ? b.link : null;
}

// Variante extendida: devuelve { prefix, link, link2, label, label2 } del
// slot que matchea (longest prefix wins). Usada por /api/user-lines/me
// para exponer ambas comunidades a la PWA.
function pickCommunityBundleForUsername(communitiesConfig, username) {
  if (!communitiesConfig || typeof communitiesConfig !== 'object') {
    return null;
  }
  const slots = Array.isArray(communitiesConfig.slots) ? communitiesConfig.slots : [];
  const defaultLink = communitiesConfig.defaultLink || null;
  const defaultLink2 = communitiesConfig.defaultLink2 || null;
  const lower = String(username || '').toLowerCase();
  let bestMatch = null;
  for (const slot of slots) {
    if (!slot || !slot.prefix || !slot.link) continue;
    const prefix = String(slot.prefix).toLowerCase().trim();
    if (!prefix) continue;
    if (lower.startsWith(prefix)) {
      if (!bestMatch || prefix.length > bestMatch.prefix.length) {
        bestMatch = {
          prefix,
          link: String(slot.link).trim(),
          link2: slot.link2 ? String(slot.link2).trim() : null,
          label: slot.label ? String(slot.label).trim() : null,
          label2: slot.label2 ? String(slot.label2).trim() : null,
          // Flag opt-out por equipo: si true, el equipo queda fuera del
          // sistema de códigos canjeables y de las notifs de Telegram.
          // Usa el link original (WhatsApp, etc.) sin la migración.
          excludeFromCodes: !!slot.excludeFromCodes
        };
      }
    }
  }
  if (bestMatch) return bestMatch;
  if (defaultLink) {
    return { prefix: '', link: defaultLink, link2: defaultLink2, label: null, label2: null, excludeFromCodes: false };
  }
  return null;
}

// Devuelve true si el username matchea un slot con excludeFromCodes=true.
// Esos equipos quedan fuera del sistema de códigos: no ven el card en la
// home, no reciben notifs de códigos ni avisos de Telegram, y se les
// puede excluir de notifs generales también.
async function _isUserExcludedFromCodes(username) {
  if (!username) return false;
  try {
    const cfg = await getConfig('userCommunitiesByPrefix').catch(() => null);
    const bundle = pickCommunityBundleForUsername(cfg, username);
    return !!(bundle && bundle.excludeFromCodes);
  } catch (_) {
    return false;
  }
}

// Construye el filtro mongo para excluir users de prefijos dados.
// Devuelve null si no hay nada que excluir.
function _buildExcludePrefixesFilter(prefixes) {
  const arr = Array.isArray(prefixes)
    ? prefixes.map(p => String(p || '').toLowerCase().trim()).filter(Boolean)
    : [];
  if (arr.length === 0) return null;
  // Regex case-insensitive: ^(?!prefix1|prefix2|...).
  const escaped = arr.map(p => p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  return { username: { $not: new RegExp('^(' + escaped.join('|') + ')', 'i') } };
}

// Carga los prefijos con excludeFromCodes=true desde el config.
async function _getExcludedFromCodesPrefixes() {
  try {
    const cfg = await getConfig('userCommunitiesByPrefix').catch(() => null);
    if (!cfg || !Array.isArray(cfg.slots)) return [];
    return cfg.slots
      .filter(s => s && s.excludeFromCodes && s.prefix)
      .map(s => String(s.prefix).toLowerCase().trim())
      .filter(Boolean);
  } catch (_) {
    return [];
  }
}

// Probe endpoint para verificar versión deployada (no requiere auth)
app.get('/api/auth/_probe', (req, res) => {
  res.json({ version: 'refunds-only-v3', endpoint: 'login-username-only', timestamp: new Date().toISOString() });
});

// Lookup público (sin auth) para el botón "Consultar o crear usuario" del login.
// El usuario escribe el nombre de su equipo (ej: "atomic", "marshall", "argentum")
// y devolvemos:
//   - linePhone:    número principal del equipo (WhatsApp wa.me)
//   - communityLink, communityLink2: canal activo de la comunidad
//   - teamName:     nombre canónico del equipo
//
// FUENTES DE DATOS:
//   - Líneas: agregación del modelo User (lineTeamName + linePhone). Es la
//     misma data que ve el admin en "📊 Equipos". Por cada equipo elige el
//     linePhone con más users (la línea vigente).
//   - Comunidad: config 'userCommunitiesByPrefix' (slots con prefix + link).
//
// MATCH:
//   Sobre el input normalizado (lowercase, solo a-z0-9), buscamos el TEAM
//   cuyo nombre coincide best-effort:
//     - igual                              → score 200
//     - input startsWith teamName          → 150 + teamName.length
//     - teamName startsWith input (≥3 ch)  → 100 + input.length
//     - primeras 3 letras coinciden        → 50
//   Si hay empate, gana el equipo con más users.
let _teamsLookupCache = { ts: 0, teams: null };
const _TEAMS_LOOKUP_TTL_MS = 60 * 1000; // 1 min

async function _loadTeamsForLookup() {
  const now = Date.now();
  if (_teamsLookupCache.teams && (now - _teamsLookupCache.ts) < _TEAMS_LOOKUP_TTL_MS) {
    return _teamsLookupCache.teams;
  }
  const groups = await User.aggregate([
    { $match: {
        linePhone: { $ne: null, $exists: true },
        lineTeamName: { $ne: null, $exists: true }
      }
    },
    {
      $group: {
        _id: { teamName: '$lineTeamName', linePhone: '$linePhone' },
        count: { $sum: 1 }
      }
    }
  ]);
  // Por cada teamName quedarse con el linePhone que más users tiene.
  const byTeam = new Map();
  for (const g of groups) {
    const teamName = (g._id.teamName || '').trim();
    const linePhone = (g._id.linePhone || '').trim();
    if (!teamName || !linePhone) continue;
    const norm = teamName.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (!norm) continue;
    const existing = byTeam.get(norm);
    if (!existing || g.count > existing.count) {
      byTeam.set(norm, { teamName, teamNameNorm: norm, linePhone, count: g.count });
    }
  }
  const teams = Array.from(byTeam.values());
  _teamsLookupCache = { ts: now, teams };
  return teams;
}

app.get('/api/teams/lookup', authLimiter, async (req, res) => {
  try {
    const rawQ = String(req.query.q || req.query.team || '').trim();
    if (!rawQ) return res.status(400).json({ error: 'Falta parámetro q' });
    const q = rawQ.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (!q) return res.status(400).json({ error: 'Equipo inválido' });

    const [teams, communitiesCfg] = await Promise.all([
      _loadTeamsForLookup().catch(() => []),
      getConfig('userCommunitiesByPrefix').catch(() => null)
    ]);

    // 1) Match contra teamName de usuarios reales.
    let best = null;
    const q3 = q.slice(0, 3);
    for (const t of teams) {
      let score = 0;
      if (q === t.teamNameNorm) score = 200;
      else if (t.teamNameNorm.length >= 2 && q.startsWith(t.teamNameNorm)) score = 150 + t.teamNameNorm.length;
      else if (q.length >= 3 && t.teamNameNorm.startsWith(q)) score = 100 + q.length;
      else if (q3.length === 3 && t.teamNameNorm.slice(0, 3) === q3) score = 50;
      if (score > 0 && (!best || score > best.score || (score === best.score && t.count > best.count))) {
        best = { ...t, score };
      }
    }

    // 2) Si no matcheó, probar el config viejo userLinesByPrefix (compat).
    let usedFallback = false;
    if (!best) {
      const linesCfg = await getConfig('userLinesByPrefix').catch(() => null);
      const lineSlots = (linesCfg && Array.isArray(linesCfg.slots)) ? linesCfg.slots : [];
      for (const slot of lineSlots) {
        if (!slot || !slot.prefix || !slot.phone) continue;
        const prefix = String(slot.prefix).toLowerCase().replace(/[^a-z0-9]/g, '');
        if (!prefix) continue;
        if (q.startsWith(prefix) || prefix.startsWith(q)) {
          best = {
            teamName: (slot.teamName || '').trim(),
            teamNameNorm: (slot.teamName || '').toLowerCase().replace(/[^a-z0-9]/g, '') || prefix,
            linePhone: String(slot.phone).trim(),
            count: 0,
            score: 5
          };
          usedFallback = true;
          break;
        }
      }
      // Default phone como último recurso.
      if (!best && linesCfg && linesCfg.defaultPhone) {
        best = {
          teamName: linesCfg.defaultTeamName || 'Línea general',
          teamNameNorm: '',
          linePhone: String(linesCfg.defaultPhone).trim(),
          count: 0,
          score: 1
        };
        usedFallback = true;
      }
    }

    // 3) Buscar comunidad: match del prefijo del community-config contra el
    //    teamName del best match (ej: teamName="Atomic" → prefix "ato").
    let communityLink = null, communityLink2 = null, communityLabel = null, communityLabel2 = null;
    let communityMatchedPrefix = null;
    if (best && best.teamNameNorm) {
      const commSlots = (communitiesCfg && Array.isArray(communitiesCfg.slots)) ? communitiesCfg.slots : [];
      let commBest = null;
      for (const slot of commSlots) {
        if (!slot || !slot.prefix || !slot.link) continue;
        const slotPrefix = String(slot.prefix).toLowerCase().replace(/[^a-z0-9]/g, '');
        if (!slotPrefix) continue;
        let score = 0;
        if (best.teamNameNorm === slotPrefix) score = 200;
        else if (best.teamNameNorm.startsWith(slotPrefix)) score = 150 + slotPrefix.length;
        else if (slotPrefix.startsWith(best.teamNameNorm)) score = 100 + best.teamNameNorm.length;
        if (score > 0 && (!commBest || score > commBest.score)) {
          commBest = { score, slot, prefix: slotPrefix };
        }
      }
      if (commBest) {
        communityLink = commBest.slot.link ? String(commBest.slot.link).trim() : null;
        communityLink2 = commBest.slot.link2 ? String(commBest.slot.link2).trim() : null;
        communityLabel = commBest.slot.label ? String(commBest.slot.label).trim() : null;
        communityLabel2 = commBest.slot.label2 ? String(commBest.slot.label2).trim() : null;
        communityMatchedPrefix = commBest.prefix;
      }
    }
    if (!communityLink && communitiesCfg && communitiesCfg.defaultLink) {
      communityLink = String(communitiesCfg.defaultLink).trim();
    }
    if (!communityLink2 && communitiesCfg && communitiesCfg.defaultLink2) {
      communityLink2 = String(communitiesCfg.defaultLink2).trim();
    }

    // Debug owner-only.
    const OWNER_DEBUG_SECRET = 'vipsalida-fabio-2026-x9k';
    let _debug = null;
    if (String(req.query._owner || '') === OWNER_DEBUG_SECRET) {
      _debug = {
        inputQuery: rawQ,
        normalized: q,
        firstThreeChars: q3,
        totalTeamsFound: teams.length,
        sampleTeams: teams.slice(0, 30).map(t => ({ teamName: t.teamName, teamNameNorm: t.teamNameNorm, users: t.count })),
        communityMatchedPrefix,
        usedFallback
      };
    }

    if (!best) {
      return res.status(404).json({
        error: 'No encontramos tu equipo. Revisá el nombre con tu agente.',
        query: rawQ,
        _debug
      });
    }

    return res.json({
      teamName: best.teamName || null,
      linePhone: best.linePhone,
      communityLink,
      communityLink2,
      communityLabel,
      communityLabel2,
      usedFallback,
      _debug
    });
  } catch (err) {
    logger.error(`[TeamsLookup] ${err.message}`);
    return res.status(500).json({ error: 'Error interno' });
  }
});

const DeviceAccount = require('./src/models/DeviceAccount');

app.post('/api/auth/login-username-only', authLimiter, async (req, res, next) => {
  console.log('[LoginUsernameOnly] HIT', { body: req.body, ip: req.ip });
  try {
    const { username } = req.body || {};
    if (!username || typeof username !== 'string' || !username.trim()) {
      return res.status(400).json({ error: 'Usuario requerido' });
    }
    const cleanUsername = username.trim();

    if (_isVipUser(cleanUsername)) {
      return res.status(403).json(VIP_BLOCK_RESPONSE);
    }

    // Lookup rápido (max 3s). Antes del query, ensureMongoReady fuerza una
    // reconexión si el driver se quedó stuck en disconnected (pasa con blips
    // de Atlas que el auto-reconnect a veces no rescata).
    let user;
    try {
      await ensureMongoReady(4000);
      user = await User.findOne({
        username: { $regex: new RegExp('^' + escapeRegex(cleanUsername) + '$', 'i') }
      }).maxTimeMS(3000);
    } catch (dbErr) {
      logger.error(`[LoginUsernameOnly] DB read FAIL for ${cleanUsername}: ${dbErr.name}: ${dbErr.message}`);
      return res.status(503).json({ error: `Servicio temporalmente no disponible (${dbErr.name || 'DB'}). Intentá en 30s.` });
    }

    // Si no existe localmente, probar JUGAYGANA (mismo flujo que el login normal).
    // Hard timeout de 8s: si JUGAYGANA está lento o caído, no dejamos colgar
    // la request completa (Cloudflare/Render mata a los ~30-100s y devuelve 502).
    if (!user) {
      try {
        const jgUser = await Promise.race([
          jugaygana.getUserInfoByName(cleanUsername),
          new Promise((_, reject) => setTimeout(() => reject(new Error('JUGAYGANA lookup timeout 8s')), 8000))
        ]);
        if (jgUser) {
          const userId = uuidv4();
          user = await User.create({
            id: userId,
            username: jgUser.username,
            password: 'asd123',
            email: jgUser.email || null,
            phone: jgUser.phone || null,
            role: 'user',
            accountNumber: generateAccountNumber(),
            balance: jgUser.balance || 0,
            createdAt: new Date(),
            lastLogin: null,
            isActive: true,
            jugayganaUserId: jgUser.id,
            jugayganaUsername: jgUser.username,
            jugayganaSyncStatus: 'linked',
            source: 'jugaygana',
            tokenVersion: 0,
            mustChangePassword: true
          });
          await ChatStatus.create({
            userId,
            username: jgUser.username,
            status: 'open',
            category: 'cargas'
          });
          logger.info(`User ${cleanUsername} auto-created from JUGAYGANA via username-only login`);
        }
      } catch (jgErr) {
        logger.warn(`[LoginUsernameOnly] JUGAYGANA lookup failed: ${jgErr.message}`);
      }
    }

    if (!user) {
      return res.status(404).json({ error: 'Usuario no disponible' });
    }

    const userObj = user.toObject ? user.toObject() : user;
    const userId = userObj.id || userObj._id?.toString();

    if (!userId) {
      logger.error(`[LoginUsernameOnly] User found but has no id (username=${userObj.username})`);
      return res.status(500).json({ error: 'Error de configuración de usuario' });
    }

    if (userObj.isActive === false) {
      return res.status(404).json({ error: 'Usuario no disponible' });
    }
    if (userObj.isBlocked === true) {
      return res.status(403).json({
        error: `Tu cuenta está bloqueada: ${userObj.blockReason || 'Contactá a soporte.'}`,
        code: 'USER_BLOCKED'
      });
    }
    if (isAdminRole(userObj.role)) {
      return res.status(403).json({ error: 'Usuario no disponible' });
    }

    // === Anti multi-cuenta por dispositivo ===
    // El front manda un ID propio guardado en el navegador. Si este
    // dispositivo ya inició con OTRO usuario, se bloquea la cuenta con la
    // que intenta entrar ahora. Si la verificación falla, NO bloquea
    // (fail-open: no dejamos afuera a nadie por un error de DB).
    const deviceId = String((req.body && req.body.deviceId) || '').trim().slice(0, 80);
    logger.info(`[device-check] login user=${userObj.username} deviceId=${deviceId || 'NINGUNO (front no lo mandó)'}`);
    if (deviceId) {
      try {
        const dev = await DeviceAccount.findOne({ deviceId }).lean();
        if (!dev) {
          await DeviceAccount.updateOne(
            { deviceId },
            { $setOnInsert: { deviceId, username: userObj.username, createdAt: new Date() } },
            { upsert: true }
          );
          logger.info(`[device-check] dispositivo NUEVO — reclamado por ${userObj.username}`);
        } else if (String(dev.username || '').toLowerCase() !== String(userObj.username || '').toLowerCase()) {
          const reason = `Multi-cuenta: inició con ${userObj.username} en un dispositivo registrado a ${dev.username}.`;
          try {
            await User.updateOne({ id: userId }, { $set: {
              fraudBlocked: true,
              fraudReason: reason,
              fraudBlockedAt: new Date()
            } });
          } catch (e) {
            logger.warn(`[device-check] no se pudo flaggear ${userObj.username}: ${e.message}`);
          }
          logger.warn(`[device-check] ${userObj.username} bloqueado — dispositivo de ${dev.username}`);
          return res.status(403).json({
            error: 'Tu cuenta fue bloqueada: iniciaste sesión con un usuario distinto al registrado en este dispositivo. Contactá a soporte.',
            code: 'DEVICE_MISMATCH'
          });
        } else {
          logger.info(`[device-check] OK — el dispositivo ya pertenece a ${userObj.username}`);
        }
      } catch (devErr) {
        logger.warn(`[device-check] error, el login continúa: ${devErr.message}`);
      }
    }

    // Best-effort: actualizar lastLogin sin romper si el doc viejo falla validación.
    try {
      await User.updateOne({ id: userId }, { $set: { lastLogin: new Date() } });
    } catch (saveErr) {
      logger.warn(`[LoginUsernameOnly] No se pudo actualizar lastLogin para ${userObj.username}: ${saveErr.message}`);
    }

    let token;
    try {
      // Token con scope LIMITADO ('refunds-only'): permite ver y reclamar
      // reembolsos / regalos / sorteos (la plata cae en el balance del user
      // víctima, no del atacante), pero NO permite endpoints sensibles como
      // cambiar contraseña, modificar el perfil o tocar cuentas. La guarda la
      // hace requireFullScope. TTL 7d (antes 30d) para reducir ventana de
      // explotación si un token se filtra.
      token = jwt.sign(
        {
          userId,
          username: userObj.username,
          role: userObj.role,
          tokenVersion: userObj.tokenVersion ?? 0,
          scope: 'refunds-only'
        },
        JWT_SECRET,
        { expiresIn: '7d' }
      );
    } catch (jwtErr) {
      logger.error(`[LoginUsernameOnly] jwt.sign falló: ${jwtErr.message}`);
      return res.status(500).json({ error: 'Error generando token' });
    }

    let linePhone = null;
    try {
      // Prioridad 1: asignación explícita por Drive import (User.linePhone).
      // Si el admin importó este username desde un .xlsx, ese teléfono manda
      // por encima del matcher por prefijo.
      if (userObj.linePhone) {
        linePhone = userObj.linePhone;
      } else {
        // Prioridad 2: UserLineLookup (mapeo persistido desde un .xlsx que
        // pre-incluía a este user, aunque el user se haya creado DESPUÉS
        // del import — caso típico: importás el Drive y luego el user
        // entra por primera vez via JUGAYGANA). Si hay match, lo
        // persistimos en User.linePhone para evitar el lookup en futuros
        // logins (lazy migration).
        const lookup = await pickLineFromLookup(userObj.username);
        if (lookup && lookup.linePhone) {
          linePhone = lookup.linePhone;
          // Lazy persist (fire-and-forget): no bloquea el login.
          User.updateOne(
            { id: userId },
            {
              $set: {
                linePhone: lookup.linePhone,
                lineTeamName: lookup.lineTeamName || null,
                lineAssignedAt: new Date(),
                lineAssignedBy: 'auto-from-lookup',
                lineAssignmentSource: 'lookup',
                lineAssignmentNote: 'Pre-asignado desde import .xlsx'
              }
            }
          ).catch(err => logger.warn(`[LoginUsernameOnly] lazy persist linePhone falló: ${err.message}`));
        } else {
          // Prioridad 3: matcher por prefijo + persist con marker
          // 'prefix-fallback' o 'general-default' según corresponda.
          const linesConfig = await getConfig('userLinesByPrefix');
          const resolved = resolveLineByPrefixFallback(linesConfig, userObj.username);
          if (resolved && resolved.linePhone) {
            linePhone = resolved.linePhone;
            User.updateOne(
              { id: userId },
              {
                $set: {
                  linePhone: resolved.linePhone,
                  lineTeamName: resolved.lineTeamName,
                  lineAssignedAt: new Date(),
                  lineAssignedBy: 'auto-fallback',
                  lineAssignmentSource: resolved.source,
                  lineAssignmentNote: resolved.note
                }
              }
            ).catch(err => logger.warn(`[LoginUsernameOnly] lazy persist fallback falló: ${err.message}`));
          }
        }
      }
    } catch (cfgErr) {
      logger.warn(`[LoginUsernameOnly] No se pudo resolver línea: ${cfgErr.message}`);
    }

    res.json({
      message: 'Login exitoso',
      token,
      user: {
        id: userId,
        username: userObj.username,
        role: userObj.role
      },
      linePhone
    });
  } catch (error) {
    console.error('[LoginUsernameOnly] OUTER CATCH:', error.name, error.message, error.stack);
    logger.error(`Login username-only error (${error.name}): ${error.message}\n${error.stack}`);
    if (!res.headersSent) {
      return res.status(500).json({ error: `Error del servidor: ${error.name}: ${error.message}` });
    }
  }
});

// Devuelve la línea vigente del usuario autenticado (para refrescar sin re-login).
app.get('/api/user-lines/me', authMiddleware, async (req, res) => {
  try {
    // Refetch del User para leer linePhone/lineTeamName (no están en el JWT).
    // Query indexada por `id` — costo despreciable.
    let userDoc = null;
    try {
      userDoc = await User.findOne({ id: req.user.userId })
        .select('username linePhone lineTeamName')
        .lean();
    } catch (lookupErr) {
      logger.warn(`[user-lines/me] User lookup falló: ${lookupErr.message}`);
    }

    let phone = null;
    let teamName = null;

    // Prioridad 1: asignación explícita ya persistida en User (Drive import).
    if (userDoc && userDoc.linePhone) phone = userDoc.linePhone;
    if (userDoc && userDoc.lineTeamName) teamName = userDoc.lineTeamName;

    // Prioridad 2: UserLineLookup (el usuario está en un .xlsx pero todavía no
    // tiene linePhone seteado — puede pasar si la User se creó después del
    // import o si ese campo se limpió). Lazy persist para futuros lookups.
    if ((!phone || !teamName) && userDoc) {
      const lookup = await pickLineFromLookup(req.user.username);
      if (lookup) {
        if (!phone && lookup.linePhone) phone = lookup.linePhone;
        if (!teamName && lookup.lineTeamName) teamName = lookup.lineTeamName;
        if (phone || teamName) {
          User.updateOne(
            { id: req.user.userId },
            {
              $set: {
                ...(phone ? { linePhone: phone } : {}),
                ...(teamName ? { lineTeamName: teamName } : {}),
                lineAssignedAt: new Date(),
                lineAssignedBy: 'auto-from-lookup',
                lineAssignmentSource: 'lookup',
                lineAssignmentNote: 'Pre-asignado desde import .xlsx'
              }
            }
          ).catch(err => logger.warn(`[user-lines/me] lazy persist falló: ${err.message}`));
        }
      }
    }

    // Prioridad 3: matcher por prefijo (longest-prefix-match). Persistir
    // al User con marker 'prefix-fallback' o 'general-default'.
    if (!phone || !teamName) {
      const linesConfig = await getConfig('userLinesByPrefix');
      const resolved = resolveLineByPrefixFallback(linesConfig, req.user.username);
      if (resolved) {
        if (!phone) phone = resolved.linePhone;
        if (!teamName) teamName = resolved.lineTeamName;
        // Persistir si el User no tenía ya línea (no pisar lo que vino
        // de Drive import o lookup).
        if (userDoc && !userDoc.linePhone) {
          User.updateOne(
            { id: req.user.userId },
            {
              $set: {
                linePhone: resolved.linePhone,
                lineTeamName: resolved.lineTeamName,
                lineAssignedAt: new Date(),
                lineAssignedBy: 'auto-fallback',
                lineAssignmentSource: resolved.source,
                lineAssignmentNote: resolved.note
              }
            }
          ).catch(err => logger.warn(`[user-lines/me] lazy persist fallback falló: ${err.message}`));
        }
      }
    }

    // Resolución de comunidad: prioridad a la asignación EXPLÍCITA por
    // username (UserCommunityLookup, subida por xlsx). Si no, cae al
    // fallback de prefijo (userCommunitiesByPrefix). Si la asignación
    // explícita está marcada 'down', devolvemos link + replacementLink
    // para que la PWA muestre alerta "tu comunidad cerró, sumate acá".
    let communityLink = null;
    let communityLabel = null;
    let communityStatus = 'active';
    let communityReplacementLink = null;
    let communityReplacementLabel = null;
    try {
      const safeUser = String(req.user.username || '').toLowerCase().trim();
      if (safeUser) {
        const explicit = await UserCommunityLookup.findOne({ usernameNorm: safeUser }).lean();
        if (explicit) {
          communityLink = explicit.communityLink || null;
          communityLabel = explicit.communityLabel || null;
          communityStatus = explicit.status || 'active';
          communityReplacementLink = explicit.replacementLink || null;
          communityReplacementLabel = explicit.replacementLabel || null;
        }
      }
    } catch (e) { /* fall through to prefix */ }
    let communityLink2 = null;
    let communityLabel2 = null;
    let excludedFromCodes = false;
    if (!communityLink) {
      const communitiesConfig = await getConfig('userCommunitiesByPrefix');
      const bundle = pickCommunityBundleForUsername(communitiesConfig, req.user.username);
      if (bundle) {
        communityLink = bundle.link || null;
        communityLink2 = bundle.link2 || null;
        // Si los labels vinieron desde el slot, los usamos. Si no,
        // default a "Comunidad 1 oficial" / "Comunidad 2 oficial" cuando hay 2 links.
        communityLabel = bundle.label || (bundle.link && bundle.link2 ? 'Comunidad 1 oficial' : null);
        communityLabel2 = bundle.label2 || (bundle.link2 ? 'Comunidad 2 oficial' : null);
        excludedFromCodes = !!bundle.excludeFromCodes;
      }
    }
    // Flag de "alerta forzada" — si el admin activó el reminder por N hs
    // (vía /api/admin/community-alert/force o automáticamente al apretar
    // 📢 Avisar push), la PWA ignora el cooldown de 5 días.
    // OJO: si el user ya canjeó un código (probó que está dentro del canal
    // de Telegram), no le mandamos más este recordatorio — está dentro.
    let alertForceUntilMs = 0;
    let forceBannerMsg = null;
    let userJoinedTelegram = false;
    let showUnblockNotice = false;
    // Defensivo: si por algún motivo falla la lectura del usuario para
    // saber su joinedTelegram, NO rompemos el endpoint — solo dejamos el
    // flag en false y seguimos. Este endpoint se pega mucho, no podemos
    // permitir que tire 5xx por un detalle.
    if (req.user && req.user.userId) {
      try {
        const meDoc = await User.findOne({ id: String(req.user.userId) })
          .select('joinedTelegram unblockNoticePending unblockNoticeAt')
          .lean();
        userJoinedTelegram = !!(meDoc && meDoc.joinedTelegram);
        // Mostrar el cartel "no cambies de sesión" SOLO si pending y aún
        // dentro de los 7 días desde que se prendió. Pasado eso, se ignora.
        if (meDoc && meDoc.unblockNoticePending && meDoc.unblockNoticeAt) {
          const ageMs = Date.now() - new Date(meDoc.unblockNoticeAt).getTime();
          if (ageMs < 7 * 24 * 3600 * 1000) showUnblockNotice = true;
        }
      } catch (e) {
        logger.warn(`[user-lines/me] lookup user fields falló: ${e.message}`);
      }
    }
    try {
      const raw = await getConfig('communityAlertForceUntil').catch(() => null);
      const n = Number(raw) || 0;
      // Equipos excluídos (zz_crazy etc.) no ven el cartel forzado tampoco.
      if (n > Date.now() && !userJoinedTelegram && !excludedFromCodes) {
        alertForceUntilMs = n;
        // Mensaje custom del banner (lo setea PUT user-communities con
        // broadcastBody). Vive solo durante la ventana forzada.
        forceBannerMsg = await getConfig('communityForceBannerMsg').catch(() => null) || null;
      }
    } catch (_) {}

    res.json({
      phone: phone || null,
      teamName: teamName || null,
      communityLink: communityLink || null,
      communityLabel: communityLabel || null,
      communityLink2: communityLink2 || null,
      communityLabel2: communityLabel2 || null,
      communityStatus,
      communityReplacementLink: communityReplacementLink || null,
      communityReplacementLabel: communityReplacementLabel || null,
      communityAlertForceUntilMs: alertForceUntilMs || null,
      communityForceBannerMsg: forceBannerMsg,
      // Para que el frontend oculte el botón "Abrir Telegram" debajo del
      // input del código si el user ya canjeó alguna vez (probó estar en
      // el canal).
      joinedTelegram: userJoinedTelegram,
      // Equipo está fuera del sistema de códigos Telegram → la home no
      // muestra el card del código, ni el botón celeste, ni cambia el
      // ícono a Telegram. Sigue con WhatsApp como antes.
      excludedFromCodes: excludedFromCodes,
      // Cartel grande "no cambies de sesión" — solo prendido si el admin
      // desbloqueó o restringió a este user recientemente.
      showUnblockNotice: showUnblockNotice
    });
  } catch (error) {
    logger.error(`user-lines/me error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// User logout — limpia el token FCM actual del backend para que las
// notificaciones no sigan llegando a este dispositivo después de cerrar
// sesión. Acepta el fcmToken por body o por query; si no viene, intenta
// inferirlo del header Authorization (último token registrado del user).
// Nunca devuelve 401: cerrar sesión siempre es válido aunque el token JWT
// esté expirado.
app.post('/api/auth/logout', async (req, res) => {
  try {
    const fcmToken = (req.body && req.body.fcmToken) || (req.query && req.query.fcmToken) || null;

    // Intentar identificar al usuario por el JWT. Si está expirado o ausente,
    // hacemos best-effort: borramos el fcmToken provisto donde sea que esté.
    let userId = null;
    const authHeader = req.headers.authorization || '';
    const authToken = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : null;
    if (authToken) {
      try {
        const decoded = jwt.verify(authToken, JWT_SECRET);
        userId = decoded.userId;
      } catch (_) {
        // JWT expirado/inválido: igual seguimos para limpiar por token si vino
      }
    }

    if (fcmToken) {
      const tokenStr = String(fcmToken);
      // Borrar del array fcmTokens y del campo individual donde coincida
      if (userId) {
        await User.updateOne(
          { id: userId },
          { $pull: { fcmTokens: { token: tokenStr } } }
        );
        await User.updateOne(
          { id: userId, fcmToken: tokenStr },
          { $set: { fcmToken: null, fcmTokenUpdatedAt: null } }
        );
      } else {
        // Sin userId verificado: borrar el token donde sea que esté.
        await User.updateMany(
          { 'fcmTokens.token': tokenStr },
          { $pull: { fcmTokens: { token: tokenStr } } }
        );
        await User.updateMany(
          { fcmToken: tokenStr },
          { $set: { fcmToken: null, fcmTokenUpdatedAt: null } }
        );
      }
      logger.info(`[AUTH] logout: token FCM eliminado (user=${userId || 'unknown'}, token=...${tokenStr.slice(-8)})`);
    }

    res.json({ success: true });
  } catch (error) {
    // Logout siempre debe responder OK al cliente; loggeamos para diagnóstico.
    logger.warn(`[AUTH] logout: error limpiando token FCM: ${error.message}`);
    res.json({ success: true });
  }
});

