app.post('/api/admin/canal-url', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Solo el admin principal puede modificar la URL del canal.' });
    }
    const { url } = req.body;
    const safeUrl = (url || '').trim();
    if (safeUrl) {
      try {
        const parsed = new URL(safeUrl);
        if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
          return res.status(400).json({ error: 'URL inválida. Debe comenzar con http:// o https://' });
        }
      } catch {
        return res.status(400).json({ error: 'URL inválida. Verificá que sea una URL completa y válida.' });
      }
    }
    await setConfig('canalInformativoUrl', safeUrl);
    res.json({ success: true, message: 'URL del Canal Informativo actualizada correctamente' });
  } catch (error) {
    console.error('Error guardando canal URL:', error);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

app.put('/api/admin/config/cbu', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    // Solo el admin principal puede cambiar el CBU. Un depositor/withdrawer comprometido
    // podria redirigir los depositos de los usuarios a su propia cuenta bancaria.
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Solo el administrador principal puede modificar el CBU' });
    }

    const currentCbu = await getConfig('cbu') || {};
    // Whitelist de campos permitidos para evitar inyeccion de propiedades inesperadas.
    const allowed = {};
    if (typeof req.body.bank === 'string') allowed.bank = req.body.bank.trim();
    if (typeof req.body.titular === 'string') allowed.titular = req.body.titular.trim();
    if (typeof req.body.number === 'string') allowed.number = req.body.number.trim();
    if (typeof req.body.alias === 'string') allowed.alias = req.body.alias.trim();

    if (allowed.number !== undefined && allowed.number.length > 0 && allowed.number.length < 10) {
      return res.status(400).json({ error: 'CBU invalido (minimo 10 caracteres)' });
    }

    const newCbu = { ...currentCbu, ...allowed };
    await setConfig('cbu', newCbu);

    logger.info(`Admin ${req.user.username} updated CBU config`);
    res.json({ success: true, message: 'CBU actualizado', cbu: newCbu });
  } catch (error) {
    console.error('Error actualizando CBU:', error);
    res.status(500).json({ error: 'Error actualizando CBU' });
  }
});

// ============================================
// LÍNEAS POR USUARIO (mapeo prefijo → teléfono)
// Se muestran al usuario en la pantalla de reembolsos.
// 10 slots configurables + un teléfono default si ninguno matchea.
// ============================================
const USER_LINES_MAX_SLOTS = 30;

// Lista de usernames asignados a UNA línea (teamName + linePhone). Junta
// dos fuentes para mostrar TODOS los usuarios de la línea sin importar de
// dónde vinieron:
//   1) UserLineLookup — los del .xlsx (pre-asignados o registrados después)
//   2) User.lineTeamName/linePhone — todos los users registrados con esa
//      línea asignada (incluye los que cayeron por prefix-fallback automático,
//      no por xlsx).
// Mergeo por username y devuelvo la unión deduplicada.
app.get('/api/admin/user-lines/lookup-by-line', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const teamName = String(req.query.teamName || '').trim();
    const linePhone = String(req.query.linePhone || '').trim();
    if (!teamName && !linePhone) {
      return res.status(400).json({ error: 'Faltan params teamName o linePhone' });
    }
    const limit = Math.max(1, Math.min(5000, parseInt(req.query.limit, 10) || 2000));

    // 1) Pre-asignaciones por xlsx (UserLineLookup).
    const lookupFilter = {};
    if (teamName) lookupFilter.lineTeamName = teamName;
    if (linePhone) lookupFilter.linePhone = linePhone;
    const lookupRows = await UserLineLookup.find(lookupFilter)
      .sort({ importedAt: -1 })
      .limit(limit)
      .lean();

    // 2) Users registrados con esa línea asignada (User.lineTeamName/linePhone).
    const userFilter = {};
    if (teamName) userFilter.lineTeamName = teamName;
    if (linePhone) userFilter.linePhone = linePhone;
    const userRows = await User.find(
      userFilter,
      { username: 1, lineTeamName: 1, linePhone: 1, lineAssignedAt: 1, lineAssignmentSource: 1, fcmToken: 1, fcmTokens: 1, lastLogin: 1, phone: 1, _id: 0 }
    ).limit(limit).lean();

    // Merge por username (lowercase). UserLineLookup es la fuente de
    // "pre-asignado", User es "registrado".
    const byKey = new Map();
    for (const r of lookupRows) {
      const k = String(r.usernameNorm || '').toLowerCase();
      if (!k) continue;
      byKey.set(k, {
        usernameNorm: r.usernameNorm,
        usernameOriginal: r.usernameOriginal || r.usernameNorm,
        source: 'xlsx-pending',
        importedAt: r.importedAt,
        importedBy: r.importedBy,
        registered: false,
        hasApp: false,
        lastLogin: null,
        phone: null,
        lineAssignmentSource: null
      });
    }
    for (const u of userRows) {
      const k = String(u.username || '').toLowerCase();
      if (!k) continue;
      const hasApp = !!(u.fcmToken || (Array.isArray(u.fcmTokens) && u.fcmTokens.length > 0));
      const existing = byKey.get(k);
      if (existing) {
        // Estaba en xlsx Y además se registró → marcamos registered y enriquecemos.
        existing.registered = true;
        existing.hasApp = hasApp;
        existing.lastLogin = u.lastLogin || null;
        existing.phone = u.phone || null;
        existing.lineAssignmentSource = u.lineAssignmentSource || existing.lineAssignmentSource;
        existing.source = 'xlsx-registered';
      } else {
        // No estaba en xlsx → vino por prefix-fallback / auto / manual.
        byKey.set(k, {
          usernameNorm: u.username,
          usernameOriginal: u.username,
          source: u.lineAssignmentSource ? ('user-' + u.lineAssignmentSource) : 'user-auto',
          importedAt: u.lineAssignedAt || null,
          importedBy: null,
          registered: true,
          hasApp,
          lastLogin: u.lastLogin || null,
          phone: u.phone || null,
          lineAssignmentSource: u.lineAssignmentSource || null
        });
      }
    }

    const items = Array.from(byKey.values());
    // Ordenar: registrados primero, después pre-asignados; dentro de cada grupo, por fecha desc.
    items.sort((a, b) => {
      if (a.registered !== b.registered) return a.registered ? -1 : 1;
      const ta = a.importedAt ? new Date(a.importedAt).getTime() : 0;
      const tb = b.importedAt ? new Date(b.importedAt).getTime() : 0;
      return tb - ta;
    });

    const totalCount = items.length;
    const registeredCount = items.filter(it => it.registered).length;
    const pendingCount = totalCount - registeredCount;
    const xlsxCount = items.filter(it => it.source === 'xlsx-pending' || it.source === 'xlsx-registered').length;
    const autoCount = items.filter(it => it.source && it.source.startsWith('user-')).length;

    let lastImportAt = null, lastImportBy = null;
    if (lookupRows.length > 0) {
      lastImportAt = lookupRows[0].importedAt;
      lastImportBy = lookupRows[0].importedBy;
    }

    res.json({
      teamName: teamName || null,
      linePhone: linePhone || null,
      totalCount,
      registeredCount,
      pendingCount,
      xlsxCount,
      autoCount,
      lastImportAt,
      lastImportBy,
      items
    });
  } catch (err) {
    logger.error(`/api/admin/user-lines/lookup-by-line: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// Historial de cargas .xlsx por línea. Cada upload deja todas las filas con
// el MISMO importedAt, así que agrupando por (importedAt, importedBy)
// reconstruimos cada "sesión de carga" como si fuera un archivo separado.
app.get('/api/admin/user-lines/import-history', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const teamName = String(req.query.teamName || '').trim();
    const linePhone = String(req.query.linePhone || '').trim();
    if (!teamName && !linePhone) {
      return res.status(400).json({ error: 'Faltan params teamName o linePhone' });
    }
    const match = {};
    if (teamName) match.lineTeamName = teamName;
    if (linePhone) match.linePhone = linePhone;

    // Agrupar por (importedAt, importedBy). Como las cargas masivas usan el
    // MISMO Date para todos los rows del archivo, esto separa cada upload.
    // Toleramos jitter de 1 segundo agrupando por timestamp en segundos.
    const sessions = await UserLineLookup.aggregate([
      { $match: match },
      { $project: {
          usernameNorm: 1,
          usernameOriginal: 1,
          lineTeamName: 1,
          linePhone: 1,
          importedAt: 1,
          importedBy: 1,
          // Truncar a segundo para tolerar jitter de ms entre rows del mismo bulk.
          importedAtSec: {
            $dateToString: {
              format: '%Y-%m-%dT%H:%M:%S',
              date: '$importedAt'
            }
          }
      }},
      { $group: {
          _id: { ts: '$importedAtSec', by: '$importedBy' },
          count: { $sum: 1 },
          importedAt: { $first: '$importedAt' },
          importedBy: { $first: '$importedBy' },
          team: { $first: '$lineTeamName' },
          line: { $first: '$linePhone' },
          sampleUsers: { $push: { $ifNull: ['$usernameOriginal', '$usernameNorm'] } }
      }},
      { $sort: { importedAt: -1 } },
      { $limit: 100 }
    ]);

    const sessionsOut = sessions.map((s, idx) => ({
      id: 'session-' + idx,
      importedAt: s.importedAt,
      importedBy: s.importedBy,
      team: s.team,
      line: s.line,
      count: s.count,
      // Hasta 8 sample usernames para preview en el modal sin descargar todo.
      sampleUsernames: (s.sampleUsers || []).slice(0, 8)
    }));

    res.json({
      teamName: teamName || null,
      linePhone: linePhone || null,
      totalSessions: sessionsOut.length,
      totalUsers: sessionsOut.reduce((sum, s) => sum + (s.count || 0), 0),
      sessions: sessionsOut
    });
  } catch (err) {
    logger.error(`/api/admin/user-lines/import-history: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// CSV de UNA sesión de carga histórica (filtra por importedAt exacto).
app.get('/api/admin/user-lines/import-history.csv', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const teamName = String(req.query.teamName || '').trim();
    const linePhone = String(req.query.linePhone || '').trim();
    const importedAtStr = String(req.query.importedAt || '').trim();
    if (!importedAtStr) return res.status(400).json({ error: 'Falta param importedAt' });
    const importedAtDate = new Date(importedAtStr);
    if (isNaN(importedAtDate.getTime())) return res.status(400).json({ error: 'importedAt inválido' });

    // Tolerancia de 1s para juntar todos los rows del mismo bulk.
    const lo = new Date(importedAtDate.getTime() - 1000);
    const hi = new Date(importedAtDate.getTime() + 1000);
    const filter = { importedAt: { $gte: lo, $lt: hi } };
    if (teamName) filter.lineTeamName = teamName;
    if (linePhone) filter.linePhone = linePhone;

    const rows = await UserLineLookup.find(filter).lean();
    const escape = (v) => {
      const s = (v == null ? '' : String(v));
      return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
    };
    const lines = ['Usuario,Equipo,Linea,FechaCarga,CargadoPor'];
    for (const r of rows) {
      lines.push([
        escape(r.usernameOriginal || r.usernameNorm || ''),
        escape(r.lineTeamName || ''),
        escape(r.linePhone || ''),
        escape(r.importedAt ? new Date(r.importedAt).toISOString() : ''),
        escape(r.importedBy || '')
      ].join(','));
    }
    const csv = '﻿' + lines.join('\r\n');
    const safe = (s) => String(s || '').replace(/[^a-zA-Z0-9_-]/g, '_');
    const dateTag = importedAtDate.toISOString().slice(0, 19).replace(/[:.]/g, '-');
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition', `attachment; filename="carga-${safe(teamName)}-${dateTag}.csv"`);
    res.send(csv);
  } catch (err) {
    logger.error(`/api/admin/user-lines/import-history.csv: ${err.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// CSV: lista completa de una línea (xlsx pre-asignados + users registrados).
app.get('/api/admin/user-lines/lookup-by-line.csv', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const teamName = String(req.query.teamName || '').trim();
    const linePhone = String(req.query.linePhone || '').trim();
    if (!teamName && !linePhone) {
      return res.status(400).json({ error: 'Faltan params teamName o linePhone' });
    }

    const lookupFilter = {};
    if (teamName) lookupFilter.lineTeamName = teamName;
    if (linePhone) lookupFilter.linePhone = linePhone;
    const lookupRows = await UserLineLookup.find(lookupFilter).sort({ importedAt: -1 }).lean();

    const userFilter = {};
    if (teamName) userFilter.lineTeamName = teamName;
    if (linePhone) userFilter.linePhone = linePhone;
    const userRows = await User.find(
      userFilter,
      { username: 1, phone: 1, fcmToken: 1, fcmTokens: 1, lineAssignedAt: 1, lineAssignmentSource: 1, _id: 0 }
    ).lean();

    const byKey = new Map();
    for (const r of lookupRows) {
      const k = String(r.usernameNorm || '').toLowerCase();
      if (!k) continue;
      byKey.set(k, {
        username: r.usernameOriginal || r.usernameNorm,
        team: r.lineTeamName || teamName,
        line: r.linePhone || linePhone,
        registered: false,
        hasApp: false,
        phone: '',
        source: 'xlsx',
        importedAt: r.importedAt
      });
    }
    for (const u of userRows) {
      const k = String(u.username || '').toLowerCase();
      if (!k) continue;
      const hasApp = !!(u.fcmToken || (Array.isArray(u.fcmTokens) && u.fcmTokens.length > 0));
      const existing = byKey.get(k);
      if (existing) {
        existing.registered = true;
        existing.hasApp = hasApp;
        existing.phone = u.phone || '';
      } else {
        byKey.set(k, {
          username: u.username,
          team: teamName,
          line: linePhone,
          registered: true,
          hasApp,
          phone: u.phone || '',
          source: u.lineAssignmentSource || 'auto',
          importedAt: u.lineAssignedAt || null
        });
      }
    }

    const escape = (v) => {
      const s = (v == null ? '' : String(v));
      return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
    };
    const lines = ['Usuario,Equipo,Linea,Estado,TieneApp,Telefono,Origen,FechaCarga'];
    for (const it of byKey.values()) {
      lines.push([
        escape(it.username || ''),
        escape(it.team || ''),
        escape(it.line || ''),
        escape(it.registered ? 'Registrado' : 'Pre-asignado'),
        escape(it.hasApp ? 'Si' : 'No'),
        escape(it.phone || ''),
        escape(it.source || ''),
        escape(it.importedAt ? new Date(it.importedAt).toISOString() : '')
      ].join(','));
    }
    const csv = '﻿' + lines.join('\r\n');
    const safe = (s) => String(s || '').replace(/[^a-zA-Z0-9_-]/g, '_');
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition', `attachment; filename="linea-${safe(teamName)}-${safe(linePhone)}-${new Date().toISOString().slice(0,10)}.csv"`);
    res.send(csv);
  } catch (err) {
    logger.error(`/api/admin/user-lines/lookup-by-line.csv: ${err.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// Gateado por PIN 'numero' — el directorio completo de líneas/teléfonos
// solo se entrega si el admin ingresó el PIN en esta sesión.
app.get('/api/admin/user-lines', authMiddleware, adminMiddleware, requireSectionPin('numero'), async (req, res) => {
  try {
    const config = (await getConfig('userLinesByPrefix')) || {};
    const slots = Array.isArray(config.slots) ? config.slots : [];
    // Devolvemos solo los slots con datos (no padding); el frontend agrega
    // un botón "+ Agregar línea" para sumar más, hasta USER_LINES_MAX_SLOTS.
    // teamName es opcional — se muestra arriba a la izquierda en el header
    // del usuario cuando el prefijo matchea (ej: 'ato' -> 'Atomic').
    const cleaned = slots
      .filter(s => s && (s.prefix || s.phone || s.teamName))
      .map(s => ({
        prefix: s.prefix || '',
        phone: s.phone || '',
        teamName: s.teamName || ''
      }));
    res.json({
      slots: cleaned,
      defaultPhone: config.defaultPhone || '',
      defaultTeamName: config.defaultTeamName || '',
      maxSlots: USER_LINES_MAX_SLOTS
    });
  } catch (error) {
    console.error('Error obteniendo user-lines:', error);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

app.put('/api/admin/user-lines', authMiddleware, adminMiddleware, requireSectionPin('numero'), async (req, res) => {
  try {
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Solo el admin principal puede modificar las líneas.' });
    }
    const { slots, defaultPhone, defaultTeamName } = req.body || {};
    if (!Array.isArray(slots)) {
      return res.status(400).json({ error: 'slots debe ser un array' });
    }
    if (slots.length > USER_LINES_MAX_SLOTS) {
      return res.status(400).json({ error: `Máximo ${USER_LINES_MAX_SLOTS} slots` });
    }
    const cleaned = [];
    for (const s of slots) {
      const prefix = (s && s.prefix ? String(s.prefix) : '').trim();
      const phone = (s && s.phone ? String(s.phone) : '').trim();
      const teamName = (s && s.teamName ? String(s.teamName) : '').trim();
      if (!prefix && !phone && !teamName) continue;
      if (prefix && !phone) {
        return res.status(400).json({ error: `El prefijo "${prefix}" no tiene número` });
      }
      // teamName es opcional (no es obligatorio aunque haya prefijo).
      // Cap visual razonable para que no rompa el layout del header del user.
      if (teamName.length > 24) {
        return res.status(400).json({ error: `El nombre de equipo "${teamName.slice(0,30)}…" es demasiado largo (máx 24)` });
      }
      cleaned.push({ prefix, phone, teamName });
    }
    const newDefaultPhone = (defaultPhone ? String(defaultPhone) : '').trim();
    const newDefaultTeamName = (defaultTeamName ? String(defaultTeamName) : '').trim();
    if (newDefaultTeamName.length > 24) {
      return res.status(400).json({ error: 'El nombre de equipo por defecto es demasiado largo (máx 24)' });
    }

    const value = {
      slots: cleaned,
      defaultPhone: newDefaultPhone,
      defaultTeamName: newDefaultTeamName
    };
    await setConfig('userLinesByPrefix', value);
    res.json({ success: true, message: 'Líneas actualizadas', value });
    // Auto-notificación al cambiar línea desactivada por requerimiento del cliente.
    // El usuario igualmente verá el banner rojo de "cambio de línea" cuando entre
    // a la app (la detección es del lado del frontend comparando el último número
    // visto en localStorage contra el actual).
  } catch (error) {
    console.error('Error actualizando user-lines:', error);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// ============================================
// IMPORT DE LÍNEAS DESDE DRIVE / .XLSX
// Permite asignar masivamente usuarios a líneas específicas subiendo un .xlsx
// exportado desde Google Sheets. Cada hoja del archivo representa una línea:
//   - Nombre de la hoja = teléfono de esa línea (ej: "+5491111...")
//   - Primera fila (header "name") se ignora
//   - Filas restantes = usernames que pertenecen a esa línea
// El parámetro `teamName` (query string) se aplica a todas las hojas del archivo.
// `dryRun=true` (default) no escribe nada — solo devuelve un reporte para preview.
// ============================================
const USER_LINES_IMPORT_LIMIT = '15mb'; // ~15 hojas × 3000 filas, holgado.

app.post(
  '/api/admin/user-lines/import',
  authMiddleware,
  adminMiddleware,
  express.raw({ limit: USER_LINES_IMPORT_LIMIT, type: '*/*' }),
  async (req, res) => {
    // Lazy require — si xlsx no está instalado, devolvemos error claro
    // (admin debe correr `npm install` después del deploy con este feature).
    let XLSX;
    try {
      XLSX = require('xlsx');
    } catch (e) {
      return res.status(503).json({
        error: 'Falta instalar la dependencia "xlsx" en el servidor. Ejecutá: npm install xlsx'
      });
    }

    try {
      const teamName = (req.query.teamName ? String(req.query.teamName) : '').trim();
      if (!teamName) {
        return res.status(400).json({ error: 'Falta el parámetro teamName (nombre del equipo)' });
      }
      if (teamName.length > 24) {
        return res.status(400).json({ error: 'El nombre del equipo es demasiado largo (máx 24)' });
      }

      // Prefijo de username del equipo (ej: "ato", "argen", "tiger"). El sistema
      // concatena prefix + valor de celda para reconstruir el username completo
      // antes de matchear contra la DB. Si la celda ya empieza con el prefix,
      // se usa la celda tal cual (modo tolerante).
      const prefix = (req.query.prefix ? String(req.query.prefix) : '').trim().toLowerCase();
      if (!prefix) {
        return res.status(400).json({ error: 'Falta el parámetro prefix (las "iniciales" del equipo, ej: ato, argen, tiger)' });
      }
      if (prefix.length > 20) {
        return res.status(400).json({ error: 'El prefijo es demasiado largo (máx 20)' });
      }

      // Línea explícita (modo "import per-slot"). Si viene, TODAS las hojas
      // del archivo se asignan a este teléfono — los nombres de las hojas se
      // ignoran. Esto permite que el admin suba un .xlsx desde el slot del
      // panel "Números vigentes" y la línea sea la del slot, no parseada de
      // la hoja. Si no viene, se usa el comportamiento legacy (parsear cada
      // sheet name como teléfono).
      const overrideLinePhone = (req.query.linePhone ? String(req.query.linePhone) : '').trim();

      // dryRun por default true. Solo `dryRun=false` ejecuta escrituras.
      const dryRun = String(req.query.dryRun || 'true').toLowerCase() !== 'false';

      const buf = req.body;
      if (!buf || !Buffer.isBuffer(buf) || buf.length < 100) {
        return res.status(400).json({ error: 'Archivo vacío o muy chico' });
      }

      let workbook;
      try {
        workbook = XLSX.read(buf, { type: 'buffer', cellDates: false });
      } catch (parseErr) {
        return res.status(400).json({ error: `No se pudo leer el .xlsx: ${parseErr.message}` });
      }

      if (!workbook.SheetNames || workbook.SheetNames.length === 0) {
        return res.status(400).json({ error: 'El archivo no tiene hojas' });
      }

      // Normaliza un string para matcheo fuzzy: quita tildes/diacríticos,
      // pasa a minúscula, y elimina todo lo que no sea letra/dígito.
      // Permite que "Argen.Pedro_98", "argenpedro98", "ARGEN PEDRO 98" y
      // "argén.Pedro 98" matcheen contra el mismo username "argenpedro98".
      const _normalizeUsername = (raw) => {
        if (!raw) return '';
        return String(raw)
          .normalize('NFD').replace(/[̀-ͯ]/g, '') // strip diacríticos
          .toLowerCase()
          .replace(/[^a-z0-9]/g, '');
      };

      // Extrae el teléfono del nombre de la hoja. El nombre puede venir como
      // un teléfono puro (ej: "+5491111...") o como "ETIQUETA + número" (ej:
      // "TIGER 1 39095913748", "Atomic 2 +5493853..."). Devolvemos siempre
      // un string que arranque con '+' y tenga solo dígitos (formato canónico
      // para WhatsApp links). Si no se puede extraer, devuelve el sheetName
      // sin cambios como fallback (legacy).
      const _extractPhoneFromSheetName = (raw) => {
        const trimmed = String(raw || '').trim();
        if (!trimmed) return '';
        // Buscar la última secuencia de 7+ dígitos (con + opcional al inicio)
        // al final del string. \d{7,} cubre cualquier teléfono internacional.
        const m = trimmed.match(/(\+?\d[\d\s\-]{6,})\s*$/);
        if (m) {
          // Limpiar todo lo que no sea dígito y reagregar el +
          const digits = m[1].replace(/[^\d]/g, '');
          if (digits.length >= 7) return '+' + digits;
        }
        return trimmed;
      };

      // -------- Pase 1: extraer (sheetName -> [usernames normalizados]) y detectar
      // conflictos dentro del mismo archivo (mismo username en dos hojas distintas).
      // Los usernames se normalizan AGRESIVAMENTE (sin tildes, sin puntuación)
      // para tolerar variaciones de formato entre el .xlsx y la DB.
      const prefixNorm = _normalizeUsername(prefix);
      const sheetData = []; // [{ sheetName, linePhone, usernamesNorm: [], originalByNorm: Map }]
      const seenNormToSheet = new Map(); // norm -> first sheetName que lo trajo
      const conflictsInFile = []; // [{ username, sheets: [a, b] }]
      const allUsernamesNorm = new Set();

      for (const sheetName of workbook.SheetNames) {
        const sheetTrimmed = String(sheetName || '').trim();
        if (!sheetTrimmed) continue;
        // Si vino linePhone explícito (modo per-slot), todas las hojas usan ese.
        // Si no, parseamos el nombre de la hoja (modo legacy multi-line file).
        const linePhone = overrideLinePhone || _extractPhoneFromSheetName(sheetTrimmed);
        if (!linePhone) continue;

        const ws = workbook.Sheets[sheetName];
        if (!ws) continue;

        // header:1 → array de arrays. blankrows:false → omite filas vacías.
        const rows = XLSX.utils.sheet_to_json(ws, { header: 1, blankrows: false, defval: '' });

        // Saltar la primera fila (header "name"). Si el sheet está vacío o solo
        // tiene header, queda como hoja sin matches (no error — se reporta).
        const dataRows = rows.length > 1 ? rows.slice(1) : [];

        const usernamesNorm = [];
        const originalByNorm = new Map(); // para mostrar el valor original en notFoundSample
        for (const row of dataRows) {
          if (!row) continue;
          const raw = row[0];
          if (raw === null || raw === undefined) continue;
          const cleaned = String(raw).trim();
          if (!cleaned) continue;
          const cellNorm = _normalizeUsername(cleaned);
          if (!cellNorm) continue; // la celda no tenía letras/dígitos

          // Reconstruir el username normalizado completo:
          //   - Si la celda normalizada ya empieza con el prefijo (norm), se usa tal cual.
          //   - Si no, le concatenamos el prefijo (la celda es solo el sufijo).
          // Ejemplo: prefix='ato', celda='joaquin398' → 'atojoaquin398'.
          //          prefix='ato', celda='Ato.Joaquín_398' → 'atojoaquin398'.
          const fullNorm = cellNorm.startsWith(prefixNorm) ? cellNorm : (prefixNorm + cellNorm);

          // Detectar conflicto entre hojas del mismo upload.
          // En modo per-slot (overrideLinePhone), todas las hojas asignan al mismo
          // teléfono — los duplicados no son conflictos, simplemente se deduplican.
          if (seenNormToSheet.has(fullNorm) && seenNormToSheet.get(fullNorm) !== sheetName) {
            if (!overrideLinePhone) {
              conflictsInFile.push({
                username: fullNorm,
                sheets: [seenNormToSheet.get(fullNorm), sheetName]
              });
              // El conflicto invalida ambas asignaciones (modo legacy multi-line).
              continue;
            }
            // En modo per-slot, simplemente saltear el duplicado (ya está asignado).
            continue;
          }
          seenNormToSheet.set(fullNorm, sheetName);
          usernamesNorm.push(fullNorm);
          if (!originalByNorm.has(fullNorm)) originalByNorm.set(fullNorm, cleaned);
          allUsernamesNorm.add(fullNorm);
        }

        sheetData.push({ sheetName, linePhone, usernamesNorm, originalByNorm });
      }

      // -------- Pase 2: lookup en DB con regex-prefijo y match en memoria.
      // Cargamos TODOS los users cuyo username arranca con `prefix` (case-insensitive)
      // y construimos un Map<normalizado, doc>. Esto permite que cosas como
      // "argen pedro 98", "Argen.Pedro_98" y "argén.Pedro98" en el .xlsx matcheen
      // contra el username "argenpedro98" de la DB. Es estrictamente más tolerante
      // que $in + collation porque la collation no normaliza puntuación ni tildes.
      const escapeRegexLocal = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const prefixRegex = new RegExp('^' + escapeRegexLocal(prefix), 'i');

      // Safety: si el prefijo matchea > 50k users, abortar (algo está mal en config).
      const candidateCount = await User.countDocuments({ username: { $regex: prefixRegex } });
      if (candidateCount > 50000) {
        return res.status(400).json({
          error: `El prefijo "${prefix}" matchea ${candidateCount} usuarios (>50k). ¿Estás seguro? Achicalo más.`
        });
      }

      const candidateDocs = candidateCount > 0
        ? await User.find({ username: { $regex: prefixRegex } })
            .select('id username linePhone lineTeamName')
            .lean()
        : [];

      const docByNorm = new Map();
      for (const d of candidateDocs) {
        if (d && d.username) docByNorm.set(_normalizeUsername(d.username), d);
      }

      // -------- Pase 3: armar bulkOps y reporte por hoja.
      const bulkOps = [];
      const sheetReports = [];
      let totalMatched = 0;
      let totalNotFound = 0;
      const notFoundSample = []; // sólo guardamos los primeros 100 para no inflar la respuesta

      const now = new Date();
      const adminUsername = (req.user && req.user.username) || null;

      // Tracking global de las asignaciones para evitar duplicar bulkOps cuando
      // un mismo doc matchea varias celdas (en contains matching es común).
      const docAssignmentBySheet = new Map(); // docId → sheetName que lo reclamó

      for (const sd of sheetData) {
        let sheetMatched = 0;
        let sheetNotFound = 0;
        let sheetReassigned = 0; // ya tenían linePhone distinto → se sobreescribe

        for (const fullNorm of sd.usernamesNorm) {
          // CONTAINS matching bidireccional: matchea un User si:
          //   a) el username (normalizado) contiene la celda normalizada, O
          //   b) la celda normalizada contiene el username normalizado.
          // Esto permite que celdas con el username completo+anotaciones
          // ("argenpedro (líder)" → "argenpedrolider") matcheen contra
          // "argenpedro", y al revés que celdas con fragmentos cortos
          // ("pedro") matcheen contra "argenpedro".
          const matchedDocs = [];
          for (const [dbNorm, doc] of docByNorm) {
            if (!dbNorm) continue;
            if (dbNorm.includes(fullNorm) || fullNorm.includes(dbNorm)) {
              matchedDocs.push(doc);
            }
          }

          if (matchedDocs.length === 0) {
            sheetNotFound++;
            totalNotFound++;
            if (notFoundSample.length < 100) {
              const original = sd.originalByNorm.get(fullNorm) || fullNorm;
              notFoundSample.push({
                username: original,
                normalized: fullNorm,
                sheet: sd.sheetName
              });
            }
            continue;
          }

          sheetMatched++;
          totalMatched++;

          for (const doc of matchedDocs) {
            // En modo legacy multi-line: si este doc ya fue reclamado por otra
            // hoja, NO lo re-asignamos (preservamos el primero — comportamiento
            // determinista). En modo per-slot todas las hojas van al mismo
            // teléfono, no hay conflicto.
            if (!overrideLinePhone) {
              const prevSheet = docAssignmentBySheet.get(doc.id);
              if (prevSheet && prevSheet !== sd.sheetName) continue;
            }
            docAssignmentBySheet.set(doc.id, sd.sheetName);

            if (doc.linePhone && doc.linePhone !== sd.linePhone) {
              sheetReassigned++;
            }
            if (!dryRun) {
              bulkOps.push({
                updateOne: {
                  filter: { id: doc.id },
                  update: {
                    $set: {
                      linePhone: sd.linePhone,
                      lineTeamName: teamName,
                      lineAssignedAt: now,
                      lineAssignedBy: adminUsername
                    }
                  }
                }
              });
            }
          }
        }

        sheetReports.push({
          sheetName: sd.sheetName,
          linePhone: sd.linePhone,
          totalRows: sd.usernamesNorm.length,
          matched: sheetMatched,
          notFound: sheetNotFound,
          reassigned: sheetReassigned
        });
      }

      // -------- Escritura (solo si dryRun=false)
      // Dos bulkWrites en paralelo:
      //   1) User: asigna linePhone/lineTeamName a los usuarios YA existentes.
      //   2) UserLineLookup: persiste TODAS las celdas del .xlsx (matched o no)
      //      para que si después se crea un usuario nuevo (vía JUGAYGANA en
      //      su primer login) también se le asigne automáticamente la línea
      //      del archivo.
      let writeResult = null;
      let lookupResult = null;
      if (!dryRun) {
        const lookupOps = [];
        for (const sd of sheetData) {
          for (const fullNorm of sd.usernamesNorm) {
            lookupOps.push({
              updateOne: {
                filter: { usernameNorm: fullNorm },
                update: {
                  $set: {
                    usernameOriginal: sd.originalByNorm.get(fullNorm) || null,
                    linePhone: sd.linePhone,
                    lineTeamName: teamName,
                    prefix,
                    importedAt: now,
                    importedBy: adminUsername
                  },
                  $setOnInsert: { usernameNorm: fullNorm }
                },
                upsert: true
              }
            });
          }
        }

        const writePromises = [];
        if (bulkOps.length > 0) {
          writePromises.push(
            User.bulkWrite(bulkOps, { ordered: false }).then(r => {
              writeResult = { modifiedCount: r.modifiedCount || 0, matchedCount: r.matchedCount || 0 };
            })
          );
        }
        if (lookupOps.length > 0) {
          writePromises.push(
            UserLineLookup.bulkWrite(lookupOps, { ordered: false }).then(r => {
              lookupResult = {
                upsertedCount: r.upsertedCount || 0,
                modifiedCount: r.modifiedCount || 0
              };
            })
          );
        }
        try {
          await Promise.all(writePromises);
        } catch (bulkErr) {
          logger.error(`[user-lines/import] bulkWrite error: ${bulkErr.message}`);
          return res.status(500).json({ error: `Error escribiendo en la DB: ${bulkErr.message}` });
        }
      }

      logger.info(`[user-lines/import] team=${teamName} prefix=${prefix} dryRun=${dryRun} sheets=${sheetReports.length} matched=${totalMatched} notFound=${totalNotFound} conflicts=${conflictsInFile.length} by=${adminUsername}`);

      res.json({
        success: true,
        dryRun,
        teamName,
        prefix,
        summary: {
          totalSheets: sheetReports.length,
          totalRows: totalMatched + totalNotFound,
          matched: totalMatched,
          notFound: totalNotFound,
          conflicts: conflictsInFile.length
        },
        sheets: sheetReports,
        conflicts: conflictsInFile.slice(0, 100),
        notFoundSample,
        writeResult,
        lookupResult
      });
    } catch (error) {
      logger.error(`[user-lines/import] error: ${error.message}\n${error.stack}`);
      res.status(500).json({ error: `Error del servidor: ${error.message}` });
    }
  }
);

// =============================================================
// Import simple: 1 archivo = 1 línea, match EXACTO de username.
// =============================================================
// Pensado para listados que ya tienen el username completo en la primer
// columna (no fragmentos, no abreviaciones). Usa match exacto sobre el
// username normalizado (lowercase + sin acentos + sin puntuación). NO
// concatena prefijos ni hace contains-matching — eso evita los falsos
// positivos que tuvimos antes con archivos grandes.
//
// Inputs (query params):
//   teamName: nombre del equipo (label).
//   lineLabel: etiqueta amigable de la línea (opcional, ej "Principal", "Línea 2").
//   linePhone: teléfono WhatsApp en formato +5491... (canónico, con +).
//   dryRun: 'true' por default (solo cuenta), 'false' ejecuta.
// Body: archivo binario (.xlsx). Se lee la primera columna de la primera
// hoja con datos. Si la primera fila parece header (no contiene letras/dígitos
// pegados o es muy corta tipo "name"), se saltea.
//
// Comportamiento:
//   - Para cada nombre del archivo: busca User con username normalizado igual.
//     Si lo encuentra, le seta linePhone + lineTeamName.
//   - Siempre upsertea en UserLineLookup así si después de la importación
//     se crea un usuario nuevo con ese username (vía login a JUGAYGANA),
//     también recibe la línea automáticamente.
//   - Devuelve un reporte con matched / notFound + sample de los primeros 100
//     no-encontrados para que el admin pueda revisar typos.
app.post(
  '/api/admin/user-lines/import-exact',
  authMiddleware,
  adminMiddleware,
  express.raw({ limit: USER_LINES_IMPORT_LIMIT, type: '*/*' }),
  async (req, res) => {
    let XLSX;
    try {
      XLSX = require('xlsx');
    } catch (e) {
      return res.status(503).json({
        error: 'Falta instalar la dependencia "xlsx" en el servidor. Ejecutá: npm install xlsx'
      });
    }

    try {
      const teamName = (req.query.teamName ? String(req.query.teamName) : '').trim();
      if (!teamName) {
        return res.status(400).json({ error: 'Falta teamName' });
      }
      if (teamName.length > 32) {
        return res.status(400).json({ error: 'teamName demasiado largo (máx 32)' });
      }

      const lineLabel = (req.query.lineLabel ? String(req.query.lineLabel) : '').trim().slice(0, 32);
      // teamName + lineLabel se concatenan para mostrar al usuario "Equipo · Línea".
      const fullTeamLabel = lineLabel ? `${teamName} · ${lineLabel}` : teamName;

      const linePhoneRaw = (req.query.linePhone ? String(req.query.linePhone) : '').trim();
      if (!linePhoneRaw) {
        return res.status(400).json({ error: 'Falta linePhone (número de WhatsApp)' });
      }
      // Canonicalizar: solo dígitos, prefijar con + si no lo trae.
      const digits = linePhoneRaw.replace(/[^\d]/g, '');
      if (digits.length < 7 || digits.length > 18) {
        return res.status(400).json({ error: `linePhone inválido (${digits.length} dígitos)` });
      }
      const linePhone = '+' + digits;

      const dryRun = String(req.query.dryRun || 'true').toLowerCase() !== 'false';
      // Modo de import:
      //   'merge' (default, NO ROMPE lo que ya está): si un user ya tiene una
      //     línea asignada, lo dejamos como está. Sólo asignamos los que NO
      //     tienen línea o ya estaban en esta misma línea (re-confirma).
      //   'overwrite': fuerza la línea para todos los del archivo, incluso
      //     reasigna los que estaban en otro equipo.
      const importMode = String(req.query.mode || 'merge').toLowerCase() === 'overwrite' ? 'overwrite' : 'merge';

      const buf = req.body;
      if (!buf || !Buffer.isBuffer(buf) || buf.length < 50) {
        return res.status(400).json({ error: 'Archivo vacío o muy chico' });
      }

      let workbook;
      try {
        workbook = XLSX.read(buf, { type: 'buffer', cellDates: false });
      } catch (parseErr) {
        return res.status(400).json({ error: `No se pudo leer el .xlsx: ${parseErr.message}` });
      }
      if (!workbook.SheetNames || workbook.SheetNames.length === 0) {
        return res.status(400).json({ error: 'El archivo no tiene hojas' });
      }

      // Dos normalizaciones distintas:
      //   - normLight: para matchear contra User.username. Solo trim + lowercase,
      //     sin tocar acentos ni puntuación. El username en el archivo tiene
      //     que coincidir EXACTO con el username de JUGAYGANA / login (como
      //     entra el jugador a la plataforma a jugar).
      //   - normHeavy: la misma que usa el login (normalizeUsernameForLookup)
      //     para guardar en UserLineLookup.usernameNorm. Así un usuario nuevo
      //     que se registra después de la importación encuentra su línea
      //     mediante el helper pickLineFromLookup.
      const normLight = (raw) => {
        if (!raw) return '';
        return String(raw).trim().toLowerCase();
      };
      const normHeavy = (raw) => {
        if (!raw) return '';
        return String(raw)
          .normalize('NFD').replace(/[̀-ͯ]/g, '')
          .toLowerCase()
          .replace(/[^a-z0-9]/g, '');
      };

      // Recolectar usernames del archivo (primera columna de la primera hoja
      // con datos). Saltea header si la primera fila parece una etiqueta
      // ("name", "username", "usuario", etc).
      // Estructura: Map<normLight, { original, normHeavy }> — guardamos ambas
      // normalizaciones para usar la light en el match con User (estricto) y
      // la heavy en el upsert a UserLineLookup (consistente con el login).
      const entries = new Map();
      let totalRowsRead = 0;

      for (const sheetName of workbook.SheetNames) {
        const ws = workbook.Sheets[sheetName];
        if (!ws) continue;
        const rows = XLSX.utils.sheet_to_json(ws, { header: 1, blankrows: false, defval: '' });
        if (rows.length === 0) continue;

        // Saltar primera fila si parece header.
        const firstCell = String((rows[0] && rows[0][0]) || '').trim().toLowerCase();
        const isHeader = ['name', 'username', 'usuario', 'nombre', 'user'].includes(firstCell);
        const dataRows = isHeader ? rows.slice(1) : rows;

        for (const row of dataRows) {
          if (!row) continue;
          const raw = row[0];
          if (raw === null || raw === undefined) continue;
          const cleaned = String(raw).trim();
          if (!cleaned) continue;
          totalRowsRead++;
          const lite = normLight(cleaned);
          if (!lite) continue;
          if (!entries.has(lite)) {
            entries.set(lite, { original: cleaned, normHeavy: normHeavy(cleaned) });
          }
        }
        // Solo leemos la primera hoja con datos — el contrato es 1 archivo = 1 línea.
        if (entries.size > 0) break;
      }

      if (entries.size === 0) {
        return res.status(400).json({ error: 'El archivo no tiene usernames legibles en la primera columna' });
      }

      // Lookup en DB: traemos todos los usernames y normalizamos en memoria
      // con la misma función light. Match es 1:1 con la versión lowercased
      // del username — exacto como entra el jugador a JUGAYGANA / login.
      const allUsernames = await User.find(
        { username: { $exists: true, $ne: null } },
        { id: 1, username: 1, linePhone: 1, lineTeamName: 1, _id: 0 }
      ).lean();

      const liteToDoc = new Map();
      for (const d of allUsernames) {
        if (!d || !d.username) continue;
        const lite = normLight(d.username);
        if (lite) liteToDoc.set(lite, d);
      }

      let matched = 0;
      let alreadyOnSameLine = 0;
      let reassignedFromOtherLine = 0;
      let keptUntouchedOtherLine = 0; // merge mode: ya asignados a otra línea
      const notFoundSample = [];
      const bulkOps = [];

      const now = new Date();
      const adminUsername = (req.user && req.user.username) || null;

      for (const [lite, info] of entries) {
        const doc = liteToDoc.get(lite);
        if (!doc) {
          if (notFoundSample.length < 100) {
            notFoundSample.push({
              username: info.original,
              normalized: lite
            });
          }
          continue;
        }
        matched++;
        if (doc.linePhone === linePhone) {
          alreadyOnSameLine++;
          // Si está en la misma línea, lo "tocamos" igual para refrescar
          // lineAssignedAt/By (sirve como ack de la nueva carga).
          if (!dryRun) {
            bulkOps.push({
              updateOne: {
                filter: { id: doc.id },
                update: {
                  $set: {
                    linePhone,
                    lineTeamName: fullTeamLabel,
                    lineAssignedAt: now,
                    lineAssignedBy: adminUsername,
                    lineAssignmentSource: 'drive-import',
                    lineAssignmentNote: 'Cargado desde xlsx (' + (importMode === 'overwrite' ? 'ordenar' : 'merge') + ')'
                  }
                }
              }
            });
          }
          continue;
        }
        if (doc.linePhone) {
          // Ya tiene OTRA línea asignada.
          if (importMode === 'merge') {
            // Merge: NO TOCAR. Lo dejamos como está.
            keptUntouchedOtherLine++;
            continue;
          }
          // Overwrite: lo movemos a esta línea.
          reassignedFromOtherLine++;
        }
        if (!dryRun) {
          bulkOps.push({
            updateOne: {
              filter: { id: doc.id },
              update: {
                $set: {
                  linePhone,
                  lineTeamName: fullTeamLabel,
                  lineAssignedAt: now,
                  lineAssignedBy: adminUsername,
                  lineAssignmentSource: 'drive-import',
                  lineAssignmentNote: 'Cargado desde xlsx (' + (importMode === 'overwrite' ? 'ordenar' : 'merge') + ')'
                }
              }
            }
          });
        }
      }

      // UserLineLookup: en MERGE no pisamos entradas que ya apunten a otra
      // línea — solo upserteamos cuando no existe O cuando ya estaba en esta
      // misma línea. En OVERWRITE se actualiza siempre.
      const lookupOps = [];
      if (!dryRun) {
        for (const [lite, info] of entries) {
          if (!info.normHeavy) continue; // sin caracteres alfanuméricos: no se puede indexar
          if (importMode === 'merge') {
            const filter = {
              usernameNorm: info.normHeavy,
              $or: [
                { linePhone: { $exists: false } },
                { linePhone: null },
                { linePhone: '' },
                { linePhone: linePhone }
              ]
            };
            lookupOps.push({
              updateOne: {
                filter,
                update: {
                  $set: {
                    usernameOriginal: info.original,
                    linePhone,
                    lineTeamName: fullTeamLabel,
                    prefix: '',
                    importedAt: now,
                    importedBy: adminUsername
                  },
                  $setOnInsert: { usernameNorm: info.normHeavy }
                },
                upsert: true
              }
            });
          } else {
            // overwrite: pisar sí o sí.
            lookupOps.push({
              updateOne: {
                filter: { usernameNorm: info.normHeavy },
                update: {
                  $set: {
                    usernameOriginal: info.original,
                    linePhone,
                    lineTeamName: fullTeamLabel,
                    prefix: '',
                    importedAt: now,
                    importedBy: adminUsername
                  },
                  $setOnInsert: { usernameNorm: info.normHeavy }
                },
                upsert: true
              }
            });
          }
        }
      }

      let writeResult = null;
      let lookupResult = null;
      if (!dryRun) {
        try {
          if (bulkOps.length > 0) {
            const r = await User.bulkWrite(bulkOps, { ordered: false });
            writeResult = { modifiedCount: r.modifiedCount || 0, matchedCount: r.matchedCount || 0 };
          }
          if (lookupOps.length > 0) {
            const r2 = await UserLineLookup.bulkWrite(lookupOps, { ordered: false });
            lookupResult = {
              upsertedCount: r2.upsertedCount || 0,
              modifiedCount: r2.modifiedCount || 0
            };
          }
        } catch (bulkErr) {
          logger.error(`[user-lines/import-exact] bulkWrite error: ${bulkErr.message}`);
          return res.status(500).json({ error: `Error escribiendo en la DB: ${bulkErr.message}` });
        }
      }

      logger.info(`[user-lines/import-exact] team="${fullTeamLabel}" phone=${linePhone} mode=${importMode} dryRun=${dryRun} rows=${totalRowsRead} unique=${entries.size} matched=${matched} notFound=${entries.size - matched} keptUntouched=${keptUntouchedOtherLine} reassigned=${reassignedFromOtherLine} by=${adminUsername}`);

      res.json({
        success: true,
        dryRun,
        mode: importMode,
        teamName: fullTeamLabel,
        linePhone,
        summary: {
          totalRowsRead,
          uniqueUsernames: entries.size,
          matched,
          notFound: entries.size - matched,
          alreadyOnSameLine,
          reassignedFromOtherLine,
          keptUntouchedOtherLine
        },
        notFoundSample,
        writeResult,
        lookupResult
      });
    } catch (error) {
      logger.error(`[user-lines/import-exact] error: ${error.message}\n${error.stack}`);
      res.status(500).json({ error: `Error del servidor: ${error.message}` });
    }
  }
);

// Endpoint para limpiar la asignación de línea de TODOS los usuarios de un team
// (vuelve a usar el matcher por prefijo). Útil si se cargó un Drive equivocado.
// POST /api/admin/user-lines/reassign-orphans
// Backfill: para todos los users SIN linePhone, intenta asignar línea
// por matcheo de prefijo del username. Si el prefijo no matchea ningún
// slot del config 'userLinesByPrefix', cae a la línea general.
//
// dryRun=true (default) → no escribe, solo cuenta. Pasa dryRun=false
// en el body para ejecutar.
//
// Marca cada asignación con lineAssignmentSource='prefix-fallback' o
// 'general-default' según corresponda + lineAssignmentNote con la
// explicación humana ("argen → Argen 1 (+5491...)").
app.post('/api/admin/user-lines/reassign-orphans', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const dryRun = req.body && req.body.dryRun !== false; // default true
    // Modo destructivo (dryRun=false) → solo admin principal.
    if (!dryRun && req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Solo el admin principal puede aplicar reasignación masiva. Para preview, sí podés.' });
    }
    const linesConfig = await getConfig('userLinesByPrefix');
    if (!linesConfig) {
      return res.status(400).json({ error: 'No hay config de líneas (userLinesByPrefix). Configurá primero "Números vigentes".' });
    }

    // Encontrar huérfanos: users con role='user' y sin linePhone.
    // Limit alto pero acotado para evitar OOM en bases enormes.
    const orphans = await User.find(
      {
        role: 'user',
        $or: [{ linePhone: null }, { linePhone: '' }, { linePhone: { $exists: false } }]
      },
      { id: 1, username: 1, _id: 0 }
    ).limit(50000).lean();

    const adminUsername = req.user.username || 'admin';
    const now = new Date();

    // Computar resoluciones primero (sin escribir).
    const plan = []; // [{userId, username, resolved}]
    const breakdown = {
      total: orphans.length,
      matchedPrefix: 0,
      fellToDefault: 0,
      noResolution: 0,
      byTeam: {}
    };
    for (const u of orphans) {
      const r = resolveLineByPrefixFallback(linesConfig, u.username);
      if (!r) {
        breakdown.noResolution++;
        continue;
      }
      if (r.source === 'prefix-fallback') breakdown.matchedPrefix++;
      else if (r.source === 'general-default') breakdown.fellToDefault++;
      const teamKey = r.lineTeamName || '— Sin equipo —';
      breakdown.byTeam[teamKey] = (breakdown.byTeam[teamKey] || 0) + 1;
      plan.push({ userId: u.id, username: u.username, resolved: r });
    }

    if (dryRun) {
      // Devolvemos solo el resumen para que el admin confirme.
      return res.json({
        success: true,
        dryRun: true,
        summary: breakdown,
        sampleAssignments: plan.slice(0, 20).map(p => ({
          username: p.username,
          linePhone: p.resolved.linePhone,
          lineTeamName: p.resolved.lineTeamName,
          source: p.resolved.source,
          note: p.resolved.note
        }))
      });
    }

    // Ejecutar bulkWrite.
    if (plan.length === 0) {
      return res.json({ success: true, dryRun: false, summary: breakdown, applied: 0 });
    }

    const ops = plan.map(p => ({
      updateOne: {
        filter: { id: p.userId },
        update: {
          $set: {
            linePhone: p.resolved.linePhone,
            lineTeamName: p.resolved.lineTeamName,
            lineAssignedAt: now,
            lineAssignedBy: adminUsername + ':reassign-orphans',
            lineAssignmentSource: p.resolved.source,
            lineAssignmentNote: p.resolved.note
          }
        }
      }
    }));

    // bulkWrite en chunks para no estresar Mongo.
    let applied = 0;
    const CHUNK = 500;
    for (let i = 0; i < ops.length; i += CHUNK) {
      const slice = ops.slice(i, i + CHUNK);
      const r = await User.bulkWrite(slice, { ordered: false });
      applied += r.modifiedCount || 0;
    }

    logger.info(`[reassign-orphans] aplicado: ${applied}/${plan.length} (matched=${breakdown.matchedPrefix}, default=${breakdown.fellToDefault}, sin-resolución=${breakdown.noResolution})`);
    res.json({
      success: true,
      dryRun: false,
      summary: breakdown,
      applied
    });
  } catch (err) {
    logger.error(`POST reassign-orphans: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// Estadísticas de actividad por línea: clasifica los users de UNA línea
// (xlsx + auto-asignados) en buckets según días desde la última carga real
// (PlayerStats.lastRealDepositDate). Buckets:
//   🔥 calientes  : 0-10 días
//   ⚠ en riesgo  : 10-20 días
//   💔 perdidos   : 20-30 días
//   ☠ inactivos  : +30 días o nunca cargó
app.get('/api/admin/user-lines/line-activity-stats', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const teamName = String(req.query.teamName || '').trim();
    const linePhone = String(req.query.linePhone || '').trim();
    if (!teamName && !linePhone) {
      return res.status(400).json({ error: 'Faltan params teamName o linePhone' });
    }

    // 1) Junto la lista de usernames únicos: UserLineLookup (xlsx) + User asignados.
    const lookupFilter = {};
    if (teamName) lookupFilter.lineTeamName = teamName;
    if (linePhone) lookupFilter.linePhone = linePhone;
    const lookupRows = await UserLineLookup.find(lookupFilter, { usernameNorm: 1, usernameOriginal: 1, _id: 0 }).lean();

    const userFilter = {};
    if (teamName) userFilter.lineTeamName = teamName;
    if (linePhone) userFilter.linePhone = linePhone;
    const userRows = await User.find(userFilter, { username: 1, lastLogin: 1, fcmToken: 1, fcmTokens: 1, _id: 0 }).lean();

    // Set de usernames únicos (lowercase para match con PlayerStats).
    const allUsernames = new Set();
    const meta = new Map(); // username -> { fromXlsx, hasUser, hasApp, lastLogin, displayName }
    for (const r of lookupRows) {
      const k = String(r.usernameNorm || '').toLowerCase();
      if (!k) continue;
      allUsernames.add(k);
      meta.set(k, {
        fromXlsx: true,
        hasUser: false,
        hasApp: false,
        lastLogin: null,
        displayName: r.usernameOriginal || r.usernameNorm
      });
    }
    for (const u of userRows) {
      const k = String(u.username || '').toLowerCase();
      if (!k) continue;
      allUsernames.add(k);
      const hasApp = !!(u.fcmToken || (Array.isArray(u.fcmTokens) && u.fcmTokens.length > 0));
      const cur = meta.get(k) || { fromXlsx: false, displayName: u.username };
      cur.hasUser = true;
      cur.hasApp = hasApp;
      cur.lastLogin = u.lastLogin || null;
      meta.set(k, cur);
    }

    // 2) PlayerStats para cada uno.
    const usernamesArr = Array.from(allUsernames);
    const stats = usernamesArr.length > 0
      ? await PlayerStats.find(
          { username: { $in: usernamesArr } },
          { username: 1, lastRealDepositDate: 1, realDeposits30d: 1, _id: 0 }
        ).lean()
      : [];
    const statsMap = new Map(stats.map(s => [String(s.username || '').toLowerCase(), s]));

    // 3) Bucketize.
    const now = Date.now();
    const DAY = 24 * 60 * 60 * 1000;
    const buckets = {
      calientes:  { label: '🔥 Calientes (0-10 días)',  rangeMin: 0,  rangeMax: 10,    items: [] },
      enRiesgo:   { label: '⚠ En riesgo (10-20 días)',  rangeMin: 10, rangeMax: 20,    items: [] },
      perdidos:   { label: '💔 Perdidos (20-30 días)',  rangeMin: 20, rangeMax: 30,    items: [] },
      inactivos:  { label: '☠ Inactivos (+30 días)',    rangeMin: 30, rangeMax: 99999, items: [] }
    };
    let neverDeposited = 0;
    let totalDeposit30d = 0;

    for (const username of usernamesArr) {
      const m = meta.get(username) || { displayName: username };
      const s = statsMap.get(username);
      const lastDep = s && s.lastRealDepositDate ? new Date(s.lastRealDepositDate).getTime() : null;
      let bucket = 'inactivos';
      let daysSince = null;
      if (lastDep) {
        daysSince = Math.floor((now - lastDep) / DAY);
        if (daysSince <= 10) bucket = 'calientes';
        else if (daysSince <= 20) bucket = 'enRiesgo';
        else if (daysSince <= 30) bucket = 'perdidos';
        else bucket = 'inactivos';
      } else {
        neverDeposited++;
      }
      const item = {
        username: m.displayName || username,
        daysSince,
        lastDepositAt: lastDep ? new Date(lastDep) : null,
        deposits30d: (s && s.realDeposits30d) || 0,
        hasApp: !!m.hasApp,
        registered: !!m.hasUser,
        fromXlsx: !!m.fromXlsx
      };
      buckets[bucket].items.push(item);
      totalDeposit30d += item.deposits30d || 0;
    }

    // Ordenar items dentro de cada bucket: más recientes primero (calientes), más viejos primero (resto).
    for (const k of Object.keys(buckets)) {
      buckets[k].items.sort((a, b) => {
        const ta = a.lastDepositAt ? a.lastDepositAt.getTime() : 0;
        const tb = b.lastDepositAt ? b.lastDepositAt.getTime() : 0;
        return tb - ta;
      });
    }

    res.json({
      teamName: teamName || null,
      linePhone: linePhone || null,
      totalUsers: usernamesArr.length,
      neverDeposited,
      totalDeposit30d,
      buckets: {
        calientes:  { label: buckets.calientes.label,  count: buckets.calientes.items.length,  items: buckets.calientes.items.slice(0, 200) },
        enRiesgo:   { label: buckets.enRiesgo.label,   count: buckets.enRiesgo.items.length,   items: buckets.enRiesgo.items.slice(0, 200) },
        perdidos:   { label: buckets.perdidos.label,   count: buckets.perdidos.items.length,   items: buckets.perdidos.items.slice(0, 200) },
        inactivos:  { label: buckets.inactivos.label,  count: buckets.inactivos.items.length,  items: buckets.inactivos.items.slice(0, 200) }
      }
    });
  } catch (err) {
    logger.error(`/api/admin/user-lines/line-activity-stats: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// =====================================================================
// RECONTACTACIÓN — análisis de una lista cargada por el admin para armar
// estrategia de recuperación de clientes inactivos.
//
// Recibe un .xlsx con usernames (una columna). Para cada uno:
//   - Cruza con User (linePhone, fcmToken, fcmTokens, notifPermission, phone)
//   - Cruza con PlayerStats (tier, lastRealDepositDate, realDeposits30d, totalDeposits)
//   - Clasifica en bucket (calientes/en riesgo/perdidos/inactivos)
//   - Sugiere estrategia + monto de bono según matriz tier × bucket
//   - Marca si tiene app+notifs (target push) o no (target WhatsApp)
//
// Devuelve dashboard completo + items enriquecidos para tabla y CSV.
// =====================================================================
const RECONTACT_STRATEGY_MATRIX = {
  VIP: {
    calientes: { strat: 'mantener-engagement',  bonus: 5000,  msg: 'Seguís activo. Bono cortesía VIP de $X para tu próxima carga.' },
    enRiesgo:  { strat: 'bono-personalizado',   bonus: 8000,  msg: 'Hace unos días no te vemos. Bono de $X esperándote — VIP no se pierde.' },
    perdidos:  { strat: 'bono-fuerte-vip',      bonus: 15000, msg: 'Volvé hoy: bono PREMIUM de $X + atención prioritaria.' },
    inactivos: { strat: '🚨 ALERTA ROJA',       bonus: 30000, msg: 'Bono ESPECIAL VIP de $X + mensaje del dueño + acceso prioritario.' }
  },
  ORO: {
    calientes: { strat: 'cortesía-oro',         bonus: 2000,  msg: 'Bono ORO de $X de regalo.' },
    enRiesgo:  { strat: 'bono-mediano',         bonus: 4000,  msg: 'Volvé y tenés $X de bono + 50% extra en cargas.' },
    perdidos:  { strat: 'bono-grande',          bonus: 7000,  msg: 'Te extrañamos! $X de bono + 100% en tu próxima carga.' },
    inactivos: { strat: 'bono-recuperacion',    bonus: 12000, msg: 'Bono de regreso ORO: $X + WhatsApp directo del equipo.' }
  },
  PLATA: {
    calientes: { strat: 'cortesía-plata',       bonus: 1000,  msg: '$X de cortesía para que sigas tirando.' },
    enRiesgo:  { strat: 'reactivar',            bonus: 2000,  msg: 'Bono $X — no te pierdas.' },
    perdidos:  { strat: 'bono-mediano',         bonus: 3500,  msg: 'Vení por tu bono de $X.' },
    inactivos: { strat: 'bono-recuperacion',    bonus: 5000,  msg: 'Bono recuperación PLATA: $X esperándote.' }
  },
  BRONCE: {
    calientes: { strat: 'cortesía-bronce',      bonus: 500,   msg: '$X de bono de regreso.' },
    enRiesgo:  { strat: 'subir-ticket',         bonus: 1000,  msg: 'Cargá $10k y te damos $X extra.' },
    perdidos:  { strat: 'bono-minimo',          bonus: 1500,  msg: 'Bono $X mínimo de bienvenida de regreso.' },
    inactivos: { strat: 'bono-recuperacion',    bonus: 2500,  msg: 'Bono $X — última invitación.' }
  },
  NUEVO: {
    calientes: { strat: 'onboarding',           bonus: 1000,  msg: 'Bienvenido! Cargá y te damos $X de bono.' },
    enRiesgo:  { strat: 'onboarding-suave',     bonus: 2000,  msg: 'No te conocemos todavía. Bono $X cuando arrancás.' },
    perdidos:  { strat: 'onboarding-fuerte',    bonus: 3000,  msg: 'Bono $X especial para que te animes.' },
    inactivos: { strat: 'last-chance',          bonus: 5000,  msg: 'Última oportunidad: $X de regalo + 50% en primera carga.' }
  },
  SIN_DATOS: {
    calientes: { strat: 'datos-faltantes',      bonus: 1000,  msg: 'Bono cortesía $X.' },
    enRiesgo:  { strat: 'datos-faltantes',      bonus: 1500,  msg: 'Bono $X de reactivación.' },
    perdidos:  { strat: 'datos-faltantes',      bonus: 2000,  msg: 'Bono $X.' },
    inactivos: { strat: 'datos-faltantes',      bonus: 3000,  msg: 'Bono recuperación $X.' }
  }
};

function _recontactSuggest(tier, bucket, hasApp, hasNotifs) {
  const tierKey = (tier || 'SIN_DATOS').toUpperCase();
  const m = (RECONTACT_STRATEGY_MATRIX[tierKey] || RECONTACT_STRATEGY_MATRIX.SIN_DATOS)[bucket] ||
            RECONTACT_STRATEGY_MATRIX.SIN_DATOS.inactivos;
  const parts = [];
  parts.push(m.msg.replace('$X', '$' + Number(m.bonus).toLocaleString('es-AR')));
  if (!hasApp) parts.push('+ Instalá la app y te damos $2.000 extra de bono.');
  else if (!hasNotifs) parts.push('+ Activá las notificaciones para no perderte regalos.');
  return {
    strategy: m.strat,
    bonus: m.bonus,
    message: parts.join(' '),
    addAppOffer: !hasApp,
    addNotifsOffer: hasApp && !hasNotifs
  };
}

// Prioridad: combinación de tier weight + bucket weight (para ordenar lista)
function _recontactPriority(tier, bucket, lastDeposits30d) {
  const tw = { VIP: 100, ORO: 70, PLATA: 40, BRONCE: 20, NUEVO: 30, SIN_DATOS: 10 }[(tier || 'SIN_DATOS').toUpperCase()] || 10;
  const bw = { calientes: 0.3, enRiesgo: 0.7, perdidos: 1.0, inactivos: 0.8 }[bucket] || 0.5;
  return Math.round(tw * bw + (lastDeposits30d || 0) / 1000);
}

// Hace el cruce contra User+PlayerStats y arma la respuesta enriquecida
// a partir de un array ya pre-agregado en el cliente (admin v2).
async function _recontactAnalyzeFromJSON(req, res) {
  try {
    const body = req.body || {};
    const usersIn = Array.isArray(body.users) ? body.users : null;
    if (!usersIn || usersIn.length === 0) {
      return res.status(400).json({ error: 'Payload vacío (no hay users)' });
    }
    if (usersIn.length > 50000) {
      return res.status(413).json({ error: `Demasiados usernames (${usersIn.length}, máx 50.000)` });
    }

    const fileAgg = new Map();
    const inputUsernames = [];
    const seen = new Set();
    for (const u of usersIn) {
      const orig = String(u && u.username != null ? u.username : '').trim();
      if (!orig) continue;
      const norm = orig.toLowerCase().replace(/[^a-z0-9]/g, '');
      if (!norm || seen.has(norm)) continue;
      seen.add(norm);
      inputUsernames.push({ original: orig, norm });
      fileAgg.set(norm, {
        original: orig,
        sumDeposits:   Number(u.sumDeposits)   || 0,
        sumWithdraws:  Number(u.sumWithdraws)  || 0,
        sumBonuses:    Number(u.sumBonuses)    || 0,
        countDeposits: Number(u.countDeposits) || 0,
        countWithdraws:Number(u.countWithdraws)|| 0,
        countBonuses:  Number(u.countBonuses)  || 0
      });
    }

    if (inputUsernames.length === 0) {
      return res.status(400).json({ error: 'No se encontraron usernames válidos' });
    }

    const norms = inputUsernames.map(x => x.norm);
    const normsSet = new Set(norms);
    // Helper: normaliza igual que `inp.norm` (lowercase + solo alfanuméricos).
    // User.username y PlayerStats.username NO se guardan en esta forma
    // (User preserva mayúsculas y caracteres como `_` `.` `-`; PlayerStats
    // lowercaseiza pero preserva caracteres especiales). Por eso el $in
    // directo se perdía a todos esos usuarios — se hace el match en JS.
    const _normUname = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

    const [allUsers, allStats, lookups] = await Promise.all([
      User.find(
        {},
        { username: 1, phone: 1, fcmToken: 1, fcmTokens: 1, fcmTokenContext: 1, notifPermission: 1, lineTeamName: 1, linePhone: 1, lastLogin: 1, _id: 0 }
      ).lean(),
      PlayerStats.find(
        {},
        { username: 1, tier: 1, activityStatus: 1, lastRealDepositDate: 1, realDeposits30d: 1, realDeposits90d: 1, totalRealDeposits: 1, _id: 0 }
      ).lean(),
      // Pre-asignaciones de equipos cargadas por xlsx — resuelve línea
      // incluso para users que no están registrados o que tienen User
      // sin lineTeamName/linePhone seteados. Esta colección sí tiene
      // `usernameNorm` ya en la forma normalizada → $in funciona OK.
      UserLineLookup.find(
        { usernameNorm: { $in: norms } },
        { usernameNorm: 1, lineTeamName: 1, linePhone: 1, _id: 0 }
      ).lean()
    ]);
    const userMap = new Map();
    for (const u of allUsers) {
      const n = _normUname(u.username);
      if (n && normsSet.has(n)) userMap.set(n, u);
    }
    const statsMap = new Map();
    for (const s of allStats) {
      const n = _normUname(s.username);
      if (n && normsSet.has(n)) statsMap.set(n, s);
    }
    const lookupMap = new Map(lookups.map(l => [String(l.usernameNorm || '').toLowerCase(), l]));

    const now = Date.now();
    const DAY = 24 * 60 * 60 * 1000;
    const items = [];
    const summary = {
      totalAnalyzed: inputUsernames.length,
      foundInDb: 0, notFound: 0,
      withApp: 0, withoutApp: 0,
      withNotifs: 0, withoutNotifs: 0,
      buckets: { calientes: 0, enRiesgo: 0, perdidos: 0, inactivos: 0 },
      tiers: { VIP: 0, ORO: 0, PLATA: 0, BRONCE: 0, NUEVO: 0, SIN_DATOS: 0 },
      totalRecoverableValue: 0,
      sumDeposits30d: 0, sumDeposits90d: 0, sumTotalDeposits: 0,
      fileTotalDeposits: 0, fileTotalWithdraws: 0, fileTotalBonuses: 0,
      fileCountDeposits: 0, fileCountWithdraws: 0, fileCountBonuses: 0
    };

    for (const inp of inputUsernames) {
      const u = userMap.get(inp.norm);
      const s = statsMap.get(inp.norm);
      if (u) summary.foundInDb++; else summary.notFound++;

      // Mismo criterio que el reporte de Bono $5.000 app:
      // hasApp = token con context=standalone (PWA real instalada).
      // hasNotifs = al menos un token con notifPermission=granted.
      const tokens = (u && Array.isArray(u.fcmTokens)) ? u.fcmTokens : [];
      const standaloneTokens = tokens.filter(t => t && t.context === 'standalone');
      const hasApp = !!u && (
        u.fcmTokenContext === 'standalone' ||
        standaloneTokens.length > 0
      );
      const hasNotifs = !!u && (
        u.notifPermission === 'granted' ||
        tokens.some(t => t && t.notifPermission === 'granted')
      );
      if (hasApp) summary.withApp++; else summary.withoutApp++;
      if (hasNotifs) summary.withNotifs++; else summary.withoutNotifs++;

      const lastDep = s && s.lastRealDepositDate ? new Date(s.lastRealDepositDate).getTime() : null;
      let bucket = 'inactivos';
      let daysSince = null;
      if (lastDep) {
        daysSince = Math.floor((now - lastDep) / DAY);
        if (daysSince <= 10) bucket = 'calientes';
        else if (daysSince <= 20) bucket = 'enRiesgo';
        else if (daysSince <= 30) bucket = 'perdidos';
        else bucket = 'inactivos';
      }
      summary.buckets[bucket]++;

      const tier = (s && s.tier) ? String(s.tier).toUpperCase() : 'SIN_DATOS';
      if (summary.tiers[tier] != null) summary.tiers[tier]++;
      else summary.tiers.SIN_DATOS++;

      const sugg = _recontactSuggest(tier, bucket, hasApp, hasNotifs);
      const priority = _recontactPriority(tier, bucket, s && s.realDeposits30d);
      summary.totalRecoverableValue += sugg.bonus;
      summary.sumDeposits30d += (s && s.realDeposits30d) || 0;
      summary.sumDeposits90d += (s && s.realDeposits90d) || 0;
      summary.sumTotalDeposits += (s && s.totalRealDeposits) || 0;

      const fa = fileAgg.get(inp.norm);
      summary.fileTotalDeposits  += fa.sumDeposits;
      summary.fileTotalWithdraws += fa.sumWithdraws;
      summary.fileTotalBonuses   += fa.sumBonuses;
      summary.fileCountDeposits  += fa.countDeposits;
      summary.fileCountWithdraws += fa.countWithdraws;
      summary.fileCountBonuses   += fa.countBonuses;

      const ll = lookupMap.get(inp.norm);
      const team = (u && u.lineTeamName) || (ll && ll.lineTeamName) || null;
      const linePhone = (u && u.linePhone) || (ll && ll.linePhone) || null;
      items.push({
        username: inp.original,
        tier, bucket,
        daysSinceLastDeposit: daysSince,
        lastDepositAt: lastDep ? new Date(lastDep).toISOString() : null,
        deposits30d: (s && s.realDeposits30d) || 0,
        deposits90d: (s && s.realDeposits90d) || 0,
        totalDeposits: (s && s.totalRealDeposits) || 0,
        team,
        linePhone,
        phone: u ? (u.phone || null) : null,
        hasApp, hasNotifs,
        registered: !!u,
        strategy: sugg.strategy,
        suggestedBonus: sugg.bonus,
        suggestedMessage: sugg.message,
        addAppOffer: sugg.addAppOffer,
        addNotifsOffer: sugg.addNotifsOffer,
        priority,
        fileDeposits: fa.sumDeposits,
        fileWithdraws: fa.sumWithdraws,
        fileBonuses: fa.sumBonuses,
        fileCountDeposits: fa.countDeposits,
        fileCountWithdraws: fa.countWithdraws,
        fileCountBonuses: fa.countBonuses,
        fileNet: fa.sumDeposits - fa.sumWithdraws
      });
    }

    items.sort((a, b) => b.priority - a.priority);
    logger.info(`[recontact/analyze v2] analyzed=${summary.totalAnalyzed} found=${summary.foundInDb} byBucket=${JSON.stringify(summary.buckets)} byTier=${JSON.stringify(summary.tiers)} by=${(req.user && req.user.username) || 'admin'}`);
    return res.json({ success: true, summary, items });
  } catch (err) {
    logger.error(`[recontact/analyze v2] error: ${err.message}\n${err.stack}`);
    return res.status(500).json({ error: err.message });
  }
}

// Helper: arma express middleware que parsea raw o JSON según content-type.
// El cliente moderno (admin v2) parsea el .xlsx en el browser y manda JSON
// pre-agregado — evita timeouts/502 con archivos grandes. El raw legacy
// queda como fallback por si alguien sube un archivo del modo viejo.
const _recontactBodyParser = (req, res, next) => {
  const ct = (req.headers['content-type'] || '').toLowerCase();
  if (ct.includes('application/json')) {
    return express.json({ limit: '20mb' })(req, res, next);
  }
  return express.raw({ limit: '25mb', type: '*/*' })(req, res, next);
};

app.post(
  '/api/admin/recontact/analyze',
  authMiddleware,
  adminMiddleware,
  _recontactBodyParser,
  async (req, res) => {
    try {
      const ct = (req.headers['content-type'] || '').toLowerCase();
      logger.info(`[recontact/analyze] received contentType=${ct} contentLength=${req.headers['content-length']}`);

      // Modo NUEVO: el cliente ya parseó el .xlsx en el browser y manda JSON
      // pre-agregado: { version: 2, users: [{ username, sumDeposits, ... }], totalRows }.
      if (ct.includes('application/json')) {
        return _recontactAnalyzeFromJSON(req, res);
      }

      // Modo LEGACY: raw .xlsx (queda como fallback para clientes viejos).
      let XLSX;
      try { XLSX = require('xlsx'); }
      catch (_) { return res.status(503).json({ error: 'Falta dependencia "xlsx"' }); }

      const buf = req.body;
      logger.info(`[recontact/analyze legacy] bufType=${typeof buf} isBuffer=${Buffer.isBuffer(buf)} length=${buf && buf.length ? buf.length : 0}`);
      if (!buf || !Buffer.isBuffer(buf) || buf.length < 50) {
        return res.status(400).json({ error: `Archivo vacío o muy chico (recibido ${buf && buf.length ? buf.length : 0} bytes). Probá subir el archivo de nuevo.` });
      }
      let workbook;
      try { workbook = XLSX.read(buf, { type: 'buffer', cellDates: false }); }
      catch (e) { return res.status(400).json({ error: `No se pudo leer el .xlsx: ${e.message}` }); }

      // Sacar usernames únicos del workbook (recorre todas las hojas, primera columna).
      // Detectar columnas (Type / Amount / User) por header. Si no hay header
      // claro se cae a "primera columna = username" (legacy).
      // Soporta archivos con filas transaccionales — agrega depósitos /
      // retiros / bonos por usuario.
      const HEADER_TYPE = new Set(['type', 'tipo', 'movimiento']);
      const HEADER_AMOUNT = new Set(['amount', 'monto', 'cantidad', 'importe']);
      const HEADER_USER = new Set(['user', 'username', 'usuario']);
      const TYPE_DEPOSIT = new Set(['deposit', 'deposito', 'depósito', 'carga']);
      const TYPE_WITHDRAW = new Set(['withdraw', 'withdrawal', 'retiro', 'extraccion', 'extracción']);
      const TYPE_BONUS = new Set(['individual_bonus', 'bonus', 'bonificacion', 'bonificación', 'bono']);

      const fileAgg = new Map(); // norm -> { original, sumDeposits, sumWithdraws, sumBonuses, countDeposits, countWithdraws, countBonuses }
      const seen = new Set();
      const inputUsernames = [];

      for (const sheetName of workbook.SheetNames) {
        const sheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, blankrows: false, defval: null });
        if (!rows || rows.length === 0) continue;

        // Detectar columnas a partir de la primera fila.
        let colType = -1, colAmount = -1, colUser = -1;
        const firstRow = Array.isArray(rows[0]) ? rows[0] : [];
        for (let i = 0; i < firstRow.length; i++) {
          const h = String(firstRow[i] == null ? '' : firstRow[i]).trim().toLowerCase();
          if (HEADER_TYPE.has(h)) colType = i;
          else if (HEADER_AMOUNT.has(h)) colAmount = i;
          else if (HEADER_USER.has(h)) colUser = i;
        }
        const hasHeader = (colUser !== -1) || (colType !== -1) || (colAmount !== -1);
        const userColIdx = (colUser !== -1) ? colUser : 0; // fallback: primera columna

        const startRow = hasHeader ? 1 : 0;
        for (let r = startRow; r < rows.length; r++) {
          const row = rows[r];
          if (!Array.isArray(row) || row.length === 0) continue;

          const userCell = row[userColIdx];
          if (userCell == null) continue;
          const v = String(userCell).trim();
          if (!v) continue;
          const lower = v.toLowerCase();
          // En modo sin-header, ignorar headers comunes que aparezcan en col 0.
          if (!hasHeader && (lower === 'username' || lower === 'usuario' || lower === 'user')) continue;
          const norm = lower.replace(/[^a-z0-9]/g, '');
          if (!norm) continue;

          if (!seen.has(norm)) {
            seen.add(norm);
            inputUsernames.push({ original: v, norm });
            fileAgg.set(norm, {
              original: v,
              sumDeposits: 0, sumWithdraws: 0, sumBonuses: 0,
              countDeposits: 0, countWithdraws: 0, countBonuses: 0
            });
          }

          // Agregar movimiento si tenemos type+amount.
          if (colType !== -1 && colAmount !== -1) {
            const tRaw = String(row[colType] == null ? '' : row[colType]).trim().toLowerCase();
            const amtRaw = row[colAmount];
            const amt = (amtRaw == null || amtRaw === '') ? 0 : Number(String(amtRaw).replace(/[^\d.\-]/g, ''));
            if (Number.isFinite(amt) && amt > 0) {
              const a = fileAgg.get(norm);
              if (TYPE_DEPOSIT.has(tRaw))      { a.sumDeposits  += amt; a.countDeposits++; }
              else if (TYPE_WITHDRAW.has(tRaw)){ a.sumWithdraws += amt; a.countWithdraws++; }
              else if (TYPE_BONUS.has(tRaw))   { a.sumBonuses   += amt; a.countBonuses++; }
            }
          }
        }
      }

      if (inputUsernames.length === 0) {
        return res.status(400).json({ error: 'No se encontraron usernames en el archivo' });
      }
      if (inputUsernames.length > 50000) {
        return res.status(413).json({ error: 'Archivo demasiado grande (>50k usernames)' });
      }

      // Lookup batch contra User, PlayerStats y UserLineLookup (este último
      // resuelve la línea/equipo de pre-asignaciones cargadas por xlsx
      // aunque la persona no esté registrada ni tenga User.lineTeamName).
      // User.username y PlayerStats.username NO se guardan en forma normalizada
      // (User preserva mayúsculas y caracteres `_` `.` `-`; PlayerStats lowercase
      // pero preserva caracteres). Por eso traemos toda la base con projection
      // chica y matcheamos en JS — un $in directo perdía a esos usuarios.
      const norms = inputUsernames.map(u => u.norm);
      const normsSet = new Set(norms);
      const _normUname = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

      const [allUsers, allStats, lookups] = await Promise.all([
        User.find(
          {},
          { username: 1, phone: 1, fcmToken: 1, fcmTokens: 1, fcmTokenContext: 1, notifPermission: 1, lineTeamName: 1, linePhone: 1, lastLogin: 1, _id: 0 }
        ).lean(),
        PlayerStats.find(
          {},
          { username: 1, tier: 1, activityStatus: 1, lastRealDepositDate: 1, realDeposits30d: 1, realDeposits90d: 1, totalRealDeposits: 1, _id: 0 }
        ).lean(),
        UserLineLookup.find(
          { usernameNorm: { $in: norms } },
          { usernameNorm: 1, lineTeamName: 1, linePhone: 1, _id: 0 }
        ).lean()
      ]);
      const userMap = new Map();
      for (const u of allUsers) {
        const n = _normUname(u.username);
        if (n && normsSet.has(n)) userMap.set(n, u);
      }
      const statsMap = new Map();
      for (const s of allStats) {
        const n = _normUname(s.username);
        if (n && normsSet.has(n)) statsMap.set(n, s);
      }
      const lookupMap = new Map(lookups.map(l => [String(l.usernameNorm || '').toLowerCase(), l]));

      const now = Date.now();
      const DAY = 24 * 60 * 60 * 1000;
      const items = [];
      const summary = {
        totalAnalyzed: inputUsernames.length,
        foundInDb: 0, notFound: 0,
        withApp: 0, withoutApp: 0,
        withNotifs: 0, withoutNotifs: 0,
        buckets: { calientes: 0, enRiesgo: 0, perdidos: 0, inactivos: 0 },
        tiers: { VIP: 0, ORO: 0, PLATA: 0, BRONCE: 0, NUEVO: 0, SIN_DATOS: 0 },
        totalRecoverableValue: 0,
        sumDeposits30d: 0,
        sumDeposits90d: 0,
        sumTotalDeposits: 0,
        // Datos del archivo (si trae Type/Amount/User).
        fileTotalDeposits: 0,
        fileTotalWithdraws: 0,
        fileTotalBonuses: 0,
        fileCountDeposits: 0,
        fileCountWithdraws: 0,
        fileCountBonuses: 0
      };

      for (const inp of inputUsernames) {
        const u = userMap.get(inp.norm);
        const s = statsMap.get(inp.norm);
        if (u) summary.foundInDb++;
        else summary.notFound++;

        // Mismo criterio que el reporte de Bono $5.000 app:
        // hasApp = token con context=standalone (PWA real instalada).
        // hasNotifs = al menos un token con notifPermission=granted.
        const tokens = (u && Array.isArray(u.fcmTokens)) ? u.fcmTokens : [];
        const standaloneTokens = tokens.filter(t => t && t.context === 'standalone');
        const hasApp = !!u && (
          u.fcmTokenContext === 'standalone' ||
          standaloneTokens.length > 0
        );
        const hasNotifs = !!u && (
          u.notifPermission === 'granted' ||
          tokens.some(t => t && t.notifPermission === 'granted')
        );
        if (hasApp) summary.withApp++; else summary.withoutApp++;
        if (hasNotifs) summary.withNotifs++; else summary.withoutNotifs++;

        const lastDep = s && s.lastRealDepositDate ? new Date(s.lastRealDepositDate).getTime() : null;
        let bucket = 'inactivos';
        let daysSince = null;
        if (lastDep) {
          daysSince = Math.floor((now - lastDep) / DAY);
          if (daysSince <= 10) bucket = 'calientes';
          else if (daysSince <= 20) bucket = 'enRiesgo';
          else if (daysSince <= 30) bucket = 'perdidos';
          else bucket = 'inactivos';
        }
        summary.buckets[bucket]++;

        const tier = (s && s.tier) ? String(s.tier).toUpperCase() : 'SIN_DATOS';
        if (summary.tiers[tier] != null) summary.tiers[tier]++;
        else summary.tiers.SIN_DATOS++;

        const sugg = _recontactSuggest(tier, bucket, hasApp, hasNotifs);
        const priority = _recontactPriority(tier, bucket, s && s.realDeposits30d);
        summary.totalRecoverableValue += sugg.bonus;
        summary.sumDeposits30d += (s && s.realDeposits30d) || 0;
        summary.sumDeposits90d += (s && s.realDeposits90d) || 0;
        summary.sumTotalDeposits += (s && s.totalRealDeposits) || 0;

        const fa = fileAgg.get(inp.norm) || { sumDeposits: 0, sumWithdraws: 0, sumBonuses: 0, countDeposits: 0, countWithdraws: 0, countBonuses: 0 };
        summary.fileTotalDeposits  += fa.sumDeposits;
        summary.fileTotalWithdraws += fa.sumWithdraws;
        summary.fileTotalBonuses   += fa.sumBonuses;
        summary.fileCountDeposits  += fa.countDeposits;
        summary.fileCountWithdraws += fa.countWithdraws;
        summary.fileCountBonuses   += fa.countBonuses;

        const ll = lookupMap.get(inp.norm);
        const team = (u && u.lineTeamName) || (ll && ll.lineTeamName) || null;
        const linePhone = (u && u.linePhone) || (ll && ll.linePhone) || null;
        items.push({
          username: inp.original,
          tier,
          bucket,
          daysSinceLastDeposit: daysSince,
          lastDepositAt: lastDep ? new Date(lastDep).toISOString() : null,
          deposits30d: (s && s.realDeposits30d) || 0,
          deposits90d: (s && s.realDeposits90d) || 0,
          totalDeposits: (s && s.totalRealDeposits) || 0,
          team,
          linePhone,
          phone: u ? (u.phone || null) : null,
          hasApp,
          hasNotifs,
          registered: !!u,
          strategy: sugg.strategy,
          suggestedBonus: sugg.bonus,
          suggestedMessage: sugg.message,
          addAppOffer: sugg.addAppOffer,
          addNotifsOffer: sugg.addNotifsOffer,
          priority,
          // Agregados desde el archivo (si trae Type/Amount/User).
          fileDeposits: fa.sumDeposits,
          fileWithdraws: fa.sumWithdraws,
          fileBonuses: fa.sumBonuses,
          fileCountDeposits: fa.countDeposits,
          fileCountWithdraws: fa.countWithdraws,
          fileCountBonuses: fa.countBonuses,
          fileNet: fa.sumDeposits - fa.sumWithdraws
        });
      }

      // Ordenar por prioridad descendente.
      items.sort((a, b) => b.priority - a.priority);

      logger.info(`[recontact/analyze] analyzed=${summary.totalAnalyzed} found=${summary.foundInDb} byBucket=${JSON.stringify(summary.buckets)} byTier=${JSON.stringify(summary.tiers)} by=${(req.user && req.user.username) || 'admin'}`);

      res.json({
        success: true,
        summary,
        items
      });
    } catch (err) {
      logger.error(`[recontact/analyze] error: ${err.message}\n${err.stack}`);
      res.status(500).json({ error: err.message });
    }
  }
);

// ============================================
// RECONTACT — análisis compartido entre admins
// ============================================
// El cache antes vivía en IndexedDB del browser (per-device). Ahora se
// persiste en MongoDB para que TODOS los admins vean el mismo análisis
// activo. Items se comprimen con gzip — 50k usuarios pasan de ~30MB a ~5MB.
const _zlib = require('zlib');
const RECONTACT_TTL_MS = 7 * 24 * 60 * 60 * 1000; // 7 días
const RECONTACT_HISTORY_MAX = 50;

// GET — devuelve el análisis activo (descomprimiendo items).
app.get('/api/admin/recontact/current', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const doc = await RecontactAnalysis.findOne({ _id: 'current' }).lean();
    if (!doc) return res.json({ exists: false });
    if (doc.expiresAt && doc.expiresAt < new Date()) {
      // El TTL de Mongo barre solo, pero por las dudas si pegan justo en el medio.
      return res.json({ exists: false });
    }
    let items = [];
    if (doc.itemsCompressed) {
      const buf = doc.itemsCompressed.buffer
        ? Buffer.from(doc.itemsCompressed.buffer)
        : Buffer.from(doc.itemsCompressed);
      try {
        const json = _zlib.gunzipSync(buf).toString('utf8');
        items = JSON.parse(json);
      } catch (decompErr) {
        logger.warn(`[recontact/current] decompress fail: ${decompErr.message}`);
        items = [];
      }
    }
    return res.json({
      exists: true,
      savedAt: doc.savedAt,
      fileLabel: doc.fileLabel,
      savedByUsername: doc.savedByUsername,
      summary: doc.summary || {},
      items,
      itemsCount: doc.itemsCount || items.length
    });
  } catch (err) {
    logger.error(`[recontact/current] error: ${err.message}\n${err.stack}`);
    return res.status(500).json({ error: err.message });
  }
});

// POST — guarda el análisis como "current" y agrega snapshot al historial.
app.post(
  '/api/admin/recontact/save',
  authMiddleware,
  adminMiddleware,
  express.json({ limit: '60mb' }),
  async (req, res) => {
    try {
      const body = req.body || {};
      const items = Array.isArray(body.items) ? body.items : null;
      const summary = body.summary || {};
      const fileLabel = String(body.fileLabel || '').slice(0, 200);
      if (!items || items.length === 0) {
        return res.status(400).json({ error: 'items requerido' });
      }
      if (items.length > 60000) {
        return res.status(413).json({ error: `Demasiados items (${items.length})` });
      }

      const json = JSON.stringify(items);
      const compressed = _zlib.gzipSync(Buffer.from(json, 'utf8'));

      const now = new Date();
      const expiresAt = new Date(now.getTime() + RECONTACT_TTL_MS);
      const savedByUsername = (req.user && req.user.username) || 'admin';

      await RecontactAnalysis.replaceOne(
        { _id: 'current' },
        {
          _id: 'current',
          savedAt: now,
          fileLabel,
          savedByUsername,
          summary,
          itemsCompressed: compressed,
          itemsCount: items.length,
          expiresAt
        },
        { upsert: true }
      );

      // Snapshot al historial.
      let sinLinea = 0;
      for (const it of items) if (!it.team && !it.linePhone) sinLinea++;
      await RecontactHistory.create({
        at: now,
        fileLabel,
        savedByUsername,
        totalAnalyzed: summary.totalAnalyzed || items.length,
        foundInDb: summary.foundInDb || 0,
        buckets: summary.buckets || {},
        tiers: summary.tiers || {},
        withApp: summary.withApp || 0,
        withNotifs: summary.withNotifs || 0,
        withoutApp: summary.withoutApp || 0,
        fileTotalDeposits: summary.fileTotalDeposits || 0,
        fileTotalWithdraws: summary.fileTotalWithdraws || 0,
        fileTotalBonuses: summary.fileTotalBonuses || 0,
        totalRecoverableValue: summary.totalRecoverableValue || 0,
        sinLinea
      });

      // Trim historial al máximo (las más viejas se borran).
      const allHist = await RecontactHistory.find().sort({ at: -1 }).select('_id').lean();
      if (allHist.length > RECONTACT_HISTORY_MAX) {
        const toDelete = allHist.slice(RECONTACT_HISTORY_MAX).map(h => h._id);
        await RecontactHistory.deleteMany({ _id: { $in: toDelete } });
      }

      logger.info(`[recontact/save] count=${items.length} compressedKB=${Math.round(compressed.length / 1024)} by=${savedByUsername} file="${fileLabel}"`);
      return res.json({ success: true, savedAt: now, expiresAt, savedByUsername });
    } catch (err) {
      logger.error(`[recontact/save] error: ${err.message}\n${err.stack}`);
      return res.status(500).json({ error: err.message });
    }
  }
);

// DELETE — limpia el análisis activo (no toca el historial).
app.delete('/api/admin/recontact/current', authMiddleware, superAdminMiddleware, async (req, res) => {
  try {
    await RecontactAnalysis.deleteOne({ _id: 'current' });
    logger.info(`[recontact/current] cleared by=${(req.user && req.user.username) || 'admin'}`);
    return res.json({ success: true });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

// GET historial — devuelve los snapshots resumidos (sin items).
app.get('/api/admin/recontact/history', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const docs = await RecontactHistory.find().sort({ at: -1 }).limit(RECONTACT_HISTORY_MAX).lean();
    return res.json({ history: docs });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

// DELETE historial — vacía todo.
app.delete('/api/admin/recontact/history', authMiddleware, superAdminMiddleware, async (req, res) => {
  try {
    const r = await RecontactHistory.deleteMany({});
    logger.info(`[recontact/history] cleared ${r.deletedCount} entries by=${(req.user && req.user.username) || 'admin'}`);
    return res.json({ success: true, deletedCount: r.deletedCount });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

// DELETE individual: borra UNA entrada del historial por su _id.
// Usado cuando el admin sube un XLSX duplicado y quiere limpiar uno.
app.delete('/api/admin/recontact/history/:id', authMiddleware, superAdminMiddleware, async (req, res) => {
  try {
    const id = String((req.params && req.params.id) || '').trim();
    if (!id || !/^[0-9a-fA-F]{24}$/.test(id)) {
      return res.status(400).json({ error: 'id inválido (formato ObjectId)' });
    }
    const r = await RecontactHistory.deleteOne({ _id: id });
    if (r.deletedCount === 0) {
      return res.status(404).json({ error: 'Entrada no encontrada' });
    }
    logger.info(`[recontact/history] deleted entry ${id} by=${(req.user && req.user.username) || 'admin'}`);
    return res.json({ success: true, deletedId: id });
  } catch (err) {
    logger.error(`[recontact/history DELETE :id] ${err.message}`);
    return res.status(500).json({ error: err.message });
  }
});

// ============================================
// RECONTACT — Evolución de cohortes entre 2 fechas
// ============================================
// Compara el bucket de actividad de cada usuario AHORA vs en una fecha
// pasada. La fecha pasada se elige (default = snapshot más reciente del
// historial). Para cada user del análisis actual, calcula:
//   - bucket AHORA = (now - lastRealDepositDate) bucketizado
//   - bucket EN prevDate = (prevDate - lastDepositBeforePrev) bucketizado
//     donde lastDepositBeforePrev = última carga del user ANTES de prevDate
//     (consultando Transaction.timestamp). Si nunca cargó antes = 'noDeposit'.
// Devuelve:
//   - matrix: cross-tab prev × current (counts)
//   - transitions: top movimientos clave (cooled, recovered, new, lost)
//   - totals: agregados (currentCalientes, prevCalientes, retained, new, lost)
app.get('/api/admin/recontact/cohort-evolution', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const prevDateStr = String(req.query.prevDate || '').trim();
    if (!/^\d{4}-\d{2}-\d{2}/.test(prevDateStr)) {
      return res.status(400).json({ error: 'prevDate (YYYY-MM-DD) requerido' });
    }
    const prevDate = new Date(prevDateStr);
    if (isNaN(prevDate.getTime())) {
      return res.status(400).json({ error: 'prevDate inválida' });
    }
    const now = new Date();
    const DAY = 24 * 60 * 60 * 1000;

    // 1) Cargar items del análisis actual (descomprimir).
    const cur = await RecontactAnalysis.findOne({ _id: 'current' }).lean();
    if (!cur || !cur.itemsCompressed) {
      return res.status(404).json({ error: 'No hay análisis actual cargado. Subí un XLSX primero.' });
    }
    let items = [];
    try {
      const buf = cur.itemsCompressed.buffer
        ? Buffer.from(cur.itemsCompressed.buffer)
        : Buffer.from(cur.itemsCompressed);
      items = JSON.parse(_zlib.gunzipSync(buf).toString('utf8'));
    } catch (e) {
      return res.status(500).json({ error: 'No se pudo descomprimir el análisis actual' });
    }
    if (!Array.isArray(items) || items.length === 0) {
      return res.status(404).json({ error: 'El análisis actual no tiene items' });
    }

    // 2) Sacar lista de usernames del archivo (lowercase para join robusto).
    const usernames = items.map(it => String((it && it.username) || '').toLowerCase()).filter(Boolean);
    const uniqueUsernames = Array.from(new Set(usernames));

    // 3) Para cada user, buscar última carga ANTES de prevDate. Aggregation única.
    // Indices ya existen: { username: 1, timestamp: -1 } y { type: 1, timestamp: -1 }.
    // Procesamos en chunks por si el array de usernames es muy grande (>10k).
    const lastDepositBeforePrev = new Map(); // username (lc) → Date
    const CHUNK = 5000;
    for (let i = 0; i < uniqueUsernames.length; i += CHUNK) {
      const chunk = uniqueUsernames.slice(i, i + CHUNK);
      const rows = await Transaction.aggregate([
        {
          $match: {
            type: 'deposit',
            status: 'completed',
            timestamp: { $lt: prevDate },
            // username viene en lower del análisis, pero en Transaction puede venir mixto —
            // hacemos $expr con toLower para garantizar match case-insensitive.
            $expr: { $in: [{ $toLower: '$username' }, chunk] }
          }
        },
        { $sort: { username: 1, timestamp: -1 } },
        { $group: { _id: { $toLower: '$username' }, lastDep: { $first: '$timestamp' } } }
      ], { allowDiskUse: true });
      for (const r of rows) {
        if (r && r._id) lastDepositBeforePrev.set(r._id, r.lastDep);
      }
    }

    // 4) Helper bucketize (mismo criterio que el resto del sistema).
    const bucketize = (days) => {
      if (days == null || !isFinite(days)) return 'noDeposit';
      if (days <= 10) return 'calientes';
      if (days <= 20) return 'enRiesgo';
      if (days <= 30) return 'perdidos';
      return 'inactivos';
    };

    // 5) Construir matriz + listas de transiciones.
    const BUCKETS = ['calientes', 'enRiesgo', 'perdidos', 'inactivos', 'noDeposit'];
    const matrix = {};
    for (const p of BUCKETS) {
      matrix[p] = {};
      for (const c of BUCKETS) matrix[p][c] = 0;
    }

    // Transiciones específicas que importan al admin (top 100 c/u, ordenadas).
    const transitions = {
      retainedHot: [],   // CAL → CAL (seguís calientes, los más valiosos)
      cooledHotToRisk: [], // CAL → RIESGO (se están enfriando, recuperables)
      cooledHotToPerd: [], // CAL → PERDIDOS (preocupante)
      cooledHotToInact: [], // CAL → INACTIVOS (perdidos, alta señal)
      recoveredFromInact: [], // INACT → CAL (recuperaste — métrica de tu trabajo)
      recoveredFromPerd: [], // PERD → CAL (recuperaste — métrica de tu trabajo)
      recoveredFromRisk: [], // RIESGO → CAL (recuperaste)
      newDepositors: []  // noDeposit → CAL (depósito por primera vez después de prevDate)
    };

    for (const it of items) {
      const userLc = String((it && it.username) || '').toLowerCase();
      if (!userLc) continue;
      const curDaysSince = (it.daysSinceLastDeposit != null && isFinite(it.daysSinceLastDeposit))
        ? Number(it.daysSinceLastDeposit)
        : (it.lastDepositAt ? Math.floor((now - new Date(it.lastDepositAt)) / DAY) : null);
      const curBucket = bucketize(curDaysSince);

      const prevDep = lastDepositBeforePrev.get(userLc);
      let prevBucket;
      if (!prevDep) {
        prevBucket = 'noDeposit';
      } else {
        const prevDays = Math.floor((prevDate - new Date(prevDep)) / DAY);
        prevBucket = bucketize(prevDays < 0 ? 0 : prevDays);
      }

      matrix[prevBucket][curBucket] += 1;

      // Acumular para listas (con info para mostrar).
      const sample = {
        username: it.username || userLc,
        prevBucket, curBucket,
        prevDaysSince: prevDep ? Math.floor((prevDate - new Date(prevDep)) / DAY) : null,
        curDaysSince,
        lastDepositAt: it.lastDepositAt || null,
        hasApp: !!it.hasApp,
        team: it.team || null
      };
      if (prevBucket === 'calientes' && curBucket === 'calientes') transitions.retainedHot.push(sample);
      else if (prevBucket === 'calientes' && curBucket === 'enRiesgo') transitions.cooledHotToRisk.push(sample);
      else if (prevBucket === 'calientes' && curBucket === 'perdidos') transitions.cooledHotToPerd.push(sample);
      else if (prevBucket === 'calientes' && curBucket === 'inactivos') transitions.cooledHotToInact.push(sample);
      else if (prevBucket === 'inactivos' && curBucket === 'calientes') transitions.recoveredFromInact.push(sample);
      else if (prevBucket === 'perdidos' && curBucket === 'calientes') transitions.recoveredFromPerd.push(sample);
      else if (prevBucket === 'enRiesgo' && curBucket === 'calientes') transitions.recoveredFromRisk.push(sample);
      else if (prevBucket === 'noDeposit' && curBucket !== 'noDeposit') transitions.newDepositors.push(sample);
    }

    // Cortar listas a 300 por categoría para no inflar el response.
    for (const k of Object.keys(transitions)) {
      transitions[k].sort((a, b) => (a.curDaysSince || 0) - (b.curDaysSince || 0));
      transitions[k] = transitions[k].slice(0, 300);
    }

    // Totales útiles.
    const totals = {
      analyzedItems: items.length,
      prevCalientes: BUCKETS.reduce((s, c) => s + matrix.calientes[c], 0),
      curCalientes: BUCKETS.reduce((s, p) => s + matrix[p].calientes, 0),
      retained: matrix.calientes.calientes,
      cooled: matrix.calientes.enRiesgo + matrix.calientes.perdidos + matrix.calientes.inactivos,
      recovered: matrix.inactivos.calientes + matrix.perdidos.calientes + matrix.enRiesgo.calientes,
      brandNew: matrix.noDeposit.calientes + matrix.noDeposit.enRiesgo + matrix.noDeposit.perdidos
    };
    totals.netCalientesChange = totals.curCalientes - totals.prevCalientes;

    res.json({
      success: true,
      prevDate: prevDateStr,
      currentSavedAt: cur.savedAt,
      currentFileLabel: cur.fileLabel || '',
      daysBetween: Math.max(0, Math.floor((now - prevDate) / DAY)),
      matrix,
      totals,
      transitions
    });
  } catch (err) {
    logger.error(`[recontact/cohort-evolution] ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// ============================================
// USUARIOS CON APP — conteo real sobre toda la base
// ============================================
// Cuenta exacta de cuántos usuarios tienen la PWA instalada (token con
// context=standalone) y cuántos también tienen notifs activas. Usa el
// MISMO criterio que el reporte de Bono $5.000 app y Recontactación,
// para que los números cuadren entre secciones.
// Helper: dayKey en hora ART (UTC-3) → YYYY-MM-DD
function _appUsersDayKey(d) {
  const date = d || new Date();
  const ms = date.getTime() - 3 * 60 * 60 * 1000; // shift a ART
  return new Date(ms).toISOString().slice(0, 10);
}

// Toma un snapshot de los counts y lo upsertea en AppUsersDailySnapshot.
// Se llama desde el endpoint /stats (oportunístico) y desde un cron diario.
async function _captureAppUsersSnapshot() {
  const HAS_APP_QUERY = {
    $or: [
      { fcmTokenContext: 'standalone' },
      { 'fcmTokens.context': 'standalone' }
    ]
  };
  const HAS_NOTIFS_QUERY = {
    $or: [
      { notifPermission: 'granted' },
      { 'fcmTokens.notifPermission': 'granted' }
    ]
  };
  const HAS_BOTH_QUERY = { $and: [HAS_APP_QUERY, HAS_NOTIFS_QUERY] };
  const HAS_APP_NO_NOTIFS_QUERY = { $and: [HAS_APP_QUERY, { $nor: [HAS_NOTIFS_QUERY] }] };

  const [totalUsers, withApp, withNotifs, withBoth, withAppNoNotifs] = await Promise.all([
    User.countDocuments({}),
    User.countDocuments(HAS_APP_QUERY),
    User.countDocuments(HAS_NOTIFS_QUERY),
    User.countDocuments(HAS_BOTH_QUERY),
    User.countDocuments(HAS_APP_NO_NOTIFS_QUERY)
  ]);
  const platformAgg = await User.aggregate([
    { $match: HAS_APP_QUERY },
    { $unwind: '$fcmTokens' },
    { $match: { 'fcmTokens.context': 'standalone' } },
    { $group: { _id: '$fcmTokens.platform', count: { $sum: 1 } } }
  ]);
  const byPlatform = {};
  for (const p of platformAgg) byPlatform[p._id || 'desconocido'] = p.count;

  const dayKey = _appUsersDayKey();
  await AppUsersDailySnapshot.findOneAndUpdate(
    { dayKey },
    {
      dayKey,
      takenAt: new Date(),
      totalUsers, withApp, withNotifs, withBoth, withAppNoNotifs,
      sinApp: totalUsers - withApp,
      byPlatform
    },
    { upsert: true, new: true }
  );

  return { dayKey, totalUsers, withApp, withNotifs, withBoth };
}

// GET evolución diaria — devuelve los últimos N snapshots para graficar/tabular.
app.get('/api/admin/app-users/history', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const days = Math.min(180, Math.max(1, parseInt(req.query.days, 10) || 60));
    const snaps = await AppUsersDailySnapshot.find({})
      .sort({ dayKey: -1 })
      .limit(days)
      .lean();
    return res.json({ history: snaps });
  } catch (err) {
    logger.error(`[app-users/history] error: ${err.message}`);
    return res.status(500).json({ error: err.message });
  }
});

app.get('/api/admin/app-users/stats', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const HAS_APP_QUERY = {
      $or: [
        { fcmTokenContext: 'standalone' },
        { 'fcmTokens.context': 'standalone' }
      ]
    };
    const HAS_NOTIFS_QUERY = {
      $or: [
        { notifPermission: 'granted' },
        { 'fcmTokens.notifPermission': 'granted' }
      ]
    };
    const HAS_BOTH_QUERY = {
      $and: [HAS_APP_QUERY, HAS_NOTIFS_QUERY]
    };
    const HAS_APP_NO_NOTIFS_QUERY = {
      $and: [HAS_APP_QUERY, { $nor: [HAS_NOTIFS_QUERY] }]
    };

    const [totalUsers, withApp, withNotifs, withBoth, withAppNoNotifs] = await Promise.all([
      User.countDocuments({}),
      User.countDocuments(HAS_APP_QUERY),
      User.countDocuments(HAS_NOTIFS_QUERY),
      User.countDocuments(HAS_BOTH_QUERY),
      User.countDocuments(HAS_APP_NO_NOTIFS_QUERY)
    ]);

    // Breakdown por equipo (lineTeamName) — sólo de los que tienen app.
    const byTeam = await User.aggregate([
      { $match: HAS_APP_QUERY },
      {
        $group: {
          _id: '$lineTeamName',
          withApp: { $sum: 1 },
          withBoth: {
            $sum: {
              $cond: [
                {
                  $or: [
                    { $eq: ['$notifPermission', 'granted'] },
                    {
                      $gt: [
                        {
                          $size: {
                            $filter: {
                              input: { $ifNull: ['$fcmTokens', []] },
                              as: 't',
                              cond: { $eq: ['$$t.notifPermission', 'granted'] }
                            }
                          }
                        },
                        0
                      ]
                    }
                  ]
                },
                1, 0
              ]
            }
          }
        }
      },
      { $sort: { withApp: -1 } }
    ]);

    // Misma agregación sobre TODOS los users (con o sin app) por equipo,
    // para tener el "total registrados por equipo" como denominador.
    const totalByTeam = await User.aggregate([
      { $group: { _id: '$lineTeamName', total: { $sum: 1 } } }
    ]);
    const totalByTeamMap = new Map(totalByTeam.map(t => [t._id || '', t.total]));

    const teamRows = byTeam.map(t => ({
      team: t._id || '(sin equipo)',
      withApp: t.withApp,
      withBoth: t.withBoth,
      withAppNoNotifs: t.withApp - t.withBoth,
      totalRegistered: totalByTeamMap.get(t._id || '') || 0,
      pctOfTeam: (totalByTeamMap.get(t._id || '') || 0) > 0
        ? Math.round((t.withApp / (totalByTeamMap.get(t._id || '') || 1)) * 1000) / 10
        : 0
    }));

    // Plataformas (Android / iOS / desktop) de los tokens standalone.
    const platformAgg = await User.aggregate([
      { $match: HAS_APP_QUERY },
      { $unwind: '$fcmTokens' },
      { $match: { 'fcmTokens.context': 'standalone' } },
      { $group: { _id: '$fcmTokens.platform', count: { $sum: 1 } } },
      { $sort: { count: -1 } }
    ]);
    const platforms = platformAgg.map(p => ({ platform: p._id || 'desconocido', count: p.count }));

    // Atribución Callbell — cuántos usuarios CON app fueron etiquetados antes
    // y se convirtieron (no tenían app al momento del tag y ahora sí).
    let callbellAttribution = { total: 0, manualConfirmed: 0, autoDetected: 0 };
    try {
      const cbConverted = await CallbellTag.countDocuments({
        convertedAt: { $ne: null }, hadAppAtFirstTag: { $ne: true }
      });
      const cbManual = await CallbellTag.countDocuments({
        convertedAt: { $ne: null }, hadAppAtFirstTag: { $ne: true }, convertedBy: 'manual'
      });
      callbellAttribution = {
        total: cbConverted,
        manualConfirmed: cbManual,
        autoDetected: cbConverted - cbManual
      };
    } catch (cbErr) {
      logger.warn(`[app-users/stats] callbell attribution fail: ${cbErr.message}`);
    }

    // Aprovechamos el cómputo para upsertear el snapshot del día (oportunístico).
    // Si nadie entra hoy a la sección, igual lo captura el cron diario abajo.
    try {
      const dayKey = _appUsersDayKey();
      const byPlatform = {};
      for (const p of platforms) byPlatform[p.platform] = p.count;
      await AppUsersDailySnapshot.findOneAndUpdate(
        { dayKey },
        {
          dayKey, takenAt: new Date(),
          totalUsers, withApp, withNotifs, withBoth, withAppNoNotifs,
          sinApp: totalUsers - withApp,
          byPlatform
        },
        { upsert: true, new: true }
      );
    } catch (snapErr) {
      logger.warn(`[app-users/stats] snapshot upsert fail: ${snapErr.message}`);
    }

    res.json({
      generatedAt: new Date().toISOString(),
      totals: {
        totalUsers,
        withApp,
        withNotifs,
        withBoth,
        withAppNoNotifs,
        sinApp: totalUsers - withApp
      },
      byTeam: teamRows,
      platforms,
      callbellAttribution
    });
  } catch (err) {
    logger.error(`[app-users/stats] error: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// Cron: capturar snapshot diario de usuarios con app a las 03:00 ART
// (las 06:00 UTC). Usa setInterval que dispara cada hora y chequea si es la
// hora apropiada — sirve para entornos sin cron del sistema.
setInterval(async () => {
  try {
    const now = new Date();
    const artHour = (now.getUTCHours() + 24 - 3) % 24; // ART = UTC-3
    if (artHour !== 3) return;
    const dayKey = _appUsersDayKey();
    const exists = await AppUsersDailySnapshot.findOne({ dayKey }).lean();
    if (exists) return; // ya capturado hoy
    const r = await _captureAppUsersSnapshot();
    logger.info(`[app-users/cron] daily snapshot taken dayKey=${r.dayKey} totalUsers=${r.totalUsers} withApp=${r.withApp} withBoth=${r.withBoth}`);
  } catch (err) {
    logger.warn(`[app-users/cron] error: ${err.message}`);
  }
}, 60 * 60 * 1000).unref(); // cada hora

// ============================================
// CALLBELL TAGS — tracking de etiqueta WhatsApp → conversión a app
// ============================================
function _normUsername(s) {
  return String(s || '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');
}

// Helper: chequea si un user tiene app instalada (token standalone).
async function _userHasStandaloneApp(usernameNorm) {
  const u = await User.findOne(
    { username: usernameNorm },
    { fcmTokenContext: 1, fcmTokens: 1, _id: 0 }
  ).lean();
  if (!u) return false;
  if (u.fcmTokenContext === 'standalone') return true;
  return Array.isArray(u.fcmTokens) && u.fcmTokens.some(t => t && t.context === 'standalone');
}

// POST /api/admin/callbell/tag
// Toggle de un flag (etiqueta | wa) o set de respuesta (instalo | no_contesto).
// body: { username, action: 'etiqueta'|'wa'|'instalo'|'no_contesto', set: true|false,
//         bucket, tier, analysisLabel }
app.post('/api/admin/callbell/tag', authMiddleware, adminMiddleware, express.json({ limit: '50kb' }), async (req, res) => {
  try {
    const username = String((req.body && req.body.username) || '').trim();
    const action = String((req.body && req.body.action) || '').trim();
    const set = !!(req.body && req.body.set);
    const bucket = String((req.body && req.body.bucket) || '').trim();
    const tier = String((req.body && req.body.tier) || '').trim();
    const analysisLabel = String((req.body && req.body.analysisLabel) || '').trim().slice(0, 200);
    if (!username) return res.status(400).json({ error: 'username requerido' });
    if (!['etiqueta', 'wa', 'favorito', 'instalo', 'no_contesto'].includes(action)) {
      return res.status(400).json({ error: 'action inválida' });
    }
    const norm = _normUsername(username);
    if (!norm) return res.status(400).json({ error: 'username inválido' });
    const adminUser = (req.user && req.user.username) || 'admin';

    let doc = await CallbellTag.findOne({ usernameNorm: norm });
    const isNew = !doc;
    if (!doc) doc = new CallbellTag({ usernameNorm: norm, username });

    const now = new Date();
    if (action === 'etiqueta' || action === 'wa' || action === 'favorito') {
      // Asegurarse que el sub-doc esté inicializado.
      if (!doc[action]) doc[action] = {};
      doc[action].tagged = set;
      if (set) {
        doc[action].taggedAt = now;
        doc[action].taggedBy = adminUser;
        // bucket/tier/analysisLabel solo aplican a etiqueta y wa (origen XLSX).
        if (action !== 'favorito') {
          doc[action].fromBucket = bucket || doc[action].fromBucket || '';
          doc[action].fromTier = tier || doc[action].fromTier || '';
          doc[action].analysisLabel = analysisLabel || doc[action].analysisLabel || '';
        }
      }
      // Marcar como modified para asegurar persistencia (Mongoose a veces no
      // detecta cambios en sub-documents anidados).
      doc.markModified(action);
      // Si es la primera vez que se etiqueta cualquier flag, snapshot del estado de app.
      const justGotFirstTag = set && !doc.firstTaggedAt;
      if (justGotFirstTag) {
        doc.firstTaggedAt = now;
        doc.hadAppAtFirstTag = await _userHasStandaloneApp(norm);
      }
    } else if (action === 'instalo' || action === 'no_contesto') {
      if (!doc.respuesta) doc.respuesta = {};
      // Mutuamente excluyentes: setear instalo desmarca no_contesto y viceversa.
      // set=false → limpiar el campo.
      if (set) {
        doc.respuesta.status = action;
        doc.respuesta.markedAt = now;
        doc.respuesta.markedBy = adminUser;
        // Si marca "instalo" manualmente, también persistimos convertedAt
        // (si todavía no hadAppAtFirstTag).
        if (action === 'instalo' && !doc.convertedAt && !doc.hadAppAtFirstTag) {
          doc.convertedAt = now;
          doc.convertedBy = 'manual';
        }
      } else {
        doc.respuesta.status = null;
        doc.respuesta.markedAt = undefined;
        doc.respuesta.markedBy = undefined;
      }
      doc.markModified('respuesta');
    }

    const saved = await doc.save();
    logger.info(`[callbell/tag] saved username=${norm} action=${action} set=${set} by=${adminUser} hadAppAtFirstTag=${saved.hadAppAtFirstTag} convertedAt=${saved.convertedAt}`);
    return res.json({ success: true, tag: saved.toObject() });
  } catch (err) {
    logger.error(`[callbell/tag] error: ${err.message}\n${err.stack}`);
    return res.status(500).json({ error: err.message });
  }
});

// POST /api/admin/callbell/tags-by-usernames — batch lookup
// body: { usernames: [...] } → returns { tags: { norm: {etiqueta, wa, respuesta, convertedAt, hadAppAtFirstTag} } }
app.post('/api/admin/callbell/tags-by-usernames', authMiddleware, adminMiddleware, express.json({ limit: '5mb' }), async (req, res) => {
  try {
    const usernames = Array.isArray(req.body && req.body.usernames) ? req.body.usernames : [];
    if (usernames.length === 0) return res.json({ tags: {} });
    if (usernames.length > 60000) return res.status(413).json({ error: 'Demasiados usernames' });
    const norms = usernames.map(_normUsername).filter(Boolean);
    const docs = await CallbellTag.find(
      { usernameNorm: { $in: norms } },
      { usernameNorm: 1, etiqueta: 1, wa: 1, favorito: 1, respuesta: 1, convertedAt: 1, hadAppAtFirstTag: 1, firstTaggedAt: 1, _id: 0 }
    ).lean();
    const map = {};
    for (const d of docs) map[d.usernameNorm] = d;
    return res.json({ tags: map });
  } catch (err) {
    logger.error(`[callbell/tags-by-usernames] error: ${err.message}`);
    return res.status(500).json({ error: err.message });
  }
});

// GET /api/admin/recontact/daily-progress?date=YYYY-MM-DD
// Devuelve TODOS los tildes (etiqueta / wa / favorito / respuesta) hechos en
// el día indicado, agrupados por user. Sirve para auditar avance diario del
// personal: quién tildó qué, a qué hora, sobre qué user. Default: hoy.
app.get('/api/admin/recontact/daily-progress', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const dateStr = String((req.query && req.query.date) || '').trim();
    let dayStart, dayEnd;
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
      dayStart = new Date(dateStr + 'T00:00:00');
      dayEnd = new Date(dateStr + 'T23:59:59.999');
    } else {
      dayStart = new Date(); dayStart.setHours(0,0,0,0);
      dayEnd = new Date(); dayEnd.setHours(23,59,59,999);
    }
    if (isNaN(dayStart.getTime())) return res.status(400).json({ error: 'date inválida (YYYY-MM-DD)' });

    // Query: cualquier tag cuyo taggedAt/markedAt caiga en el día.
    // Ojo: el doc se devuelve si AL MENOS UNO de los timestamps está en rango;
    // después filtramos sub-acciones por timestamp.
    const docs = await CallbellTag.find({
      $or: [
        { 'etiqueta.taggedAt': { $gte: dayStart, $lte: dayEnd } },
        { 'wa.taggedAt':       { $gte: dayStart, $lte: dayEnd } },
        { 'favorito.taggedAt': { $gte: dayStart, $lte: dayEnd } },
        { 'respuesta.markedAt':{ $gte: dayStart, $lte: dayEnd } }
      ]
    }, {
      username: 1, usernameNorm: 1,
      etiqueta: 1, wa: 1, favorito: 1, respuesta: 1,
      _id: 0
    }).lean();

    // Aplanar a una lista de eventos { username, action, set, at, by }.
    const events = [];
    const inRange = (d) => d && new Date(d).getTime() >= dayStart.getTime() && new Date(d).getTime() <= dayEnd.getTime();
    for (const d of docs) {
      const u = d.username || d.usernameNorm;
      if (d.etiqueta && inRange(d.etiqueta.taggedAt)) {
        events.push({ username: u, action: 'etiqueta', set: !!d.etiqueta.tagged, at: d.etiqueta.taggedAt, by: d.etiqueta.taggedBy || null });
      }
      if (d.wa && inRange(d.wa.taggedAt)) {
        events.push({ username: u, action: 'wa', set: !!d.wa.tagged, at: d.wa.taggedAt, by: d.wa.taggedBy || null });
      }
      if (d.favorito && inRange(d.favorito.taggedAt)) {
        events.push({ username: u, action: 'favorito', set: !!d.favorito.tagged, at: d.favorito.taggedAt, by: d.favorito.taggedBy || null });
      }
      if (d.respuesta && inRange(d.respuesta.markedAt)) {
        events.push({ username: u, action: 'respuesta:' + (d.respuesta.status || ''), set: true, at: d.respuesta.markedAt, by: d.respuesta.markedBy || null });
      }
    }
    // Orden: más reciente arriba.
    events.sort((a, b) => new Date(b.at).getTime() - new Date(a.at).getTime());

    // Agregados: por admin, por acción.
    const byAdmin = {};
    const byAction = {};
    for (const e of events) {
      const adm = e.by || 'desconocido';
      byAdmin[adm] = (byAdmin[adm] || 0) + 1;
      const act = e.action.split(':')[0];
      byAction[act] = (byAction[act] || 0) + 1;
    }

    return res.json({
      date: (dayStart.toISOString().slice(0, 10)),
      total: events.length,
      uniqueUsers: new Set(events.map(e => (e.username || '').toLowerCase())).size,
      byAdmin, byAction,
      events
    });
  } catch (err) {
    logger.error(`[recontact/daily-progress] error: ${err.message}\n${err.stack}`);
    return res.status(500).json({ error: err.message });
  }
});

// GET /api/admin/users/search?q=<text>&limit=50
// Busca usuarios por substring del username (case-insensitive) y devuelve
// info básica + tags Callbell + favorito. Limit hard 100. Pensado para el
// buscador de la sección Recontactación: el admin teclea, ve resultados, y
// puede tildar etiqueta/wa/favorito desde ahí mismo sin subir XLSX.
// ============================================================
// CLAVES PARA SECCIONES PROTEGIDAS (CENTRAL / Números vigentes)
// ============================================================
// Cada sección protegida tiene su PIN (default 1818). Se guarda en Config con
// key='admin_section_pins'. El admin ya pasó por authMiddleware/adminMiddleware,
// el PIN es una capa extra de friccion antes de tocar settings sensibles
// (números, equipos). El PIN se almacena en plaintext porque ya está dentro
// del admin; no es un secret externo.

const _DEFAULT_SECTION_PIN = '1818';
// Defaults específicos por sección — overridean _DEFAULT_SECTION_PIN.
// Útil para que distintas secciones empiecen con PIN distinto sin que el
// admin tenga que ir a cambiarlos a mano.
const _SECTION_DEFAULT_PINS = { closings: '3333' };
// PINs previos seedeados por defecto en deploys anteriores. Si el valor en
// la DB todavía es uno de estos, se rotará al default nuevo en el próximo
// _getSectionPins(). Si el owner ya cambió la clave a otro valor distinto,
// no se toca. Esto evita que el dueño tenga que pasar por "Cambiar clave"
// cada vez que se actualiza el default vía deploy.
const _SECTION_LEGACY_PINS = { closings: ['1515', '1818'] };
const _defaultPinForSection = (s) => _SECTION_DEFAULT_PINS[s] || _DEFAULT_SECTION_PIN;
// 'teams' está protegido — el detalle por equipo (stats agregados, líneas,
// usuarios) requiere PIN. Las features que solo necesitan el listado de
// nombres de equipo (líneas caídas, refund-reminders) usan /teams/names
// que NO está gateado.
// 'backupPhones' protege el listado de números de respaldo.
// 'closings' protege la sección CIERRES GENERAL en el panel admin (es solo
// frontend-gate: los endpoints /api/admin/closings* NO requieren el token
// de section-pin porque también los usa el rol closings_viewer que no es
// full admin y no puede llamar a /section-pins/verify).
const _PROTECTED_SECTIONS = ['numero', 'backupPhones', 'teams', 'closings'];

async function _getSectionPins() {
  let v = await getConfig('admin_section_pins', null);
  let changed = false;
  if (!v || typeof v !== 'object') { v = {}; changed = true; }
  // Asegurar que toda sección protegida tenga PIN — completa con default si
  // falta (cubre el caso de secciones nuevas agregadas en deploys posteriores).
  for (const s of _PROTECTED_SECTIONS) {
    const def = _defaultPinForSection(s);
    if (!v[s]) {
      v[s] = def;
      changed = true;
    } else if (Array.isArray(_SECTION_LEGACY_PINS[s]) &&
               _SECTION_LEGACY_PINS[s].map(String).includes(String(v[s])) &&
               String(v[s]) !== String(def)) {
      // El valor en DB es un default viejo (no fue cambiado por el owner).
      // Rotamos al default nuevo para que el deploy refleje el cambio.
      v[s] = def;
      changed = true;
    }
  }
  if (changed) await setConfig('admin_section_pins', v);
  return v;
}

// POST verify — valida el PIN para una sección. Si coincide, emite un
// JWT corto (30 min) que el cliente debe mandar como X-Section-Pin-Token
// en las llamadas a endpoints protegidos. Sin ese token, el backend
// responde 403 aunque el admin esté autenticado.
app.post('/api/admin/section-pins/verify', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const { section, pin } = req.body || {};
    if (!_PROTECTED_SECTIONS.includes(section)) return res.status(400).json({ error: 'section inválida' });
    const pins = await _getSectionPins();
    const expected = pins[section] || _defaultPinForSection(section);
    const valid = String(pin || '') === String(expected);
    if (!valid) return res.json({ valid: false });
    const token = _signSectionPinToken(section, req.user && req.user.username);
    res.json({ valid: true, token, expiresIn: _SECTION_PIN_TOKEN_TTL_SEC });
  } catch (err) {
    logger.error(`/api/admin/section-pins/verify: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// POST change — cambia el PIN. Requiere el PIN actual + el nuevo.
app.post('/api/admin/section-pins/change', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const { section, currentPin, newPin } = req.body || {};
    if (!_PROTECTED_SECTIONS.includes(section)) return res.status(400).json({ error: 'section inválida' });
    if (!/^\d{4,8}$/.test(String(newPin || ''))) return res.status(400).json({ error: 'El PIN nuevo debe tener 4-8 dígitos' });
    const pins = await _getSectionPins();
    const expected = pins[section] || _defaultPinForSection(section);
    if (String(currentPin || '') !== String(expected)) return res.status(403).json({ error: 'PIN actual incorrecto' });
    pins[section] = String(newPin);
    await setConfig('admin_section_pins', pins);
    logger.info(`[section-pins] ${section} cambiado por ${(req.user && req.user.username) || 'admin'}`);
    res.json({ success: true });
  } catch (err) {
    logger.error(`/api/admin/section-pins/change: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// GET sections — devuelve qué secciones tienen PIN activo (sin exponer el PIN).
app.get('/api/admin/section-pins/status', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const pins = await _getSectionPins();
    const out = {};
    for (const s of _PROTECTED_SECTIONS) out[s] = !!pins[s];
    res.json({ sections: out });
  } catch (err) {
    logger.error(`/api/admin/section-pins/status: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// ============================================================
// PIN GATE BACKEND — defensa real, no sólo UI
// ============================================================
// Antes el PIN era cosmético: el frontend mostraba el modal pero el backend
// devolvía los datos sólo con auth+admin. Esto significa que un withdrawer
// con sesión válida (o un admin con cookie robada via XSS) podía bajar todo
// el directorio de números sin tocar el PIN.
//
// Fix: en /verify exitoso firmamos un JWT corto (scope='section-pin:<seccion>',
// exp 30 min) y se lo devolvemos al cliente. El cliente lo manda como header
// X-Section-Pin-Token. requireSectionPin valida que el token sea para la
// sección correcta, no expirado, y firmado con el mismo JWT_SECRET — sin
// eso, 403.
//
// El token caduca a los 30 min — el admin re-ingresa el PIN entonces. El
// trade-off de cosmético→funcional es 1 modal cada 30 min para el admin
// legítimo, a cambio de que un atacante sin el PIN no pueda bajar nada.

const _SECTION_PIN_TOKEN_TTL_SEC = 30 * 60; // 30 min

function _signSectionPinToken(section, username) {
  return jwt.sign(
    { scope: 'section-pin', section: String(section), u: String(username || '') },
    JWT_SECRET,
    { expiresIn: _SECTION_PIN_TOKEN_TTL_SEC }
  );
}

function _verifySectionPinToken(token, expectedSection) {
  try {
    const d = jwt.verify(String(token || ''), JWT_SECRET);
    if (!d || d.scope !== 'section-pin') return false;
    if (String(d.section) !== String(expectedSection)) return false;
    return true;
  } catch (_) {
    return false;
  }
}

function requireSectionPin(section) {
  return (req, res, next) => {
    const token = req.headers['x-section-pin-token'] || req.headers['X-Section-Pin-Token'];
    if (!_verifySectionPinToken(token, section)) {
      return res.status(403).json({ error: 'PIN_REQUIRED', section });
    }
    next();
  };
}

app.get('/api/admin/users/search', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const q = String((req.query && req.query.q) || '').trim();
    const limit = Math.max(1, Math.min(100, parseInt(req.query.limit, 10) || 50));
    if (!q || q.length < 2) return res.json({ items: [], q, hint: 'Escribí al menos 2 caracteres.' });
    const safe = q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const rx = new RegExp(safe, 'i');

    const users = await User.find(
      { username: { $regex: rx } },
      { username: 1, fcmToken: 1, fcmTokens: 1, fcmTokenContext: 1, notifPermission: 1, lineTeamName: 1, linePhone: 1, lastLogin: 1, _id: 0 }
    )
      .sort({ lastLogin: -1 })
      .limit(limit)
      .lean();

    if (users.length === 0) return res.json({ items: [], q });

    const norms = users.map(u => _normUsername(u.username)).filter(Boolean);
    const tagDocs = await CallbellTag.find(
      { usernameNorm: { $in: norms } },
      { usernameNorm: 1, etiqueta: 1, wa: 1, favorito: 1, respuesta: 1, _id: 0 }
    ).lean();
    const tagMap = new Map(tagDocs.map(d => [d.usernameNorm, d]));

    const items = users.map(u => {
      const norm = _normUsername(u.username);
      const t = tagMap.get(norm) || {};
      // hasApp = mismo criterio que el resto del sistema (fcmTokenContext='standalone'
      // o algún token con context='standalone'). Antes era 'cualquier token', lo que
      // inflaba el conteo y no coincidía con Equipamiento/Usuarios con app.
      const tokens = Array.isArray(u.fcmTokens) ? u.fcmTokens : [];
      const standaloneToken = tokens.some(t => t && t.context === 'standalone');
      const hasApp = u.fcmTokenContext === 'standalone' || standaloneToken;
      return {
        username: u.username,
        usernameNorm: norm,
        hasApp,
        notifPermission: u.notifPermission || null,
        lineTeamName: u.lineTeamName || null,
        linePhone: u.linePhone || null,
        lastLogin: u.lastLogin || null,
        cbEtiqueta: !!(t.etiqueta && t.etiqueta.tagged),
        cbWa: !!(t.wa && t.wa.tagged),
        cbFavorito: !!(t.favorito && t.favorito.tagged),
        cbRespuesta: (t.respuesta && t.respuesta.status) || null
      };
    });
    return res.json({ items, q, total: items.length });
  } catch (err) {
    logger.error(`[users/search] error: ${err.message}`);
    return res.status(500).json({ error: err.message });
  }
});

// GET /api/admin/callbell/report?days=30
// Reporte diario: por día, cuántos etiquetados / WA enviados / convertidos
// (manual o auto) / sin respuesta. También conversion rate global.
app.get('/api/admin/callbell/report', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const days = Math.min(180, Math.max(1, parseInt(req.query.days, 10) || 30));
    const cutoff = new Date(Date.now() - days * 24 * 60 * 60 * 1000);

    // Auto-detección: para los etiquetados sin convertedAt y sin hadAppAtFirstTag,
    // chequear si ahora tienen app y setear convertedAt.
    const candidates = await CallbellTag.find({
      $or: [{ 'etiqueta.tagged': true }, { 'wa.tagged': true }],
      hadAppAtFirstTag: { $ne: true },
      convertedAt: null
    }, { usernameNorm: 1, _id: 1 }).lean();
    if (candidates.length > 0) {
      const norms = candidates.map(c => c.usernameNorm);
      // Buscar quiénes tienen standalone token ahora
      const usersWithApp = await User.find(
        {
          username: { $in: norms },
          $or: [
            { fcmTokenContext: 'standalone' },
            { 'fcmTokens.context': 'standalone' }
          ]
        },
        { username: 1, _id: 0 }
      ).lean();
      const convertedNorms = usersWithApp.map(u => String(u.username || '').toLowerCase());
      if (convertedNorms.length > 0) {
        await CallbellTag.updateMany(
          { usernameNorm: { $in: convertedNorms }, convertedAt: null },
          { $set: { convertedAt: new Date(), convertedBy: 'auto' } }
        );
        logger.info(`[callbell/report] auto-conversion: ${convertedNorms.length} users marcados como convertidos`);
      }
    }

    // Totales globales
    const [totalTagged, totalWA, totalConverted, totalNoContesto, totalInstalo] = await Promise.all([
      CallbellTag.countDocuments({ 'etiqueta.tagged': true }),
      CallbellTag.countDocuments({ 'wa.tagged': true }),
      CallbellTag.countDocuments({ convertedAt: { $ne: null } }),
      CallbellTag.countDocuments({ 'respuesta.status': 'no_contesto' }),
      CallbellTag.countDocuments({ 'respuesta.status': 'instalo' })
    ]);

    // Daily breakdown — agregamos por día (ART) los eventos.
    const tagDocs = await CallbellTag.find({
      $or: [
        { 'etiqueta.taggedAt': { $gte: cutoff } },
        { 'wa.taggedAt': { $gte: cutoff } },
        { 'respuesta.markedAt': { $gte: cutoff } },
        { convertedAt: { $gte: cutoff } }
      ]
    }, {
      'etiqueta.taggedAt': 1, 'wa.taggedAt': 1, 'respuesta': 1,
      convertedAt: 1, hadAppAtFirstTag: 1, _id: 0
    }).lean();

    const dayKeyOf = (d) => {
      if (!d) return null;
      const ms = new Date(d).getTime() - 3 * 60 * 60 * 1000;
      return new Date(ms).toISOString().slice(0, 10);
    };
    const byDay = new Map();
    const ensure = (k) => {
      if (!byDay.has(k)) byDay.set(k, { dayKey: k, etiquetados: 0, wa: 0, instalo: 0, noContesto: 0, convertedAuto: 0 });
      return byDay.get(k);
    };
    for (const d of tagDocs) {
      const ke = dayKeyOf(d.etiqueta && d.etiqueta.taggedAt);
      if (ke) ensure(ke).etiquetados++;
      const kw = dayKeyOf(d.wa && d.wa.taggedAt);
      if (kw) ensure(kw).wa++;
      const kr = dayKeyOf(d.respuesta && d.respuesta.markedAt);
      if (kr && d.respuesta.status === 'instalo') ensure(kr).instalo++;
      if (kr && d.respuesta.status === 'no_contesto') ensure(kr).noContesto++;
      const kc = dayKeyOf(d.convertedAt);
      if (kc && !d.hadAppAtFirstTag) ensure(kc).convertedAuto++;
    }
    const dailyArr = Array.from(byDay.values()).sort((a, b) => b.dayKey.localeCompare(a.dayKey));

    return res.json({
      totals: {
        totalTagged,
        totalWA,
        totalConverted,
        totalInstalo,
        totalNoContesto,
        conversionRatePct: totalTagged > 0 ? +(100 * totalConverted / totalTagged).toFixed(2) : 0
      },
      daily: dailyArr,
      windowDays: days
    });
  } catch (err) {
    logger.error(`[callbell/report] error: ${err.message}\n${err.stack}`);
    return res.status(500).json({ error: err.message });
  }
});

// Lista detallada de conversiones: etiquetados que instalaron la app
// DESPUÉS de haber sido marcados (no los que ya tenían app al etiquetar).
// Devuelve ordenado por fecha de conversión DESC para ir midiendo el avance.
app.get('/api/admin/callbell/conversions', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const limit = Math.min(500, Math.max(1, parseInt(req.query.limit, 10) || 200));

    const tags = await CallbellTag.find(
      {
        'etiqueta.tagged': true,
        convertedAt: { $ne: null },
        hadAppAtFirstTag: { $ne: true }
      },
      {
        usernameNorm: 1, username: 1,
        'etiqueta.taggedAt': 1, 'etiqueta.taggedBy': 1,
        'etiqueta.fromBucket': 1, 'etiqueta.fromTier': 1,
        convertedAt: 1, convertedBy: 1, _id: 0
      }
    ).sort({ convertedAt: -1 }).limit(limit).lean();

    if (tags.length === 0) {
      return res.json({ conversions: [], total: 0 });
    }

    const norms = tags.map(t => t.usernameNorm);
    const users = await User.find(
      { username: { $in: norms } },
      { username: 1, phone: 1, lineTeamName: 1, linePhone: 1, appFirstInstalledAt: 1, _id: 0 }
    ).lean();
    const userMap = new Map(users.map(u => [String(u.username || '').toLowerCase(), u]));

    const conversions = tags.map(t => {
      const u = userMap.get(t.usernameNorm) || {};
      const taggedAt = (t.etiqueta && t.etiqueta.taggedAt) || null;
      // Fecha de instalación REAL: appFirstInstalledAt si existe, sino el convertedAt detectado.
      const installedAt = u.appFirstInstalledAt || t.convertedAt || null;
      const daysToInstall = (taggedAt && installedAt)
        ? Math.max(0, Math.floor((new Date(installedAt).getTime() - new Date(taggedAt).getTime()) / (24 * 60 * 60 * 1000)))
        : null;
      return {
        username: t.username || t.usernameNorm,
        etiquetadoAt: taggedAt,
        etiquetadoBy: (t.etiqueta && t.etiqueta.taggedBy) || null,
        fromBucket: (t.etiqueta && t.etiqueta.fromBucket) || null,
        fromTier: (t.etiqueta && t.etiqueta.fromTier) || null,
        installedAt,
        convertedBy: t.convertedBy || null,
        daysToInstall,
        team: u.lineTeamName || null,
        linePhone: u.linePhone || null,
        phone: u.phone || null
      };
    });

    return res.json({ conversions, total: conversions.length });
  } catch (err) {
    logger.error(`[callbell/conversions] error: ${err.message}\n${err.stack}`);
    return res.status(500).json({ error: err.message });
  }
});

// DELETE /api/admin/callbell/conversions/:username
// Saca a un usuario de la lista de Post recontactación. NO borra el CallbellTag
// (preserva la etiqueta original — solo limpia los campos convertedAt + convertedBy
// para que el filtro convertedAt:{$ne:null} ya no lo agarre). Idempotente.
app.delete('/api/admin/callbell/conversions/:username', authMiddleware, superAdminMiddleware, async (req, res) => {
  try {
    const raw = String(req.params.username || '').trim();
    if (!raw) return res.status(400).json({ error: 'username requerido' });
    const norm = raw.toLowerCase().replace(/[^a-z0-9]/g, '');
    const r = await CallbellTag.updateOne(
      { usernameNorm: norm },
      { $set: { convertedAt: null, convertedBy: null } }
    );
    if (r.matchedCount === 0) return res.status(404).json({ error: 'No encontrada' });
    logger.info(`[callbell/conversions DELETE] ${raw} (norm=${norm}) by=${(req.user && req.user.username) || 'admin'}`);
    res.json({ success: true });
  } catch (err) {
    logger.error(`[callbell/conversions DELETE] ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// CSV con todos los items enriquecidos. Se manda en POST porque no podemos
// guardar el archivo en el server — el admin manda el xlsx de nuevo y
// recibimos el CSV directo. Así evitamos persistir state intermedio.
app.post(
  '/api/admin/recontact/export.csv',
  authMiddleware,
  adminMiddleware,
  express.json({ limit: '20mb' }),
  async (req, res) => {
    try {
      const items = (req.body && req.body.items) || [];
      if (!Array.isArray(items) || items.length === 0) {
        return res.status(400).json({ error: 'No hay items para exportar' });
      }
      const escape = (v) => {
        const s = (v == null ? '' : String(v));
        return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
      };
      const lines = ['Prioridad,Usuario,Tier,Bucket,DiasSinCargar,Cargas30d,Cargas90d,TotalCargas,DepositosArchivo,RetirosArchivo,BonosArchivo,NetoArchivo,CantDepositos,CantRetiros,CantBonos,TieneApp,TieneNotifs,Equipo,Linea,Telefono,Estrategia,BonoSugerido,MensajeSugerido,OfreceApp,OfreceNotifs'];
      for (const it of items) {
        lines.push([
          escape(it.priority),
          escape(it.username),
          escape(it.tier),
          escape(it.bucket),
          escape(it.daysSinceLastDeposit),
          escape(it.deposits30d),
          escape(it.deposits90d),
          escape(it.totalDeposits),
          escape(it.fileDeposits || 0),
          escape(it.fileWithdraws || 0),
          escape(it.fileBonuses || 0),
          escape(it.fileNet || 0),
          escape(it.fileCountDeposits || 0),
          escape(it.fileCountWithdraws || 0),
          escape(it.fileCountBonuses || 0),
          escape(it.hasApp ? 'Si' : 'No'),
          escape(it.hasNotifs ? 'Si' : 'No'),
          escape(it.team || ''),
          escape(it.linePhone || ''),
          escape(it.phone || ''),
          escape(it.strategy),
          escape(it.suggestedBonus),
          escape(it.suggestedMessage),
          escape(it.addAppOffer ? 'Si' : 'No'),
          escape(it.addNotifsOffer ? 'Si' : 'No')
        ].join(','));
      }
      const csv = '﻿' + lines.join('\r\n');
      res.setHeader('Content-Type', 'text/csv; charset=utf-8');
      res.setHeader('Content-Disposition', `attachment; filename="recontactacion-${new Date().toISOString().slice(0,10)}.csv"`);
      res.send(csv);
    } catch (err) {
      logger.error(`[recontact/export.csv] error: ${err.message}`);
      res.status(500).json({ error: err.message });
    }
  }
);

// XLSX multi-hoja: una hoja por bucket (Calientes / En riesgo / Perdidos /
// Inactivos), una hoja con los que tienen app+notifs (push directo), una
// con los que no tienen app (WhatsApp), más una de Resumen. Cada hoja trae
// columnas detalladas con equipo + línea WhatsApp para derivar.
app.post(
  '/api/admin/recontact/export.xlsx',
  authMiddleware,
  adminMiddleware,
  express.json({ limit: '20mb' }),
  async (req, res) => {
    let XLSX;
    try { XLSX = require('xlsx'); }
    catch (_) { return res.status(503).json({ error: 'Falta dependencia "xlsx"' }); }

    try {
      const items = (req.body && req.body.items) || [];
      const summary = (req.body && req.body.summary) || {};
      if (!Array.isArray(items) || items.length === 0) {
        return res.status(400).json({ error: 'No hay items para exportar' });
      }

      const fmtNum = (n) => Number(n || 0);
      const yesNo = (v) => v ? 'Si' : 'No';

      // Columnas standard que van en cada hoja de detalle.
      const buildRow = (it) => ({
        Prioridad: fmtNum(it.priority),
        Usuario: it.username || '',
        Tier: it.tier || '',
        Bucket: it.bucket || '',
        DiasSinCargar: it.daysSinceLastDeposit == null ? '' : Number(it.daysSinceLastDeposit),
        Cargas30d: fmtNum(it.deposits30d),
        Cargas90d: fmtNum(it.deposits90d),
        TotalCargas: fmtNum(it.totalDeposits),
        // Datos del archivo subido
        ArchCargas: fmtNum(it.fileDeposits),
        ArchRetiros: fmtNum(it.fileWithdraws),
        ArchBonos: fmtNum(it.fileBonuses),
        ArchNeto: fmtNum(it.fileNet),
        CantCargas: fmtNum(it.fileCountDeposits),
        CantRetiros: fmtNum(it.fileCountWithdraws),
        CantBonos: fmtNum(it.fileCountBonuses),
        // App/notifs
        TieneApp: yesNo(it.hasApp),
        TieneNotifs: yesNo(it.hasNotifs),
        // Equipo + línea (de Equipos / UserLineLookup)
        Equipo: it.team || '',
        LineaWhatsApp: it.linePhone || '',
        TelCliente: it.phone || '',
        // Estrategia
        Estrategia: it.strategy || '',
        BonoSugerido: fmtNum(it.suggestedBonus),
        MensajeSugerido: it.suggestedMessage || '',
        OfreceApp: yesNo(it.addAppOffer),
        OfreceNotifs: yesNo(it.addNotifsOffer)
      });

      // Particionar por bucket y por app status.
      const byBucket = { calientes: [], enRiesgo: [], perdidos: [], inactivos: [] };
      const conAppNotifs = [];
      const conAppSinNotifs = [];
      const sinApp = [];
      const sinLineaAsignada = [];
      for (const it of items) {
        const b = it.bucket || 'inactivos';
        if (byBucket[b]) byBucket[b].push(it);
        if (it.hasApp && it.hasNotifs) conAppNotifs.push(it);
        else if (it.hasApp && !it.hasNotifs) conAppSinNotifs.push(it);
        else sinApp.push(it);
        if (!it.team && !it.linePhone) sinLineaAsignada.push(it);
      }

      const wb = XLSX.utils.book_new();

      // Helper: agrega una hoja con headers en bold y autosize aproximado.
      const addSheet = (name, rows, leadingInfo) => {
        const data = [];
        if (leadingInfo && leadingInfo.length) {
          for (const r of leadingInfo) data.push(r);
          data.push([]); // separador
        }
        if (rows.length === 0) {
          data.push(['(sin items en esta categoría)']);
          const sheet = XLSX.utils.aoa_to_sheet(data);
          XLSX.utils.book_append_sheet(wb, sheet, name.slice(0, 31));
          return;
        }
        const headers = Object.keys(rows[0]);
        data.push(headers);
        for (const r of rows) data.push(headers.map(h => r[h]));
        const sheet = XLSX.utils.aoa_to_sheet(data);
        // Anchos aprox por columna (chars).
        const colWidths = headers.map(h => {
          let max = h.length;
          for (const r of rows) {
            const v = r[h] == null ? '' : String(r[h]);
            if (v.length > max) max = v.length;
          }
          return { wch: Math.min(Math.max(max + 1, 8), 60) };
        });
        sheet['!cols'] = colWidths;
        XLSX.utils.book_append_sheet(wb, sheet, name.slice(0, 31));
      };

      // 1) Resumen
      const resumen = [
        ['RECONTACTACIÓN — Resumen general', ''],
        ['Generado', new Date().toLocaleString('es-AR')],
        ['', ''],
        ['Total analizados', items.length],
        ['Encontrados en base', summary.foundInDb || 0],
        ['No encontrados', summary.notFound || 0],
        ['', ''],
        ['Con app + notifs (push directo)', conAppNotifs.length],
        ['Con app pero sin notifs', conAppSinNotifs.length],
        ['Sin app (solo WhatsApp)', sinApp.length],
        ['Sin línea asignada', sinLineaAsignada.length],
        ['', ''],
        ['Por bucket de actividad', ''],
        ['🔥 Calientes (0-10 días)', byBucket.calientes.length],
        ['⚠ En riesgo (10-20 días)', byBucket.enRiesgo.length],
        ['💔 Perdidos (20-30 días)', byBucket.perdidos.length],
        ['☠ Inactivos (+30 días)', byBucket.inactivos.length],
        ['', ''],
        ['Datos del archivo subido', ''],
        ['Total cargas', summary.fileTotalDeposits || 0],
        ['Total retiros', summary.fileTotalWithdraws || 0],
        ['Total bonos', summary.fileTotalBonuses || 0],
        ['Cantidad cargas', summary.fileCountDeposits || 0],
        ['Cantidad retiros', summary.fileCountWithdraws || 0],
        ['Cantidad bonos', summary.fileCountBonuses || 0],
        ['', ''],
        ['Bono total sugerido', summary.totalRecoverableValue || 0]
      ];
      const resSheet = XLSX.utils.aoa_to_sheet(resumen);
      resSheet['!cols'] = [{ wch: 38 }, { wch: 22 }];
      XLSX.utils.book_append_sheet(wb, resSheet, '📋 Resumen');

      // 2) Hojas por bucket
      addSheet('🔥 Calientes (0-10d)', byBucket.calientes.map(buildRow));
      addSheet('⚠ En riesgo (10-20d)', byBucket.enRiesgo.map(buildRow));
      addSheet('💔 Perdidos (20-30d)', byBucket.perdidos.map(buildRow));
      addSheet('☠ Inactivos (+30d)', byBucket.inactivos.map(buildRow));

      // 3) Hojas por estado de app
      addSheet('📱 Con app+notifs (PUSH)', conAppNotifs.map(buildRow));
      addSheet('🔕 Con app sin notifs', conAppSinNotifs.map(buildRow));
      addSheet('💬 Sin app (WhatsApp)', sinApp.map(buildRow));

      // 4) Hoja de los que no tienen línea asignada (huérfanos del archivo).
      addSheet('⚠ Sin línea asignada', sinLineaAsignada.map(buildRow));

      // 5) Hoja "Todos" con el universo completo, ordenado por prioridad.
      addSheet('🌐 Todos (por prioridad)', items.map(buildRow));

      const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });
      const filename = `recontactacion-${new Date().toISOString().slice(0, 10)}.xlsx`;
      res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
      res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
      res.send(buf);
    } catch (err) {
      logger.error(`[recontact/export.xlsx] error: ${err.message}\n${err.stack}`);
      res.status(500).json({ error: err.message });
    }
  }
);

// Cambiar el TELÉFONO de UNA línea sin afectar nada más. Actualiza User
// y UserLineLookup. NO manda push de aviso (eso es lineDown). Útil cuando
// el admin solo quiere corregir un número mal cargado.
// ============================================
// UNIFICAR EQUIPOS / LÍNEAS — preview + execute
// ============================================
// Permite mergear dos lineTeamName en uno solo. Útil cuando se cargaron
// dos veces el mismo equipo con nombres ligeramente distintos
// (ej: "Argentum" y "Argentum 1") y los queremos unificar.
//
// Mode "preview" (default): hace un análisis sin tocar nada — devuelve
// totales por lado, overlap (usernames duplicados), y para los
// duplicados dice cuántos tienen app en uno, en el otro, o en ambos.
//
// Mode "execute": hace el merge real. Updatea User.lineTeamName y
// UserLineLookup.lineTeamName desde "from" hacia "to". Para los
// duplicados: el doc del lado "from" se elimina y el del lado "to"
// se mantiene (asumiendo que es la versión correcta). NO toca FCM
// tokens, schedules ni nada que dispare notifs — sólo cambia el label
// del equipo.
app.post('/api/admin/teams/merge', authMiddleware, superAdminMiddleware, async (req, res) => {
  try {
    const from = String((req.body && req.body.from) || '').trim();
    const to = String((req.body && req.body.to) || '').trim();
    const mode = String((req.body && req.body.mode) || 'preview').toLowerCase();
    if (!from || !to) return res.status(400).json({ error: 'Faltan from y to' });
    if (from === to) return res.status(400).json({ error: 'from y to son iguales' });
    if (!['preview', 'execute'].includes(mode)) return res.status(400).json({ error: 'mode inválido' });

    // 1) Sacar usernames de cada lado en User y UserLineLookup
    const [usersFrom, usersTo, lookupFrom, lookupTo] = await Promise.all([
      User.find({ lineTeamName: from }, { username: 1, fcmTokens: 1, fcmTokenContext: 1, notifPermission: 1, _id: 0 }).lean(),
      User.find({ lineTeamName: to },   { username: 1, fcmTokens: 1, fcmTokenContext: 1, notifPermission: 1, _id: 0 }).lean(),
      UserLineLookup.find({ lineTeamName: from }, { usernameNorm: 1, _id: 0 }).lean(),
      UserLineLookup.find({ lineTeamName: to },   { usernameNorm: 1, _id: 0 }).lean()
    ]);

    const fromSet = new Set(usersFrom.map(u => String(u.username || '').toLowerCase()));
    const toSet   = new Set(usersTo.map(u => String(u.username || '').toLowerCase()));
    const overlap = [...fromSet].filter(u => toSet.has(u));

    // Contar app en cada lado.
    const isStandalone = (u) => {
      if (!u) return false;
      if (u.fcmTokenContext === 'standalone') return true;
      const tokens = Array.isArray(u.fcmTokens) ? u.fcmTokens : [];
      return tokens.some(t => t && t.context === 'standalone');
    };
    const isGranted = (u) => {
      if (!u) return false;
      if (u.notifPermission === 'granted') return true;
      const tokens = Array.isArray(u.fcmTokens) ? u.fcmTokens : [];
      return tokens.some(t => t && t.notifPermission === 'granted');
    };

    const fromMap = new Map(usersFrom.map(u => [String(u.username || '').toLowerCase(), u]));
    const toMap   = new Map(usersTo.map(u => [String(u.username || '').toLowerCase(), u]));

    let fromWithApp = 0, toWithApp = 0;
    let fromWithBoth = 0, toWithBoth = 0;
    for (const u of usersFrom) {
      const a = isStandalone(u);
      const b = isGranted(u);
      if (a) fromWithApp++;
      if (a && b) fromWithBoth++;
    }
    for (const u of usersTo) {
      const a = isStandalone(u);
      const b = isGranted(u);
      if (a) toWithApp++;
      if (a && b) toWithBoth++;
    }

    // De los duplicados: quiénes tienen app en uno, otro, o ambos.
    let dupAppOnlyFrom = 0, dupAppOnlyTo = 0, dupAppBoth = 0, dupAppNeither = 0;
    const dupSamples = [];
    for (const username of overlap) {
      const a = isStandalone(fromMap.get(username));
      const b = isStandalone(toMap.get(username));
      if (a && b) dupAppBoth++;
      else if (a) dupAppOnlyFrom++;
      else if (b) dupAppOnlyTo++;
      else dupAppNeither++;
      if (dupSamples.length < 25) dupSamples.push({ username, appFrom: a, appTo: b });
    }

    const lookupFromSet = new Set(lookupFrom.map(l => l.usernameNorm));
    const lookupToSet   = new Set(lookupTo.map(l => l.usernameNorm));
    const lookupOverlap = [...lookupFromSet].filter(u => lookupToSet.has(u));

    // Después del merge: cuántos únicos quedan
    const unionUsers = new Set([...fromSet, ...toSet]);
    const unionLookup = new Set([...lookupFromSet, ...lookupToSet]);

    const summary = {
      from, to, mode,
      sideFrom: {
        userDocs: usersFrom.length,
        lookupDocs: lookupFrom.length,
        withApp: fromWithApp,
        withBoth: fromWithBoth
      },
      sideTo: {
        userDocs: usersTo.length,
        lookupDocs: lookupTo.length,
        withApp: toWithApp,
        withBoth: toWithBoth
      },
      duplicatesUsers: overlap.length,
      duplicatesLookup: lookupOverlap.length,
      duplicatesAppBreakdown: {
        appBothSides: dupAppBoth,
        appOnlyFrom: dupAppOnlyFrom,
        appOnlyTo: dupAppOnlyTo,
        appNeither: dupAppNeither
      },
      afterMerge: {
        uniqueUsers: unionUsers.size,
        uniqueLookup: unionLookup.size
      },
      dupSamples
    };

    if (mode === 'preview') {
      return res.json({ success: true, preview: true, summary });
    }

    // === EXECUTE ===
    // 1) En User: para los duplicados, eliminamos el doc del lado "from"
    //    (mantenemos el "to" porque es el destino canónico). Para los
    //    no-duplicados de "from", actualizamos lineTeamName a "to".
    const overlapSet = new Set(overlap);
    const onlyFromUsers = [...fromSet].filter(u => !overlapSet.has(u));
    let userUpdatedCount = 0, userDeletedDupCount = 0;

    if (onlyFromUsers.length > 0) {
      const r = await User.updateMany(
        { lineTeamName: from, username: { $in: onlyFromUsers } },
        {
          $set: {
            lineTeamName: to,
            lineAssignedAt: new Date(),
            lineAssignedBy: (req.user && req.user.username) || 'admin',
            lineAssignmentNote: `Merge equipo: "${from}" → "${to}"`
          }
        }
      );
      userUpdatedCount = r.modifiedCount || 0;
    }
    if (overlap.length > 0) {
      // Borramos el lado "from" de los duplicados (el "to" gana).
      const r = await User.deleteMany({
        lineTeamName: from,
        username: { $in: overlap }
      });
      userDeletedDupCount = r.deletedCount || 0;
    }

    // 2) UserLineLookup: misma lógica.
    const lookupOverlapSet = new Set(lookupOverlap);
    const onlyFromLookup = [...lookupFromSet].filter(u => !lookupOverlapSet.has(u));
    let lookupUpdatedCount = 0, lookupDeletedDupCount = 0;
    if (onlyFromLookup.length > 0) {
      const r = await UserLineLookup.updateMany(
        { lineTeamName: from, usernameNorm: { $in: onlyFromLookup } },
        { $set: { lineTeamName: to } }
      );
      lookupUpdatedCount = r.modifiedCount || 0;
    }
    if (lookupOverlap.length > 0) {
      const r = await UserLineLookup.deleteMany({
        lineTeamName: from,
        usernameNorm: { $in: lookupOverlap }
      });
      lookupDeletedDupCount = r.deletedCount || 0;
    }

    logger.info(`[teams/merge] from="${from}" to="${to}" by=${(req.user && req.user.username) || 'admin'} userUpdated=${userUpdatedCount} userDeletedDup=${userDeletedDupCount} lookupUpdated=${lookupUpdatedCount} lookupDeletedDup=${lookupDeletedDupCount}`);

    return res.json({
      success: true,
      preview: false,
      summary,
      executed: {
        userDocsRenamedFromTo: userUpdatedCount,
        userDocsDeletedDup: userDeletedDupCount,
        lookupDocsRenamedFromTo: lookupUpdatedCount,
        lookupDocsDeletedDup: lookupDeletedDupCount
      }
    });
  } catch (err) {
    logger.error(`[teams/merge] error: ${err.message}\n${err.stack}`);
    return res.status(500).json({ error: err.message });
  }
});

app.post('/api/admin/user-lines/change-phone', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const teamName = String((req.body && req.body.teamName) || '').trim();
    const oldPhone = String((req.body && req.body.oldPhone) || '').trim();
    const newPhoneRaw = String((req.body && req.body.newPhone) || '').trim();
    if (!teamName || !oldPhone || !newPhoneRaw) {
      return res.status(400).json({ error: 'Faltan teamName / oldPhone / newPhone' });
    }
    const digits = newPhoneRaw.replace(/[^\d]/g, '');
    if (digits.length < 7 || digits.length > 18) {
      return res.status(400).json({ error: `newPhone inválido (${digits.length} dígitos)` });
    }
    const newPhone = '+' + digits;
    if (newPhone === oldPhone) {
      return res.status(400).json({ error: 'El número nuevo es igual al actual' });
    }

    const userResult = await User.updateMany(
      { lineTeamName: teamName, linePhone: oldPhone },
      { $set: { linePhone: newPhone, lineAssignedAt: new Date(), lineAssignedBy: (req.user && req.user.username) || 'admin', lineAssignmentNote: 'Phone cambiado: ' + oldPhone + ' → ' + newPhone } }
    );
    const lookupResult = await UserLineLookup.updateMany(
      { lineTeamName: teamName, linePhone: oldPhone },
      { $set: { linePhone: newPhone } }
    );

    logger.info(`[user-lines/change-phone] team="${teamName}" ${oldPhone} → ${newPhone} usersUpdated=${userResult.modifiedCount || 0} lookupUpdated=${lookupResult.modifiedCount || 0} by=${(req.user && req.user.username) || 'admin'}`);

    res.json({
      success: true,
      teamName,
      oldPhone,
      newPhone,
      usersUpdated: userResult.modifiedCount || 0,
      lookupUpdated: lookupResult.modifiedCount || 0
    });
  } catch (error) {
    logger.error(`[user-lines/change-phone] error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// Renombrar UNA línea (cambiar la etiqueta después de "Equipo · ").
// Recibe: { teamName (label completo actual, ej "Oro · Línea 1"), linePhone,
//          newLabel (la parte después del " · " — si vacío, queda solo "Oro") }
// Actualiza User.lineTeamName y UserLineLookup.lineTeamName en bloque.
// NO afecta otras líneas del equipo ni el linePhone.
app.post('/api/admin/user-lines/rename-line', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const teamName = String((req.body && req.body.teamName) || '').trim();
    const linePhone = String((req.body && req.body.linePhone) || '').trim();
    const newLabel = String((req.body && req.body.newLabel) || '').trim().slice(0, 32);
    if (!teamName) return res.status(400).json({ error: 'Falta teamName' });
    if (!linePhone) return res.status(400).json({ error: 'Falta linePhone' });

    // Calcular el nuevo fullLabel respetando el prefix del equipo.
    const sepIdx = teamName.indexOf(' · ');
    const teamPrefix = sepIdx >= 0 ? teamName.slice(0, sepIdx) : teamName;
    const newFullLabel = newLabel ? `${teamPrefix} · ${newLabel}` : teamPrefix;

    if (newFullLabel === teamName) {
      return res.status(400).json({ error: 'El nombre nuevo es igual al actual' });
    }

    const userResult = await User.updateMany(
      { lineTeamName: teamName, linePhone },
      { $set: { lineTeamName: newFullLabel, lineAssignedAt: new Date(), lineAssignedBy: (req.user && req.user.username) || 'admin', lineAssignmentNote: 'Renombrado: ' + teamName + ' → ' + newFullLabel } }
    );
    const lookupResult = await UserLineLookup.updateMany(
      { lineTeamName: teamName, linePhone },
      { $set: { lineTeamName: newFullLabel } }
    );

    logger.info(`[user-lines/rename-line] "${teamName}" → "${newFullLabel}" phone=${linePhone} usersUpdated=${userResult.modifiedCount || 0} lookupUpdated=${lookupResult.modifiedCount || 0} by=${(req.user && req.user.username) || 'admin'}`);

    res.json({
      success: true,
      oldName: teamName,
      newName: newFullLabel,
      usersUpdated: userResult.modifiedCount || 0,
      lookupUpdated: lookupResult.modifiedCount || 0
    });
  } catch (error) {
    logger.error(`[user-lines/rename-line] error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// Diagnóstico: para una línea específica, devuelve detalles de la asignación
// de cada user (cuándo se asignó, source, si tiene match en xlsx). Sirve
// para auditar si un merge dejó users en la línea correcta o si quedaron
// huérfanos / mal asignados.
app.get('/api/admin/user-lines/diagnose-line', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const teamName = String(req.query.teamName || '').trim();
    const linePhone = String(req.query.linePhone || '').trim();
    if (!teamName && !linePhone) {
      return res.status(400).json({ error: 'Faltan params teamName o linePhone' });
    }

    const userFilter = {};
    if (teamName) userFilter.lineTeamName = teamName;
    if (linePhone) userFilter.linePhone = linePhone;
    const users = await User.find(
      userFilter,
      { username: 1, linePhone: 1, lineTeamName: 1, lineAssignedAt: 1, lineAssignedBy: 1, lineAssignmentSource: 1, _id: 0 }
    ).limit(2000).lean();

    // Usernames del UserLineLookup para esta línea (los del xlsx).
    const lookupFilter = {};
    if (teamName) lookupFilter.lineTeamName = teamName;
    if (linePhone) lookupFilter.linePhone = linePhone;
    const lookup = await UserLineLookup.find(lookupFilter).select('usernameNorm').lean();
    const xlsxSet = new Set(lookup.map(l => String(l.usernameNorm || '').toLowerCase()));

    // Bucketizar
    const bySource = {};
    let inXlsx = 0, notInXlsx = 0;
    for (const u of users) {
      const src = u.lineAssignmentSource || 'unknown';
      bySource[src] = (bySource[src] || 0) + 1;
      if (xlsxSet.has(String(u.username || '').toLowerCase())) inXlsx++;
      else notInXlsx++;
    }

    res.json({
      teamName: teamName || null,
      linePhone: linePhone || null,
      totalUsers: users.length,
      inXlsx,           // users en User asignados a esta línea Y en el xlsx → match perfecto
      notInXlsx,        // users en User asignados a esta línea PERO NO en el xlsx → cayeron por otro mecanismo
      bySource,         // breakdown por source: drive-import, lookup, prefix-fallback, etc.
      sampleNotInXlsx: users
        .filter(u => !xlsxSet.has(String(u.username || '').toLowerCase()))
        .slice(0, 20)
        .map(u => ({
          username: u.username,
          lineAssignedAt: u.lineAssignedAt,
          source: u.lineAssignmentSource || null
        }))
    });
  } catch (err) {
    logger.error(`/api/admin/user-lines/diagnose-line: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// Borra TODAS las asignaciones de UNA línea específica (teamName + linePhone),
// sin tocar otras líneas del mismo equipo. Útil para "vaciar" una línea
// antes de cargar un archivo nuevo y que el admin no quede con sobras.
//   - User: pone linePhone/lineTeamName a null SOLO para users de esa línea.
//   - UserLineLookup: borra las entradas (xlsx pre-asignados) de esa línea.
app.post('/api/admin/user-lines/clear-line', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const teamName = String((req.body && req.body.teamName) || '').trim();
    const linePhone = String((req.body && req.body.linePhone) || '').trim();
    if (!teamName && !linePhone) {
      return res.status(400).json({ error: 'Faltan teamName o linePhone' });
    }
    const userFilter = {};
    const lookupFilter = {};
    if (teamName)  { userFilter.lineTeamName = teamName; lookupFilter.lineTeamName = teamName; }
    if (linePhone) { userFilter.linePhone = linePhone; lookupFilter.linePhone = linePhone; }

    const userResult = await User.updateMany(
      userFilter,
      { $set: { linePhone: null, lineTeamName: null, lineAssignedAt: null, lineAssignedBy: null, lineAssignmentSource: null } }
    );
    const lookupResult = await UserLineLookup.deleteMany(lookupFilter);

    logger.info(`[user-lines/clear-line] team="${teamName}" phone=${linePhone} clearedUsers=${userResult.modifiedCount || 0} deletedLookups=${lookupResult.deletedCount || 0} by=${(req.user && req.user.username) || 'admin'}`);

    res.json({
      success: true,
      teamName: teamName || null,
      linePhone: linePhone || null,
      clearedUsers: userResult.modifiedCount || 0,
      deletedLookups: lookupResult.deletedCount || 0
    });
  } catch (error) {
    logger.error(`[user-lines/clear-line] error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

app.post('/api/admin/user-lines/clear-team', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const { teamName } = req.body || {};
    if (!teamName || typeof teamName !== 'string' || !teamName.trim()) {
      return res.status(400).json({ error: 'Falta teamName' });
    }
    const cleanTeam = teamName.trim();
    const r = await User.updateMany(
      { lineTeamName: cleanTeam },
      { $set: { linePhone: null, lineTeamName: null, lineAssignedAt: null, lineAssignedBy: null } }
    );
    res.json({
      success: true,
      teamName: cleanTeam,
      cleared: r.modifiedCount || 0
    });
  } catch (error) {
    logger.error(`[user-lines/clear-team] error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// Stats de asignaciones de línea (para mostrar resumen en el panel admin).
// =============================================================
// Stats por equipo: agrupa lineTeamName por la parte antes del " · "
// y devuelve, para cada equipo, total de usuarios + canal abierto +
// activos en la semana + desglose por línea dentro del equipo.
// =============================================================
// Endpoint "lite": solo los nombres de equipo, sin stats. Usado por features
// que necesitan poblar selectores (líneas caídas, refund-reminders) y que
// no requieren ver el detalle gateado por PIN.
app.get('/api/admin/teams/names', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const teams = await User.distinct('lineTeamName', {
      role: 'user',
      lineTeamName: { $exists: true, $ne: null, $nin: [''] }
    });
    const sorted = (teams || []).filter(Boolean).sort((a, b) => a.localeCompare(b, 'es-AR'));
    res.json({ teams: sorted.map(teamName => ({ teamName })) });
  } catch (error) {
    logger.error(`/api/admin/teams/names: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// Stats agregados por equipo (PII + métricas). Gateado por PIN 'teams' —
// sin el PIN, un depositor/withdrawer (o admin con cookie robada) no puede
// bajar el detalle completo de cada equipo.
app.get('/api/admin/teams/stats', authMiddleware, adminMiddleware, requireSectionPin('teams'), async (req, res) => {
  try {
    const oneWeekAgo = Date.now() - 7 * 24 * 3600 * 1000;

    // Agregación por línea (lineTeamName trim()) DENTRO de Mongo: en vez de
    // bajar TODOS los users a Node, el pipeline deriva por-user hasChannel
    // (igual que APP_NOTIFS_FILTER: AMBAS condiciones en el MISMO token, o
    // legacy single-token con ambos) y isActiveThisWeek, y suma por línea.
    // El re-agrupado teamPrefix (split " · ") se hace después con ~N líneas
    // (muchos menos docs que usuarios).
    const lineAgg = await User.aggregate([
      { $match: { role: 'user' } },
      {
        $project: {
          _id: 0,
          fullLabel: { $trim: { input: { $ifNull: ['$lineTeamName', ''] } } },
          linePhone: 1,
          // legacy single-token: context standalone + notifPermission granted
          legacyMatch: {
            $and: [
              { $eq: ['$fcmTokenContext', 'standalone'] },
              { $eq: ['$notifPermission', 'granted'] }
            ]
          },
          // array: algún token con context standalone + notifPermission granted
          arrayMatch: {
            $gt: [
              {
                $size: {
                  $filter: {
                    input: { $ifNull: ['$fcmTokens', []] },
                    as: 't',
                    cond: {
                      $and: [
                        { $eq: ['$$t.context', 'standalone'] },
                        { $eq: ['$$t.notifPermission', 'granted'] }
                      ]
                    }
                  }
                }
              },
              0
            ]
          },
          isActiveThisWeek: {
            $and: [
              { $ne: ['$lastLogin', null] },
              {
                $gte: [
                  {
                    $convert: {
                      input: '$lastLogin',
                      to: 'date',
                      onError: new Date(0),
                      onNull: new Date(0)
                    }
                  },
                  new Date(oneWeekAgo)
                ]
              }
            ]
          }
        }
      },
      {
        $project: {
          fullLabel: 1,
          linePhone: 1,
          isActiveThisWeek: 1,
          hasChannel: { $or: ['$legacyMatch', '$arrayMatch'] }
        }
      },
      {
        $group: {
          _id: '$fullLabel',
          count: { $sum: 1 },
          withChannel: { $sum: { $cond: ['$hasChannel', 1, 0] } },
          activeThisWeek: { $sum: { $cond: ['$isActiveThisWeek', 1, 0] } },
          // linePhone representativo de la línea (igual que antes: el primero
          // visto). $first sobre el grupo.
          linePhone: { $first: '$linePhone' }
        }
      }
    ]);

    const teams = new Map(); // teamPrefix -> { totalUsers, withChannel, activeThisWeek, lines: Map }

    let totalWithTeam = 0;
    let totalWithoutTeam = 0;
    let totalUsers = 0;

    for (const lg of lineAgg) {
      const fullLabel = String(lg._id || '').trim();
      const cnt = lg.count || 0;
      totalUsers += cnt;
      if (!fullLabel) {
        totalWithoutTeam += cnt;
        continue;
      }
      totalWithTeam += cnt;

      // Equipo = parte antes del primer " · " (si existe). Si no hay " · ",
      // el label completo ES el equipo (sin sub-línea).
      const sepIdx = fullLabel.indexOf(' · ');
      const teamPrefix = sepIdx >= 0 ? fullLabel.slice(0, sepIdx) : fullLabel;

      let team = teams.get(teamPrefix);
      if (!team) {
        team = {
          teamName: teamPrefix,
          totalUsers: 0,
          withChannel: 0,
          activeThisWeek: 0,
          lines: new Map() // fullLabel -> { fullLabel, linePhone, count, withChannel, activeThisWeek }
        };
        teams.set(teamPrefix, team);
      }
      team.totalUsers += cnt;
      team.withChannel += (lg.withChannel || 0);
      team.activeThisWeek += (lg.activeThisWeek || 0);

      // Sub-grupo por línea exacta (incluye la etiqueta opcional).
      let line = team.lines.get(fullLabel);
      if (!line) {
        line = {
          fullLabel,
          linePhone: lg.linePhone || null,
          count: 0,
          withChannel: 0,
          activeThisWeek: 0
        };
        team.lines.set(fullLabel, line);
      }
      line.count += cnt;
      line.withChannel += (lg.withChannel || 0);
      line.activeThisWeek += (lg.activeThisWeek || 0);
    }

    // Pre-asignaciones pendientes (UserLineLookup): cuenta por equipo de los
    // usuarios que están en el archivo pero todavía NO se registraron.
    let pendingByTeam = new Map();
    try {
      const pendings = await UserLineLookup.aggregate([
        { $match: { lineTeamName: { $ne: null } } },
        { $group: { _id: '$lineTeamName', count: { $sum: 1 } } }
      ]);
      for (const p of pendings) {
        const fullLabel = String(p._id || '').trim();
        if (!fullLabel) continue;
        const sepIdx = fullLabel.indexOf(' · ');
        const teamPrefix = sepIdx >= 0 ? fullLabel.slice(0, sepIdx) : fullLabel;
        pendingByTeam.set(teamPrefix, (pendingByTeam.get(teamPrefix) || 0) + (p.count || 0));
      }
    } catch (lookupErr) {
      logger.warn(`[teams/stats] lookup agg falló: ${lookupErr.message}`);
    }

    // Convertir Maps a array y sortear.
    const teamsArr = Array.from(teams.values()).map(t => ({
      teamName: t.teamName,
      totalUsers: t.totalUsers,
      withChannel: t.withChannel,
      channelPct: t.totalUsers > 0 ? Math.round((t.withChannel / t.totalUsers) * 100) : 0,
      activeThisWeek: t.activeThisWeek,
      activePct: t.totalUsers > 0 ? Math.round((t.activeThisWeek / t.totalUsers) * 100) : 0,
      pendingPreAssigned: pendingByTeam.get(t.teamName) || 0,
      lines: Array.from(t.lines.values()).sort((a, b) => b.count - a.count)
    })).sort((a, b) => b.totalUsers - a.totalUsers);

    // Equipos que SOLO tienen pre-asignados (nadie registrado todavía):
    // mostrarlos también para que el admin vea que la lista está cargada.
    for (const [teamPrefix, count] of pendingByTeam) {
      if (!teams.has(teamPrefix)) {
        teamsArr.push({
          teamName: teamPrefix,
          totalUsers: 0,
          withChannel: 0,
          channelPct: 0,
          activeThisWeek: 0,
          activePct: 0,
          pendingPreAssigned: count,
          lines: []
        });
      }
    }

    res.json({
      success: true,
      totalUsers: totalUsers,
      totalWithTeam,
      totalWithoutTeam,
      teams: teamsArr
    });
  } catch (error) {
    logger.error(`/api/admin/teams/stats error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

app.get('/api/admin/user-lines/stats', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const pipeline = [
      { $match: { linePhone: { $ne: null, $exists: true } } },
      {
        $group: {
          _id: { teamName: '$lineTeamName', linePhone: '$linePhone' },
          count: { $sum: 1 }
        }
      },
      { $sort: { '_id.teamName': 1, '_id.linePhone': 1 } }
    ];
    const groups = await User.aggregate(pipeline);
    const totalAssigned = groups.reduce((acc, g) => acc + (g.count || 0), 0);
    const totalUsers = await User.countDocuments({});
    res.json({
      totalUsers,
      totalAssigned,
      totalUnassigned: totalUsers - totalAssigned,
      lines: groups.map(g => ({
        teamName: g._id.teamName || '(sin team)',
        linePhone: g._id.linePhone,
        count: g.count
      }))
    });
  } catch (error) {
    logger.error(`[user-lines/stats] error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// ============================================
// LINKS DE COMUNIDAD POR USUARIO (mapeo prefijo -> link)
// ============================================================================
// POST /api/admin/user-communities/import-list — sube xlsx con usernames
// para asignarlos a una comunidad específica + manda push notif.
// ============================================================================
// Body params (query):
//   communityLink  = wa.me/... o link de invitación al grupo (REQUIRED)
//   communityLabel = nombre display (opcional, ej "Comunidad Sur")
//   notify         = "true" para mandar push a los users asignados (default true)
//   dryRun         = "true" para preview sin escribir DB
// Body raw: archivo .xlsx con una columna "name" (usernames)
app.post(
  '/api/admin/user-communities/import-list',
  authMiddleware,
  adminMiddleware,
  express.raw({ limit: '8mb', type: '*/*' }),
  async (req, res) => {
    let XLSX;
    try { XLSX = require('xlsx'); }
    catch (e) { return res.status(503).json({ error: 'Falta xlsx en server' }); }

    try {
      const communityLink = String((req.query.communityLink || '')).trim();
      const communityLabel = String((req.query.communityLabel || '')).trim().slice(0, 60);
      const notify = String(req.query.notify || 'true').toLowerCase() !== 'false';
      const dryRun = String(req.query.dryRun || 'false').toLowerCase() === 'true';

      if (!communityLink) return res.status(400).json({ error: 'Falta communityLink' });
      if (!/^https?:\/\//i.test(communityLink)) {
        return res.status(400).json({ error: 'communityLink debe empezar con http:// o https://' });
      }

      const buf = req.body;
      if (!buf || !Buffer.isBuffer(buf) || buf.length < 50) {
        return res.status(400).json({ error: 'Archivo vacío o muy chico' });
      }

      let workbook;
      try { workbook = XLSX.read(buf, { type: 'buffer', cellDates: false }); }
      catch (e) { return res.status(400).json({ error: `No se pudo leer xlsx: ${e.message}` }); }

      // Recolectar usernames (columna "name" o primera columna).
      const usernames = new Set();
      for (const sheetName of (workbook.SheetNames || [])) {
        const ws = workbook.Sheets[sheetName];
        if (!ws) continue;
        const rows = XLSX.utils.sheet_to_json(ws, { header: 1, blankrows: false, defval: '' });
        if (rows.length === 0) continue;
        // Detectar header: si primera fila parece "name"/"username"/"usuario", saltearla.
        const firstCell = String((rows[0] && rows[0][0]) || '').trim().toLowerCase();
        const startIdx = ['name','username','usuario','user'].includes(firstCell) ? 1 : 0;
        for (let i = startIdx; i < rows.length; i++) {
          const cell = rows[i] && rows[i][0];
          if (!cell) continue;
          const u = String(cell).trim();
          if (u) usernames.add(u);
        }
      }

      if (usernames.size === 0) {
        return res.status(400).json({ error: 'No se encontraron usernames en el xlsx' });
      }
      if (usernames.size > 5000) {
        return res.status(400).json({ error: 'Máximo 5000 usernames por import' });
      }

      const list = Array.from(usernames);
      const adminUser = req.user.username || null;

      if (dryRun) {
        return res.json({
          success: true,
          dryRun: true,
          totalRowsRead: list.length,
          sample: list.slice(0, 20)
        });
      }

      // Upsert por usernameNorm.
      let upserted = 0, modified = 0;
      const ops = [];
      for (const u of list) {
        const norm = u.toLowerCase().trim();
        ops.push({
          updateOne: {
            filter: { usernameNorm: norm },
            update: {
              $set: {
                username: u,
                usernameNorm: norm,
                communityLink,
                communityLabel: communityLabel || null,
                status: 'active',
                replacementLink: null,
                replacementLabel: null,
                assignedAt: new Date(),
                assignedBy: adminUser
              },
              $inc: { version: 1 }
            },
            upsert: true
          }
        });
      }
      try {
        const r = await UserCommunityLookup.bulkWrite(ops, { ordered: false });
        upserted = (r && r.upsertedCount) || 0;
        modified = (r && r.modifiedCount) || 0;
      } catch (e) {
        logger.error(`[user-communities] bulkWrite: ${e.message}`);
        return res.status(500).json({ error: 'Error guardando asignaciones' });
      }

      // Push notif a los usuarios asignados.
      let pushed = 0;
      if (notify && list.length > 0) {
        try {
          const norms = list.map(u => u.toLowerCase().trim());
          const users = await User.find(
            { username: { $in: list.map(u => new RegExp('^' + u.replace(/[.*+?^${}()|[\]\\]/g,'\\$&') + '$', 'i')) } },
            { fcmToken: 1, fcmTokens: 1, username: 1 }
          ).lean();
          const title = '🎉 Nueva comunidad';
          const body = communityLabel
            ? `Te sumamos a "${communityLabel}". Entrá para tener el canal informativo de nuestro servicio y novedades.`
            : 'Te sumamos a una nueva comunidad. Entrá para tener el canal informativo de nuestro servicio y novedades.';
          const sendPromises = [];
          for (const u of users) {
            const tokens = [];
            if (u.fcmToken) tokens.push(u.fcmToken);
            if (Array.isArray(u.fcmTokens)) {
              for (const tk of u.fcmTokens) { const t = tk && tk.token ? tk.token : tk; if (t && !tokens.includes(t)) tokens.push(t); }
            }
            for (const tk of tokens) {
              sendPromises.push(
                _sendPushToUser(tk, title, body, { source: 'new-community', communityLink })
                  .then(r => { if (r && r.success) pushed++; })
                  .catch(() => {})
              );
            }
          }
          await Promise.all(sendPromises);
        } catch (e) { logger.warn(`[user-communities] push falló: ${e.message}`); }
      }

      logger.info(`[user-communities] import label="${communityLabel}" assigned=${list.length} upserted=${upserted} modified=${modified} pushed=${pushed} by=${adminUser}`);
      res.json({
        success: true,
        assigned: list.length,
        upserted, modified, pushed,
        communityLabel, communityLink
      });
    } catch (err) {
      logger.error(`/api/admin/user-communities/import-list: ${err.message}`);
      res.status(500).json({ error: err.message });
    }
  }
);

// ============================================================================
// COMMUNITY LINK CLICK TRACKING — cuenta cuántos users tappean el link.
// ============================================================================
const CommunityLinkClick = require('./src/models/CommunityLinkClick');

function _communityDateKeyART() {
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Argentina/Buenos_Aires',
    year: 'numeric', month: '2-digit', day: '2-digit'
  });
  return formatter.format(new Date());
}

// POST /api/community/link-click — user tappea el link. Fire and forget.
app.post('/api/community/link-click', authMiddleware, async (req, res) => {
  try {
    const userId = req.user.userId;
    const username = String(req.user.username || '').toLowerCase();
    const source = String((req.body && req.body.source) || 'home_button').trim();
    const communityLink = String((req.body && req.body.communityLink) || '').slice(0, 300).trim();
    const validSources = ['home_button', 'home_button_2', 'modal_join', 'replacement'];
    const safeSource = validSources.includes(source) ? source : 'home_button';
    // Calculamos teamPrefix: el match más largo contra userCommunitiesByPrefix,
    // o fallback a los 3 primeros chars.
    let teamPrefix = '';
    try {
      const cfg = await getConfig('userCommunitiesByPrefix');
      if (cfg && Array.isArray(cfg.slots)) {
        let best = null;
        for (const s of cfg.slots) {
          if (!s || !s.prefix) continue;
          const p = String(s.prefix).toLowerCase().trim();
          if (username.startsWith(p) && (!best || p.length > best.length)) best = p;
        }
        if (best) teamPrefix = best;
      }
    } catch (_) {}
    if (!teamPrefix) teamPrefix = username.slice(0, 3);

    await CommunityLinkClick.create({
      userId, username,
      teamPrefix,
      communityLink,
      source: safeSource,
      dateKey: _communityDateKeyART(),
      clickedAt: new Date()
    });
    res.json({ success: true });
  } catch (err) {
    logger.error(`/api/community/link-click: ${err.message}`);
    res.status(500).json({ error: 'Error' });
  }
});

// GET /api/admin/community/link-stats — agregados por día + por equipo
// + top users + total general.
app.get('/api/admin/community/link-stats', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const days = Math.max(1, Math.min(60, Number(req.query.days) || 14));
    const sinceDate = new Date(Date.now() - days * 24 * 3600 * 1000);

    const [byDay, byTeam, byDayTeam, byCommunity, byCommunityDay, topUsers, total, bySource, byTeamSource] = await Promise.all([
      // Total clicks por día (últimos N días).
      CommunityLinkClick.aggregate([
        { $match: { clickedAt: { $gte: sinceDate } } },
        { $group: { _id: '$dateKey', clicks: { $sum: 1 }, uniqueUsers: { $addToSet: '$userId' } } },
        { $project: { dateKey: '$_id', clicks: 1, uniqueUsers: { $size: '$uniqueUsers' } } },
        { $sort: { dateKey: -1 } }
      ]),
      // Total clicks por equipo/prefijo.
      CommunityLinkClick.aggregate([
        { $match: { clickedAt: { $gte: sinceDate } } },
        { $group: { _id: '$teamPrefix', clicks: { $sum: 1 }, uniqueUsers: { $addToSet: '$userId' } } },
        { $project: { teamPrefix: '$_id', clicks: 1, uniqueUsers: { $size: '$uniqueUsers' } } },
        { $sort: { clicks: -1 } }
      ]),
      // Cruzado día x equipo (para tabla detallada).
      CommunityLinkClick.aggregate([
        { $match: { clickedAt: { $gte: sinceDate } } },
        { $group: { _id: { dateKey: '$dateKey', teamPrefix: '$teamPrefix' }, clicks: { $sum: 1 } } },
        { $project: { dateKey: '$_id.dateKey', teamPrefix: '$_id.teamPrefix', clicks: 1, _id: 0 } },
        { $sort: { dateKey: -1, clicks: -1 } }
      ]),
      // Total clicks por COMUNIDAD (link) — sirve para comparar
      // cuál comunidad performa mejor, independiente del prefijo.
      CommunityLinkClick.aggregate([
        { $match: { clickedAt: { $gte: sinceDate }, communityLink: { $ne: '' } } },
        { $group: {
          _id: '$communityLink',
          clicks: { $sum: 1 },
          uniqueUsers: { $addToSet: '$userId' },
          uniqueTeams: { $addToSet: '$teamPrefix' },
          firstClick: { $min: '$clickedAt' },
          lastClick: { $max: '$clickedAt' }
        }},
        { $project: {
          communityLink: '$_id',
          clicks: 1,
          uniqueUsers: { $size: '$uniqueUsers' },
          uniqueTeams: { $size: '$uniqueTeams' },
          firstClick: 1, lastClick: 1, _id: 0
        }},
        { $sort: { clicks: -1 } }
      ]),
      // Cruzado comunidad x día (para chart por comunidad).
      CommunityLinkClick.aggregate([
        { $match: { clickedAt: { $gte: sinceDate }, communityLink: { $ne: '' } } },
        { $group: {
          _id: { communityLink: '$communityLink', dateKey: '$dateKey' },
          clicks: { $sum: 1 }
        }},
        { $project: {
          communityLink: '$_id.communityLink',
          dateKey: '$_id.dateKey',
          clicks: 1, _id: 0
        }},
        { $sort: { dateKey: -1 } }
      ]),
      // Top 10 users que más click hicieron.
      CommunityLinkClick.aggregate([
        { $match: { clickedAt: { $gte: sinceDate } } },
        { $group: { _id: '$username', clicks: { $sum: 1 }, lastClick: { $max: '$clickedAt' } } },
        { $sort: { clicks: -1, lastClick: -1 } },
        { $limit: 10 }
      ]),
      CommunityLinkClick.countDocuments({ clickedAt: { $gte: sinceDate } }),
      // Breakdown por source — para ver Comunidad 1 vs Comunidad 2 vs
      // modal forzado vs reemplazo.
      CommunityLinkClick.aggregate([
        { $match: { clickedAt: { $gte: sinceDate } } },
        { $group: { _id: '$source', clicks: { $sum: 1 }, uniqueUsers: { $addToSet: '$userId' } } },
        { $project: { source: '$_id', clicks: 1, uniqueUsers: { $size: '$uniqueUsers' }, _id: 0 } },
        { $sort: { clicks: -1 } }
      ]),
      // Cruzado team x source (para mostrar por cada equipo cuántos
      // entraron a Comunidad 1 vs Comunidad 2).
      CommunityLinkClick.aggregate([
        { $match: { clickedAt: { $gte: sinceDate } } },
        { $group: {
          _id: { teamPrefix: '$teamPrefix', source: '$source' },
          clicks: { $sum: 1 },
          uniqueUsers: { $addToSet: '$userId' }
        }},
        { $project: {
          teamPrefix: '$_id.teamPrefix',
          source: '$_id.source',
          clicks: 1,
          uniqueUsers: { $size: '$uniqueUsers' },
          _id: 0
        }}
      ])
    ]);

    // Enriquecemos byCommunity con el label desde userCommunitiesByPrefix
    // y desde UserCommunityLookup (asignaciones explícitas por xlsx).
    let communityLabels = new Map(); // link -> label
    try {
      const cfg = await getConfig('userCommunitiesByPrefix').catch(() => null);
      if (cfg && Array.isArray(cfg.slots)) {
        for (const s of cfg.slots) {
          if (!s) continue;
          if (s.link) {
            const lbl = s.label || (s.prefix ? `Equipo "${s.prefix}" · Comunidad 1` : 'Comunidad 1');
            communityLabels.set(s.link, lbl);
          }
          if (s.link2) {
            const lbl2 = s.label2 || (s.prefix ? `Equipo "${s.prefix}" · Comunidad 2` : 'Comunidad 2');
            communityLabels.set(s.link2, lbl2);
          }
        }
      }
      // Labels desde UserCommunityLookup (más prioritario porque suele
      // tener label real cargado por el admin al subir xlsx).
      const explicits = await UserCommunityLookup.aggregate([
        { $group: { _id: '$communityLink', label: { $first: '$communityLabel' } } }
      ]);
      for (const e of explicits) {
        if (e._id && e.label) communityLabels.set(e._id, e.label);
      }
    } catch (_) {}
    const byCommunityEnriched = byCommunity.map(c => ({
      ...c,
      communityLabel: communityLabels.get(c.communityLink) || ''
    }));

    res.json({
      success: true,
      days,
      total,
      byDay, byTeam, byDayTeam,
      byCommunity: byCommunityEnriched, byCommunityDay,
      bySource,
      byTeamSource,
      topUsers
    });
  } catch (err) {
    logger.error(`/api/admin/community/link-stats: ${err.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// POST /api/admin/community-alert/force — fuerza que la alerta "revisá
// si estás unido a la comunidad" se muestre en la PWA sin respetar
// cooldown durante N horas. Config key: communityAlertForceUntil.
app.post('/api/admin/community-alert/force', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const hours = Math.max(0, Math.min(168, Number((req.body && req.body.hours)) || 24));
    if (hours === 0) {
      await setConfig('communityAlertForceUntil', null);
      return res.json({ success: true, active: false });
    }
    const until = Date.now() + hours * 3600 * 1000;
    await setConfig('communityAlertForceUntil', until);
    logger.info(`[community-alert] FORCE ON hours=${hours} until=${new Date(until).toISOString()} by=${req.user.username}`);
    res.json({ success: true, active: true, untilMs: until, untilISO: new Date(until).toISOString() });
  } catch (err) {
    logger.error(`/api/admin/community-alert/force: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/admin/community-alert/status', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const until = await getConfig('communityAlertForceUntil').catch(() => null);
    const ms = Number(until) || 0;
    const active = ms > Date.now();
    res.json({ success: true, active, untilMs: active ? ms : null, untilISO: active ? new Date(ms).toISOString() : null });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/admin/user-communities/notify-prefix-test — manda el push
// EXACTO que recibirian los users del prefix, pero a UN solo usuario
// de prueba. Sirve para ver como queda el texto antes del broadcast real.
app.post('/api/admin/user-communities/notify-prefix-test', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const testUsername = String((req.body && req.body.testUsername) || '').trim();
    const communityLink = String((req.body && req.body.communityLink) || '').trim();
    const communityLabel = String((req.body && req.body.communityLabel) || '').trim().slice(0, 60);
    const customTitle = String((req.body && req.body.customTitle) || '').slice(0, 100).trim();
    const customBody = String((req.body && req.body.customBody) || '').slice(0, 200).trim();
    if (!testUsername) return res.status(400).json({ error: 'Falta testUsername' });
    if (!communityLink) return res.status(400).json({ error: 'Falta communityLink' });

    const safeUser = testUsername.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const u = await User.findOne(
      { username: { $regex: '^' + safeUser + '$', $options: 'i' } },
      { fcmToken: 1, fcmTokens: 1, username: 1 }
    ).lean();
    if (!u) return res.status(404).json({ error: 'Usuario no encontrado en la base' });
    const tokens = [];
    if (u.fcmToken) tokens.push(u.fcmToken);
    if (Array.isArray(u.fcmTokens)) {
      for (const tk of u.fcmTokens) { const t = tk && tk.token ? tk.token : tk; if (t && !tokens.includes(t)) tokens.push(t); }
    }
    if (tokens.length === 0) return res.status(400).json({ error: 'El user no tiene FCM tokens activos' });

    const title = customTitle || '🔔 Nueva comunidad · canal informativo';
    const body = customBody || (communityLabel
      ? `Estamos unificando una nueva comunidad y canal informativo. Estamos trabajando para eso, ¡unite a "${communityLabel}"!`
      : 'Estamos unificando una nueva comunidad y canal informativo. Estamos trabajando para eso, ¡unite!');

    let pushed = 0;
    const sendPromises = tokens.map(tk =>
      _sendPushToUser(tk, title, body, { source: 'community-reminder-test', communityLink })
        .then(r => { if (r && r.success) pushed++; })
        .catch(() => {})
    );
    await Promise.all(sendPromises);

    // Activar también el flag de 24hs cuando se manda test — así el admin
    // ve el banner rojo + modal en su propia PWA enseguida para verificar
    // cómo queda. Si querés solo el push sin activar la alerta visual,
    // pasá { skipForceFlag: true } en el body.
    let alertForceActivated = false;
    if (!(req.body && req.body.skipForceFlag === true)) {
      try {
        const until = Date.now() + 24 * 3600 * 1000;
        await setConfig('communityAlertForceUntil', until);
        alertForceActivated = true;
        logger.info(`[community-notify-prefix TEST] auto-activated force-alert 24h until=${new Date(until).toISOString()}`);
      } catch (e) { logger.warn(`[community-notify-prefix TEST] no se pudo activar force-alert: ${e.message}`); }
    }

    logger.info(`[community-notify-prefix TEST] target=${u.username} pushed=${pushed}/${tokens.length} by=${req.user.username}`);
    res.json({
      success: true,
      target: u.username,
      tokensSent: pushed,
      tokensTotal: tokens.length,
      previewTitle: title,
      previewBody: body,
      alertForceActivated,
      alertForceHours: alertForceActivated ? 24 : 0
    });
  } catch (err) {
    logger.error(`/api/admin/user-communities/notify-prefix-test: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// POST /api/admin/user-communities/notify-prefix — manda push a todos
// los users cuyo username empieza con el prefijo dado, recordando que se
// sumen a su comunidad. Usado desde la sección legacy de prefijos.
app.post('/api/admin/user-communities/notify-prefix', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const prefix = String((req.body && req.body.prefix) || '').toLowerCase().trim();
    const communityLink = String((req.body && req.body.communityLink) || '').trim();
    const communityLabel = String((req.body && req.body.communityLabel) || '').trim().slice(0, 60);
    if (!prefix) return res.status(400).json({ error: 'Falta prefix' });
    if (!communityLink) return res.status(400).json({ error: 'Falta communityLink' });

    // Buscar users con FCM tokens cuyo username empieza con el prefijo.
    const safe = prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const filter = {
      username: { $regex: '^' + safe, $options: 'i' },
      $or: [
        { fcmToken: { $exists: true, $ne: null } },
        { 'fcmTokens.0': { $exists: true } }
      ]
    };
    const users = await User.find(filter, { fcmToken: 1, fcmTokens: 1, username: 1 }).lean();
    const audience = users.length;
    // Texto default unificado pedido por el dueño 2026-05-12: "estamos
    // trabajando en una nueva comunidad / canal informativo". Si el admin
    // pasó customTitle/customBody en el body, se usa eso; si no, el
    // texto por defecto.
    const customTitle = String((req.body && req.body.customTitle) || '').slice(0, 100).trim();
    const customBody = String((req.body && req.body.customBody) || '').slice(0, 200).trim();
    const title = customTitle || '🔔 Nueva comunidad · canal informativo';
    const body = customBody || (communityLabel
      ? `Estamos unificando una nueva comunidad y canal informativo. Estamos trabajando para eso, ¡unite a "${communityLabel}"!`
      : 'Estamos unificando una nueva comunidad y canal informativo. Estamos trabajando para eso, ¡unite!');
    let pushed = 0;
    const sendPromises = [];
    for (const u of users) {
      const tokens = [];
      if (u.fcmToken) tokens.push(u.fcmToken);
      if (Array.isArray(u.fcmTokens)) {
        for (const tk of u.fcmTokens) { const t = tk && tk.token ? tk.token : tk; if (t && !tokens.includes(t)) tokens.push(t); }
      }
      for (const tk of tokens) {
        sendPromises.push(
          _sendPushToUser(tk, title, body, { source: 'community-reminder', communityLink, prefix })
            .then(r => { if (r && r.success) pushed++; })
            .catch(() => {})
        );
      }
    }
    await Promise.all(sendPromises);

    // Auto-activar la alerta de "revisá tu comunidad" en la PWA por 24hs.
    // Cuando el user entre, se le muestra el modal SIN respetar el
    // cooldown de 5 días — pedido del dueño 2026-05-12. La idea es que
    // todos los del prefijo vean el reminder dentro de la ventana del push.
    try {
      const until = Date.now() + 24 * 3600 * 1000;
      await setConfig('communityAlertForceUntil', until);
      logger.info(`[community-notify-prefix] auto-activated force-alert 24h until=${new Date(until).toISOString()}`);
    } catch (e) { logger.warn(`[community-notify-prefix] no se pudo activar force-alert: ${e.message}`); }

    logger.info(`[community-notify-prefix] prefix=${prefix} audience=${audience} pushed=${pushed} by=${req.user.username}`);
    res.json({ success: true, audience, pushed, alertForceActivated: true, alertForceHours: 24 });
  } catch (err) {
    logger.error(`/api/admin/user-communities/notify-prefix: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// POST /api/admin/user-communities/mark-down — marca una comunidad como
// caída y avisa a los users asignados con replacement link.
app.post('/api/admin/user-communities/mark-down', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const communityLink = String((req.body && req.body.communityLink) || '').trim();
    const replacementLink = String((req.body && req.body.replacementLink) || '').trim();
    const replacementLabel = String((req.body && req.body.replacementLabel) || '').trim().slice(0, 60);
    const notify = (req.body && req.body.notify) !== false;
    if (!communityLink) return res.status(400).json({ error: 'Falta communityLink' });
    if (replacementLink && !/^https?:\/\//i.test(replacementLink)) {
      return res.status(400).json({ error: 'replacementLink inválido' });
    }
    const r = await UserCommunityLookup.updateMany(
      { communityLink },
      { $set: {
        status: 'down',
        replacementLink: replacementLink || null,
        replacementLabel: replacementLabel || null
      }}
    );
    let pushed = 0;
    if (notify && replacementLink && r.modifiedCount > 0) {
      try {
        const affected = await UserCommunityLookup.find({ communityLink, status: 'down' }, { username: 1, _id: 0 }).lean();
        const norms = affected.map(a => a.username);
        if (norms.length > 0) {
          const users = await User.find(
            { username: { $in: norms.map(u => new RegExp('^' + u.replace(/[.*+?^${}()|[\]\\]/g,'\\$&') + '$', 'i')) } },
            { fcmToken: 1, fcmTokens: 1 }
          ).lean();
          const title = '⚠️ Cambio de comunidad';
          const body = replacementLabel
            ? `Tu comunidad anterior cerró. Sumate a la nueva: ${replacementLabel}`
            : 'Tu comunidad anterior cerró. Entrá a la app para sumarte a la nueva.';
          const sendPromises = [];
          for (const u of users) {
            const tokens = [];
            if (u.fcmToken) tokens.push(u.fcmToken);
            if (Array.isArray(u.fcmTokens)) {
              for (const tk of u.fcmTokens) { const t = tk && tk.token ? tk.token : tk; if (t && !tokens.includes(t)) tokens.push(t); }
            }
            for (const tk of tokens) {
              sendPromises.push(
                _sendPushToUser(tk, title, body, { source: 'community-down', replacementLink })
                  .then(r => { if (r && r.success) pushed++; })
                  .catch(() => {})
              );
            }
          }
          await Promise.all(sendPromises);
        }
      } catch (e) { logger.warn(`[community-down] push: ${e.message}`); }
    }
    res.json({ success: true, modified: r.modifiedCount || 0, pushed });
  } catch (err) {
    logger.error(`/api/admin/user-communities/mark-down: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// GET /api/admin/user-communities/lookups — lista paginada de asignaciones
app.get('/api/admin/user-communities/lookups', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const page = Math.max(1, Number(req.query.page) || 1);
    const pageSize = Math.max(10, Math.min(200, Number(req.query.pageSize) || 50));
    const filter = {};
    if (req.query.communityLink) filter.communityLink = String(req.query.communityLink);
    if (req.query.status) filter.status = String(req.query.status);
    const [items, total, byCommunity] = await Promise.all([
      UserCommunityLookup.find(filter).sort({ assignedAt: -1 }).skip((page-1)*pageSize).limit(pageSize).lean(),
      UserCommunityLookup.countDocuments(filter),
      UserCommunityLookup.aggregate([
        { $group: {
          _id: { link: '$communityLink', label: '$communityLabel', status: '$status' },
          count: { $sum: 1 }
        }},
        { $sort: { count: -1 } }
      ])
    ]);
    res.json({ success: true, total, page, pageSize, items, byCommunity });
  } catch (err) {
    logger.error(`/api/admin/user-communities/lookups: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// Mismo patron que user-lines pero para links de WhatsApp/comunidades.
// ============================================
const USER_COMMUNITIES_MAX_SLOTS = 30;

app.get('/api/admin/user-communities', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const config = (await getConfig('userCommunitiesByPrefix')) || {};
    const slots = Array.isArray(config.slots) ? config.slots : [];
    const cleaned = slots
      .filter(s => s && (s.prefix || s.link || s.link2))
      .map(s => ({
        prefix: s.prefix || '',
        link: s.link || '',
        link2: s.link2 || '',
        label: s.label || '',
        label2: s.label2 || '',
        excludeFromCodes: !!s.excludeFromCodes
      }));
    res.json({
      slots: cleaned,
      defaultLink: config.defaultLink || '',
      defaultLink2: config.defaultLink2 || '',
      maxSlots: USER_COMMUNITIES_MAX_SLOTS
    });
  } catch (error) {
    console.error('Error obteniendo user-communities:', error);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

app.put('/api/admin/user-communities', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const { slots, defaultLink, defaultLink2, broadcastOnChange, broadcastTitle, broadcastBody } = req.body || {};
    if (!Array.isArray(slots)) {
      return res.status(400).json({ error: 'slots debe ser un array' });
    }
    if (slots.length > USER_COMMUNITIES_MAX_SLOTS) {
      return res.status(400).json({ error: `Máximo ${USER_COMMUNITIES_MAX_SLOTS} slots` });
    }
    const cleaned = [];
    for (const s of slots) {
      const prefix = (s && s.prefix ? String(s.prefix) : '').trim();
      const link = (s && s.link ? String(s.link) : '').trim();
      const link2 = (s && s.link2 ? String(s.link2) : '').trim();
      const label = (s && s.label ? String(s.label) : '').trim().slice(0, 60);
      const label2 = (s && s.label2 ? String(s.label2) : '').trim().slice(0, 60);
      const excludeFromCodes = !!(s && s.excludeFromCodes);
      if (!prefix && !link && !link2) continue;
      if (prefix && !link) {
        return res.status(400).json({ error: `El prefijo "${prefix}" no tiene link` });
      }
      // Validacion minima: que sea http(s) o wa.me/chat link
      if (link && !/^https?:\/\//i.test(link)) {
        return res.status(400).json({ error: `El link "${link}" debe empezar con http:// o https://` });
      }
      if (link2 && !/^https?:\/\//i.test(link2)) {
        return res.status(400).json({ error: `El segundo link "${link2}" debe empezar con http:// o https://` });
      }
      cleaned.push({ prefix, link, link2, label, label2, excludeFromCodes });
    }
    const newDefaultLink = (defaultLink ? String(defaultLink) : '').trim();
    if (newDefaultLink && !/^https?:\/\//i.test(newDefaultLink)) {
      return res.status(400).json({ error: 'El link por defecto debe empezar con http:// o https://' });
    }
    const newDefaultLink2 = (defaultLink2 ? String(defaultLink2) : '').trim();
    if (newDefaultLink2 && !/^https?:\/\//i.test(newDefaultLink2)) {
      return res.status(400).json({ error: 'El segundo link por defecto debe empezar con http:// o https://' });
    }

    const value = {
      slots: cleaned,
      defaultLink: newDefaultLink,
      defaultLink2: newDefaultLink2
    };

    // Detectar si CAMBIÓ algún link respecto al guardado previo. Si cambió
    // y broadcastOnChange=true (default), disparamos:
    //   1. Activar communityAlertForceUntil por 24h (banner rojo "Unite")
    //   2. Guardar communityForceBannerMsg custom (para que el banner
    //      muestre "a las 23 hs reclamá plata con el código")
    //   3. Mandar push a TODOS los users con tokens FCM
    let linkChanged = false;
    let pushResult = null;
    try {
      const prev = (await getConfig('userCommunitiesByPrefix')) || {};
      const norm = v => (v || '').toString().trim().toLowerCase();
      const prevDef = [norm(prev.defaultLink), norm(prev.defaultLink2)].sort().join('||');
      const newDef = [norm(newDefaultLink), norm(newDefaultLink2)].sort().join('||');
      if (prevDef !== newDef) linkChanged = true;
      if (!linkChanged) {
        const prevSlotsKey = (Array.isArray(prev.slots) ? prev.slots : [])
          .map(s => norm(s.prefix) + ':' + norm(s.link) + ':' + norm(s.link2))
          .sort().join('|');
        const newSlotsKey = cleaned
          .map(s => norm(s.prefix) + ':' + norm(s.link) + ':' + norm(s.link2))
          .sort().join('|');
        if (prevSlotsKey !== newSlotsKey) linkChanged = true;
      }
    } catch (_) {}

    await setConfig('userCommunitiesByPrefix', value);

    const wantBroadcast = broadcastOnChange !== false; // default true
    if (linkChanged && wantBroadcast) {
      try {
        const until = Date.now() + 24 * 3600 * 1000;
        await setConfig('communityAlertForceUntil', until);
        const customMsg = (broadcastBody && String(broadcastBody).trim()) || null;
        if (customMsg) {
          await setConfig('communityForceBannerMsg', customMsg.slice(0, 250));
        } else {
          // Mensaje default si admin no completó nada
          await setConfig('communityForceBannerMsg', 'Nuevo canal de Telegram — unite y a las 23:00 hs publicamos un código para reclamar plata gratis 💸');
        }
        const title = (broadcastTitle && String(broadcastTitle).trim()) || '🚀 Nuevo canal de Telegram';
        const body  = customMsg || 'Unite al nuevo canal — a las 23:00 hs publicamos un código para reclamar plata gratis 💸';
        try {
          // Filtrar equipos con excludeFromCodes=true (zz_crazy, etc.) — esos
          // se quedan con WhatsApp, no reciben el aviso de Telegram.
          const excludedPrefixes = (cleaned || [])
            .filter(s => s && s.excludeFromCodes && s.prefix)
            .map(s => String(s.prefix).toLowerCase().trim())
            .filter(Boolean);
          const exclF = _buildExcludePrefixesFilter(excludedPrefixes) || {};
          pushResult = await sendNotificationToAllUsers(User, title.slice(0, 80), body.slice(0, 250), {
            source: 'community-link-changed'
          }, exclF);
          logger.info(`[user-communities] link CAMBIO → push enviado success=${pushResult && pushResult.successCount} fail=${pushResult && pushResult.failureCount} excluyendo=[${excludedPrefixes.join(',')}]`);
        } catch (e) {
          logger.warn(`[user-communities] push falló: ${e.message}`);
        }
      } catch (e) { logger.warn(`[user-communities] force-banner falló: ${e.message}`); }
    }

    res.json({
      success: true,
      message: 'Links de comunidad actualizados',
      value,
      linkChanged,
      broadcastFired: !!(linkChanged && wantBroadcast),
      pushResult: pushResult ? {
        successCount: pushResult.successCount || 0,
        failureCount: pushResult.failureCount || 0,
        error: pushResult.error || null
      } : null
    });
  } catch (error) {
    console.error('Error actualizando user-communities:', error);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// ============================================
// BONO DE BIENVENIDA — $5.000 one-time por usuario (req: 5 cargas en 30d)
// Requisitos client-side: PWA instalada + notificaciones activas. El backend
// NO los puede verificar (son flags del navegador), confia en que el flujo
// del cliente solo dispara la request cuando ambos estan OK. La proteccion
// real contra doble cobro es el indice unique de RefundClaim.
// ============================================
const WELCOME_BONUS_AMOUNT = 5000;

// Caps de seguridad para el money giveaway. Si el admin (o un atacante con
// la cookie) crea un giveaway con cifras absurdas (typo de un 0 de mas, o
// drain malicioso) estos topes lo frenan en el endpoint POST. Si el negocio
// realmente necesita superar estos limites hay que tocar el codigo a
// proposito — un click accidental no puede vaciar JUGAYGANA.
const GIVEAWAY_MAX_AMOUNT_PER_USER = 50000;     // 5x el welcome bonus
const GIVEAWAY_MAX_TOTAL_BUDGET    = 5000000;   // $5M por giveaway
const GIVEAWAY_MAX_CLAIMS          = 1000;      // 1000 personas por giveaway

// Requisito de actividad: para reclamar el welcome bonus el usuario debe
// tener al menos N cargas en los ultimos M dias. Esto reemplaza al chequeo
// por antiguedad de cuenta. Configurable por env.
// Default 0 = sin requisito de cargas (basta con tener cuenta + app
// instalada para reclamar). El owner pidio sacar la friction al regalo
// de instalacion. Si en el futuro se quiere reactivar el anti-fraude
// (ej: pedir 5 cargas en 30 dias antes de poder reclamar), se setea la
// env var WELCOME_BONUS_MIN_DEPOSITS al numero deseado y el codigo de
// _welcomeDepositCheck lo respeta automaticamente.
const WELCOME_BONUS_MIN_DEPOSITS = Math.max(0, parseInt(process.env.WELCOME_BONUS_MIN_DEPOSITS, 10) || 0);
const WELCOME_BONUS_DEPOSIT_WINDOW_DAYS = Math.max(1, parseInt(process.env.WELCOME_BONUS_DEPOSIT_WINDOW_DAYS, 10) || 30);

async function _welcomeDepositCheck(username) {
  // Devuelve { eligible, depositCount, requiredDeposits, windowDays, source }.
  // Cuenta cargas (deposits) reales del usuario en JUGAYGANA durante la
  // ventana, excluyendo bonos que acreditamos nosotros (welcome / refunds /
  // giveaways) — esos llegan como "deposit" en JUGAYGANA por usar
  // creditUserBalance, pero no son cargas del usuario.
  const required = WELCOME_BONUS_MIN_DEPOSITS;
  const windowDays = WELCOME_BONUS_DEPOSIT_WINDOW_DAYS;
  if (required <= 0) {
    return { eligible: true, depositCount: 0, requiredDeposits: 0, windowDays, source: 'disabled' };
  }
  if (!username) {
    return { eligible: false, depositCount: 0, requiredDeposits: required, windowDays, source: 'no_username' };
  }
  try {
    const now = Date.now();
    const startMs = now - windowDays * 24 * 3600 * 1000;
    const startDate = new Date(startMs).toISOString().split('T')[0];
    const endDate = new Date(now + 24 * 3600 * 1000).toISOString().split('T')[0];

    // tx ids de bonos acreditados a este usuario (refunds + giveaways) para
    // descontar del conteo: aparecen como "deposit" en JUGAYGANA.
    const [refundDocs, giveawayDocs] = await Promise.all([
      RefundClaim.find(
        { username, transactionId: { $ne: null } },
        { transactionId: 1, _id: 0 }
      ).lean().catch(() => []),
      MoneyGiveawayClaim.find(
        { username, transactionId: { $ne: null } },
        { transactionId: 1, _id: 0 }
      ).lean().catch(() => [])
    ]);
    const bonusTxIds = new Set();
    for (const d of refundDocs) if (d.transactionId) bonusTxIds.add(String(d.transactionId));
    for (const d of giveawayDocs) if (d.transactionId) bonusTxIds.add(String(d.transactionId));

    const result = await jugayganaMovements.getUserMovements(username, {
      startDate,
      endDate,
      operationType: 'deposit',
      pageSize: 500
    });
    if (!result || !result.success) {
      logger.warn(`[BONUS] welcome — getUserMovements fallo para ${username} err=${result && result.error}`);
      return { eligible: false, depositCount: 0, requiredDeposits: required, windowDays, source: 'movements_failed' };
    }

    let count = 0;
    for (const m of (result.movements || [])) {
      const mid = String(
        m.id || m.Id || m._id ||
        m.transfer_id || m.transferId ||
        m.transactionId || m.TransactionId || ''
      );
      if (mid && bonusTxIds.has(mid)) continue;

      const type = (m.type || m.operation || m.OperationType || m.Type || m.Operation || '').toString().toLowerCase();
      let amt = 0;
      if (m.amount !== undefined) amt = parseFloat(m.amount);
      else if (m.Amount !== undefined) amt = parseFloat(m.Amount);
      else if (m.value !== undefined) amt = parseFloat(m.value);
      else if (m.Value !== undefined) amt = parseFloat(m.Value);
      else if (m.monto !== undefined) amt = parseFloat(m.monto);
      else if (m.Monto !== undefined) amt = parseFloat(m.Monto);

      // Allowlist estricta: SOLO contamos cargas reales del usuario. Tipos
      // como "withdrawal_reversed", "bonus", "promo", "adjustment" tambien
      // tienen amt>0 pero no son cargas — antes los contabamos como tales,
      // permitiendo que ajustes manuales del admin habiliten el bono.
      const isDep = (
        (type.includes('deposit') || type.includes('credit') ||
         type.includes('carga')   || type.includes('recarga')) &&
        amt > 0
      );
      if (!isDep) continue;

      // Sin timestamp parseable -> descartar. Antes se contaban best-effort
      // pero eso permitia que cargas viejas sin fecha se sumen a la ventana.
      const tsRaw = m.created_at || m.createdAt || m.date || m.Date ||
                    m.datetime || m.timestamp || m.time || m.created || null;
      let ts = 0;
      if (tsRaw) {
        const d = new Date(tsRaw);
        ts = isNaN(d.getTime()) ? 0 : d.getTime();
      }
      if (!ts) continue;
      if (ts < startMs) continue;
      count++;
    }

    return {
      eligible: count >= required,
      depositCount: count,
      requiredDeposits: required,
      windowDays,
      source: 'movements'
    };
  } catch (err) {
    logger.error(`[BONUS] welcome — _welcomeDepositCheck error para ${username}: ${err.message}`);
    return { eligible: false, depositCount: 0, requiredDeposits: required, windowDays, source: 'exception' };
  }
}

// =====================================================================
// ENCUESTA DE PREFERENCIA DE NOTIFICACIONES (Fase 1)
// =====================================================================
// El user elige una vez al primer login post-survey. Se persiste en
