// Welcome push: al responder la encuesta, el user queda inscripto en
// la estrategia automaticamente. Le mandamos un push de bienvenida
// agradeciendo y avisando que recibira sus bonos.
const _SURVEY_WELCOME_MESSAGES = [
  { title: '🎉 ¡Bienvenido!', body: 'Gracias por sumarte. Configuramos tus notifs personalizadas. Te van a llegar bonos exclusivos.' },
  { title: '🙏 ¡Sos parte!', body: 'Gracias por estar con nosotros. Desde hoy te llegan los mejores bonos directo al saldo.' },
  { title: '✨ Listo, sos parte', body: 'Te esperan bonos del 50% en tus cargas + 1 bono del 100% al mes. Vamos a por más.' },
  { title: '💎 Bienvenido a la familia', body: 'Tu plan de notifs ya quedó activo. Bonos, regalos y novedades — solo lo que te conviene.' }
];

// Blueprints por categoría × tier para el calendario mensual. Cada push
// programado tiene su propia copy según qué representa: BONOS (oferta de
// carga), JUEGOS (invitación a jugar), REGALOS (plata de regalo). El user
// recibe las 3 categorías mezcladas en distintos días del mes.
const _STRATEGY_CATEGORY_BLUEPRINTS = {
  bonos: {
    suave:  { title: '🟢 Tu bono suave del mes', body: 'Cargá hoy y te damos 50% extra. Tocá para usar el código.' },
    normal: { title: '🟡 Bono activo para vos', body: 'Hoy hay 50% en cargas. Aprovechalo antes de que cierre.' },
    activo: { title: '🔴 BONO 100% ACTIVO', body: 'Hoy duplicás tu carga. Tocá ahora — ventana corta.' }
  },
  juegos: {
    suave:  { title: '🎮 Vení a jugar un rato', body: 'Tu plataforma te espera. Pegale una vuelta hoy.' },
    normal: { title: '🎰 Hora de jugar', body: 'Pasá un rato y probá los juegos nuevos. Buenos ratos al toque.' },
    activo: { title: '🔥 ¡A jugar!', body: 'Movete, los slots están pagando. Vení antes de que se acabe.' }
  },
  regalos: {
    suave:  { title: '🎁 Hay un regalo para vos', body: 'Pasá por la app — te dejamos plata extra para hoy.' },
    normal: { title: '🎁 Regalo activo', body: 'Tu regalo del mes está listo. Reclamalo dentro de la app.' },
    activo: { title: '💎 REGALO PREMIUM', body: 'Plata de regalo cargada para vos — limitada en tiempo. Tocá ya.' }
  }
};
const _STRATEGY_CATEGORIES = ['bonos', 'juegos', 'regalos'];

// Devuelve los días que quedan del mes en curso, desde HOY (inclusive) hasta
// el último día del mes (inclusive). Cada elemento es un Date con la hora 00:00.
function _remainingDaysOfMonth() {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();
  const lastDay = new Date(year, month + 1, 0).getDate();
  const today = now.getDate();
  const days = [];
  for (let d = today; d <= lastDay; d++) {
    days.push(new Date(year, month, d, 0, 0, 0, 0));
  }
  return days;
}

// Elige `count` días distintos al azar de la lista `days`. Si count >= days.length,
// devuelve todos los días (algunos van a tener más de un push si count > days.length).
function _pickRandomDays(days, count) {
  if (count <= 0) return [];
  if (count >= days.length) {
    // Si pedimos más pushes que días disponibles, repetimos días pero ordenados.
    const extra = count - days.length;
    const result = days.slice();
    for (let i = 0; i < extra; i++) {
      result.push(days[Math.floor(Math.random() * days.length)]);
    }
    return result.sort((a, b) => a.getTime() - b.getTime());
  }
  // Sampling sin reemplazo (Fisher-Yates parcial).
  const pool = days.slice();
  const picked = [];
  for (let i = 0; i < count; i++) {
    const idx = Math.floor(Math.random() * pool.length);
    picked.push(pool.splice(idx, 1)[0]);
  }
  return picked.sort((a, b) => a.getTime() - b.getTime());
}

// Genera una fecha-hora random dentro de la ventana del día dado. Si el día
// es hoy y la ventana ya pasó, devuelve null (caller decide si saltar).
function _randomTimeInDayWindow(dayDate, startHour, endHour) {
  const start = new Date(dayDate);
  start.setHours(startHour, 0, 0, 0);
  const end = new Date(dayDate);
  end.setHours(endHour, 0, 0, 0);
  const now = new Date();
  if (now >= end) return null; // ventana ya pasó este día
  const effectiveStart = now > start ? now : start;
  const span = end.getTime() - effectiveStart.getTime();
  return new Date(effectiveStart.getTime() + Math.floor(Math.random() * span));
}

// Programa el calendario mensual completo para UN usuario según su tier.
// Crea ScheduledNotifications por cada push: bonos + juegos + regalos.
// Cada push cae un día random del mes (sin repetir si hay días suficientes)
// y a una hora random dentro de la ventana configurada [startHour, endHour).
//
// Retorna: { scheduled, failed, perCategory: { bonos, juegos, regalos } }
// Códigos de promo por tier de la encuesta. El cliente lee promoCode desde
// el push y lo muestra en el cartel "RECLAMÁ" con wa.link a cargar.
const _STRATEGY_PROMO_CODES = {
  suave: 'BONO50',
  normal: 'BONO50',
  activo: 'BONO100'
};

// Calcula el monto del regalo para un user dado, "rotativo" según su
// actividad real (PlayerStats.realDeposits30d) sobre la base del budget
// del tier dividido entre la cantidad de regalos del mes. Boost por
// actividad (hasta +50%) y variación random ±15% para que dos regalos
// del mismo user no caigan iguales. Floor $500, redondeo a $100.
function _computeStrategyGiftAmount({ tierBudget, regalosCount, realDeposits30d }) {
  const base = (Number(tierBudget) > 0 && Number(regalosCount) > 0)
    ? (Number(tierBudget) / Number(regalosCount))
    : 1000;
  const activityBoost = 1 + Math.min(0.5, Math.max(0, Number(realDeposits30d) || 0) / 10000);
  const variance = 0.85 + Math.random() * 0.30; // 0.85 .. 1.15
  const raw = base * activityBoost * variance;
  const rounded = Math.round(raw / 100) * 100;
  return Math.max(500, rounded);
}

async function _scheduleMonthlyStrategyForUser({ user, tier, cfg, monthKey, reason }) {
  const out = { scheduled: 0, failed: 0, perCategory: { bonos: 0, juegos: 0, regalos: 0 } };
  if (tier === 'solo_reembolsos' || tier === 'opt_out') return out;
  const prefs = (cfg && cfg.preferences && cfg.preferences[tier]) || {};
  const startHour = (cfg && Number.isFinite(cfg.windowStartHour)) ? cfg.windowStartHour : 18;
  const endHour   = (cfg && Number.isFinite(cfg.windowEndHour))   ? cfg.windowEndHour   : 21;
  const days = _remainingDaysOfMonth();
  if (days.length === 0) return out;

  const username = String(user.username || '').toLowerCase().trim();
  if (!username) return out;
  const reasonStr = String(reason || 'monthly-activate');

  // PlayerStats define el monto rotativo de los regalos (categoría 'regalos').
  // Si el user no tiene stats, factor de actividad neutro (boost 0%).
  let realDeposits30d = 0;
  try {
    const ps = await PlayerStats.findOne({ username }, { realDeposits30d: 1, _id: 0 }).lean();
    if (ps && Number.isFinite(ps.realDeposits30d)) realDeposits30d = ps.realDeposits30d;
  } catch (_) { /* best-effort */ }
  const tierBudget = Number(prefs.budget) || 0;
  const regalosCount = Math.max(1, Number(prefs.regalos) || 0);

  for (const cat of _STRATEGY_CATEGORIES) {
    const count = Math.max(0, Number(prefs[cat]) || 0);
    if (count === 0) continue;
    const bp = (_STRATEGY_CATEGORY_BLUEPRINTS[cat] && _STRATEGY_CATEGORY_BLUEPRINTS[cat][tier]) ||
               { title: '🎁 Hay algo para vos', body: 'Tocá la app.' };
    const pickedDays = _pickRandomDays(days, count);
    for (const day of pickedDays) {
      const when = _randomTimeInDayWindow(day, startHour, endHour);
      if (!when) continue; // ventana del día ya pasó (caso: hoy después de endHour)
      // BONIFICACIONES Y REGALOS AUTOMÁTICOS DESACTIVADOS (admin lo maneja
      // manual). El push se manda igual (informativo), pero no se crea
      // promo ni giveaway server-side. Para reactivar: descomentar el
      // bloque condicional de abajo.
      const extra = { extraType: 'none' };
      // if (cat === 'regalos') {
      //   extra.extraType = 'giveaway';
      //   extra.giveawayAmount = _computeStrategyGiftAmount({ tierBudget, regalosCount, realDeposits30d });
      //   extra.giveawayDurationMinutes = 360;
      // } else if (cat === 'bonos') {
      //   extra.extraType = 'promo';
      //   extra.promoCode = _STRATEGY_PROMO_CODES[tier] || 'BONO50';
      //   extra.promoMessage = bp.body;
      //   extra.promoDurationHours = 6;
      // }
      try {
        await ScheduledNotification.create({
          id: uuidv4(),
          scheduledFor: when,
          status: 'pending',
          title: bp.title,
          body: bp.body,
          targetUsername: username,
          audiencePrefix: null,
          createdBy: `strategy-month:${monthKey}:${tier}:${cat}:${reasonStr}`,
          ...extra
        });
        out.scheduled++;
        out.perCategory[cat]++;
      } catch (e) {
        out.failed++;
        logger.warn(`[STRATEGY-MONTH] no se pudo programar ${cat} para ${username}: ${e.message}`);
      }
    }
  }

  return out;
}

// Cancela todos los ScheduledNotification pendientes que vengan del scheduler
// mensual o de waves de la estrategia. Se usa antes de re-programar para
// evitar duplicar pushes.
async function _cancelPendingStrategyNotifications() {
  const r = await ScheduledNotification.updateMany(
    {
      status: 'pending',
      $or: [
        { createdBy: { $regex: /^strategy-month:/ } },
        { createdBy: { $regex: /^strategy-wave:/ } }
      ]
    },
    { $set: { status: 'cancelled' } }
  );
  return r.modifiedCount || 0;
}

// Genera la clave del mes en curso (YYYY-MM) — sirve como tag para poder
// distinguir el calendario de un mes vs el del próximo en el createdBy.
function _currentMonthKey() {
  const d = new Date();
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
}

app.post('/api/user/notif-preference', authMiddleware, async (req, res) => {
  try {
    const pref = String((req.body && req.body.preference) || '').toLowerCase().trim();
    if (!_NOTIF_PREF_VALUES.includes(pref)) {
      return res.status(400).json({ error: 'Preferencia inválida. Valores: ' + _NOTIF_PREF_VALUES.join(', ') });
    }
    // Detectar si es PRIMERA respuesta — solo en ese caso mandamos welcome.
    const before = await User.findOne({ id: req.user.userId }, { notifPreference: 1, fcmToken: 1, fcmTokens: 1, _id: 0 }).lean();
    const isFirstAnswer = !before || !before.notifPreference;

    const updated = await User.findOneAndUpdate(
      { id: req.user.userId },
      { $set: { notifPreference: pref, notifPreferenceAt: new Date() } },
      { new: true, projection: { notifPreference: 1, notifPreferenceAt: 1 } }
    ).lean();
    if (!updated) return res.status(404).json({ error: 'Usuario no encontrado' });
    logger.info(`[SURVEY] notif-preference set ${req.user.username}=${pref} (firstAnswer=${isFirstAnswer})`);

    // Welcome push (best effort, no bloquea la response).
    if (isFirstAnswer && before && pref !== 'opt_out') {
      const tokens = [];
      if (before.fcmToken) tokens.push(before.fcmToken);
      if (Array.isArray(before.fcmTokens)) tokens.push(...before.fcmTokens.filter(t => t && !tokens.includes(t)));
      if (tokens.length > 0) {
        const msg = _SURVEY_WELCOME_MESSAGES[Math.floor(Math.random() * _SURVEY_WELCOME_MESSAGES.length)];
        Promise.all(tokens.map(t =>
          _sendPushToUser(t, msg.title, msg.body, { kind: 'survey_welcome', preference: pref })
            .catch(e => logger.warn(`[SURVEY] welcome push fail ${req.user.username}: ${e.message}`))
        )).then(() => {
          logger.info(`[SURVEY] welcome push enviado a ${req.user.username} · ${tokens.length} token(s)`);
        });
      } else {
        logger.info(`[SURVEY] ${req.user.username} respondio pero no tiene FCM tokens — sin welcome push.`);
      }
    }

    res.json({
      success: true,
      preference: updated.notifPreference,
      answeredAt: updated.notifPreferenceAt
    });

    // Hook auto-fire per-user DESACTIVADO 2026-05-11 — reemplazado por la
    // automatización por equipo (TeamCampaign). Las campañas se disparan al
    // equipo completo respetando el tier de cada user. Para reactivar la
    // automatización per-user en el futuro: descomentar el bloque siguiente
    // y desactivar la auto-estrategia por equipo desde el panel.
    /*
    if (isFirstAnswer && pref !== 'opt_out' && pref !== 'solo_reembolsos') {
      setImmediate(async () => {
        try {
          const cfg = await NotifStrategyConfig.findOne({ key: 'monthly-default' });
          if (!cfg || !cfg.isActive) return;
          const u = await User.findOne(
            { id: req.user.userId },
            { username: 1, notifPreference: 1, fcmToken: 1, fcmTokens: 1, _id: 0 }
          ).lean();
          if (!u) return;
          const hasToken = !!(u.fcmToken || (Array.isArray(u.fcmTokens) && u.fcmTokens.length > 0));
          if (!hasToken) return;
          await _scheduleMonthlyStrategyForUser({
            user: u, tier: u.notifPreference, cfg: cfg.toObject(),
            monthKey: _currentMonthKey(), reason: 'survey-response'
          });
        } catch (e) { logger.warn(`[STRATEGY-MONTH] hook survey falló: ${e.message}`); }
      });
    }
    */
  } catch (err) {
    logger.error(`/api/user/notif-preference POST: ${err.message}`);
    res.status(500).json({ error: err.message || 'Error del servidor' });
  }
});

// Stats agregadas para el panel admin: distribucion de respuestas.
app.get('/api/admin/users/notif-preference-stats', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const agg = await User.aggregate([
      { $group: { _id: '$notifPreference', count: { $sum: 1 } } }
    ]);
    const counts = { suave: 0, normal: 0, activo: 0, opt_out: 0, solo_reembolsos: 0, sin_responder: 0 };
    let total = 0;
    for (const row of agg) {
      total += row.count;
      const k = row._id || 'sin_responder';
      if (counts[k] != null) counts[k] = row.count;
    }
    res.json({ total, counts });
  } catch (err) {
    logger.error(`/api/admin/users/notif-preference-stats: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

