    const u = await User.findOne(
      { id: req.user.userId },
      { backupContactPhone: 1, backupContactPhoneAt: 1, _id: 0 }
    ).lean();
    res.json({
      phone: (u && u.backupContactPhone) || null,
      submittedAt: (u && u.backupContactPhoneAt) || null,
      hasSubmitted: !!(u && u.backupContactPhone)
    });
