// Helper: regex case-insensitive seguro para filtros — evita que diferencias
// de mayúsculas/minúsculas dejen users fuera del match. Útil cuando los team
// names o line names pueden venir con casing inconsistente.
function _ciExact(s) {
  const safe = String(s || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('^' + safe + '$', 'i');
}

// Helper: estima cuántos users matchean los filtros de una campaña.
async function _countTeamCampaignAudience(c) {
  const q = {};
  if (c.teamFilter) q.lineTeamName = _ciExact(c.teamFilter);
  if (c.lineFilter) q.linePhone = _ciExact(c.lineFilter);
  if (c.requireApp) {
    q.$or = [{ fcmToken: { $exists: true, $ne: null, $ne: '' } }, { fcmTokens: { $exists: true, $ne: [], $not: { $size: 0 } } }];
  }
  if (c.requireSurveyAnswered) {
    q.notifPreference = { $exists: true, $ne: null };
  }
  if (c.tierFilter) {
    q.notifPreference = c.tierFilter;
  }
  // requireActiveDays se chequea contra PlayerStats.lastSeenApp — más caro,
  // hacemos un find separado y intersectamos. Para preview rápido del audience
  // count si no hay requireActiveDays usamos solo el User count.
  if (!c.requireActiveDays) {
    return await User.countDocuments(q);
  }
  const candidates = await User.find(q, { username: 1, _id: 0 }).lean();
  if (candidates.length === 0) return 0;
  const usernames = candidates.map(u => u.username.toLowerCase());
  const cutoff = new Date(Date.now() - c.requireActiveDays * 86400000);
  const activeStats = await PlayerStats.find({
    username: { $in: usernames },
    lastSeenApp: { $gte: cutoff }
  }, { username: 1, _id: 0 }).lean();
  return activeStats.length;
}

// Cron: corre cada 60s, dispara campañas activas que tienen que correr HOY
// y la hora actual está dentro de [startHour, endHour). Idempotente vía
// lastFiredOnDate (solo dispara una vez por día).
let _TEAM_CAMPAIGN_TICK_RUNNING = false;
async function _teamCampaignTick() {
  if (_TEAM_CAMPAIGN_TICK_RUNNING) return;
  _TEAM_CAMPAIGN_TICK_RUNNING = true;
  try {
    const now = new Date();
    const todayStr = now.toISOString().slice(0, 10);
    const currentDay = now.getDay(); // 0=Sun..6=Sat
    const currentHour = now.getHours();
    // Filtrar las campañas que aplican HOY y este horario.
    const candidates = await TeamCampaign.find({ isActive: true }).lean();
    for (const c of candidates) {
      // Skip si ya disparó hoy.
      if (c.lastFiredOnDate === todayStr) continue;
      // Match día: o dayOfWeek == hoy, o specificDate == hoy, o ambos null = todos los días.
      const dayMatch = (c.dayOfWeek == null && !c.specificDate)
        || (c.dayOfWeek != null && c.dayOfWeek === currentDay)
        || (c.specificDate && c.specificDate === todayStr);
      if (!dayMatch) continue;
      // Match hora: estamos dentro del rango [startHour, endHour).
      if (currentHour < c.startHour || currentHour >= c.endHour) continue;
      try {
        const result = await _fireTeamCampaign(c, now);
        await TeamCampaign.updateOne(
          { id: c.id },
          {
            $set: { lastFiredOnDate: todayStr, totalUsersImpactedLastFire: result.scheduled },
            $inc: { totalFires: 1 }
          }
        );
        logger.info(`[TEAM-CAMPAIGN] fired "${c.name}" → ${result.scheduled} users (skipped ${result.skipped})`);
      } catch (e) {
        logger.error(`[TEAM-CAMPAIGN] fail firing "${c.name}": ${e.message}`);
      }
    }
  } catch (e) {
    logger.error(`[TEAM-CAMPAIGN] tick global error: ${e.message}`);
  } finally {
    _TEAM_CAMPAIGN_TICK_RUNNING = false;
  }
}

// Encola ScheduledNotifications para todos los users del filter, con hora random
// dentro del rango. Si extraType=promo|giveaway el _executeScheduledNotification
// crea el promo/giveaway scoped por user (audienceWhitelist) cuando dispare cada uno.
async function _fireTeamCampaign(c, fireDate) {
  const out = { scheduled: 0, skipped: 0 };
  // Levantar candidatos. Filtros de team/line vía regex case-insensitive
  // para que diferencias de casing (Atomic / atomic / ATOMIC) no dejen
  // users afuera del match.
  const q = {};
  if (c.teamFilter) q.lineTeamName = _ciExact(c.teamFilter);
  if (c.lineFilter) q.linePhone = _ciExact(c.lineFilter);
  if (c.tierFilter) q.notifPreference = c.tierFilter;
  else if (c.requireSurveyAnswered) q.notifPreference = { $exists: true, $ne: null };
  if (c.requireApp) {
    q.$or = [{ fcmToken: { $exists: true, $ne: null, $ne: '' } }, { fcmTokens: { $exists: true, $ne: [], $not: { $size: 0 } } }];
  }
  const users = await User.find(q, { username: 1, _id: 0 }).limit(20000).lean();
  if (users.length === 0) return out;
  let usernames = users.map(u => u.username.toLowerCase());
  // Filtro activeDays.
  if (c.requireActiveDays) {
    const cutoff = new Date(Date.now() - c.requireActiveDays * 86400000);
    const active = await PlayerStats.find({
      username: { $in: usernames },
      lastSeenApp: { $gte: cutoff }
    }, { username: 1, _id: 0 }).lean();
    usernames = active.map(a => a.username.toLowerCase());
  }
  // Filtro excludeUsernames — saca regalo-hunters de la audience (solo aplica
  // en categoria 'regalos' tipicamente, pero acepta cualquier lista de exclusion).
  if (Array.isArray(c.excludeUsernames) && c.excludeUsernames.length > 0) {
    const excludeLc = new Set(c.excludeUsernames.map(u => String(u || '').toLowerCase()).filter(Boolean));
    usernames = usernames.filter(u => !excludeLc.has(u));
  }
  if (usernames.length === 0) return out;

  const startMs = new Date(fireDate); startMs.setHours(c.startHour, 0, 0, 0);
  const endMs = new Date(fireDate); endMs.setHours(c.endHour, 0, 0, 0);
  const windowMs = endMs.getTime() - startMs.getTime();
  const nowMs = Date.now();

  for (const username of usernames) {
    // Hora random dentro del rango, pero no en el pasado.
    let when = new Date(startMs.getTime() + Math.random() * windowMs);
    if (when.getTime() < nowMs + 30 * 1000) when = new Date(nowMs + 30 * 1000); // mínimo +30s
    if (when.getTime() > endMs.getTime()) when = new Date(endMs.getTime() - 1000); // dentro de la ventana

    const sched = {
      id: uuidv4(),
      scheduledFor: when,
      status: 'pending',
      title: c.title,
      body: c.body,
      targetUsername: username,
      audiencePrefix: null,
      extraType: c.extraType || 'none',
      createdBy: `team-campaign:${c.id}:${c.name.slice(0, 30)}`
    };
    if (c.extraType === 'promo') {
      sched.promoCode = c.promoCode;
      sched.promoMessage = c.promoMessage || c.body;
      sched.promoDurationHours = c.promoDurationHours || 6;
    } else if (c.extraType === 'giveaway') {
      sched.giveawayAmount = c.giveawayAmount;
      sched.giveawayDurationMinutes = c.giveawayDurationMinutes || 360;
    }
    try {
      await ScheduledNotification.create(sched);
      out.scheduled++;
    } catch (e) {
      out.skipped++;
      logger.warn(`[TEAM-CAMPAIGN] no se pudo encolar push a ${username}: ${e.message}`);
    }
  }
  return out;
}

// Arrancar el cron 45s después del boot, correr cada 60s.
setTimeout(() => { _teamCampaignTick(); }, 45 * 1000);
setInterval(() => { _teamCampaignTick(); }, 60 * 1000);

// =====================================================================
// AUTO-ESTRATEGIA POR EQUIPO — generación masiva de TeamCampaigns basadas
// en la encuesta (NotifStrategyConfig) y la distribución de tiers por
// (team, line). Para cada combo con users, distribuye los N pushes del
// tier en días distintos del mes con horario random dentro de la ventana.
// Marca las campañas con origin='auto-strategy' + autoStrategyMonth='YYYY-MM'
// para poder regenerar o limpiar después.
// =====================================================================

// Default blueprints por (categoría, tier) — title/body templates.
const _AUTO_STRATEGY_BLUEPRINTS = {
  bonos: {
    suave:  { title: '🟢 Tu bono suave', body: 'Cargá hoy y te damos un bono extra. Aprovechá la oferta.' },
    normal: { title: '🟡 Bono activo para vos', body: 'Hoy hay bono en cargas. Aprovechalo antes de que cierre.' },
    activo: { title: '🔴 BONO PREMIUM', body: 'Hoy duplicás tu carga. Ventana corta — entrá ahora.' }
  },
  juegos: {
    suave:  { title: '🎮 Vení a jugar un rato', body: 'Tu plataforma te espera. Pegale una vuelta hoy.' },
    normal: { title: '🎰 Hora de jugar', body: 'Pasá un rato y probá los juegos nuevos.' },
    activo: { title: '🔥 ¡A jugar!', body: 'Los slots están pagando. Entrá antes de que se acabe.' }
  },
  regalos: {
    suave:  { title: '🎁 Hay un regalo para vos', body: 'Pasá por la app — te dejamos plata extra para hoy.' },
    normal: { title: '🎁 Regalo activo', body: 'Tu regalo del mes está listo. Reclamalo dentro de la app.' },
    activo: { title: '💎 REGALO PREMIUM', body: 'Plata de regalo cargada para vos — limitada en tiempo.' }
  }
};

// Distribuye N elementos en M slots — devuelve indices distintos (si N <= M)
// o todos los slots + extra random repetidos (si N > M).
function _autoStrategyPickDays(remainingDays, count) {
  if (count <= 0 || remainingDays.length === 0) return [];
  if (count >= remainingDays.length) {
    const extras = count - remainingDays.length;
    const out = remainingDays.slice();
    for (let i = 0; i < extras; i++) out.push(remainingDays[Math.floor(Math.random() * remainingDays.length)]);
    return out.sort((a, b) => a.getTime() - b.getTime());
  }
  const pool = remainingDays.slice();
  const picked = [];
  for (let i = 0; i < count; i++) {
    const idx = Math.floor(Math.random() * pool.length);
    picked.push(pool.splice(idx, 1)[0]);
  }
  return picked.sort((a, b) => a.getTime() - b.getTime());
}

// Cuenta distribucion de tier por (team, line). Devuelve mapa team::line → {suave, normal, activo, total}.
async function _autoStrategyGetDistribution() {
  // Incluyo solo_reembolsos en el aggregate aunque no generemos campañas de
  // bonos/juegos para ellos — sirve para que el admin vea CUÁNTOS users hay
  // en ese segmento por equipo. Esos users SOLO reciben recordatorios de
  // reembolso a las 23hs cuando tienen plata pendiente.
  const agg = await User.aggregate([
    {
      $match: {
        lineTeamName: { $exists: true, $ne: null, $ne: '' },
        notifPreference: { $in: ['suave', 'normal', 'activo', 'solo_reembolsos'] }
      }
    },
    { $group: { _id: { team: '$lineTeamName', line: '$linePhone', tier: '$notifPreference' }, count: { $sum: 1 } } }
  ]);
  const dist = {}; // key: team::line → {suave, normal, activo, solo_reembolsos, total}
  for (const row of agg) {
    const team = row._id.team || '';
    const line = row._id.line || '';
    const tier = row._id.tier || '';
    const k = team + '::' + line;
    if (!dist[k]) dist[k] = { team, line, suave: 0, normal: 0, activo: 0, solo_reembolsos: 0, total: 0 };
    dist[k][tier] = row.count;
    dist[k].total += row.count;
  }
  return Object.values(dist);
}

// Detecta "regalo-hunters": users que en los últimos N días reclamaron
// muchos regalos PERO no cargaron nada. Estos son los que vienen a sacar
// plata sin poner — la auto-estrategia los excluye de los REGALOS (pero
// sigue mandándoles bonos/juegos para darles chance de convertir).
//
// Criterio default (configurable):
//   - claimCount30d >= 3 (reclamó 3+ regalos)
//   - realDeposits30d === 0 (no cargó nada de su bolsillo)
//
// Devuelve array de { username, claimCount, totalClaimedAmount, lastClaimAt,
// lastDepositDate, realDeposits30d, daysSinceLastDeposit, lineTeamName }.
async function _detectRegaloHunters({ days = 30, minClaims = 3, maxDeposits = 0 } = {}) {
  const since = new Date(Date.now() - days * 86400000);

  // 1) Aggregate de claims en MoneyGiveawayClaim por username.
  // Cruzamos con MoneyGiveaway para sacar monto reclamado por cada claim.
  const claimAgg = await MoneyGiveawayClaim.aggregate([
    { $match: { claimedAt: { $gte: since } } },
    {
      $lookup: {
        from: 'money_giveaways',
        localField: 'giveawayId',
        foreignField: 'id',
        as: 'gw'
      }
    },
    {
      $group: {
        _id: { $toLower: '$username' },
        username: { $first: '$username' },
        claimCount: { $sum: 1 },
        totalClaimedAmount: { $sum: { $ifNull: [{ $arrayElemAt: ['$gw.amountPerWinner', 0] }, 0] } },
        lastClaimAt: { $max: '$claimedAt' }
      }
    },
    { $match: { claimCount: { $gte: minClaims } } }
  ], { allowDiskUse: true });

  if (claimAgg.length === 0) return [];

  // 2) Cruzar con PlayerStats para sacar realDeposits30d.
  const usernamesLc = claimAgg.map(c => c._id);
  const stats = await PlayerStats.find(
    { username: { $in: usernamesLc.map(u => new RegExp('^' + u.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '$', 'i')) } },
    { username: 1, realDeposits30d: 1, lastRealDepositDate: 1, _id: 0 }
  ).lean();
  const statsMap = new Map();
  for (const s of stats) statsMap.set(String(s.username || '').toLowerCase(), s);

  // 3) Cruzar con User para sacar lineTeamName (para mostrar en el reporte).
  const users = await User.find(
    { username: { $in: usernamesLc.map(u => new RegExp('^' + u.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '$', 'i')) } },
    { username: 1, lineTeamName: 1, linePhone: 1, _id: 0 }
  ).lean();
  const userMap = new Map();
  for (const u of users) userMap.set(String(u.username || '').toLowerCase(), u);

  // 4) Filtrar a los que cumplen los 2 criterios: many claims + 0 deposits.
  const out = [];
  const now = Date.now();
  for (const c of claimAgg) {
    const s = statsMap.get(c._id) || {};
    const u = userMap.get(c._id) || {};
    const deposits30d = Number(s.realDeposits30d) || 0;
    if (deposits30d > Number(maxDeposits)) continue; // tiene cargas → no es hunter
    const lastDep = s.lastRealDepositDate ? new Date(s.lastRealDepositDate).getTime() : null;
    out.push({
      username: c.username,
      claimCount: c.claimCount,
      totalClaimedAmount: c.totalClaimedAmount || 0,
      lastClaimAt: c.lastClaimAt,
      realDeposits30d: deposits30d,
      lastRealDepositDate: s.lastRealDepositDate || null,
      daysSinceLastDeposit: lastDep ? Math.floor((now - lastDep) / 86400000) : null,
      lineTeamName: u.lineTeamName || null,
      linePhone: u.linePhone || null
    });
  }
  // Orden: más sospechosos primero (más reclamos + más plata reclamada).
  out.sort((a, b) => {
    if (b.claimCount !== a.claimCount) return b.claimCount - a.claimCount;
    return (b.totalClaimedAmount || 0) - (a.totalClaimedAmount || 0);
  });
  return out;
}

// Análisis general de usuarios: top depositantes (los que mejor cargan),
// top reclamadores (los más sospechosos), y net positive/negative.
// Sirve para que el personal revise quiénes son los buenos clientes y
// quiénes los regalo-hunters de un vistazo.
async function _userAnalysisReport({ days = 30 } = {}) {
  const since = new Date(Date.now() - days * 86400000);

  // 1) Top depositantes por monto.
  const topDepositors = await Transaction.aggregate([
    {
      $match: {
        type: 'deposit',
        status: 'completed',
        timestamp: { $gte: since }
      }
    },
    {
      $group: {
        _id: { $toLower: '$username' },
        username: { $first: '$username' },
        totalDeposited: { $sum: '$amount' },
        depositCount: { $sum: 1 },
        lastDepositAt: { $max: '$timestamp' }
      }
    },
    { $sort: { totalDeposited: -1 } },
    { $limit: 50 }
  ], { allowDiskUse: true });

  // 2) Top reclamadores (todos los que reclamaron, ordenado por plata recibida).
  const topClaimers = await MoneyGiveawayClaim.aggregate([
    { $match: { claimedAt: { $gte: since } } },
    {
      $lookup: {
        from: 'money_giveaways',
        localField: 'giveawayId',
        foreignField: 'id',
        as: 'gw'
      }
    },
    {
      $group: {
        _id: { $toLower: '$username' },
        username: { $first: '$username' },
        claimCount: { $sum: 1 },
        totalClaimed: { $sum: { $ifNull: [{ $arrayElemAt: ['$gw.amountPerWinner', 0] }, 0] } },
        lastClaimAt: { $max: '$claimedAt' }
      }
    },
    { $sort: { totalClaimed: -1 } },
    { $limit: 50 }
  ], { allowDiskUse: true });

  // 3) Para cada top claimer, cruzar con sus deposits para calcular net.
  const claimerUsernames = topClaimers.map(c => c._id);
  let depositsByClaimer = new Map();
  if (claimerUsernames.length > 0) {
    const depAgg = await Transaction.aggregate([
      {
        $match: {
          type: 'deposit',
          status: 'completed',
          timestamp: { $gte: since },
          $expr: { $in: [{ $toLower: '$username' }, claimerUsernames] }
        }
      },
      {
        $group: {
          _id: { $toLower: '$username' },
          totalDep: { $sum: '$amount' }
        }
      }
    ], { allowDiskUse: true });
    for (const r of depAgg) depositsByClaimer.set(r._id, r.totalDep);
  }
  // Net per claimer.
  const claimersEnriched = topClaimers.map(c => {
    const dep = depositsByClaimer.get(c._id) || 0;
    return {
      username: c.username,
      claimCount: c.claimCount,
      totalClaimed: c.totalClaimed || 0,
      totalDeposited: dep,
      net: dep - (c.totalClaimed || 0),
      lastClaimAt: c.lastClaimAt,
      flag: dep === 0 && c.claimCount >= 3 ? 'regalo-hunter' : (dep < c.totalClaimed ? 'net-negative' : 'ok')
    };
  });

  // 4) Totales globales.
  const [globalDep, globalClaims] = await Promise.all([
    Transaction.aggregate([
      { $match: { type: 'deposit', status: 'completed', timestamp: { $gte: since } } },
      { $group: { _id: null, total: { $sum: '$amount' }, count: { $sum: 1 }, uniqueUsers: { $addToSet: { $toLower: '$username' } } } }
    ], { allowDiskUse: true }),
    MoneyGiveawayClaim.aggregate([
      { $match: { claimedAt: { $gte: since } } },
      {
        $lookup: { from: 'money_giveaways', localField: 'giveawayId', foreignField: 'id', as: 'gw' }
      },
      { $group: { _id: null, total: { $sum: { $ifNull: [{ $arrayElemAt: ['$gw.amountPerWinner', 0] }, 0] } }, count: { $sum: 1 }, uniqueUsers: { $addToSet: { $toLower: '$username' } } } }
    ], { allowDiskUse: true })
  ]);
  const totals = {
    depositTotal: (globalDep[0] && globalDep[0].total) || 0,
    depositCount: (globalDep[0] && globalDep[0].count) || 0,
    depositUniqueUsers: (globalDep[0] && globalDep[0].uniqueUsers && globalDep[0].uniqueUsers.length) || 0,
    claimedTotal: (globalClaims[0] && globalClaims[0].total) || 0,
    claimedCount: (globalClaims[0] && globalClaims[0].count) || 0,
    claimedUniqueUsers: (globalClaims[0] && globalClaims[0].uniqueUsers && globalClaims[0].uniqueUsers.length) || 0
  };
  totals.netToHouse = totals.depositTotal - totals.claimedTotal;
  return {
    days,
    totals,
    topDepositors: topDepositors.map(d => ({
      username: d.username,
      totalDeposited: d.totalDeposited,
      depositCount: d.depositCount,
      lastDepositAt: d.lastDepositAt
    })),
    topClaimers: claimersEnriched
  };
}

// Calcula monto rotativo para regalo (mismo algoritmo que la per-user vieja).
function _autoStrategyGiftAmount({ tierBudget, regalosCount }) {
  const base = (Number(tierBudget) > 0 && Number(regalosCount) > 0)
    ? (Number(tierBudget) / Number(regalosCount))
    : 1000;
  // Sin activity boost porque acá es por equipo, no individual. Aplica variación ±15%.
  const variance = 0.85 + Math.random() * 0.30;
  const rounded = Math.round(base * variance / 100) * 100;
  return Math.max(500, rounded);
}

// Generación: arma TeamCampaign drafts para preview (no persiste) o para
// activar (persiste). Si commit=true, borra las auto-strategy del mes
// actual primero y crea las nuevas. Si commit=false, devuelve los drafts.
// Opciones: maxTotal (cap $ total — escala montos si excede), excludedTeams (array de teams a saltear).
async function _autoStrategyGenerate({ commit, createdBy, maxTotal, excludedTeams, reincludeUsernames }) {
  const cfg = await NotifStrategyConfig.findOne({ key: 'monthly-default' }).lean();
  if (!cfg) throw new Error('No hay NotifStrategyConfig — guardá la estrategia mensual primero.');

  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();
  const monthKey = year + '-' + String(month + 1).padStart(2, '0');
  // Días que quedan del mes (desde mañana, no hoy — para no caer dentro de minutos del request).
  const lastDay = new Date(year, month + 1, 0).getDate();
  const today = now.getDate();
  const remainingDays = [];
  for (let d = today + 1; d <= lastDay; d++) remainingDays.push(new Date(year, month, d));
  if (remainingDays.length === 0) {
    return { drafts: [], summary: { totalCampaigns: 0, totalSlotsImpacted: 0, byDay: {}, byTier: {}, byCategory: {}, byTeamLine: {} }, monthKey, regaloHunters: [], warning: 'No quedan días del mes para programar.' };
  }

  const startHour = Number.isFinite(cfg.windowStartHour) ? cfg.windowStartHour : 18;
  const endHour = Number.isFinite(cfg.windowEndHour) ? cfg.windowEndHour : 22;

  const distribution = await _autoStrategyGetDistribution();
  const drafts = [];
  // Set de equipos excluidos (case-insensitive).
  const excludedSet = new Set((Array.isArray(excludedTeams) ? excludedTeams : []).map(t => String(t || '').trim().toLowerCase()).filter(Boolean));

  // Detectar regalo-hunters y armar el set de usernames a excluir de los REGALOS.
  // Si el admin pasó reincludeUsernames (manual override), esos NO se excluyen.
  const reincludeLc = new Set((Array.isArray(reincludeUsernames) ? reincludeUsernames : []).map(u => String(u || '').toLowerCase()).filter(Boolean));
  const detectedHunters = await _detectRegaloHunters({ days: 30, minClaims: 3, maxDeposits: 0 });
  const hunterUsernames = detectedHunters
    .filter(h => !reincludeLc.has(String(h.username).toLowerCase()))
    .map(h => h.username);
  for (const dist of distribution) {
    if (!dist.team || !dist.line) continue;
    if (excludedSet.has(String(dist.team).toLowerCase())) continue; // skip equipo excluido
    for (const tier of ['suave', 'normal', 'activo']) {
      const userCount = dist[tier] || 0;
      if (userCount === 0) continue;
      const prefs = (cfg.preferences && cfg.preferences[tier]) || {};
      const tierBudget = Number(prefs.budget) || 0;
      // Solo bonos (con wa.link) y juegos (notif pelada). Los regalos
      // (giveaways de plata directa) quedan EXCLUIDOS de la auto-estrategia
      // por decisión del owner: la plata se regala via wa.link (bonos)
      // donde el user tiene que cargar para usarlo, no via plata gratis.
      // Si en algún momento querés volver a habilitarlos, agregá 'regalos'
      // de vuelta a este array.
      for (const cat of ['bonos', 'juegos']) {
        const count = Math.max(0, Number(prefs[cat]) || 0);
        if (count === 0) continue;
        const pickedDays = _autoStrategyPickDays(remainingDays, count);
        for (let i = 0; i < pickedDays.length; i++) {
          const day = pickedDays[i];
          const dayOfWeek = day.getDay();
          const specificDate = day.toISOString().slice(0, 10);
          const blueprint = (_AUTO_STRATEGY_BLUEPRINTS[cat] && _AUTO_STRATEGY_BLUEPRINTS[cat][tier])
            || { title: '🎁 Hay algo para vos', body: 'Tocá la app.' };
          // Horario por categoría:
          // - Bonos: HARDCODED 18:00 a 24:00 (00hs) — la ventana de mayor
          //   tráfico para que el user vea el wa.link y vaya a cargar de noche.
          // - Juegos: respeta el config (windowStart/EndHour) o defaults 18-22.
          const catStartHour = cat === 'bonos' ? 18 : startHour;
          const catEndHour = cat === 'bonos' ? 24 : endHour;
          const draft = {
            id: uuidv4(),
            name: cat.charAt(0).toUpperCase() + cat.slice(1) + ' ' + tier + ' · ' + dist.line + ' · ' + specificDate,
            teamFilter: dist.team,
            lineFilter: dist.line,
            tierFilter: tier,
            category: cat,
            dayOfWeek: null,
            specificDate,
            startHour: catStartHour,
            endHour: catEndHour,
            title: blueprint.title,
            body: blueprint.body,
            extraType: cat === 'regalos' ? 'giveaway' : (cat === 'bonos' ? 'promo' : 'none'),
            promoCode: cat === 'bonos' ? (tier === 'activo' ? 'BONO100' : 'BONO50') : null,
            promoMessage: cat === 'bonos' ? blueprint.body : null,
            promoDurationHours: 6,
            giveawayAmount: cat === 'regalos' ? _autoStrategyGiftAmount({ tierBudget, regalosCount: count }) : null,
            giveawayDurationMinutes: 360,
            requireApp: true,
            requireSurveyAnswered: true,
            requireActiveDays: null,
            // Solo los regalos excluyen a los regalo-hunters. Bonos y juegos
            // siguen llegándoles porque son incentivos para que vuelvan a cargar.
            excludeUsernames: cat === 'regalos' ? hunterUsernames : [],
            isActive: true,
            origin: 'auto-strategy',
            autoStrategyMonth: monthKey,
            createdBy: createdBy || 'auto-strategy'
          };
          drafts.push({ ...draft, _meta: { audienceCount: userCount } });
        }
      }
    }
  }

  // Summary: para mostrar en preview.
  // Contar usuarios solo_reembolsos para mostrar en el preview como segmento
  // informativo: estos users NO reciben bonos ni juegos, SOLO recordatorios
  // de reembolso a las 23hs cuando tienen plata pendiente (lo maneja el cron
  // de refund-reminders separado).
  const soloReembolsosByTeamLine = {};
  let soloReembolsosTotal = 0;
  for (const dist of distribution) {
    const cnt = Number(dist.solo_reembolsos) || 0;
    if (cnt === 0) continue;
    const key = (dist.team || '') + ' · ' + (dist.line || '');
    soloReembolsosByTeamLine[key] = (soloReembolsosByTeamLine[key] || 0) + cnt;
    soloReembolsosTotal += cnt;
  }

  const summary = {
    totalCampaigns: drafts.length,
    totalSlotsImpacted: drafts.reduce((s, d) => s + (d._meta?.audienceCount || 0), 0),
    byDay: {},
    byTier: { suave: 0, normal: 0, activo: 0 },
    byCategory: { bonos: 0, juegos: 0, regalos: 0 },
    byTeamLine: {},
    // Segmento solo_reembolsos: visible en el preview pero NO se generan
    // campañas para ellos. Los maneja refundReminderService a las 23hs.
    soloReembolsos: {
      total: soloReembolsosTotal,
      byTeamLine: soloReembolsosByTeamLine
    },
    // Costos $ potenciales (worst case: si todos reclaman)
    money: {
      regalosMaxTotal: 0,           // suma de (giveawayAmount × audienceCount) de todos los drafts de regalo
      regalosCampaignCount: 0,
      avgGiveawayAmount: 0,
      byTeamLineMoney: {},          // dinero potencial por equipo/línea
      byTierMoney: { suave: 0, normal: 0, activo: 0 }
    }
  };
  for (const d of drafts) {
    summary.byDay[d.specificDate] = (summary.byDay[d.specificDate] || 0) + 1;
    summary.byTier[d.tierFilter] = (summary.byTier[d.tierFilter] || 0) + 1;
    summary.byCategory[d.category] = (summary.byCategory[d.category] || 0) + 1;
    const key = d.teamFilter + ' · ' + d.lineFilter;
    summary.byTeamLine[key] = (summary.byTeamLine[key] || 0) + 1;
    // Costos en plata
    if (d.category === 'regalos' && d.giveawayAmount) {
      const audience = d._meta?.audienceCount || 0;
      const potentialCost = d.giveawayAmount * audience;
      summary.money.regalosMaxTotal += potentialCost;
      summary.money.regalosCampaignCount++;
      summary.money.byTeamLineMoney[key] = (summary.money.byTeamLineMoney[key] || 0) + potentialCost;
      summary.money.byTierMoney[d.tierFilter] = (summary.money.byTierMoney[d.tierFilter] || 0) + potentialCost;
    }
  }
  summary.money.avgGiveawayAmount = summary.money.regalosCampaignCount > 0
    ? Math.round(summary.money.regalosMaxTotal / Math.max(1, summary.totalSlotsImpacted))
    : 0;

  // CAP — si el total máximo a regalar excede `maxTotal`, escalamos los
  // montos proporcionalmente hacia abajo para encajar. Floor $500 por regalo.
  const cap = Number(maxTotal) > 0 ? Number(maxTotal) : 0;
  summary.money.cap = cap;
  summary.money.scaled = false;
  summary.money.scaleFactor = 1;
  if (cap > 0 && summary.money.regalosMaxTotal > cap) {
    const factor = cap / summary.money.regalosMaxTotal;
    // Aplicar al campo `giveawayAmount` de cada draft de regalo. Floor 500.
    let newTotal = 0;
    const tlMoneyNew = {};
    const tierMoneyNew = { suave: 0, normal: 0, activo: 0 };
    for (const d of drafts) {
      if (d.category === 'regalos' && d.giveawayAmount) {
        const scaled = Math.max(500, Math.round(d.giveawayAmount * factor / 100) * 100);
        d.giveawayAmount = scaled;
        const audience = d._meta?.audienceCount || 0;
        const cost = scaled * audience;
        newTotal += cost;
        const key = d.teamFilter + ' · ' + d.lineFilter;
        tlMoneyNew[key] = (tlMoneyNew[key] || 0) + cost;
        if (tierMoneyNew[d.tierFilter] !== undefined) tierMoneyNew[d.tierFilter] += cost;
      }
    }
    summary.money.regalosMaxTotal = newTotal;
    summary.money.byTeamLineMoney = tlMoneyNew;
    summary.money.byTierMoney = tierMoneyNew;
    summary.money.scaled = true;
    summary.money.scaleFactor = factor;
    summary.money.avgGiveawayAmount = summary.money.regalosCampaignCount > 0
      ? Math.round(newTotal / Math.max(1, summary.totalSlotsImpacted))
      : 0;
  }
  // Info sobre teams excluidos para devolver al cliente.
  summary.excludedTeams = Array.from(excludedSet);

  if (commit) {
    // Borrar campañas auto-strategy del mes actual antes de crear las nuevas.
    await TeamCampaign.deleteMany({ origin: 'auto-strategy', autoStrategyMonth: monthKey });
    // Insertar todas las drafts.
    const toInsert = drafts.map(d => { const x = { ...d }; delete x._meta; return x; });
    if (toInsert.length > 0) {
      await TeamCampaign.insertMany(toInsert);
    }
    logger.info(`[AUTO-STRATEGY] generated ${toInsert.length} campaigns for ${monthKey} by=${createdBy || 'admin'}`);
  }
  return {
    drafts, summary, monthKey,
    remainingDaysCount: remainingDays.length,
    // Info de regalo-hunters para que el admin la vea en el preview.
    regaloHunters: {
      detected: detectedHunters,        // lista completa con detalle
      excludedCount: hunterUsernames.length, // los que efectivamente quedan excluidos
      reincludedCount: detectedHunters.length - hunterUsernames.length,
      reincludedUsernames: Array.from(reincludeLc)
    }
  };
}

// GET preview: arma drafts sin persistir, devuelve summary + listado resumido.
// Acepta query params: maxTotal (cap $), excludedTeams (csv de teams a saltear).
app.get('/api/admin/team-campaigns/auto-strategy/preview', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const maxTotal = Number(req.query.maxTotal) || 1000000;
    const excludedTeams = String(req.query.excludedTeams || '').split(',').map(t => t.trim()).filter(Boolean);
    const reincludeUsernames = String(req.query.reincludeUsernames || '').split(',').map(u => u.trim()).filter(Boolean);
    const r = await _autoStrategyGenerate({ commit: false, maxTotal, excludedTeams, reincludeUsernames });
    res.json({
      success: true,
      monthKey: r.monthKey,
      remainingDaysCount: r.remainingDaysCount,
      summary: r.summary,
      maxTotal,
      excludedTeams,
      reincludeUsernames,
      regaloHunters: r.regaloHunters || { detected: [], excludedCount: 0, reincludedCount: 0, reincludedUsernames: [] },
      sampleDrafts: r.drafts.slice(0, 20).map(d => ({
        name: d.name, teamFilter: d.teamFilter, lineFilter: d.lineFilter, tierFilter: d.tierFilter,
        category: d.category, specificDate: d.specificDate, startHour: d.startHour, endHour: d.endHour,
        extraType: d.extraType, promoCode: d.promoCode, giveawayAmount: d.giveawayAmount,
        audienceCount: d._meta?.audienceCount || 0,
        excludeUsernamesCount: Array.isArray(d.excludeUsernames) ? d.excludeUsernames.length : 0
      }))
    });
  } catch (err) {
    logger.error(`/api/admin/team-campaigns/auto-strategy/preview: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// GET regalo-hunters — lista detectada con detalle (sin generar nada).
// Sirve para que el personal revise quiénes son los sospechosos sin tocar
// la auto-estrategia. Query params: days (30 default), minClaims (3 default).
app.get('/api/admin/team-campaigns/regalo-hunters', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const days = Math.max(1, Math.min(180, parseInt(req.query.days, 10) || 30));
    const minClaims = Math.max(1, parseInt(req.query.minClaims, 10) || 3);
    const maxDeposits = Math.max(0, Number(req.query.maxDeposits) || 0);
    const list = await _detectRegaloHunters({ days, minClaims, maxDeposits });
    res.json({ success: true, days, minClaims, maxDeposits, hunters: list, total: list.length });
  } catch (err) {
    logger.error(`/api/admin/team-campaigns/regalo-hunters: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// GET user-analysis — top depositantes / top reclamadores / net positive/negative.
// Sirve para que el personal vea de un vistazo quiénes son los buenos clientes
// y los que solo vienen a sacar.
app.get('/api/admin/team-campaigns/user-analysis', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const days = Math.max(1, Math.min(180, parseInt(req.query.days, 10) || 30));
    const data = await _userAnalysisReport({ days });
    res.json({ success: true, ...data });
  } catch (err) {
    logger.error(`/api/admin/team-campaigns/user-analysis: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// POST test-fire: dispara UN push de prueba inmediato a un user de prueba
// (default 'lalodj') usando el blueprint del tier+categoría elegidos. Sirve
// para verificar que el sistema entrega bien antes de activar la estrategia
// completa del mes. NO persiste ninguna campaña — solo crea una
// ScheduledNotification one-off a +30s. Cuando el cron del scheduler la
// levante (_executeScheduledNotification), creará el promo/giveaway scoped
// al user via audienceWhitelist (el fix de leak está en esa función).
app.post('/api/admin/team-campaigns/auto-strategy/test-fire', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (req.user.role !== 'admin') return res.status(403).json({ error: 'Solo el admin principal puede disparar tests' });
    const b = req.body || {};
    const testUser = String(b.testUser || 'lalodj').trim().toLowerCase();
    const category = ['bonos','juegos','regalos'].includes(b.category) ? b.category : 'bonos';
    const tier = ['suave','normal','activo'].includes(b.tier) ? b.tier : 'normal';

    // Verificar que el user existe.
    const u = await User.findOne({ username: _ciExact(testUser) }, { username: 1, fcmToken: 1, fcmTokens: 1, _id: 0 }).lean();
    if (!u) return res.status(404).json({ error: `Usuario '${testUser}' no existe en la base.` });
    const hasToken = !!u.fcmToken || (Array.isArray(u.fcmTokens) && u.fcmTokens.length > 0);
    if (!hasToken) return res.status(400).json({ error: `Usuario '${testUser}' no tiene la app instalada (sin fcmToken). El push no llegaría.` });

    // Tomar blueprint y montos defaults del config para que el preview real coincida.
    const blueprint = (_AUTO_STRATEGY_BLUEPRINTS[category] && _AUTO_STRATEGY_BLUEPRINTS[category][tier])
      || { title: '🧪 Test', body: 'Push de prueba.' };
    const cfg = await NotifStrategyConfig.findOne({ key: 'monthly-default' }).lean();
    const tierBudget = (cfg && cfg.preferences && cfg.preferences[tier] && cfg.preferences[tier].budget) || 100000;
    const regalosCount = (cfg && cfg.preferences && cfg.preferences[tier] && cfg.preferences[tier].regalos) || 2;

    const sched = {
      id: uuidv4(),
      scheduledFor: new Date(), // ahora — fire inmediato
      status: 'processing',     // marca processing directo para que el cron no lo agarre
      processingStartedAt: new Date(),
      title: blueprint.title + ' (PRUEBA)',
      body: blueprint.body,
      targetUsername: u.username, // preserva casing real
      audiencePrefix: null,
      extraType: category === 'regalos' ? 'giveaway' : (category === 'bonos' ? 'promo' : 'none'),
      createdBy: `team-campaign-test:${tier}:${category}:${u.username}`
    };
    if (sched.extraType === 'promo') {
      sched.promoCode = tier === 'activo' ? 'BONO100' : 'BONO50';
      sched.promoMessage = blueprint.body;
      sched.promoDurationHours = 6;
    } else if (sched.extraType === 'giveaway') {
      sched.giveawayAmount = _autoStrategyGiftAmount({ tierBudget, regalosCount });
      sched.giveawayDurationMinutes = 360;
    }
    const doc = await ScheduledNotification.create(sched);
    // Disparar AHORA — sin esperar al cron de 60s. Replica lo que hace el
    // scheduler: ejecuta el push + crea el promo/giveaway scoped via
    // audienceWhitelist, marca como sent. Si falla, queda failed con el error.
    let executed = false;
    let executeError = null;
    try {
      await _executeScheduledNotification(sched);
      await ScheduledNotification.updateOne(
        { id: sched.id },
        { $set: { status: 'sent', executedAt: new Date() }, $unset: { processingStartedAt: 1 } }
      ).catch(() => {});
      executed = true;
      logger.info(`[test-fire] notif ${sched.id} ejecutada INMEDIATO para ${u.username}`);
    } catch (e) {
      executeError = e.message || String(e);
      logger.error(`[test-fire] error ejecutando ${sched.id}: ${executeError}`);
      await ScheduledNotification.updateOne(
        { id: sched.id },
        { $set: { status: 'failed', errorMsg: executeError.slice(0, 500) }, $unset: { processingStartedAt: 1 } }
      ).catch(() => {});
    }
    res.json({
      success: executed,
      executed,
      executeError,
      scheduledFor: sched.scheduledFor,
      targetUsername: u.username,
      category, tier,
      extraType: sched.extraType,
      promoCode: sched.promoCode || null,
      giveawayAmount: sched.giveawayAmount || null,
      title: sched.title,
      message: executed
        ? `Push enviado AHORA a ${u.username}. Si tiene la app abierta, ya debería ver la notif + ${sched.extraType === 'promo' ? 'cartel wa.link de promo' : sched.extraType === 'giveaway' ? 'botón para reclamar plata' : 'solo el push'}.`
        : `Falló el envío: ${executeError}`
    });
  } catch (err) {
    logger.error(`/api/admin/team-campaigns/auto-strategy/test-fire: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// POST commit: borra las auto-strategy del mes y crea las nuevas.
// Acepta body: { maxTotal, excludedTeams }
app.post('/api/admin/team-campaigns/auto-strategy/commit', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (req.user.role !== 'admin') return res.status(403).json({ error: 'Solo el admin principal' });
    const b = req.body || {};
    const maxTotal = Number(b.maxTotal) || 1000000;
    const excludedTeams = Array.isArray(b.excludedTeams) ? b.excludedTeams : [];
    const reincludeUsernames = Array.isArray(b.reincludeUsernames) ? b.reincludeUsernames : [];
    const r = await _autoStrategyGenerate({ commit: true, createdBy: req.user.username || 'admin', maxTotal, excludedTeams, reincludeUsernames });
    res.json({
      success: true,
      monthKey: r.monthKey,
      campaignsCreated: r.drafts.length,
      summary: r.summary,
      regaloHunters: r.regaloHunters || { detected: [], excludedCount: 0 }
    });
  } catch (err) {
    logger.error(`/api/admin/team-campaigns/auto-strategy/commit: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// GET /api/admin/giveaway-claims.csv?from=YYYY-MM-DD&to=YYYY-MM-DD&source=...
// Descarga CSV con TODOS los bonos reclamados por usuarios. Sirve para
// auditar quién cobró qué, cuándo, y de qué giveaway.
//
// Filtros opcionales:
//   from / to: rango de fecha de claim (ART). Default = últimos 30 días.
//   source:    'auto-strategy' | 'auto-rule' | 'manual' | 'individual_grant'.
//              Default = todos los sources.
//   status:    'completed' | 'pending_credit_failed'. Default = todos.
//
// Columnas: Fecha, Hora, Usuario, Monto, Origen, Status, GiveawayID, TransactionID.
app.get('/api/admin/giveaway-claims.csv', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const ART_DAY_START_OFFSET_MS = 3 * 60 * 60 * 1000;
    const DAY_MS = 24 * 60 * 60 * 1000;
    const { from, to, source, status } = req.query || {};

    // Parsear rango de fechas (defaults: últimos 30 días ART).
    let startUTC, endUTC;
    if (from && to && /^\d{4}-\d{2}-\d{2}$/.test(from) && /^\d{4}-\d{2}-\d{2}$/.test(to)) {
      const [fy, fm, fd] = from.split('-').map(Number);
      const [ty, tm, td] = to.split('-').map(Number);
      startUTC = new Date(Date.UTC(fy, fm - 1, fd, 3, 0, 0, 0));
      endUTC = new Date(Date.UTC(ty, tm - 1, td, 3, 0, 0, 0) + DAY_MS - 1);
    } else {
      endUTC = new Date();
      startUTC = new Date(endUTC.getTime() - 30 * DAY_MS);
    }

    // Filtros para la query.
    const claimFilter = { claimedAt: { $gte: startUTC, $lte: endUTC } };
    if (status === 'completed' || status === 'pending_credit_failed') {
      claimFilter.status = status;
    }

    // Traer claims (cap defensivo en 50k para no tumbar memoria del server).
    const claims = await MoneyGiveawayClaim
      .find(claimFilter, { username: 1, amount: 1, claimedAt: 1, giveawayId: 1, transactionId: 1, status: 1, _id: 0 })
      .sort({ claimedAt: -1 })
      .limit(50000)
      .lean();

    // Resolver el `strategySource` de cada giveaway (1 query agregada por id).
    const giveawayIds = Array.from(new Set(claims.map(c => c.giveawayId).filter(Boolean)));
    let sourceByGiveaway = new Map();
    if (giveawayIds.length > 0) {
      const giveaways = await MoneyGiveaway
        .find({ id: { $in: giveawayIds } }, { id: 1, strategySource: 1, prefix: 1, createdBy: 1, _id: 0 })
        .lean();
      for (const g of giveaways) sourceByGiveaway.set(g.id, g);
    }

    // Filtro por source (si vino).
    let rows = claims;
    if (typeof source === 'string' && source.trim()) {
      const wanted = source.trim();
      rows = rows.filter(c => {
        const g = sourceByGiveaway.get(c.giveawayId);
        return g && g.strategySource === wanted;
      });
    }

    // Helper: formato Fecha + Hora en ART desde un Date UTC.
    const fmtArt = (utcDate) => {
      const ms = new Date(utcDate).getTime() - ART_DAY_START_OFFSET_MS;
      const d = new Date(ms);
      const date = d.toISOString().slice(0, 10); // YYYY-MM-DD
      // Hora: tomamos el Date UTC original, le restamos 3h, y leemos las
      // horas/minutos del nuevo Date. iso slice(11,19) da HH:MM:SS.
      const time = d.toISOString().slice(11, 19);
      return { date, time };
    };

    // Escape CSV: quotear si tiene coma, comilla, salto o CR.
    const csvEscape = (v) => {
      const s = v == null ? '' : String(v);
      return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
    };

    const lines = ['Fecha,Hora,Usuario,Monto,Origen,Status,GiveawayID,TransactionID'];
    for (const c of rows) {
      const { date, time } = fmtArt(c.claimedAt);
      const g = sourceByGiveaway.get(c.giveawayId) || {};
      lines.push([
        csvEscape(date),
        csvEscape(time),
        csvEscape(c.username),
        csvEscape(c.amount),
        csvEscape(g.strategySource || 'unknown'),
        csvEscape(c.status || 'completed'),
        csvEscape(c.giveawayId || ''),
        csvEscape(c.transactionId || '')
      ].join(','));
    }
    // BOM UTF-8 + CRLF para que Excel lo abra bien con tildes.
    const csv = '﻿' + lines.join('\r\n');

    const fname = `bonos-claims_${startUTC.toISOString().slice(0,10)}_${endUTC.toISOString().slice(0,10)}.csv`;
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition', `attachment; filename="${fname}"`);
    res.send(csv);
  } catch (error) {
    logger.error(`/api/admin/giveaway-claims.csv: ${error.message}\n${error.stack}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// GET agenda: devuelve qué campañas se van a disparar en una fecha dada
// (default: mañana). Agrupa por equipo para que el personal sepa qué
// notifs salen ese día. Muestra: hora, categoría, contenido, target,
// estimación de audience.
app.get('/api/admin/team-campaigns/agenda', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const dateStr = String((req.query && req.query.date) || '').trim();
    let targetDate;
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
      targetDate = new Date(dateStr + 'T00:00:00');
    } else {
      // Default: mañana.
      targetDate = new Date();
      targetDate.setDate(targetDate.getDate() + 1);
      targetDate.setHours(0, 0, 0, 0);
    }
    if (isNaN(targetDate.getTime())) return res.status(400).json({ error: 'date inválida (YYYY-MM-DD)' });
    const targetDateStr = targetDate.toISOString().slice(0, 10);
    const targetDayOfWeek = targetDate.getDay();

    // Defensive: verificar que el modelo está cargado antes de usarlo.
    // Si TeamCampaign está undefined acá significa que hay un problema con
    // los imports/registros — devolvemos un error claro en vez de el genérico
    // "Cannot read properties of undefined (reading 'find')".
    if (!TeamCampaign || typeof TeamCampaign.find !== 'function') {
      logger.error('[agenda] TeamCampaign model is undefined or invalid');
      return res.status(500).json({ error: 'Modelo TeamCampaign no disponible — reinicia el server.' });
    }

    // Levantar campañas activas que matchean ese día.
    const allActive = await TeamCampaign.find({ isActive: true }).lean();
    const matching = allActive.filter(c => {
      // Match día: dayOfWeek == target OR specificDate == target OR ambos null=todos los días.
      return (c.dayOfWeek == null && !c.specificDate)
          || (c.dayOfWeek != null && c.dayOfWeek === targetDayOfWeek)
          || (c.specificDate && c.specificDate === targetDateStr);
    });

    if (matching.length === 0) {
      return res.json({ date: targetDateStr, dayName: ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'][targetDayOfWeek], total: 0, byTeam: {}, items: [] });
    }

    // Para cada campaña matching, estimar audience count.
    const items = [];
    for (const c of matching) {
      const audienceCount = await _countTeamCampaignAudience(c);
      items.push({
        id: c.id,
        name: c.name,
        team: c.teamFilter || 'Todos los equipos',
        line: c.lineFilter || null,
        tier: c.tierFilter || null,
        category: c.category,
        startHour: c.startHour,
        endHour: c.endHour,
        title: c.title,
        body: c.body,
        extraType: c.extraType,
        promoCode: c.promoCode || null,
        giveawayAmount: c.giveawayAmount || null,
        origin: c.origin,
        audienceCount,
        potentialCost: (c.category === 'regalos' && c.giveawayAmount) ? c.giveawayAmount * audienceCount : 0
      });
    }
    // Orden: por hora ascendente, luego por equipo.
    items.sort((a, b) => (a.startHour - b.startHour) || a.team.localeCompare(b.team) || (a.line || '').localeCompare(b.line || ''));

    // Agrupar por equipo (para la vista del personal).
    const byTeam = {};
    for (const it of items) {
      if (!byTeam[it.team]) byTeam[it.team] = { team: it.team, items: [], totalAudience: 0, totalCost: 0 };
      byTeam[it.team].items.push(it);
      byTeam[it.team].totalAudience += it.audienceCount;
      byTeam[it.team].totalCost += it.potentialCost;
    }

    res.json({
      date: targetDateStr,
      dayName: ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'][targetDayOfWeek],
      total: items.length,
      totalAudience: items.reduce((s, it) => s + it.audienceCount, 0),
      totalPotentialCost: items.reduce((s, it) => s + it.potentialCost, 0),
      byTeam,
      items
    });
  } catch (err) {
    logger.error(`/api/admin/team-campaigns/agenda: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// GET reaction de UNA campaña: cruza NotificationHistory (disparos
// efectivos vía scheduler) con waClicks (clicks en wa.link) y
// MoneyGiveawayClaim (reclamos de regalos). Mide la conversión real.
app.get('/api/admin/team-campaigns/:id([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})/reaction', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const campaignId = String(req.params.id || '').trim();
    const campaign = await TeamCampaign.findOne({ id: campaignId }).lean();
    if (!campaign) return res.status(404).json({ error: 'Campaña no encontrada' });

    // Buscar NotificationHistory creadas a partir de scheduled notifs de esta campaña.
    // El sentBy de NotificationHistory == createdBy de la ScheduledNotification origin
    // que arranca con `team-campaign:${id}:`.
    const sentByPrefix = '^team-campaign:' + campaignId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ':';
    const histories = await NotificationHistory.find({
      sentBy: { $regex: sentByPrefix }
    }, {
      id: 1, sentAt: 1, audienceType: 1, totalUsers: 1, successCount: 1, failureCount: 1,
      type: 1, promoCode: 1, giveawayAmount: 1, giveawayExpiresAt: 1, waClicks: 1, _id: 0
    }).sort({ sentAt: -1 }).limit(200).lean();

    // Para cada fire que era giveaway, buscar MoneyGiveaway → MoneyGiveawayClaim.
    const histIds = histories.filter(h => h.type === 'money_giveaway').map(h => h.id);
    let giveawaysByHistId = new Map();
    if (histIds.length > 0) {
      const gws = await MoneyGiveaway.find({ notificationHistoryId: { $in: histIds } }, { id: 1, notificationHistoryId: 1, totalGiven: 1, claimedCount: 1, _id: 0 }).lean();
      giveawaysByHistId = new Map(gws.map(g => [g.notificationHistoryId, g]));
    }

    // Armar fires con sus métricas.
    const fires = histories.map(h => {
      const gw = giveawaysByHistId.get(h.id) || null;
      const totalUsers = h.totalUsers || 0;
      const successCount = h.successCount || 0;
      const waClicks = h.waClicks || 0;
      const claims = gw ? (gw.claimedCount || 0) : 0;
      const totalGiven = gw ? (gw.totalGiven || 0) : 0;
      return {
        historyId: h.id,
        sentAt: h.sentAt,
        type: h.type,
        totalUsers,
        successCount,
        failureCount: h.failureCount || 0,
        promoCode: h.promoCode || null,
        giveawayAmount: h.giveawayAmount || null,
        waClicks,
        waClickRate: successCount > 0 ? (waClicks / successCount) : 0,
        claims,
        claimRate: successCount > 0 ? (claims / successCount) : 0,
        totalGiven
      };
    });

    // Agregados.
    const agg = {
      totalFires: fires.length,
      totalUsersReached: fires.reduce((s, f) => s + f.successCount, 0),
      totalWaClicks: fires.reduce((s, f) => s + f.waClicks, 0),
      totalClaims: fires.reduce((s, f) => s + f.claims, 0),
      totalGiven: fires.reduce((s, f) => s + f.totalGiven, 0),
      avgWaClickRate: 0,
      avgClaimRate: 0
    };
    if (agg.totalUsersReached > 0) {
      agg.avgWaClickRate = agg.totalWaClicks / agg.totalUsersReached;
      agg.avgClaimRate = agg.totalClaims / agg.totalUsersReached;
    }

    // Per-user breakdown — cruza audienceUsernames de cada history con WaClickLog
    // y MoneyGiveawayClaim. Mide: ¿le llegó? ¿tocó wa.link? ¿reclamó plata?
    // Útil para auditar conversión por jugador y exportar a CSV.
    const perUser = {};
    // 1) Levantar audienceUsernames + datos extra desde NotificationHistory.
    const allHistIds = histories.map(h => h.id);
    if (allHistIds.length > 0) {
      const fullHists = await NotificationHistory.find(
        { id: { $in: allHistIds } },
        { id: 1, sentAt: 1, audienceUsernames: 1, _id: 0 }
      ).lean();
      // Map id → {sentAt, audienceUsernames}
      const histMeta = new Map(fullHists.map(h => [h.id, h]));
      for (const h of fullHists) {
        const list = Array.isArray(h.audienceUsernames) ? h.audienceUsernames : [];
        for (const uname of list) {
          const key = String(uname || '').toLowerCase();
          if (!key) continue;
          if (!perUser[key]) {
            perUser[key] = { username: uname, pushesReceived: 0, waClicks: 0, claims: 0, totalClaimedAmount: 0, lastPushAt: null, lastWaClickAt: null, lastClaimAt: null };
          }
          perUser[key].pushesReceived += 1;
          if (!perUser[key].lastPushAt || h.sentAt > perUser[key].lastPushAt) perUser[key].lastPushAt = h.sentAt;
        }
      }

      // 2) WaClickLog scoped por estos history ids.
      const waLogs = await WaClickLog.find(
        { notificationHistoryId: { $in: allHistIds } },
        { username: 1, clickedAt: 1, _id: 0 }
      ).lean();
      for (const wl of waLogs) {
        const key = String(wl.username || '').toLowerCase();
        if (!key) continue;
        if (!perUser[key]) {
          perUser[key] = { username: wl.username, pushesReceived: 0, waClicks: 0, claims: 0, totalClaimedAmount: 0, lastPushAt: null, lastWaClickAt: null, lastClaimAt: null };
        }
        perUser[key].waClicks += 1;
        if (!perUser[key].lastWaClickAt || wl.clickedAt > perUser[key].lastWaClickAt) perUser[key].lastWaClickAt = wl.clickedAt;
      }

      // 3) MoneyGiveawayClaim — necesitamos ir via MoneyGiveaway.notificationHistoryId.
      if (histIds.length > 0) {
        const gws = await MoneyGiveaway.find(
          { notificationHistoryId: { $in: histIds } },
          { id: 1, notificationHistoryId: 1, amountPerWinner: 1, totalGiven: 1, claimedCount: 1, _id: 0 }
        ).lean();
        const gwIds = gws.map(g => g.id);
        if (gwIds.length > 0) {
          const gwById = new Map(gws.map(g => [g.id, g]));
          const claims = await MoneyGiveawayClaim.find(
            { giveawayId: { $in: gwIds } },
            { giveawayId: 1, username: 1, claimedAt: 1, _id: 0 }
          ).lean();
          for (const cl of claims) {
            const key = String(cl.username || '').toLowerCase();
            if (!key) continue;
            const gw = gwById.get(cl.giveawayId);
            const amount = gw ? (gw.amountPerWinner || 0) : 0;
            if (!perUser[key]) {
              perUser[key] = { username: cl.username, pushesReceived: 0, waClicks: 0, claims: 0, totalClaimedAmount: 0, lastPushAt: null, lastWaClickAt: null, lastClaimAt: null };
            }
            perUser[key].claims += 1;
            perUser[key].totalClaimedAmount += amount;
            if (!perUser[key].lastClaimAt || cl.claimedAt > perUser[key].lastClaimAt) perUser[key].lastClaimAt = cl.claimedAt;
          }
        }
      }
    }
    // Convertir a array y ordenar: primero los que reclamaron (más valioso), luego los que tocaron wa.link, luego los pasivos.
    const perUserArr = Object.values(perUser).sort((a, b) => {
      if (b.claims !== a.claims) return b.claims - a.claims;
      if (b.waClicks !== a.waClicks) return b.waClicks - a.waClicks;
      return (b.totalClaimedAmount || 0) - (a.totalClaimedAmount || 0);
    });

    res.json({ campaign, fires, aggregate: agg, perUser: perUserArr });
  } catch (err) {
    logger.error(`/api/admin/team-campaigns/:id/reaction: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// GET reaction agregado por team/tier/categoría sobre TODAS las campañas
// activas del último período (default 30 días). Sirve para responder
// "qué team responde mejor", "qué tier convierte más en bonos vs regalos".
app.get('/api/admin/team-campaigns/reaction/summary', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const days = Math.max(1, Math.min(180, parseInt(req.query.days, 10) || 30));
    const since = new Date(Date.now() - days * 86400000);

    // Pull TODAS las campañas + sus histories en el período.
    const campaigns = await TeamCampaign.find({}).lean();
    const campaignMap = new Map(campaigns.map(c => [c.id, c]));

    // Pull histories del período cuyo sentBy arranca con team-campaign:
    const histories = await NotificationHistory.find({
      sentAt: { $gte: since },
      sentBy: { $regex: '^team-campaign:' }
    }, {
      id: 1, sentAt: 1, totalUsers: 1, successCount: 1, type: 1, waClicks: 1, sentBy: 1, _id: 0
    }).lean();

    // Pull giveaway claims para los histories que son money_giveaway.
    const gwHistIds = histories.filter(h => h.type === 'money_giveaway').map(h => h.id);
    const giveaways = gwHistIds.length > 0
      ? await MoneyGiveaway.find({ notificationHistoryId: { $in: gwHistIds } }, { notificationHistoryId: 1, claimedCount: 1, totalGiven: 1, _id: 0 }).lean()
      : [];
    const gwByHist = new Map(giveaways.map(g => [g.notificationHistoryId, g]));

    // Bucket por (team, tier, category).
    const buckets = {}; // key: team::tier::category → stats
    const byTeam = {};
    const byTier = { suave: { reached:0, waClicks:0, claims:0, given:0 }, normal: { reached:0, waClicks:0, claims:0, given:0 }, activo: { reached:0, waClicks:0, claims:0, given:0 } };
    const byCategory = { bonos: { reached:0, waClicks:0, claims:0, given:0 }, juegos: { reached:0, waClicks:0, claims:0, given:0 }, regalos: { reached:0, waClicks:0, claims:0, given:0 } };

    for (const h of histories) {
      // Extraer campaignId del sentBy.
      const m = String(h.sentBy || '').match(/^team-campaign:([^:]+):/);
      if (!m) continue;
      const cId = m[1];
      const c = campaignMap.get(cId);
      if (!c) continue;
      const team = c.teamFilter || 'sin-equipo';
      const tier = c.tierFilter || 'sin-tier';
      const cat = c.category || 'notif';
      const reached = h.successCount || 0;
      const waClicks = h.waClicks || 0;
      const gw = gwByHist.get(h.id);
      const claims = gw ? (gw.claimedCount || 0) : 0;
      const given = gw ? (gw.totalGiven || 0) : 0;

      const k = team + '::' + tier + '::' + cat;
      if (!buckets[k]) buckets[k] = { team, tier, category: cat, fires: 0, reached: 0, waClicks: 0, claims: 0, given: 0 };
      buckets[k].fires++;
      buckets[k].reached += reached;
      buckets[k].waClicks += waClicks;
      buckets[k].claims += claims;
      buckets[k].given += given;

      if (!byTeam[team]) byTeam[team] = { reached: 0, waClicks: 0, claims: 0, given: 0 };
      byTeam[team].reached += reached;
      byTeam[team].waClicks += waClicks;
      byTeam[team].claims += claims;
      byTeam[team].given += given;

      if (tier && byTier[tier]) {
        byTier[tier].reached += reached;
        byTier[tier].waClicks += waClicks;
        byTier[tier].claims += claims;
        byTier[tier].given += given;
      }
      if (cat && byCategory[cat]) {
        byCategory[cat].reached += reached;
        byCategory[cat].waClicks += waClicks;
        byCategory[cat].claims += claims;
        byCategory[cat].given += given;
      }
    }

    // Convertir buckets a array ordenado por reach desc.
    const bucketList = Object.values(buckets).sort((a, b) => b.reached - a.reached);

    // Totales globales.
    const totals = {
      reached: histories.reduce((s, h) => s + (h.successCount || 0), 0),
      waClicks: histories.reduce((s, h) => s + (h.waClicks || 0), 0),
      claims: giveaways.reduce((s, g) => s + (g.claimedCount || 0), 0),
      given: giveaways.reduce((s, g) => s + (g.totalGiven || 0), 0),
      fires: histories.length
    };

    res.json({ days, totals, byTeam, byTier, byCategory, buckets: bucketList });
  } catch (err) {
    logger.error(`/api/admin/team-campaigns/reaction/summary: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// DELETE all auto-strategy del mes: limpieza.
app.delete('/api/admin/team-campaigns/auto-strategy', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (req.user.role !== 'admin') return res.status(403).json({ error: 'Solo el admin principal' });
    const now = new Date();
    const monthKey = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
    const r = await TeamCampaign.deleteMany({ origin: 'auto-strategy', autoStrategyMonth: monthKey });
    logger.info(`[AUTO-STRATEGY] cleared ${r.deletedCount} for ${monthKey}`);
    res.json({ success: true, deletedCount: r.deletedCount });
  } catch (err) {
    logger.error(`/api/admin/team-campaigns/auto-strategy DELETE: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// =====================================================================
// REVIEWS — opiniones de usuarios (1 por user, 1-5★, comentario ≤ 100ch).
// Categorización: 1-2★ malo · 3★ regular · 4-5★ bueno.
// =====================================================================
function _maskUsername(u) {
  const s = String(u || '');
  if (!s) return '***';
  // Mostrar el último 20% (mínimo 1, máximo 6 chars), el resto con *.
  const visibleChars = Math.max(1, Math.min(6, Math.ceil(s.length * 0.20)));
  const hiddenChars = s.length - visibleChars;
  return '*'.repeat(hiddenChars) + s.slice(hiddenChars);
}
function _bucketOf(stars) {
  const n = Number(stars) || 0;
  if (n >= 4) return 'bueno';
  if (n === 3) return 'regular';
  return 'malo';
}

// POST /api/reviews — el user crea su review (1 sola vez, no se puede editar).
app.post('/api/reviews', authMiddleware, async (req, res) => {
  try {
    const userId = req.user.userId;
    const username = req.user.username;
    const stars = Math.round(Number((req.body && req.body.stars) || 0));
    const comment = String((req.body && req.body.comment) || '').trim().slice(0, 100);
    // Teléfono opcional — solo dígitos, +, espacios y guiones. Truncado a 25.
    const contactPhone = String((req.body && req.body.contactPhone) || '')
      .trim().replace(/[^\d+\-\s()]/g, '').slice(0, 25);
    if (!isFinite(stars) || stars < 1 || stars > 5) {
      return res.status(400).json({ error: 'Estrellas inválidas (1-5)' });
    }
    // 1 review por user — si ya votó, no permitir más.
    const existing = await Review.findOne({ userId }).lean();
    if (existing) {
      return res.status(409).json({ error: 'Ya enviaste tu opinión. Solo se permite una por usuario.', alreadyReviewed: true });
    }
    const now = new Date();
    let saved;
    try {
      saved = await Review.create({
        id: uuidv4(),
        userId,
        username,
        stars,
        comment,
        contactPhone,
        createdAt: now,
        updatedAt: now
      });
      saved = saved.toObject ? saved.toObject() : saved;
    } catch (e) {
      // Race: otro POST simultáneo creó la review primero (unique index).
      if (e && e.code === 11000) {
        return res.status(409).json({ error: 'Ya enviaste tu opinión.', alreadyReviewed: true });
      }
      throw e;
    }
    res.json({
      success: true,
      review: {
        stars: saved.stars,
        comment: saved.comment || '',
        updatedAt: saved.updatedAt
      }
    });
  } catch (err) {
    logger.error(`POST /api/reviews: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// GET /api/reviews/mine — devuelve la review propia (si existe).
app.get('/api/reviews/mine', authMiddleware, async (req, res) => {
  try {
    const r = await Review.findOne({ userId: req.user.userId }).lean();
    if (!r) return res.json({ review: null });
    res.json({
      review: {
        stars: r.stars,
        comment: r.comment || '',
        updatedAt: r.updatedAt
      }
    });
  } catch (err) {
    logger.error(`GET /api/reviews/mine: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// ============================================================
// USER NOTIFICATION INBOX — para que el user relea pushes recibidos
// ============================================================

// Helper: persiste 1 row por (user, push) para que aparezca en el inbox.
// Fire-and-forget — errores no rompen el flow del push.
// `targets` puede venir como array de { userId, username } o de docs User.
async function _persistUserNotifications(targets, payload) {
  try {
    if (!Array.isArray(targets) || targets.length === 0) return 0;
    const now = new Date();
    const docs = [];
    for (const t of targets) {
      if (!t) continue;
      const uname = String(t.username || '').trim().toLowerCase();
      const uid = t.userId || t.id || null;
      if (!uname || !uid) continue;
      docs.push({
        id: uuidv4(),
        userId: uid,
        username: uname,
        type: payload.type || 'plain',
        title: String(payload.title || '').slice(0, 200),
        body:  String(payload.body  || '').slice(0, 600),
        data:  payload.data || {},
        sentAt: now,
        readAt: null
      });
    }
    if (docs.length === 0) return 0;
    // insertMany con ordered:false — si alguno falla por dup key u otro, los demás insertan.
    await UserNotification.insertMany(docs, { ordered: false }).catch(() => {});
    return docs.length;
  } catch (e) {
    logger.warn(`[user-notif] persist failed: ${e.message}`);
    return 0;
  }
}

// GET /api/notifications/mine?limit=30 — inbox del user logueado.
app.get('/api/notifications/mine', authMiddleware, async (req, res) => {
  try {
    const limit = Math.max(1, Math.min(100, parseInt(req.query.limit, 10) || 30));
    const username = String(req.user.username || '').toLowerCase();
    const [items, unread] = await Promise.all([
      UserNotification.find(
        { username },
        { id: 1, type: 1, title: 1, body: 1, data: 1, sentAt: 1, readAt: 1, _id: 0 }
      ).sort({ sentAt: -1 }).limit(limit).lean(),
      UserNotification.countDocuments({ username, readAt: null })
    ]);
    res.json({ items, unread });
  } catch (err) {
    logger.error(`GET /api/notifications/mine: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

