// ============================================================
// LIBRO DE QUEJAS — público + admin
// ============================================================
// Cualquier user logueado puede enviar una queja. Foto opcional (URL
// pública que ya subió a S3 via /api/upload/presigned-url).
// Admin las ve en NUEVO TOP → Libro de quejas (filtrable por status).

// POST /api/complaints — el user envía una queja nueva.
// El cap por user (5/día) ya existe abajo, pero un atacante autenticado
// con scripts podía mandar 5 quejas de 1.4MB cada una sin tope por IP.
// sensitiveLimiter (10 req / 15 min por IP) corta ese vector.
app.post('/api/complaints', sensitiveLimiter, authMiddleware, async (req, res) => {
  try {
    const userId = req.user.userId;
    const username = req.user.username;
    const b = req.body || {};
    const incidentDate = String(b.incidentDate || '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(incidentDate)) {
      return res.status(400).json({ error: 'Fecha del incidente inválida (YYYY-MM-DD)' });
    }
    const incidentTime = String(b.incidentTime || '').trim();
    if (incidentTime && !/^\d{2}:\d{2}$/.test(incidentTime)) {
      return res.status(400).json({ error: 'Hora del incidente inválida (HH:MM)' });
    }
    const description = String(b.description || '').trim();
    if (description.length < 5) {
      return res.status(400).json({ error: 'Describí brevemente qué pasó (mínimo 5 caracteres).' });
    }
    if (description.length > 2000) {
      return res.status(400).json({ error: 'El detalle es muy largo (máx 2000 caracteres).' });
    }
    const subject = String(b.subject || '').trim().slice(0, 100);
    // imageUrl puede ser URL S3 (https://) o data URL base64 (la PWA comprime antes).
    // 1.5MB cap para que un usuario malintencionado no llene la DB.
    let imageUrl = String(b.imageUrl || '').trim();
    if (imageUrl.length > 1500000) {
      return res.status(413).json({ error: 'La foto es muy grande. Sacá una más liviana o probá de nuevo.' });
    }
    // Validación de MIME para data-URLs — sin esto un atacante podía mandar
    // data:text/html;base64,... y, si el admin panel lo renderiza vía
    // innerHTML o <iframe src>, ejecutar XSS. Aceptamos sólo imágenes
    // tipicas. Para URLs http(s) confiamos en S3 (presigned upload bloquea
    // tipos no-imagen vía content-type policy).
    if (imageUrl) {
      if (imageUrl.startsWith('data:')) {
        if (!/^data:image\/(png|jpe?g|webp|gif|heic);base64,[A-Za-z0-9+/=]+$/.test(imageUrl)) {
          return res.status(400).json({ error: 'Formato de imagen inválido. Subí PNG, JPG o WEBP.' });
        }
      } else if (!/^https:\/\//.test(imageUrl)) {
        return res.status(400).json({ error: 'URL de imagen inválida.' });
      }
    }

    // Anti-spam: máx 5 quejas por user por día.
    const todayStart = new Date(); todayStart.setHours(0,0,0,0);
    const recentCount = await Complaint.countDocuments({
      userId,
      createdAt: { $gte: todayStart }
    });
    if (recentCount >= 5) {
      return res.status(429).json({ error: 'Llegaste al límite de 5 quejas por día. Si necesitás algo urgente, contactá a soporte.' });
    }

    const doc = await Complaint.create({
      id: uuidv4(),
      userId,
      username,
      incidentDate,
      incidentTime,
      subject,
      description,
      imageUrl,
      status: 'pending'
    });
    logger.info(`[complaints] new from ${username} (${doc.id})`);
    res.json({ success: true, id: doc.id });
  } catch (err) {
    logger.error(`POST /api/complaints: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// GET /api/complaints/mine — el user puede ver sus propias quejas.
app.get('/api/complaints/mine', authMiddleware, async (req, res) => {
  try {
    const list = await Complaint.find(
      { userId: req.user.userId },
      { id: 1, incidentDate: 1, incidentTime: 1, subject: 1, description: 1, imageUrl: 1, status: 1, createdAt: 1, adminResponse: 1, respondedAt: 1, respondedBy: 1, messages: 1, _id: 0 }
    ).sort({ createdAt: -1 }).limit(50).lean();
    res.json({ complaints: list });
  } catch (err) {
    logger.error(`GET /api/complaints/mine: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// GET /api/admin/complaints — listado para el admin con filtros.
// Query params: status (pending|reviewed|resolved|all), limit (default 200), q (búsqueda por username).
app.get('/api/admin/complaints', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const status = String(req.query.status || 'all').trim();
    const limit = Math.max(1, Math.min(500, parseInt(req.query.limit, 10) || 200));
    const q = String(req.query.q || '').trim();
    const filter = {};
    if (['pending', 'reviewed', 'resolved'].includes(status)) filter.status = status;
    if (q) {
      const safe = q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      filter.username = { $regex: safe, $options: 'i' };
    }
    const [list, counts] = await Promise.all([
      Complaint.find(filter).sort({ createdAt: -1 }).limit(limit).lean(),
      Complaint.aggregate([
        { $group: { _id: '$status', count: { $sum: 1 } } }
      ])
    ]);
    const summary = { pending: 0, reviewed: 0, resolved: 0, total: 0 };
    for (const row of counts) {
      if (row._id && summary[row._id] !== undefined) summary[row._id] = row.count;
      summary.total += row.count;
    }
    res.json({ complaints: list, summary });
  } catch (err) {
    logger.error(`GET /api/admin/complaints: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// Helper interno: manda un push al user dueño de la queja con un mensaje
// nuevo del admin. Fire-and-forget — los errores se loguean pero no
// bloquean al caller.
async function _notifyUserAboutComplaint(complaintDoc, opts) {
  const o = opts || {};
  try {
    if (!complaintDoc || !complaintDoc.userId) return;
    const targetUser = await User.findOne(
      { id: complaintDoc.userId },
      { fcmTokens: 1, fcmTokenContext: 1, notifPermission: 1, username: 1, _id: 0 }
    ).lean();
    if (!targetUser) return;
    const tokens = Array.isArray(targetUser.fcmTokens) ? targetUser.fcmTokens : [];
    const standaloneTokens = tokens
      .filter(t => t && t.context === 'standalone' && t.notifPermission === 'granted' && t.token)
      .map(t => t.token);
    const title = o.title || '📩 Mensaje en tu queja';
    const subj = (complaintDoc.subject || '').trim();
    const body = o.body || (subj
      ? `Nuevo mensaje sobre: "${subj.slice(0, 60)}". Tocá para responder.`
      : 'Hay un nuevo mensaje en tu queja. Tocá para responder.');
    const clickUrl = '/?openComplaint=' + encodeURIComponent(complaintDoc.id);
    // Inbox per-user: persistimos el mensaje incluso si no tiene tokens FCM
    // standalone — así el user lo ve en su inbox cuando abra la app.
    await _persistUserNotifications([{ userId: complaintDoc.userId, username: complaintDoc.username }], {
      type: 'complaint',
      title, body,
      data: { complaintId: complaintDoc.id, url: clickUrl }
    });
    if (standaloneTokens.length === 0) {
      logger.info(`[complaints] push skipped — sin tokens standalone para ${complaintDoc.username} (queja ${complaintDoc.id}, queda solo en inbox)`);
      return false;
    }
    const { sendNotificationToMultiple } = require('./src/services/notificationService');
    await sendNotificationToMultiple(standaloneTokens, title, body, {
      type: 'complaint_message',
      complaintId: complaintDoc.id,
      url: clickUrl
    });
    logger.info(`[complaints] push enviado a ${complaintDoc.username} (queja ${complaintDoc.id})`);
    return true;
  } catch (e) {
    logger.error(`[complaints] push failed for ${(complaintDoc && complaintDoc.id) || 'unknown'}: ${e.message}`);
    return false;
  }
}

// PUT /api/admin/complaints/:id — actualiza status y/o notas internas.
// (Las respuestas al user se mandan vía POST /messages — ya no se usan
// adminResponse + notifyUser; el hilo conversacional lo reemplazó.)
//
// Body opcional:
//   status: 'pending' | 'reviewed' | 'resolved'
//   adminNotes: string (interno, solo admins)
app.put('/api/admin/complaints/:id', authMiddleware, superAdminMiddleware, async (req, res) => {
  try {
    const id = String(req.params.id || '').trim();
    const b = req.body || {};
    const adminUser = (req.user && req.user.username) || 'admin';
    const $set = {};
    if (['pending', 'reviewed', 'resolved'].includes(b.status)) {
      $set.status = b.status;
      if (b.status === 'resolved') {
        $set.resolvedBy = adminUser;
        $set.resolvedAt = new Date();
      } else if (b.status === 'pending') {
        // Reabrir: limpio resolvedBy/resolvedAt para que el front sepa que
        // volvió a estar activa.
        $set.resolvedBy = null;
        $set.resolvedAt = null;
      }
    }
    if (b.adminNotes !== undefined) {
      $set.adminNotes = String(b.adminNotes || '').slice(0, 2000);
    }
    const $addToSet = { readBy: adminUser };
    const update = { $set, $addToSet };
    const existing = await Complaint.findOne({ id }, { readAt: 1, _id: 0 }).lean();
    if (!existing) return res.status(404).json({ error: 'No encontrada' });
    if (!existing.readAt) update.$set.readAt = new Date();
    const doc = await Complaint.findOneAndUpdate({ id }, update, { new: true }).lean();
    res.json({ success: true, complaint: doc });
  } catch (err) {
    logger.error(`PUT /api/admin/complaints/:id: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// POST /api/admin/complaints/:id/messages — admin agrega un mensaje al
// hilo conversacional. Por default manda push al user; con notifyUser:false
// el mensaje queda guardado sin notificar.
//
// El status NO cambia automáticamente — el admin lo marca 'resolved'
// cuando da el caso por cerrado, vía PUT /api/admin/complaints/:id.
app.post('/api/admin/complaints/:id/messages', authMiddleware, superAdminMiddleware, async (req, res) => {
  try {
    const id = String(req.params.id || '').trim();
    const b = req.body || {};
    const adminUser = (req.user && req.user.username) || 'admin';
    const text = String(b.text || '').trim();
    if (!text) return res.status(400).json({ error: 'El mensaje no puede estar vacío.' });
    if (text.length > 2000) return res.status(400).json({ error: 'Máx 2000 caracteres.' });
    const shouldNotify = b.notifyUser !== false; // default true

    const existing = await Complaint.findOne({ id }).lean();
    if (!existing) return res.status(404).json({ error: 'No encontrada' });
    if (existing.status === 'resolved') {
      return res.status(409).json({ error: 'La queja está marcada como resuelta. Reabrila primero si querés seguir respondiendo.' });
    }

    const msg = {
      from: 'admin',
      authorName: adminUser,
      text,
      notifiedAt: shouldNotify ? new Date() : null,
      createdAt: new Date()
    };
    const $set = {};
    // Cuando el admin manda un mensaje, marca la queja como 'reviewed' si
    // todavía está 'pending' (señal visual: alguien la está atendiendo).
    if (existing.status === 'pending') $set.status = 'reviewed';
    if (!existing.readAt) $set.readAt = new Date();
    if (shouldNotify) $set.userNotifiedAt = new Date();

    const doc = await Complaint.findOneAndUpdate(
      { id },
      { $push: { messages: msg }, $set, $addToSet: { readBy: adminUser } },
      { new: true }
    ).lean();

    // Push fire-and-forget al user. No bloquea la respuesta del admin.
    if (shouldNotify) {
      _notifyUserAboutComplaint(doc, {}).catch(() => {});
    }

    res.json({ success: true, complaint: doc, notified: shouldNotify });
  } catch (err) {
    logger.error(`POST /api/admin/complaints/:id/messages: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// POST /api/complaints/:id/messages — el user dueño de la queja agrega
// un mensaje propio (respuesta al admin). Bloqueado si la queja está
// resuelta — el caso quedó cerrado.
app.post('/api/complaints/:id/messages', authMiddleware, async (req, res) => {
  try {
    const id = String(req.params.id || '').trim();
    const userId = req.user.userId;
    const username = req.user.username;
    const text = String((req.body || {}).text || '').trim();
    if (!text) return res.status(400).json({ error: 'El mensaje no puede estar vacío.' });
    if (text.length > 2000) return res.status(400).json({ error: 'Máx 2000 caracteres.' });

    const existing = await Complaint.findOne({ id }).lean();
    if (!existing) return res.status(404).json({ error: 'No encontrada' });
    if (existing.userId !== userId) {
      return res.status(403).json({ error: 'Solo el dueño de la queja puede responder.' });
    }
    if (existing.status === 'resolved') {
      return res.status(409).json({ error: 'Esta queja fue cerrada por el equipo. Si necesitás reabrirla, abrí una nueva.' });
    }

    // Cap anti-flood: máx 30 mensajes del user en una misma queja.
    const userMsgCount = (existing.messages || []).filter(m => m.from === 'user').length;
    if (userMsgCount >= 30) {
      return res.status(429).json({ error: 'Llegaste al límite de mensajes en esta queja.' });
    }

    const msg = {
      from: 'user',
      authorName: username,
      text,
      notifiedAt: null, // no notificamos a admins automáticamente (lo verán al entrar al panel)
      createdAt: new Date()
    };
    // Si la queja estaba 'reviewed', volverla a 'pending' para que el admin
    // vea que hay actividad nueva del user.
    const $set = {};
    if (existing.status === 'reviewed') $set.status = 'pending';

    const doc = await Complaint.findOneAndUpdate(
      { id },
      { $push: { messages: msg }, $set },
      { new: true, projection: { id: 1, messages: 1, status: 1, _id: 0 } }
    ).lean();

    res.json({ success: true, complaint: doc });
  } catch (err) {
    logger.error(`POST /api/complaints/:id/messages: ${err.message}\n${err.stack}`);
    res.status(500).json({ error: err.message });
  }
});

// GET /api/reviews/feed — feed público (los usernames vienen enmascarados).
// Devuelve también el promedio + cantidad por bucket.
//
// Stats agregadas via $group sobre TODA la colección (sin cap), así total
// y promedio reflejan la realidad aunque haya miles. La lista de items que
// se muestra es la última N (limit configurable, máx 100).
app.get('/api/reviews/feed', authMiddleware, async (req, res) => {
  try {
    const limit = Math.max(1, Math.min(100, parseInt(req.query.limit, 10) || 30));
    const [aggRes, items] = await Promise.all([
      Review.aggregate([
        {
          $group: {
            _id: null,
            total: { $sum: 1 },
            sumStars: { $sum: '$stars' },
            bueno:   { $sum: { $cond: [{ $gte: ['$stars', 4] }, 1, 0] } },
            regular: { $sum: { $cond: [{ $eq:  ['$stars', 3] }, 1, 0] } },
            malo:    { $sum: { $cond: [{ $lte: ['$stars', 2] }, 1, 0] } },
            // "Solo estrellas" = sin comentario o con comentario default "N estrellas".
            starsOnly: {
              $sum: {
                $cond: [
                  {
                    $or: [
                      { $eq: [{ $ifNull: ['$comment', ''] }, ''] },
                      { $regexMatch: { input: { $ifNull: ['$comment', ''] }, regex: /^[1-5] estrellas$/ } }
                    ]
                  },
                  1, 0
                ]
              }
            }
          }
        }
      ]),
      Review.find({}, { stars: 1, comment: 1, username: 1, updatedAt: 1, _id: 0 })
        .sort({ updatedAt: -1 })
        .limit(limit)
        .lean()
    ]);
    const stats = aggRes[0] || { total: 0, sumStars: 0, bueno: 0, regular: 0, malo: 0, starsOnly: 0 };
    const total = stats.total || 0;
    const avgStars = total > 0 ? (stats.sumStars / total) : 0;
    const counts = { bueno: stats.bueno || 0, regular: stats.regular || 0, malo: stats.malo || 0 };
    const starsOnlyTotal = stats.starsOnly || 0;
    const list = items.map(r => ({
      stars: r.stars,
      comment: r.comment || '',
      maskedUsername: _maskUsername(r.username),
      updatedAt: r.updatedAt
    }));
    res.json({ total, avgStars, counts, starsOnlyTotal, items: list });
  } catch (err) {
    logger.error(`GET /api/reviews/feed: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// GET /api/admin/reviews — lista admin con username completo + filtro.
app.get('/api/admin/reviews', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const bucket = String(req.query.bucket || 'all').toLowerCase();
    const limit = Math.max(1, Math.min(500, parseInt(req.query.limit, 10) || 200));
    const filter = {};
    if (bucket === 'bueno')         filter.stars = { $gte: 4 };
    else if (bucket === 'regular')  filter.stars = 3;
    else if (bucket === 'malo')     filter.stars = { $lte: 2 };

    // Sacar de la VISTA las 5★ de hace +3 días sin comentario — no aportan
    // al análisis. Siguen contando en el total/promedio (query `all` de abajo).
    const _reviewCutoff = new Date(Date.now() - 3 * 24 * 60 * 60 * 1000);
    filter.$nor = [{
      stars: 5,
      comment: { $in: ['', null] },
      createdAt: { $lt: _reviewCutoff }
    }];

    const all = await Review.find({}, { stars: 1, _id: 0 }).lean();
    const total = all.length;
    const sumStars = all.reduce((acc, r) => acc + (r.stars || 0), 0);
    const avgStars = total > 0 ? (sumStars / total) : 0;
    const counts = { bueno: 0, regular: 0, malo: 0 };
    for (const r of all) counts[_bucketOf(r.stars)]++;

    const items = await Review.find(filter)
      .sort({ updatedAt: -1 })
      .limit(limit)
      .lean();

    res.json({
      total,
      avgStars,
      counts,
      items: items.map(r => ({
        id: r.id,
        username: r.username,
        stars: r.stars,
        comment: r.comment || '',
        contactPhone: r.contactPhone || '',
        bucket: _bucketOf(r.stars),
        createdAt: r.createdAt,
        updatedAt: r.updatedAt
      }))
    });
  } catch (err) {
    logger.error(`GET /api/admin/reviews: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// DELETE /api/admin/reviews/:id — borra una opinión (admin only). El user
// dueño queda libre para volver a opinar (no recreamos el constraint).
app.delete('/api/admin/reviews/:id', authMiddleware, superAdminMiddleware, async (req, res) => {
  try {
    const id = String(req.params.id || '').trim();
    if (!id) return res.status(400).json({ error: 'id requerido' });
    const removed = await Review.findOneAndDelete({ id }).lean();
    if (!removed) return res.status(404).json({ error: 'Opinión no encontrada' });
    logger.info(`[REVIEW-DELETE] ${removed.username} (${removed.stars}★) borrada por ${req.user.username}`);
    res.json({ success: true });
  } catch (err) {
    logger.error(`DELETE /api/admin/reviews: ${err.message}`);
    res.status(500).json({ error: err.message });
  }
});

// =====================================================================
// WIN-BACK AUTOMÁTICO (estrategia de recuperación)
// Cron horario: si isActive, escanea PlayerStats.lastRealDepositDate y
// dispara push escalonado en 3 tiers según días sin cargar.
// Cada wave reutiliza la infra existente:
//   - Tier 1: solo push (FCM directo)
//   - Tier 2: MoneyGiveaway con audienceWhitelist=[user]
//   - Tier 3: promo-alert per-user con código COD<pct>
// Se graba 1 fila en RecoveryPush por cada send (sentBy='cron-winback').
// El outcome resolver existente (en _refreshPendingRecoveryOutcomes) ya
// se encarga de marcar recovered/opportunist/no_response sin tocar nada.
// =====================================================================
let _WINBACK_TICK_RUNNING = false;

function _winbackTierForDays(days, cfg) {
  if (days >= cfg.tier4Days) return 4;        // cooldown
  if (days >= cfg.tier3Days) return 3;
  if (days >= cfg.tier2Days) return 2;
  if (days >= cfg.tier1Days) return 1;
  return 0;
}

async function _fireWinbackForUser(user, tier, cfg, opts = {}) {
  const username = (user.username || '').toLowerCase();
  const userId = user.id || user.userId;
  if (!username || !userId) return { fired: false, reason: 'no-user-id' };

  const tokens = [];
  if (user.fcmToken) tokens.push(user.fcmToken);
  if (Array.isArray(user.fcmTokens)) {
    for (const t of user.fcmTokens) if (t && !tokens.includes(t)) tokens.push(t);
  }
  if (tokens.length === 0) return { fired: false, reason: 'no-tokens' };

  const msg = tier === 1 ? cfg.tier1Message
            : tier === 2 ? cfg.tier2Message
            : tier === 3 ? cfg.tier3Message
            : null;
  if (!msg || !msg.title) return { fired: false, reason: 'no-msg' };

  // Setup bono según tier (antes del push para que cuando el user toque
  // ya tenga lo que necesita listo).
  let bonusType = 'none', bonusAmount = 0;
  let promoCode = null, giveawayId = null;
  const now = new Date();
  // Winback usa SOLO promos wa.link (sin regalar plata directa).
  // Tier 1 = 50%, Tier 2 = 50%, Tier 3 = 100% (configurable).
  // Para tier 2 los giveaways cash quedaron deprecated — ahora todos los
  // tiers crean promo-alert con código (COD50/COD100/etc).
  const AUTO_BONUS_ENABLED = true;
  try {
    // Determinar parametros del bono según tier.
    let bonusPct = 0, suggestedAmount = 0, durationHours = 0;
    if (tier === 1) {
      bonusPct = cfg.tier1BonusPct || 50;
      suggestedAmount = cfg.tier1SuggestedAmount || 2000;
      durationHours = cfg.tier1DurationHours || 48;
    } else if (tier === 2) {
      bonusPct = cfg.tier2BonusPct || 50;
      suggestedAmount = cfg.tier2SuggestedAmount || 2000;
      durationHours = cfg.tier2DurationHours || 48;
    } else if (tier === 3) {
      bonusPct = cfg.tier3BonusPct || 100;
      suggestedAmount = cfg.tier3SuggestedAmount || 2000;
      durationHours = cfg.tier3DurationHours || 72;
    }

    if (AUTO_BONUS_ENABLED && bonusPct > 0 && (tier === 1 || tier === 2 || tier === 3)) {
      promoCode = 'COD' + Math.round(bonusPct);
      const promoMessage = `🎁 Cargás $${suggestedAmount.toLocaleString('es-AR')} y te damos un ${bonusPct}% extra. Pedí el código ${promoCode}.`;
      const promo = {
        id: uuidv4(),
        message: promoMessage,
        code: promoCode,
        expiresAt: new Date(now.getTime() + durationHours * 3600 * 1000).toISOString(),
        createdAt: now.toISOString(),
        createdBy: 'cron-winback',
        prefix: null,
        audienceWhitelist: [username],
        kind: 'winback_grant',
        grantAmount: suggestedAmount,
        grantPct: bonusPct,
        notificationHistoryId: null
      };
      const arr = (await getConfig(TIER_PROMOS_KEY, [])) || [];
      const nowMs = Date.now();
      const cleaned = arr.filter(p => {
        if (!p || !p.expiresAt) return false;
        const exp = new Date(p.expiresAt).getTime();
        if (!isFinite(exp) || exp <= nowMs) return false;
        const sameUser = Array.isArray(p.audienceWhitelist)
          && p.audienceWhitelist.some(x => String(x).toLowerCase() === username)
          && (p.kind === 'individual_grant' || p.kind === 'winback_grant');
        return !sameUser;
      });
      cleaned.push(promo);
      await setConfig(TIER_PROMOS_KEY, cleaned);
      bonusType = 'promo';
      bonusAmount = suggestedAmount;
    }

    // Push.
    let pushOk = false;
    for (const tok of tokens) {
      try {
        await _sendPushToUser(tok, msg.title, msg.body, {
          kind: 'winback_auto',
          tier: String(tier),
          promoCode: promoCode || '',
          giveawayId: giveawayId || ''
        });
        pushOk = true;
      } catch (e) {
        logger.warn(`[WINBACK] push fail ${username} t${tier}: ${e.message}`);
      }
    }
    if (!pushOk && !opts.dryRun) {
      logger.warn(`[WINBACK] ${username} t${tier} sin push exitoso`);
    }

    // Audit row en RecoveryPush para que el outcome resolver lo levante.
    try {
      await RecoveryPush.create({
        username,
        segmentAtSend: null,
        tierAtSend: null,
        activityStatusAtSend: null,
        bonusAmount,
        bonusType,
        notificationHistoryId: null,
        campaignBatchId: 'winback-auto-' + new Date().toISOString().slice(0, 10),
        sentAt: now,
        sentBy: 'cron-winback'
      });
    } catch (e) {
      logger.warn(`[WINBACK] no se pudo grabar RecoveryPush: ${e.message}`);
    }

    return { fired: true, bonusType, bonusAmount, promoCode, giveawayId };
  } catch (e) {
    logger.warn(`[WINBACK] _fireWinbackForUser ${username} t${tier} error: ${e.message}`);
    return { fired: false, reason: 'error', error: e.message };
  }
}

// Tick del cron — si ya hay uno corriendo, sale. Default OFF.
async function winbackCronTick(opts = {}) {
  if (_WINBACK_TICK_RUNNING) return { skipped: true, reason: 'already-running' };
  _WINBACK_TICK_RUNNING = true;
  const startedAt = new Date();
  try {
    const cfg = await WinbackStrategyConfig.findOne({ key: 'winback-default' });
    if (!cfg) {
      // Crear singleton con defaults la primera vez.
      await WinbackStrategyConfig.create({ key: 'winback-default' });
      return { skipped: true, reason: 'no-config-created' };
    }
    if (!cfg.isActive && !opts.force) {
      return { skipped: true, reason: 'disabled' };
    }

    const now = Date.now();
    const cutoffMin = now - cfg.tier1Days * 86400000;
    const cutoffMax = now - 0;
    const useAppMetric = (cfg.inactivityMetric || 'app') === 'app';

    // Source de inactividad:
    //   'app'     → PlayerStats.lastSeenApp (días sin USAR la app — actualizado en
    //               cada request autenticada del user, throttled 1/min). NO usamos
    //               User.lastLogin porque solo se actualiza al re-loguearse, no
    //               refleja uso real (sesión persiste 30-90 días).
    //   'deposit' → PlayerStats.lastRealDepositDate (legacy: días sin cargar)
    let inactivityRows; // [{ username, inactiveSince }]
    if (useAppMetric) {
      // PlayerStats.lastSeenApp ya tiene su propio index — query rápido.
      const stats = await PlayerStats.find({
        lastSeenApp: { $exists: true, $ne: null, $lt: new Date(cutoffMin) }
      }, { username: 1, lastSeenApp: 1, _id: 0 })
        .sort({ lastSeenApp: 1 })
        .limit(2000)
        .lean();
      inactivityRows = stats.map(s => ({ username: (s.username || '').toLowerCase(), inactiveSince: s.lastSeenApp, _user: null }));
    } else {
      const stats = await PlayerStats.find({
        lastRealDepositDate: { $exists: true, $ne: null, $lt: new Date(cutoffMin) }
      }, { username: 1, lastRealDepositDate: 1, _id: 0 })
        .sort({ lastRealDepositDate: 1 })
        .limit(2000)
        .lean();
      inactivityRows = stats.map(s => ({ username: (s.username || '').toLowerCase(), inactiveSince: s.lastRealDepositDate, _user: null }));
    }

    if (inactivityRows.length === 0) {
      cfg.lastCronRunAt = startedAt;
      cfg.lastCronOutcome = { skipped: 'no-users-matched', startedAt, metric: cfg.inactivityMetric || 'app' };
      await cfg.save();
      return { skipped: true, reason: 'no-users-matched' };
    }

    const usernames = inactivityRows.map(r => r.username);
    // Ambas métricas ('app' y 'deposit') vienen ahora de PlayerStats, así que
    // siempre cargamos los Users aparte para tener fcm tokens + winbackTier.
    const users = await User.find(
      { username: { $in: usernames } },
      { id: 1, username: 1, fcmToken: 1, fcmTokens: 1, winbackTier: 1, winbackLastSentAt: 1, notifPreference: 1, _id: 0 }
    ).lean();
    const userByName = new Map(users.map(u => [u.username.toLowerCase(), u]));
    // Lookup isOpportunist (de PlayerStats) — solo si el filtro está prendido.
    let opportunistByName = new Map();
    if (cfg.excludeOpportunists) {
      const ps = await PlayerStats.find(
        { username: { $in: usernames }, isOpportunist: true },
        { username: 1, isOpportunist: 1, _id: 0 }
      ).lean();
      opportunistByName = new Map(ps.map(p => [p.username.toLowerCase(), true]));
    }

    // Caps diarios.
    const todayStart = new Date(); todayStart.setHours(0,0,0,0);
    const sentTodayByTier = await RecoveryPush.aggregate([
      { $match: { sentBy: 'cron-winback', sentAt: { $gte: todayStart } } },
      { $group: { _id: '$bonusType', count: { $sum: 1 } } }
    ]);
    let tier2SentToday = 0, tier3SentToday = 0;
    for (const row of sentTodayByTier) {
      if (row._id === 'giveaway') tier2SentToday = row.count;
      else if (row._id === 'promo') tier3SentToday = row.count;
    }

    const result = { tier1: 0, tier2: 0, tier3: 0, skipped_cap: 0, skipped_recent: 0, skipped_no_user: 0, skipped_no_tokens: 0, skipped_filter: 0, errors: 0, metric: cfg.inactivityMetric || 'app' };

    for (const s of inactivityRows) {
      const days = Math.floor((now - new Date(s.inactiveSince).getTime()) / 86400000);
      const targetTier = _winbackTierForDays(days, cfg);
      // Username regex case-insensitive — PlayerStats guarda lowercase pero
      // User.username puede tener mixed case; sin esto el match podría perder users.
      const usernameRx = new RegExp('^' + s.username.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '$', 'i');
      if (targetTier === 0 || targetTier === 4) {
        // 0 = no aplicable, 4 = cooldown (no mandar más).
        if (targetTier === 4) {
          // Marcar tier 4 sin mandar nada para que no escale más.
          await User.updateOne(
            { username: usernameRx, winbackTier: { $lt: 4 } },
            { $set: { winbackTier: 4, winbackLastSentAt: new Date() } }
          );
        }
        continue;
      }
      const u = userByName.get(s.username);
      if (!u) { result.skipped_no_user++; continue; }
      // Filtros.
      if (cfg.onlySurveyResponders && !u.notifPreference) { result.skipped_filter++; continue; }
      if (cfg.excludeOpportunists && opportunistByName.get(s.username)) { result.skipped_filter++; continue; }
      // Idempotencia: solo si tier nuevo > tier actual.
      if ((u.winbackTier || 0) >= targetTier) continue;
      // Anti-spam: 24h mínimo entre mandadas.
      if (u.winbackLastSentAt && (now - new Date(u.winbackLastSentAt).getTime()) < 24 * 3600 * 1000) {
        result.skipped_recent++;
        continue;
      }
      // Daily caps.
      if (targetTier === 2 && tier2SentToday >= cfg.dailyCapTier2) { result.skipped_cap++; continue; }
      if (targetTier === 3 && tier3SentToday >= cfg.dailyCapTier3) { result.skipped_cap++; continue; }

      // Claim atómico: solo escala si seguimos en el tier viejo.
      const claimed = await User.findOneAndUpdate(
        {
          username: usernameRx,
          $or: [{ winbackTier: { $lt: targetTier } }, { winbackTier: { $exists: false } }]
        },
        { $set: { winbackTier: targetTier, winbackLastSentAt: new Date() } },
        { new: true }
      );
      if (!claimed) continue;

      // Fire.
      const r = await _fireWinbackForUser(u, targetTier, cfg, opts);
      if (r.fired) {
        result['tier' + targetTier]++;
        if (targetTier === 2) tier2SentToday++;
        if (targetTier === 3) tier3SentToday++;
      } else {
        if (r.reason === 'no-tokens') result.skipped_no_tokens++;
        else result.errors++;
      }
    }

    // Stats agregadas.
    cfg.totalSentByTier.tier1 = (cfg.totalSentByTier.tier1 || 0) + result.tier1;
    cfg.totalSentByTier.tier2 = (cfg.totalSentByTier.tier2 || 0) + result.tier2;
    cfg.totalSentByTier.tier3 = (cfg.totalSentByTier.tier3 || 0) + result.tier3;
    cfg.lastCronRunAt = startedAt;
    cfg.lastCronOutcome = { ...result, startedAt, durationMs: Date.now() - startedAt.getTime() };
    await cfg.save();

    logger.info(`[WINBACK] tick · t1=${result.tier1} t2=${result.tier2} t3=${result.tier3} skipped(cap=${result.skipped_cap},recent=${result.skipped_recent},filter=${result.skipped_filter},notok=${result.skipped_no_tokens})`);
    return result;
  } catch (err) {
    logger.error(`[WINBACK] tick error: ${err.message}\n${err.stack}`);
    return { error: err.message };
  } finally {
    _WINBACK_TICK_RUNNING = false;
  }
}

// Cron: cada 60 min (no-op si isActive=false). El primer tick ocurre 5 min
// después del boot del server para no chocar con otros crons del start.
setTimeout(() => {
  winbackCronTick().catch(err => logger.warn(`[WINBACK] first tick: ${err.message}`));
  setInterval(() => {
    winbackCronTick().catch(err => logger.warn(`[WINBACK] tick interval: ${err.message}`));
  }, 60 * 60 * 1000).unref();
}, 5 * 60 * 1000);

// Reset winback tier cuando el user vuelve a cargar — hook en el outcome
// resolver no es necesario porque _refreshPendingRecoveryOutcomes ya lo
// hace por su cuenta. Pero igual vamos a resetear cada 6h como red de
// seguridad: cualquier user con realDepositMade reciente y winbackTier>0
// lo bajamos a 0.
async function _resetWinbackTierForReturners() {
  try {
    // Resetear el tier de quienes volvieron a usar la app O volvieron a cargar
    // en los últimos 7 días. Cualquiera de las dos cuenta como "volvieron al ciclo".
    const since = new Date(Date.now() - 7 * 86400000);
    const cfg = await WinbackStrategyConfig.findOne({ key: 'winback-default' }).lean();
    const useAppMetric = (cfg && cfg.inactivityMetric || 'app') === 'app';
    // Para 'app' usamos lastSeenApp (uso real); para 'deposit' usamos lastRealDepositDate.
    const matchField = useAppMetric ? 'lastSeenApp' : 'lastRealDepositDate';
    const recent = await PlayerStats.find(
      { [matchField]: { $gte: since } },
      { username: 1, _id: 0 }
    ).lean();
    if (recent.length === 0) return;
    const usernames = recent.map(s => s.username);
    const r = await User.updateMany(
      { username: { $in: usernames }, winbackTier: { $gt: 0 } },
      { $set: { winbackTier: 0, winbackLastSentAt: null } }
    );
    if (r.modifiedCount > 0) {
      logger.info(`[WINBACK] reset tier para ${r.modifiedCount} returners (metric=${useAppMetric ? 'app' : 'deposit'})`);
    }
  } catch (e) {
    logger.warn(`[WINBACK] reset returners falló: ${e.message}`);
  }
}
setTimeout(() => {
  _resetWinbackTierForReturners().catch(() => {});
  setInterval(() => _resetWinbackTierForReturners().catch(() => {}), 6 * 3600 * 1000).unref();
}, 8 * 60 * 1000);

