// ============================================
// EXPORT DEL PLAN SEMANAL DE RECUPERACIÓN A .XLSX
// ============================================
// Genera un workbook con:
//   - Hoja "Resumen": totales por (equipo × estado) y $ potencial.
//   - Una hoja por (equipo, estado): cada fila es un usuario recuperable
//     con todos los datos para que un agente de WhatsApp trabaje sin
//     tener que abrir nada más (usuario, WA, línea del equipo, tier,
//     días sin cargar, estrategia/bono/frecuencia/por qué del playbook,
//     y dos columnas vacías "Notas" + "Resultado" para que el agente
//     complete a mano cuando contacte).
// Excluye automáticamente oportunistas (isOpportunist=true).

// Playbook duplicado en backend — debe mantenerse sincronizado con
// PLAYBOOK_DATA en public/adminprivado2026/admin.js. Si en el futuro
// se mueve a Config DB, ambas lecturas leen de ahí.
const _PLAYBOOK_BACKEND = [
  {tierKey: 'VIP', stateKey: 'ACTIVO', strategy: 'Hacerlo sentir único', bonus: 'Giveaway VIP $5k-$10k exclusivo + atención WA preferencial', freq: '1x/mes sorpresa', why: 'Ya está dando. No molestar, solo recordarle que es especial.'},
  {tierKey: 'VIP', stateKey: 'EN_RIESGO', strategy: '🚨 ALERTA ROJA', bonus: 'Bono $10k+ personalizado + mensaje del "dueño" + WhatsApp directo', freq: '1x máximo', why: 'Vale invertir fuerte en retener al top.'},
  {tierKey: 'VIP', stateKey: 'PERDIDO', strategy: 'Último intento valor alto', bonus: '$15k + mensaje personal', freq: '1x', why: 'Si no vuelve, abandonar — el LTV ya se cobró.'},
  {tierKey: 'VIP', stateKey: 'INACTIVO', strategy: 'Último intento valor alto', bonus: '$15k + mensaje personal', freq: '1x', why: 'Si no vuelve, abandonar — el LTV ya se cobró.'},
  {tierKey: 'ORO', stateKey: 'ACTIVO', strategy: 'Mantener engaged', bonus: 'Reembolsos visibles + giveaway $2k-$5k', freq: 'Cada 7-10 días', why: 'Empujoncito constante mantiene el hábito.'},
  {tierKey: 'ORO', stateKey: 'EN_RIESGO', strategy: 'Push fuerte', bonus: 'Bono $5k + recordatorio WA', freq: '1-2x', why: 'Recuperar rápido antes que sea PERDIDO.'},
  {tierKey: 'ORO', stateKey: 'PERDIDO', strategy: 'Bono medio + storytelling', bonus: '$5k-$8k + mensaje "volvé hoy"', freq: '1x', why: 'Recuperación con ROI razonable.'},
  {tierKey: 'ORO', stateKey: 'INACTIVO', strategy: 'Último resort', bonus: '$2k-$5k + "te extrañamos"', freq: 'Cada 30-60 días', why: 'Si no responde a la 2da, dejar de gastar.'},
  {tierKey: 'PLATA', stateKey: 'ACTIVO', strategy: 'Subir el ticket', bonus: '"Cargá $10k → te damos $2k extra"', freq: 'Quincenal', why: 'Incentivás cargas más grandes.'},
  {tierKey: 'PLATA', stateKey: 'EN_RIESGO', strategy: 'Reactivar', bonus: 'Bono $1k-$3k', freq: '1x', why: 'Suficiente para tentar sin gastar mucho.'},
  {tierKey: 'PLATA', stateKey: 'PERDIDO', strategy: 'Bono chico', bonus: '$2k', freq: '1x', why: 'Si no vuelve, no rentable más.'},
  {tierKey: 'PLATA', stateKey: 'INACTIVO', strategy: 'Último resort', bonus: '$2k-$5k + "te extrañamos"', freq: 'Cada 30-60 días', why: 'Si no responde a la 2da, dejar de gastar.'},
  {tierKey: 'BRONCE', stateKey: 'ACTIVO', strategy: 'Fidelización', bonus: 'Racha de cargas (5 cargas seguidas = $1k extra)', freq: 'Continuo', why: 'Los hacés sentir parte de algo.'},
  {tierKey: 'BRONCE', stateKey: 'EN_RIESGO', strategy: 'Bono mínimo', bonus: '$500-$1.500', freq: '1x máximo', why: 'No rentable invertir mucho.'},
  {tierKey: 'BRONCE', stateKey: 'PERDIDO', strategy: 'Bono mínimo', bonus: '$500-$1.500', freq: '1x máximo', why: 'No rentable invertir mucho.'},
  {tierKey: 'BRONCE', stateKey: 'INACTIVO', strategy: 'Último resort', bonus: '$2k-$5k + "te extrañamos"', freq: 'Cada 30-60 días', why: 'Si no responde a la 2da, dejar de gastar.'},
  {tierKey: 'NUEVO', stateKey: '*', strategy: 'Onboarding agresivo', bonus: 'Welcome $10k visible + bonus continuidad $3k al hacer 2da carga', freq: 'Período crítico 14 días', why: 'Engancharlo en el hábito.'},
  {tierKey: 'SIN_DATOS', stateKey: '*', strategy: 'Identificar primero', bonus: '—', freq: '—', why: 'Sin data de cargas/retiros, no sabemos cómo tratarlo.'}
];
function _playbookFor(tier, state) {
  return _PLAYBOOK_BACKEND.find(p => p.tierKey === tier && p.stateKey === state)
      || _PLAYBOOK_BACKEND.find(p => p.tierKey === tier && p.stateKey === '*')
      || { strategy: 'Recuperación estándar', bonus: '—', freq: '1x', why: '' };
}

app.get('/api/admin/stats/recovery-export.xlsx', authMiddleware, adminMiddleware, async (req, res) => {
  let XLSX;
  try {
    XLSX = require('xlsx');
  } catch (e) {
    return res.status(503).json({ error: 'Falta instalar xlsx en el server. Ejecutá: npm install xlsx' });
  }

  try {
    // 1) Players recuperables (no oportunistas, no activos, no nuevos sin datos).
    const recoverableStates = ['EN_RIESGO', 'PERDIDO', 'INACTIVO'];
    const players = await PlayerStats.find({
      activityStatus: { $in: recoverableStates },
      isOpportunist: { $ne: true }
    }).lean();

    if (players.length === 0) {
      return res.status(200).json({ error: 'No hay jugadores recuperables para exportar.' });
    }

    // 2) Bulk lookup en User para traer phone/whatsapp + lineTeamName/linePhone.
    //    PlayerStats.username está siempre lowercase; matcheo por collation.
    const usernames = players.map(p => p.username).filter(Boolean);
    const userDocs = await User.find({ username: { $in: usernames } })
      .collation({ locale: 'en', strength: 2 })
      .select('username phone whatsapp linePhone lineTeamName')
      .lean();
    const userByLower = new Map();
    for (const u of userDocs) userByLower.set(u.username.toLowerCase(), u);

    // 3) Cargar config de líneas por prefijo para fallback team/phone.
    let prefixConfig = null;
    try { prefixConfig = await getConfig('userLinesByPrefix'); } catch (_) {}

    // 4) Agrupar por (team, state). Si el user no tiene team asignado por
    //    import ni por prefijo, va a "Sin equipo".
    const groups = new Map(); // key = "Team|State" → [rows]
    const teamStateCount = new Map(); // para Resumen
    let totalRecoverable = 0;
    let totalPotential = 0;
    const conversionByState = { EN_RIESGO: 0.35, PERDIDO: 0.15, INACTIVO: 0.07 };

    for (const p of players) {
      const u = userByLower.get((p.username || '').toLowerCase());
      let team = (u && u.lineTeamName) || pickTeamNameForUsername(prefixConfig, p.username) || '';
      let linePhone = (u && u.linePhone) || pickLinePhoneForUsername(prefixConfig, p.username) || '';
      if (!team) team = 'Sin equipo';

      const state = p.activityStatus;
      const pb = _playbookFor(p.tier, state);
      const daysSinceLast = p.lastRealDepositDate
        ? Math.floor((Date.now() - new Date(p.lastRealDepositDate).getTime()) / (24*3600*1000))
        : null;

      const conv = conversionByState[state] || 0;
      const projected = Math.round((p.realDeposits30d || 0) * conv);
      totalRecoverable++;
      totalPotential += projected;

      const row = {
        'Usuario': p.username || '',
        'WhatsApp / Teléfono del usuario': (u && (u.whatsapp || u.phone)) || '',
        'Línea de WhatsApp del equipo': linePhone,
        'Equipo': team,
        'Tier': p.tier || 'SIN_DATOS',
        'Estado': state,
        'Última carga real': p.lastRealDepositDate ? new Date(p.lastRealDepositDate).toLocaleDateString('es-AR') : '',
        'Días sin cargar': daysSinceLast == null ? '' : daysSinceLast,
        'Cargado 30d ($)': p.realDeposits30d || 0,
        'Cargas 30d (#)': p.realChargesCount30d || 0,
        'Retirado 30d ($)': p.withdraws30d || 0,
        'Bonos recibidos 30d ($)': p.bonusGiven30d || 0,
        'Neto a la casa 30d ($)': p.netToHouse30d || 0,
        'Estrategia recomendada': pb.strategy,
        'Bono sugerido': pb.bonus,
        'Frecuencia': pb.freq,
        'Por qué': pb.why,
        '$ potencial recuperable': projected,
        'Notas (completar agente)': '',
        'Resultado (completar agente)': ''
      };

      const key = team + '|' + state;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(row);
      teamStateCount.set(key, (teamStateCount.get(key) || 0) + 1);
    }

    // 5) Construir workbook.
    const wb = XLSX.utils.book_new();

    // Hoja "Resumen" primero
    const stateLabel = { EN_RIESGO: 'En riesgo', PERDIDO: 'Perdido', INACTIVO: 'Inactivo' };
    const summaryRows = [];
    const teamsSet = new Set();
    for (const k of teamStateCount.keys()) teamsSet.add(k.split('|')[0]);
    const teamsSorted = [...teamsSet].sort();

    for (const team of teamsSorted) {
      let teamTotal = 0;
      const enRiesgo = teamStateCount.get(team + '|EN_RIESGO') || 0;
      const perdido = teamStateCount.get(team + '|PERDIDO') || 0;
      const inactivo = teamStateCount.get(team + '|INACTIVO') || 0;
      teamTotal = enRiesgo + perdido + inactivo;

      // $ potencial por team-state agregado
      let teamPotential = 0;
      for (const [k, rows] of groups) {
        if (k.startsWith(team + '|')) {
          for (const r of rows) teamPotential += r['$ potencial recuperable'] || 0;
        }
      }

      summaryRows.push({
        'Equipo': team,
        'En riesgo': enRiesgo,
        'Perdidos': perdido,
        'Inactivos': inactivo,
        'Total recuperables': teamTotal,
        '$ potencial estimado': teamPotential
      });
    }
    summaryRows.push({}); // separador
    summaryRows.push({
      'Equipo': 'TOTAL GENERAL',
      'En riesgo': teamsSorted.reduce((s, t) => s + (teamStateCount.get(t + '|EN_RIESGO') || 0), 0),
      'Perdidos': teamsSorted.reduce((s, t) => s + (teamStateCount.get(t + '|PERDIDO') || 0), 0),
      'Inactivos': teamsSorted.reduce((s, t) => s + (teamStateCount.get(t + '|INACTIVO') || 0), 0),
      'Total recuperables': totalRecoverable,
      '$ potencial estimado': totalPotential
    });
    summaryRows.push({});
    summaryRows.push({ 'Equipo': 'Generado en:', 'En riesgo': new Date().toLocaleString('es-AR') });
    summaryRows.push({ 'Equipo': 'Cobertura:', 'En riesgo': 'PlayerStats actualizados — refrescá JUGAYGANA antes de exportar para tener data fresca.' });
    summaryRows.push({ 'Equipo': 'Conversión esperada:', 'En riesgo': 'En riesgo 35% · Perdidos 15% · Inactivos 7% (heurísticas del playbook)' });

    const summarySheet = XLSX.utils.json_to_sheet(summaryRows, {
      header: ['Equipo', 'En riesgo', 'Perdidos', 'Inactivos', 'Total recuperables', '$ potencial estimado']
    });
    XLSX.utils.book_append_sheet(wb, summarySheet, 'Resumen');

    // Hojas por (team, state). Limitamos cada nombre a 31 chars (Excel/Sheets).
    // Usamos " - " como separador para máxima compatibilidad con Google Sheets
    // (el caracter "·" puede romper la importación en versiones viejas).
    // También evitamos los caracteres prohibidos por Excel/Sheets en sheet names:
    //   \ / ? * [ ] :
    const _sanitizeSheetName = (name) => String(name || 'sheet')
      .replace(/[\\/\?\*\[\]:]/g, '-')
      .trim()
      .slice(0, 31) || 'sheet';

    const sortedKeys = [...groups.keys()].sort();
    for (const key of sortedKeys) {
      const [team, state] = key.split('|');
      const rows = groups.get(key);
      const sheetName = _sanitizeSheetName(team + ' - ' + (stateLabel[state] || state));
      const sheet = XLSX.utils.json_to_sheet(rows);
      // Ajustar ancho de columnas básico (XLSX no calcula auto-fit por sí solo)
      const colKeys = Object.keys(rows[0] || {});
      sheet['!cols'] = colKeys.map(k => {
        if (k.includes('Notas') || k.includes('Resultado') || k.includes('Por qué') || k.includes('Bono sugerido')) return { wch: 36 };
        if (k.includes('Estrategia') || k.includes('WhatsApp')) return { wch: 28 };
        if (k.includes('Línea')) return { wch: 22 };
        return { wch: 14 };
      });
      XLSX.utils.book_append_sheet(wb, sheet, sheetName);
    }

    // 6) Stream como descarga.
    const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });
    const filename = 'plan-recuperacion-' + new Date().toISOString().slice(0, 10) + '.xlsx';
    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    res.setHeader('Content-Disposition', 'attachment; filename="' + filename + '"');
    res.setHeader('Content-Length', buf.length);
    res.send(buf);

    logger.info(`[recovery-export] generado para ${(req.user && req.user.username) || '?'} — ${totalRecoverable} jugadores en ${groups.size} hojas`);
  } catch (error) {
    logger.error(`/api/admin/stats/recovery-export: ${error.message}\n${error.stack}`);
    if (!res.headersSent) {
      res.status(500).json({ error: 'Error generando export: ' + error.message });
    }
  }
});

// GET /api/admin/stats/segments — counts agregados por segmento + comparativo semanal
//
// Devuelve, además de la matriz tier×estado y métricas semanales:
//   - avgTicketByTier: ticket promedio (realDeposits30d) por tier
//   - recoverable: total de jugadores recuperables (EN_RIESGO + PERDIDO + INACTIVO,
//     excluyendo oportunistas). Es el target del panel de recuperación.
//   - potentialRevenue: estimación de cargas a recuperar (Σ count × ticket avg
//     del tier × conversión esperada según playbook)
//   - urgentSegments: top 5 (tier, state) combinaciones por puntaje de urgencia
//     (count × tier weight × state weight). Para mostrar arriba como foco.
app.get('/api/admin/stats/segments', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    // Counts por (tier, state) sobre USUARIOS ÚNICOS. Antes el aggregate
    // contaba documentos directos de PlayerStats — pero la colección puede
    // tener múltiples docs por username (legado de cuando el unique index no
    // estaba). Esto inflaba la matriz hasta ~5× (14k entries vs 2.7k users
    // reales). Ahora dedupeamos primero por username (tomando el doc más
    // reciente) y después agrupamos por (tier, state).
    const counts = await PlayerStats.aggregate([
      { $sort: { updatedAt: -1, _id: -1 } },
      {
        $group: {
          _id: '$username',
          tier: { $first: '$tier' },
          activityStatus: { $first: '$activityStatus' },
          isOpportunist: { $first: '$isOpportunist' },
          realDeposits30d: { $first: '$realDeposits30d' }
        }
      },
      {
        $group: {
          _id: { tier: '$tier', activityStatus: '$activityStatus' },
          count: { $sum: 1 },
          opportunists: { $sum: { $cond: ['$isOpportunist', 1, 0] } },
          avgTicket: { $avg: '$realDeposits30d' }
        }
      }
    ]);
    const matrix = {};
    const opportunistMatrix = {};
    const ticketByTierAccum = {}; // tier → { sum, n } para weighted avg
    for (const c of counts) {
      const t = c._id.tier || 'SIN_DATOS';
      const a = c._id.activityStatus || 'INACTIVO';
      const k = t + '-' + a;
      matrix[k] = c.count;
      opportunistMatrix[k] = c.opportunists || 0;
      const avgT = c.avgTicket || 0;
      if (avgT > 0) {
        if (!ticketByTierAccum[t]) ticketByTierAccum[t] = { sum: 0, n: 0 };
        ticketByTierAccum[t].sum += avgT * c.count;
        ticketByTierAccum[t].n += c.count;
      }
    }

    const tierTotals = {};
    const activityTotals = {};
    for (const c of counts) {
      const t = c._id.tier || 'SIN_DATOS';
      const a = c._id.activityStatus || 'INACTIVO';
      tierTotals[t] = (tierTotals[t] || 0) + c.count;
      activityTotals[a] = (activityTotals[a] || 0) + c.count;
    }

    const avgTicketByTier = {};
    for (const t in ticketByTierAccum) {
      const acc = ticketByTierAccum[t];
      avgTicketByTier[t] = acc.n > 0 ? Math.round(acc.sum / acc.n) : 0;
    }

    // Total recuperable y potencial de revenue.
    // Recuperable = (EN_RIESGO + PERDIDO + INACTIVO) por tier, restando oportunistas.
    // Tasa de conversión esperada por playbook (rough, podemos ajustar con data real luego):
    //   EN_RIESGO: 35% (acaban de empezar a alejarse)
    //   PERDIDO: 15% (ya están dudando)
    //   INACTIVO: 7% (muy difícil)
    const conversionByState = { EN_RIESGO: 0.35, PERDIDO: 0.15, INACTIVO: 0.07 };
    const recoverableStates = ['EN_RIESGO', 'PERDIDO', 'INACTIVO'];
    const allTiers = ['VIP', 'ORO', 'PLATA', 'BRONCE', 'NUEVO', 'SIN_DATOS'];

    let recoverableTotal = 0;
    let potentialRevenue = 0;
    const recoverableByTier = {};
    const segmentDetails = []; // para urgentSegments

    for (const t of allTiers) {
      let tierRecoverable = 0;
      let tierPotential = 0;
      for (const s of recoverableStates) {
        const k = t + '-' + s;
        const total = matrix[k] || 0;
        const opps = opportunistMatrix[k] || 0;
        const recoverable = Math.max(0, total - opps);
        const ticket = avgTicketByTier[t] || 0;
        const conv = conversionByState[s] || 0;
        const projected = recoverable * ticket * conv;

        tierRecoverable += recoverable;
        tierPotential += projected;
        recoverableTotal += recoverable;
        potentialRevenue += projected;

        if (recoverable > 0) {
          // urgencyScore: prioriza VIP/ORO + EN_RIESGO (recuperables más fáciles
          // y de mayor LTV). Es heurística para ordenar el "Foco urgente".
          const tierWeight = { VIP: 5, ORO: 3.5, PLATA: 2, BRONCE: 1, NUEVO: 0.5, SIN_DATOS: 0.2 }[t] || 0.5;
          const stateWeight = { EN_RIESGO: 3, PERDIDO: 2, INACTIVO: 1 }[s] || 1;
          const urgencyScore = recoverable * tierWeight * stateWeight;
          segmentDetails.push({
            tier: t,
            state: s,
            count: recoverable,
            countTotal: total,
            opportunists: opps,
            avgTicket: ticket,
            conversionRate: conv,
            potentialRevenue: Math.round(projected),
            urgencyScore: Math.round(urgencyScore)
          });
        }
      }
      recoverableByTier[t] = { count: tierRecoverable, potentialRevenue: Math.round(tierPotential) };
    }

    // Top 5 segmentos urgentes para mostrar arriba como "foco de la semana".
    segmentDetails.sort((a, b) => b.urgencyScore - a.urgencyScore);
    const urgentSegments = segmentDetails.slice(0, 5);

    // Recovery effectiveness ult. 30d
    const fromDate = new Date(Date.now() - 30 * 24 * 3600 * 1000);
    const recoveryAgg = await RecoveryPush.aggregate([
      { $match: { sentAt: { $gte: fromDate } } },
      { $group: { _id: '$outcome', count: { $sum: 1 }, totalBonus: { $sum: '$bonusAmount' }, totalRealDeposit: { $sum: '$realDepositAmount' } } }
    ]);
    const recovery = { sent: 0, recovered: 0, opportunist: 0, no_response: 0, pending: 0, totalBonus: 0, totalRealDeposit: 0 };
    for (const r of recoveryAgg) {
      recovery[r._id || 'pending'] = r.count;
      recovery.sent += r.count;
      recovery.totalBonus += r.totalBonus || 0;
      recovery.totalRealDeposit += r.totalRealDeposit || 0;
    }
    recovery.roiX = recovery.totalBonus > 0
      ? Number((recovery.totalRealDeposit / recovery.totalBonus).toFixed(2))
      : 0;

    // Semana vs semana anterior (basado en lastRealDepositDate). Dedupe por
    // username — mismo motivo que la matriz: PlayerStats tiene duplicados
    // legados que inflaban este número. Contamos usernames distintos.
    const oneWeekAgo = new Date(Date.now() - 7 * 24 * 3600 * 1000);
    const twoWeeksAgo = new Date(Date.now() - 14 * 24 * 3600 * 1000);
    const [activeThisWeekAgg, activeLastWeekAgg] = await Promise.all([
      PlayerStats.aggregate([
        { $match: { lastRealDepositDate: { $gte: oneWeekAgo } } },
        { $group: { _id: '$username' } },
        { $count: 'n' }
      ]),
      PlayerStats.aggregate([
        { $match: { lastRealDepositDate: { $gte: twoWeeksAgo, $lt: oneWeekAgo } } },
        { $group: { _id: '$username' } },
        { $count: 'n' }
      ])
    ]);
    const activeThisWeek = (activeThisWeekAgg[0] && activeThisWeekAgg[0].n) || 0;
    const activeLastWeek = (activeLastWeekAgg[0] && activeLastWeekAgg[0].n) || 0;
    const weekly = {
      activeThisWeek,
      activeLastWeek,
      delta: activeThisWeek - activeLastWeek,
      deltaPct: activeLastWeek > 0
        ? Number((((activeThisWeek - activeLastWeek) / activeLastWeek) * 100).toFixed(1))
        : 0
    };

    // Salud del canal de push (app instalada + notifs concedidas).
    // Mezclamos el snapshot persistido (cron diario) con el conteo en vivo
    // para que el "hoy" sea siempre exacto, aunque el cron de las 00:05 no
    // haya corrido todavía.
    let appNotifs = null;
    try {
      const todayKey = _appNotifTodayKey();
      // Live count para "hoy" (refleja altas/bajas del día corriente).
      const live = await _computeAppNotifTotalsNow();
      // Histórico: traemos los últimos 30 snapshots distintos del de hoy.
      const past = await AppNotifSnapshot.find({ dateKey: { $lt: todayKey } })
        .sort({ dateKey: -1 }).limit(30).lean();
      // Orden cronológico ASC para la sparkline.
      const series = past.slice().reverse().map(s => ({
        dateKey: s.dateKey,
        withBoth: s.withBoth || 0,
        withApp: s.withApp || 0,
        withNotifs: s.withNotifs || 0,
        totalUsers: s.totalUsers || 0,
        source: s.source
      }));
      // Le pegamos el dato de hoy al final.
      series.push({
        dateKey: todayKey,
        withBoth: live.withBoth,
        withApp: live.withApp,
        withNotifs: live.withNotifs,
        totalUsers: live.totalUsers,
        source: 'live'
      });

      const today = live.withBoth;
      const yesterday = series.length >= 2 ? series[series.length - 2].withBoth : null;
      const sevenAgo = series.length >= 8 ? series[series.length - 8].withBoth : null;
      appNotifs = {
        today,
        totalUsersToday: live.totalUsers,
        withAppToday: live.withApp,
        withNotifsToday: live.withNotifs,
        deltaYesterday: yesterday != null ? today - yesterday : null,
        delta7d: sevenAgo != null ? today - sevenAgo : null,
        coveragePct: live.totalUsers > 0
          ? Number(((today / live.totalUsers) * 100).toFixed(1))
          : 0,
        series
      };
    } catch (e) {
      logger.warn(`/api/admin/stats/segments appNotifs error: ${e.message}`);
    }

    // Breakdown app/no-app por (tier, state). Permite saber para cada celda
    // de la matriz cuántos tienen FCM token activo (les podemos pushear) y
    // cuántos no (hay que recontactarlos por WhatsApp). Lookup PlayerStats
    // dedupeado → User para sacar fcmToken/fcmTokens.
    const appBreakdownByCell = {};       // 'TIER-STATE' → { withApp, noApp }
    try {
      const appAgg = await PlayerStats.aggregate([
        { $sort: { updatedAt: -1, _id: -1 } },
        { $group: {
            _id: '$username',
            tier: { $first: '$tier' },
            activityStatus: { $first: '$activityStatus' }
        }},
        { $lookup: {
            from: 'users',
            localField: '_id',
            foreignField: 'username',
            as: 'u'
        }},
        { $addFields: {
            hasApp: {
              $let: {
                vars: { user: { $arrayElemAt: ['$u', 0] } },
                in: {
                  $or: [
                    { $ne: [{ $ifNull: ['$$user.fcmToken', null] }, null] },
                    { $gt: [{ $size: { $ifNull: ['$$user.fcmTokens', []] } }, 0] }
                  ]
                }
              }
            }
        }},
        { $group: {
            _id: { tier: '$tier', activityStatus: '$activityStatus' },
            withApp: { $sum: { $cond: ['$hasApp', 1, 0] } },
            noApp:   { $sum: { $cond: ['$hasApp', 0, 1] } }
        }}
      ]);
      for (const row of appAgg) {
        const t = row._id.tier || 'SIN_DATOS';
        const a = row._id.activityStatus || 'INACTIVO';
        appBreakdownByCell[t + '-' + a] = {
          withApp: row.withApp || 0,
          noApp: row.noApp || 0
        };
      }
      // También agregamos el conteo de app/no-app a los segmentos urgentes
      // para que el frontend los muestre directo.
      for (const seg of urgentSegments) {
        const k = seg.tier + '-' + seg.state;
        const br = appBreakdownByCell[k] || { withApp: 0, noApp: 0 };
        // Como urgentSegments excluye oportunistas (count = total - opps)
        // y el breakdown está sobre el total, escalamos proporcional para
        // estimar cuántos del recuperable tienen app vs no. Es aproximado
        // pero suficiente para guiar la acción.
        const total = seg.countTotal || 0;
        const recover = seg.count || 0;
        if (total > 0) {
          const ratio = recover / total;
          seg.withApp = Math.round((br.withApp || 0) * ratio);
          seg.noApp = Math.max(0, recover - seg.withApp);
        } else {
          seg.withApp = 0;
          seg.noApp = 0;
        }
      }
    } catch (e) {
      logger.warn(`/api/admin/stats/segments appBreakdown error: ${e.message}`);
    }

    res.json({
      matrix,
      appBreakdownByCell,
      tierTotals,
      activityTotals,
      recovery,
      weekly,
      avgTicketByTier,
      recoverable: {
        total: recoverableTotal,
        byTier: recoverableByTier,
        potentialRevenue: Math.round(potentialRevenue)
      },
      urgentSegments,
      appNotifs
    });
  } catch (error) {
    logger.error(`/api/admin/stats/segments: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// GET /api/admin/stats/segments/whatsapp-export?tier=X&state=Y
// Descarga CSV con los users de un segmento (tier + activityStatus) que NO
// tienen app/notifs activas — para campaña de recontacto vía WhatsApp.
// Columnas: equipo, usuario, telefono, ultima_carga, monto_30d.
app.get('/api/admin/stats/segments/whatsapp-export', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const tier = String(req.query.tier || '').trim().toUpperCase();
    const state = String(req.query.state || '').trim().toUpperCase();
    if (!tier || !state) {
      return res.status(400).json({ error: 'Faltan params tier y state' });
    }
    // Dedupe por username y filtra por (tier, state).
    const rows = await PlayerStats.aggregate([
      { $sort: { updatedAt: -1, _id: -1 } },
      { $group: {
          _id: '$username',
          tier: { $first: '$tier' },
          activityStatus: { $first: '$activityStatus' },
          isOpportunist: { $first: '$isOpportunist' },
          realDeposits30d: { $first: '$realDeposits30d' },
          lastRealDepositDate: { $first: '$lastRealDepositDate' }
      }},
      { $match: { tier, activityStatus: state, isOpportunist: { $ne: true } } },
      { $lookup: {
          from: 'users',
          localField: '_id',
          foreignField: 'username',
          as: 'u'
      }},
      { $addFields: { user: { $arrayElemAt: ['$u', 0] } } },
      { $addFields: {
          hasApp: {
            $or: [
              { $ne: [{ $ifNull: ['$user.fcmToken', null] }, null] },
              { $gt: [{ $size: { $ifNull: ['$user.fcmTokens', []] } }, 0] }
            ]
          }
      }},
      { $match: { hasApp: false } },
      { $sort: { realDeposits30d: -1 } }
    ]);

    const escape = (v) => {
      const s = (v == null ? '' : String(v));
      return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
    };
    const lines = ['Equipo,Usuario,Telefono,UltimaCarga,Cargas30d'];
    for (const r of rows) {
      const u = r.user || {};
      lines.push([
        escape(u.lineTeamName || ''),
        escape(r._id || ''),
        escape(u.phone || ''),
        escape(r.lastRealDepositDate ? new Date(r.lastRealDepositDate).toISOString() : ''),
        escape(r.realDeposits30d || 0)
      ].join(','));
    }
    const csv = '﻿' + lines.join('\r\n');
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition', `attachment; filename="recontacto-${tier}-${state}-${new Date().toISOString().slice(0,10)}.csv"`);
    res.send(csv);
  } catch (err) {
    logger.error(`/api/admin/stats/segments/whatsapp-export: ${err.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// GET /api/admin/stats/roi-bonus — agrega bonos por buckets de monto y ROI
app.get('/api/admin/stats/roi-bonus', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const fromDate = new Date(Date.now() - 30 * 24 * 3600 * 1000);

    // Para cada giveaway claim del ult. mes, buscar si el user hizo carga real
    // despues. Stats agregados por bucket de amount.
    const giveaways = await MoneyGiveawayClaim.aggregate([
      { $match: { status: 'completed', claimedAt: { $gte: fromDate } } },
      { $group: {
          _id: '$amount',
          count: { $sum: 1 },
          totalGiven: { $sum: '$amount' },
          users: { $addToSet: '$username' }
      }},
      { $sort: { _id: -1 } }
    ]);

    // Para cada bucket, calcular cuantos de esos users hicieron carga real
    // (lastRealDepositDate >= claimedAt aprox: usamos lastRealDepositDate
    //  posterior a fromDate, simplificacion conservadora).
    const buckets = [];
    for (const g of giveaways) {
      const stats = await PlayerStats.find({
        username: { $in: g.users },
        lastRealDepositDate: { $gte: fromDate }
      }).select('username realDeposits30d').lean();
      const recovered = stats.length;
      const realDeposits = stats.reduce((acc, s) => acc + (s.realDeposits30d || 0), 0);
      buckets.push({
        amount: g._id,
        count: g.count,
        totalGiven: g.totalGiven,
        uniqueUsers: g.users.length,
        usersThatDeposited: recovered,
        realDepositsFromThem: realDeposits,
        roiX: g.totalGiven > 0 ? Number((realDeposits / g.totalGiven).toFixed(2)) : 0
      });
    }

    res.json({ buckets, periodDays: 30 });
  } catch (error) {
    logger.error(`/api/admin/stats/roi-bonus: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// POST /api/admin/stats/recovery-push — manda push masivo a un segmento
// Body: {
//   tier: 'VIP'|'ORO'|...,           opcional, filtra
//   activityStatus: 'EN_RIESGO'|...,  opcional, filtra
//   excludeOpportunists: true,        skip oportunistas
//   title, body,                       texto de la notif
//   bonusType: 'giveaway'|'promo'|'none',
//   giveawayAmount, giveawayBudget, giveawayMaxClaims, giveawayDurationMinutes,
//   promoMessage, promoCode, promoDurationHours
// }
// Respeta cooldown de 7d por user. Crea filas RecoveryPush + dispara la
// notif via sendBulkNotification existente (filtrando por la lista de
// usernames que pasaron el cooldown).
app.post('/api/admin/stats/recovery-push', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Solo el admin principal puede mandar recovery push.' });
    }
    const b = req.body || {};
    const filter = {};
    if (b.tier) filter.tier = b.tier;
    if (b.activityStatus) filter.activityStatus = b.activityStatus;
    if (b.excludeOpportunists !== false) filter.isOpportunist = { $ne: true };

    const candidates = await PlayerStats.find(filter).select('username tier activityStatus').lean();
    if (candidates.length === 0) {
      return res.json({ success: false, message: 'No hay usuarios en ese segmento' });
    }

    // Filtrar por cooldown: skip los que ya recibieron push en los ult. 7d.
    const cutoff = new Date(Date.now() - RECOVERY_COOLDOWN_MS);
    const recent = await RecoveryPush.find({
      username: { $in: candidates.map(c => c.username) },
      sentAt: { $gte: cutoff }
    }).select('username').lean();
    const skipSet = new Set(recent.map(r => r.username));
    const toSend = candidates.filter(c => !skipSet.has(c.username));

    if (toSend.length === 0) {
      return res.json({
        success: false,
        message: 'Todos los usuarios del segmento ya recibieron push en los ultimos 7 dias',
        skipped: skipSet.size
      });
    }

    const campaignBatchId = uuidv4();
    const title = String(b.title || 'Te extrañamos').slice(0, 60);
    const body = String(b.body || 'Volve hoy y aprovecha').slice(0, 180);
    const bonusType = ['giveaway', 'promo', 'none'].includes(b.bonusType) ? b.bonusType : 'none';
    const bonusAmount = bonusType === 'giveaway' ? Number(b.giveawayAmount || 0) : 0;

    // Crear filas RecoveryPush primero (asi quedan registradas aunque la
    // notif falle parcialmente).
    const pushDocs = toSend.map(c => ({
      username: c.username,
      segmentAtSend: c.tier + '-' + c.activityStatus,
      tierAtSend: c.tier,
      activityStatusAtSend: c.activityStatus,
      bonusAmount,
      bonusType,
      campaignBatchId,
      sentAt: new Date(),
      sentBy: req.user.username || null
    }));
    await RecoveryPush.insertMany(pushDocs);

    // Update lastRecoveryPushAt en PlayerStats para que el panel lo refleje.
    await PlayerStats.updateMany(
      { username: { $in: toSend.map(c => c.username) } },
      { $set: { lastRecoveryPushAt: new Date() }, $inc: { recoveryAttemptsLifetime: 1 } }
    );

    // DISPARAR EL ENVÍO REAL del push a la lista exacta de usuarios. Antes
    // este endpoint solo registraba la campaña y dejaba el envío al admin
    // (composer manual) — eso era confuso porque el toast decía "registrado"
    // y el admin creía que ya había salido. Ahora se envía in-line.
    let sendResult = { successCount: 0, failureCount: 0, error: null };
    try {
      const filter = { username: { $in: toSend.map(c => c.username) } };
      const data = { source: 'admin-recovery', campaignBatchId, tag: 'recovery' };
      sendResult = await sendNotificationToAllUsers(User, title, body, data, filter);
    } catch (sendErr) {
      logger.error(`/api/admin/stats/recovery-push send failed: ${sendErr.message}`);
      sendResult.error = sendErr.message;
    }

    // Crear NotificationHistory para que aparezca en el historial admin.
    let historyId = null;
    try {
      historyId = uuidv4();
      await NotificationHistory.create({
        id: historyId,
        sentAt: new Date(),
        audienceType: 'list',
        audiencePrefix: null,
        audienceCount: toSend.length,
        title,
        body,
        type: bonusType === 'giveaway' ? 'money_giveaway' : 'plain',
        successCount: sendResult.successCount || 0,
        failureCount: sendResult.failureCount || 0,
        sentBy: req.user.username || null,
        meta: {
          campaignBatchId,
          source: 'recovery-push',
          tier: b.tier || null,
          activityStatus: b.activityStatus || null
        }
      });
    } catch (histErr) {
      logger.warn(`/api/admin/stats/recovery-push history creation failed: ${histErr.message}`);
    }

    res.json({
      success: true,
      campaignBatchId,
      historyId,
      sentCount: toSend.length,
      skipped: skipSet.size,
      pushDelivered: sendResult.successCount || 0,
      pushFailed: sendResult.failureCount || 0,
      sendError: sendResult.error || null,
      message: sendResult.error
        ? `Campaña registrada para ${toSend.length} jugadores pero el envío falló: ${sendResult.error}`
        : `✅ Push enviado a ${toSend.length} jugadores (${sendResult.successCount || 0} entregados, ${sendResult.failureCount || 0} con token inválido)`
    });
  } catch (error) {
    logger.error(`/api/admin/stats/recovery-push: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// ============================================
// IMPORT CSV DE JUGAYGANA — analisis bulk de transacciones
// ============================================
//
// El admin sube un CSV exportado de JUGAYGANA con todas las transacciones
// de los ultimos N dias (puede tener 200k+ filas). Procesamos en streaming
// (sin cargar archivo entero a memoria), agregamos por user, actualizamos
// PlayerStats con las cargas REALES (deposit), retiros (withdraw) y bonos
// (individual_bonus, que sabemos son los nuestros). Los datos crudos NO
// se persisten — solo queda el resumen en JugayganaImport y los agregados
// en PlayerStats.
//
// Formato del CSV (primera fila = headers):
//   A: Type   (deposit | withdraw | individual_bonus)
//   B: Amount (decimal)
//   C: Initiator (agente, no usado)
//   D: User   (username del jugador)
//   E: Parent (grupo JUGAYGANA, no usado)
//   F: Time   (DD/M/YYYY o D/M/YYYY)
//   G: hora HH:MM:SS.ms (ignorada por ahora — usamos solo fecha)
//   H: balance antes (no usado)
//   I: balance despues (no usado)
//
// Limites: aceptamos hasta 100MB de body raw. Para 200k filas eso son
// ~30MB asi que sobra.
// ============================================
const csvImportLimitMb = '100mb';

// Parser flexible: detecta delimiter (',' o ';' o '\t'), parsea fechas
// DMY o ISO, normaliza tipo de operacion a {deposit, withdraw, bonus}.
function _parseJugayganaCsv(rawText) {
  const out = {
    rows: [],          // [{ type, amount, username, dateMs }, ...]
    skipped: 0,
    delimiter: null,
    dateFormat: null,
    headerRow: false
  };
  if (!rawText || typeof rawText !== 'string') return out;

  // Detectar delimiter — el primer split por linea, contar comas/semicolons/tabs.
  const firstNewline = rawText.indexOf('\n');
  const sample = firstNewline > 0 ? rawText.slice(0, Math.min(2000, firstNewline)) : rawText.slice(0, 2000);
  const counts = {
    ',': (sample.match(/,/g) || []).length,
    ';': (sample.match(/;/g) || []).length,
    '\t': (sample.match(/\t/g) || []).length
  };
  let delim = ',';
  if (counts[';'] > counts[',']) delim = ';';
  else if (counts['\t'] > counts[',']) delim = '\t';
  out.delimiter = delim;

  const lines = rawText.split(/\r?\n/);
  if (lines.length === 0) return out;

  // Header detection: si la primera linea tiene "Type" o "type" o "Amount"
  // o "User" la tratamos como header y la skipeamos.
  const firstLine = lines[0].toLowerCase();
  const hasHeader = /\btype\b|\bamount\b|\buser\b|\btime\b/.test(firstLine);
  out.headerRow = hasHeader;
  const startIdx = hasHeader ? 1 : 0;

  for (let i = startIdx; i < lines.length; i++) {
    const line = lines[i];
    if (!line || !line.trim()) continue;
    const cols = _splitCsvLine(line, delim);
    if (cols.length < 6) { out.skipped++; continue; }

    const typeRaw = String(cols[0] || '').trim().toLowerCase();
    const amountRaw = String(cols[1] || '').trim();
    const userRaw = String(cols[3] || '').trim();
    const dateRaw = String(cols[5] || '').trim();
    const timeRaw = cols[6] ? String(cols[6]).trim() : '';

    if (!typeRaw || !userRaw || !amountRaw || !dateRaw) { out.skipped++; continue; }

    // Normalizar tipo: 'deposit', 'withdraw', 'bonus' (cubre individual_bonus,
    // bonus, etc).
    let type;
    if (typeRaw === 'deposit' || typeRaw.startsWith('depo')) type = 'deposit';
    else if (typeRaw === 'withdraw' || typeRaw.startsWith('with') || typeRaw.startsWith('retir')) type = 'withdraw';
    else if (typeRaw.includes('bonus') || typeRaw.includes('bonif')) type = 'bonus';
    else { out.skipped++; continue; }

    // Monto: limpiar $ , puntos miles, comas decimales.
    const amount = _parseAmount(amountRaw);
    if (!Number.isFinite(amount) || amount <= 0) { out.skipped++; continue; }

    // Fecha: el sample del cliente es DD/M/YYYY (mes sin cero).
    // Tambien soportamos DD/MM/YYYY y YYYY-MM-DD (ISO).
    const dateMs = _parseDateFlexible(dateRaw, timeRaw);
    if (!dateMs) { out.skipped++; continue; }

    out.rows.push({ type, amount, username: userRaw.toLowerCase(), dateMs });
  }

  if (out.rows.length > 0) {
    // Detectamos formato de fecha del primer row exitoso para el log.
    const sampleDate = lines[startIdx]?.split(delim)[5];
    out.dateFormat = /^\d{4}-\d{2}-\d{2}/.test(String(sampleDate || '')) ? 'iso' : 'dmy';
  }

  return out;
}

// Split CSV respetando comillas dobles (campos con comas adentro).
function _splitCsvLine(line, delim) {
  const out = [];
  let buf = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      if (inQuotes && line[i + 1] === '"') { buf += '"'; i++; } // escaped quote
      else inQuotes = !inQuotes;
    } else if (ch === delim && !inQuotes) {
      out.push(buf);
      buf = '';
    } else {
      buf += ch;
    }
  }
  out.push(buf);
  return out;
}

function _parseAmount(s) {
  if (!s) return NaN;
  // Quitar $, espacios.
  let t = String(s).replace(/[\s$]/g, '');
  // Si tiene tanto . como ,: el ultimo es decimal; el otro es separador miles.
  const lastDot = t.lastIndexOf('.');
  const lastComma = t.lastIndexOf(',');
  if (lastDot >= 0 && lastComma >= 0) {
    if (lastComma > lastDot) {
      // formato 1.234,56 → quitar puntos, cambiar coma por punto
      t = t.replace(/\./g, '').replace(',', '.');
    } else {
      // formato 1,234.56 → quitar comas
      t = t.replace(/,/g, '');
    }
  } else if (lastComma >= 0 && lastDot < 0) {
    // 1234,5 → coma como decimal
    t = t.replace(',', '.');
  }
  // si solo tiene punto, ya esta OK
  return parseFloat(t);
}

function _parseDateFlexible(dateStr, timeStr) {
  if (!dateStr) return null;
  let d;
  // ISO YYYY-MM-DD
  let m = /^(\d{4})-(\d{1,2})-(\d{1,2})/.exec(dateStr);
  if (m) {
    d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  } else {
    // DMY: DD/M/YYYY o DD-M-YYYY
    m = /^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/.exec(dateStr);
    if (m) {
      let year = +m[3];
      if (year < 100) year += 2000;
      d = new Date(Date.UTC(year, +m[2] - 1, +m[1]));
    }
  }
  if (!d || !Number.isFinite(d.getTime())) return null;
  // Hora opcional HH:MM:SS o HH:MM:SS.ms
  if (timeStr) {
    const tm = /^(\d{1,2}):(\d{1,2})(?::(\d{1,2})(?:\.(\d+))?)?/.exec(timeStr);
    if (tm) {
      d.setUTCHours(+tm[1], +tm[2], +(tm[3] || 0), 0);
    }
  }
  return d.getTime();
}

// Estado del import (para que el frontend polee).
let _csvImportState = { running: false, total: 0, parsed: 0, valid: 0, skipped: 0, startedAt: null, finishedAt: null, importId: null };

app.post(
  '/api/admin/stats/import-csv',
  authMiddleware,
  adminMiddleware,
  express.text({ limit: csvImportLimitMb, type: '*/*' }),
  async (req, res) => {
    if (_csvImportState.running) {
      return res.json({ success: false, message: 'Ya hay un import corriendo', state: _csvImportState });
    }
    const raw = req.body;
    if (!raw || typeof raw !== 'string' || raw.length < 100) {
      return res.status(400).json({ error: 'Archivo vacio o muy chico' });
    }

    // Hash para idempotencia.
    const contentHash = crypto.createHash('sha256').update(raw).digest('hex');
    const existing = await JugayganaImport.findOne({ contentHash, status: 'completed' }).lean();
    if (existing) {
      return res.json({
        success: true,
        skipped: true,
        message: 'Este archivo ya fue importado el ' + new Date(existing.uploadedAt).toLocaleString('es-AR') + '. No se reproceso.',
        importId: existing._id
      });
    }

    _csvImportState = {
      running: true, total: 0, parsed: 0, valid: 0, skipped: 0,
      startedAt: new Date().toISOString(), finishedAt: null, importId: null
    };
    res.json({ success: true, state: _csvImportState, message: 'Procesando en background...' });

    // Procesar en background usando el helper centralizado.
    _processCsvBackground(raw, contentHash, req.user.username || null);
  }
);

// GET state del import en curso o el ultimo terminado.
app.get('/api/admin/stats/import-csv', authMiddleware, adminMiddleware, async (req, res) => {
  const lastImport = await JugayganaImport.findOne({}).sort({ uploadedAt: -1 }).lean();
  res.json({ state: _csvImportState, lastImport });
});

// POST /api/admin/stats/import-csv-url
// Acepta un link de Google Sheets ("cualquier persona con el enlace puede
// ver"). Extrae el file ID, construye la URL de export CSV, descarga y
// procesa igual que el upload directo.
app.post('/api/admin/stats/import-csv-url', authMiddleware, adminMiddleware, async (req, res) => {
  if (_csvImportState.running) {
    return res.json({ success: false, message: 'Ya hay un import corriendo', state: _csvImportState });
  }
  const { url, gid } = req.body || {};
  if (!url || typeof url !== 'string') {
    return res.status(400).json({ error: 'Falta el link' });
  }

  // Extraer file ID. Soporta:
  //   docs.google.com/spreadsheets/d/{ID}/edit?...
  //   docs.google.com/spreadsheets/d/{ID}/
  const idMatch = url.match(/\/spreadsheets\/d\/([a-zA-Z0-9_-]{20,})/);
  if (!idMatch) {
    return res.status(400).json({ error: 'No es un link valido de Google Sheets' });
  }
  const fileId = idMatch[1];

  // Si el user paso un gid en el link original, lo respetamos. Sino, sheet 0.
  let gidParam = gid || null;
  if (!gidParam) {
    const gidMatch = url.match(/[?&#]gid=(\d+)/);
    if (gidMatch) gidParam = gidMatch[1];
  }
  const exportUrl = `https://docs.google.com/spreadsheets/d/${fileId}/export?format=csv` +
    (gidParam ? `&gid=${gidParam}` : '');

  // Bajar el CSV. axios sigue redirects por default.
  let raw = '';
  try {
    const resp = await axios.get(exportUrl, {
      timeout: 90_000,           // 90s, sheets grandes pueden tardar
      maxContentLength: 100 * 1024 * 1024, // 100MB
      maxBodyLength: 100 * 1024 * 1024,
      responseType: 'text',
      // Si la sheet no es publica Google devuelve HTML de login (200 OK,
      // text/html). Detectamos eso despues comparando content-type.
      validateStatus: (s) => s >= 200 && s < 400
    });
    const ct = String(resp.headers['content-type'] || '').toLowerCase();
    if (ct.includes('text/html')) {
      return res.status(400).json({
        error: 'El sheet no es publico. Cambialo a "Cualquier persona con el enlace puede ver" e intenta de nuevo.'
      });
    }
    raw = String(resp.data || '');
  } catch (e) {
    logger.error(`[csv-import-url] download fail: ${e.message}`);
    return res.status(400).json({ error: 'No se pudo descargar el sheet: ' + e.message });
  }

  if (!raw || raw.length < 100) {
    return res.status(400).json({ error: 'El sheet descargado esta vacio o es muy chico' });
  }

  // Idempotencia: hash + early-return si ya procesado.
  const contentHash = crypto.createHash('sha256').update(raw).digest('hex');
  const existing = await JugayganaImport.findOne({ contentHash, status: 'completed' }).lean();
  if (existing) {
    return res.json({
      success: true,
      skipped: true,
      message: 'Esta version del sheet ya fue importada el ' + new Date(existing.uploadedAt).toLocaleString('es-AR') + '. No se reproceso.',
      importId: existing._id
    });
  }

  // Lanzar el procesamiento (mismo flow que el upload directo).
  _csvImportState = {
    running: true, total: 0, parsed: 0, valid: 0, skipped: 0,
    startedAt: new Date().toISOString(), finishedAt: null, importId: null
  };
  res.json({ success: true, state: _csvImportState, message: 'Sheet descargado, procesando en background...' });

  _processCsvBackground(raw, contentHash, req.user.username || null);
});

// VENTANA DE STATS = ultimos N dias rolling. Cuando subis CSVs incrementales
// (semana a semana), siempre se ven los ultimos 45 dias. Lo que cae fuera
// se ignora en los agregados (pero queda en DailyPlayerStats hasta el
// cleanup, que es 60 dias = 45 + buffer de 15).
const STATS_WINDOW_DAYS = 45;
const DAILY_CLEANUP_DAYS = 60;

// Trunca un timestamp ms al inicio del dia UTC. Asi (username, dateUtc)
// es siempre comparable y unico-por-dia.
function _utcStartOfDay(ms) {
  const d = new Date(ms);
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
}

// Helper que centraliza el procesamiento — usado por upload directo y por
// import-csv-url. Estrategia rolling-window:
//   1. Parsear el CSV
//   2. Agrupar las transacciones por (username, dia)
//   3. Upsertear en DailyPlayerStats — incremental, no pisa otros dias
//   4. Recomputar PlayerStats sumando los ultimos 45 dias de DailyPlayerStats
//   5. Cleanup: borrar DailyPlayerStats > 60 dias
async function _processCsvBackground(raw, contentHash, uploadedBy) {
  const importDoc = await JugayganaImport.create({
    contentHash,
    uploadedBy,
    rawSizeBytes: raw.length,
    status: 'processing'
  });
  _csvImportState.importId = importDoc._id;

  try {
    const parsed = _parseJugayganaCsv(raw);
    _csvImportState.total = parsed.rows.length + parsed.skipped;
    _csvImportState.parsed = parsed.rows.length + parsed.skipped;
    _csvImportState.valid = parsed.rows.length;
    _csvImportState.skipped = parsed.skipped;

    // Agrupar por (username, dia UTC). Key: "username|dateMsUtc".
    const perUserDay = new Map();
    let minDate = Infinity, maxDate = -Infinity;
    let totalDC = 0, totalDS = 0, totalWC = 0, totalWS = 0, totalBC = 0, totalBS = 0;

    for (const r of parsed.rows) {
      const dayMs = _utcStartOfDay(r.dateMs).getTime();
      const key = r.username + '|' + dayMs;
      let agg = perUserDay.get(key);
      if (!agg) {
        agg = {
          username: r.username,
          dayMs,
          depositCount: 0, depositSum: 0,
          withdrawCount: 0, withdrawSum: 0,
          bonusCount: 0, bonusSum: 0
        };
        perUserDay.set(key, agg);
      }
      if (r.type === 'deposit') {
        agg.depositCount++; agg.depositSum += r.amount;
        totalDC++; totalDS += r.amount;
      } else if (r.type === 'withdraw') {
        agg.withdrawCount++; agg.withdrawSum += r.amount;
        totalWC++; totalWS += r.amount;
      } else if (r.type === 'bonus') {
        agg.bonusCount++; agg.bonusSum += r.amount;
        totalBC++; totalBS += r.amount;
      }
      if (r.dateMs < minDate) minDate = r.dateMs;
      if (r.dateMs > maxDate) maxDate = r.dateMs;
    }

    // Upsert por (username, dateUtc): suma a lo que ya hay si re-importas
    // datos del mismo dia. PERO si re-importas el MISMO archivo, el hash
    // ya bloqueo arriba — asi que llegamos aca solo con archivos nuevos
    // (parciales o de dias distintos). Estrategia: SET (no $inc) para que
    // cada upload sea idempotente para su periodo — si el CSV trae el dia
    // X completo, sobrescribe lo que habia para ese dia. Esto es correcto
    // porque JUGAYGANA exporta el "estado total" del dia, no incrementos.
    const ops = [];
    for (const agg of perUserDay.values()) {
      ops.push({
        updateOne: {
          filter: { username: agg.username, dateUtc: new Date(agg.dayMs) },
          update: {
            $set: {
              depositCount: agg.depositCount, depositSum: agg.depositSum,
              withdrawCount: agg.withdrawCount, withdrawSum: agg.withdrawSum,
              bonusCount: agg.bonusCount, bonusSum: agg.bonusSum,
              updatedAt: new Date()
            },
            $setOnInsert: { username: agg.username, dateUtc: new Date(agg.dayMs) }
          },
          upsert: true
        }
      });
      if (ops.length >= 500) {
        await DailyPlayerStats.bulkWrite(ops, { ordered: false });
        ops.length = 0;
      }
    }
    if (ops.length > 0) {
      await DailyPlayerStats.bulkWrite(ops, { ordered: false });
    }

    // Recomputar PlayerStats sumando ult. 45 dias de DailyPlayerStats.
    await _recomputeAllPlayerStatsFromDaily();

    // Cleanup de days > 60.
    const cleanupCutoff = _utcStartOfDay(Date.now() - DAILY_CLEANUP_DAYS * 24 * 3600 * 1000);
    const cleanupRes = await DailyPlayerStats.deleteMany({ dateUtc: { $lt: cleanupCutoff } });

    await JugayganaImport.updateOne(
      { _id: importDoc._id },
      {
        $set: {
          status: 'completed',
          totalRows: parsed.rows.length + parsed.skipped,
          validRows: parsed.rows.length,
          skippedRows: parsed.skipped,
          depositCount: totalDC, depositSum: totalDS,
          withdrawCount: totalWC, withdrawSum: totalWS,
          bonusCount: totalBC, bonusSum: totalBS,
          periodFrom: minDate < Infinity ? new Date(minDate) : null,
          periodTo: maxDate > -Infinity ? new Date(maxDate) : null,
          uniqueUsers: new Set(parsed.rows.map(r => r.username)).size,
          detectedFormat: {
            delimiter: parsed.delimiter,
            dateFormat: parsed.dateFormat,
            headerRow: parsed.headerRow
          }
        }
      }
    );

    await _resolvePendingRecoveryOutcomes();

    logger.info(`[csv-import] OK: ${parsed.rows.length} rows, ${perUserDay.size} user-days, cleanup deleted ${cleanupRes.deletedCount} old days`);
  } catch (e) {
    logger.error(`[csv-import] FAILED: ${e.message}\n${e.stack}`);
    await JugayganaImport.updateOne(
      { _id: importDoc._id },
      { $set: { status: 'failed', errorMsg: e.message } }
    );
  } finally {
    _csvImportState.running = false;
    _csvImportState.finishedAt = new Date().toISOString();
  }
}

// Suma los ultimos STATS_WINDOW_DAYS dias de DailyPlayerStats por usuario,
// recalcula tier/activityStatus/oportunista, persiste en PlayerStats.
// Se llama despues de cada CSV import.
async function _recomputeAllPlayerStatsFromDaily() {
  const cutoff = _utcStartOfDay(Date.now() - STATS_WINDOW_DAYS * 24 * 3600 * 1000);
  const NOW = Date.now();
  const dayMs = 24 * 3600 * 1000;

  // Agregar por usuario los ultimos N dias.
  const agg = await DailyPlayerStats.aggregate([
    { $match: { dateUtc: { $gte: cutoff } } },
    { $group: {
        _id: '$username',
        depositCount: { $sum: '$depositCount' },
        depositSum: { $sum: '$depositSum' },
        withdrawSum: { $sum: '$withdrawSum' },
        bonusCount: { $sum: '$bonusCount' },
        bonusSum: { $sum: '$bonusSum' },
        // Para "ultima carga real" buscamos el ultimo dia con depositCount > 0.
        lastDepositDay: {
          $max: {
            $cond: [{ $gt: ['$depositCount', 0] }, '$dateUtc', null]
          }
        }
    }}
  ]);

  const TIER = STATS_TIER_RULES;
  const ACT = STATS_ACTIVITY_DAYS;
  const ops = [];

  for (const u of agg) {
    const realDeposits = u.depositSum || 0;
    const realCount = u.depositCount || 0;
    const withdraws = u.withdrawSum || 0;
    const bonusGiven = u.bonusSum || 0;
    const bonusCount = u.bonusCount || 0;
    const lastDeposit = u.lastDepositDay || null;
    const daysSince = lastDeposit ? Math.floor((NOW - new Date(lastDeposit).getTime()) / dayMs) : null;
    const netToHouse = realDeposits - withdraws - bonusGiven;

    let tier = 'SIN_DATOS';
    if (realCount >= TIER.vipMinCharges && realDeposits >= TIER.vipMinAmount) tier = 'VIP';
    else if (realCount >= TIER.oroMinCharges && realDeposits >= TIER.oroMinAmount) tier = 'ORO';
    else if (realCount >= TIER.plataMinCharges || realDeposits >= TIER.plataMinAmount) tier = 'PLATA';
    else if (realCount >= TIER.bronceMinCharges) tier = 'BRONCE';

    let activityStatus = 'INACTIVO';
    if (daysSince == null) activityStatus = 'NUEVO';
    else if (daysSince <= ACT.activo) activityStatus = 'ACTIVO';
    else if (daysSince <= ACT.enRiesgo) activityStatus = 'EN_RIESGO';
    else if (daysSince <= ACT.perdido) activityStatus = 'PERDIDO';

    let bonusesWithoutDeposit = 0;
    if (bonusCount > 0 && realCount === 0) bonusesWithoutDeposit = bonusCount;
    else if (bonusCount > realCount * 2) bonusesWithoutDeposit = bonusCount - realCount;
    const isOpportunist = bonusesWithoutDeposit >= OPPORTUNIST_THRESHOLD;

    ops.push({
      updateOne: {
        filter: { username: u._id },
        update: {
          $set: {
            realDeposits30d: realDeposits,
            realChargesCount30d: realCount,
            withdraws30d: withdraws,
            bonusGiven30d: bonusGiven,
            bonusCount30d: bonusCount,
            netToHouse30d: netToHouse,
            lastRealDepositDate: lastDeposit,
            tier,
            activityStatus,
            bonusesClaimedWithoutDeposit30d: bonusesWithoutDeposit,
            isOpportunist,
            refreshedAt: new Date()
          },
          $setOnInsert: { username: u._id }
        },
        upsert: true
      }
    });
    if (ops.length >= 500) {
      await PlayerStats.bulkWrite(ops, { ordered: false });
      ops.length = 0;
    }
  }
  if (ops.length > 0) {
    await PlayerStats.bulkWrite(ops, { ordered: false });
  }

  // OPCIONAL: usuarios que estaban en PlayerStats pero ya no aparecen en
  // los ult. 45d (cayeron del todo) — los marcamos INACTIVO con valores 0.
  // Asi se ven en el segmento INACTIVO y no quedan stale con datos viejos.
  const aliveUsernames = agg.map(u => u._id);
  await PlayerStats.updateMany(
    { username: { $nin: aliveUsernames } },
    {
      $set: {
        realDeposits30d: 0, realChargesCount30d: 0, withdraws30d: 0,
        bonusGiven30d: 0, bonusCount30d: 0, netToHouse30d: 0,
        activityStatus: 'INACTIVO', tier: 'SIN_DATOS',
        refreshedAt: new Date()
      }
    }
  );
}

// ============================================
// GET /api/admin/reports/top-engagement
// Top usuarios por interaccion: cuentas y montos de
//   - reembolsos reclamados (RefundClaim)
//   - clicks en cartel WhatsApp (WaClickLog)
//   - regalos de difusion reclamados (MoneyGiveawayClaim)
// + score combinado para ordenar.
//
// Devuelve top 100 por score combinado, con todos los breakdowns.
// El frontend permite re-ordenar por cada metrica.
// ============================================
app.get('/api/admin/reports/top-engagement', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    // 1) Refunds: agrupar por username, sumar count y amount (excluyendo
    //    rows pendientes de credit que no llegaron a acreditar).
    const refundAgg = await RefundClaim.aggregate([
      { $match: { status: { $ne: 'pending_credit_failed' } } },
      {
        $group: {
          _id: { $toLower: '$username' },
          username: { $first: '$username' },
          refundCount: { $sum: 1 },
          refundTotal: { $sum: '$amount' },
          lastRefundAt: { $max: '$claimedAt' }
        }
      }
    ]);

    // 2) WA clicks: agrupar por username.
    const waAgg = await WaClickLog.aggregate([
      {
        $group: {
          _id: { $toLower: '$username' },
          username: { $first: '$username' },
          waClickCount: { $sum: 1 },
          lastWaClickAt: { $max: '$clickedAt' }
        }
      }
    ]);

    // 3) Giveaway claims: agrupar por username (excluye pending_credit_failed).
    const gAgg = await MoneyGiveawayClaim.aggregate([
      { $match: { status: { $ne: 'pending_credit_failed' } } },
      {
        $group: {
          _id: { $toLower: '$username' },
          username: { $first: '$username' },
          giveawayCount: { $sum: 1 },
          giveawayTotal: { $sum: '$amount' },
          lastGiveawayAt: { $max: '$claimedAt' }
        }
      }
    ]);

    // Merge en una map por username (lowercased).
    const map = new Map();
    const ensure = (key, username) => {
      if (!map.has(key)) {
        map.set(key, {
          username: username || key,
          refundCount: 0, refundTotal: 0, lastRefundAt: null,
          waClickCount: 0, lastWaClickAt: null,
          giveawayCount: 0, giveawayTotal: 0, lastGiveawayAt: null
        });
      }
      return map.get(key);
    };
    for (const r of refundAgg) {
      const o = ensure(r._id, r.username);
      o.refundCount = r.refundCount;
      o.refundTotal = r.refundTotal;
      o.lastRefundAt = r.lastRefundAt;
    }
    for (const r of waAgg) {
      const o = ensure(r._id, r.username);
      o.waClickCount = r.waClickCount;
      o.lastWaClickAt = r.lastWaClickAt;
    }
    for (const r of gAgg) {
      const o = ensure(r._id, r.username);
      o.giveawayCount = r.giveawayCount;
      o.giveawayTotal = r.giveawayTotal;
      o.lastGiveawayAt = r.lastGiveawayAt;
    }

    // Score combinado para ranking default. Pesos:
    // - cada reembolso vale 2 puntos (esfuerzo recurrente)
    // - cada click WA vale 1 (intencion de carga)
    // - cada giveaway vale 3 (alta interaccion + cobra de inmediato)
    const list = Array.from(map.values()).map(u => ({
      ...u,
      lastActivityAt: [u.lastRefundAt, u.lastWaClickAt, u.lastGiveawayAt]
        .filter(Boolean)
        .map(d => new Date(d).getTime())
        .reduce((a, b) => Math.max(a, b), 0) || null,
      score: u.refundCount * 2 + u.waClickCount * 1 + u.giveawayCount * 3
    }));

    list.sort((a, b) => b.score - a.score);
    const top = list.slice(0, 100);

    res.json({
      generatedAt: new Date().toISOString(),
      totalUniqueUsers: list.length,
      top
    });
  } catch (error) {
    logger.error(`/api/admin/reports/top-engagement error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// GET admin: lista paginada del historial de notificaciones.
// Query: ?limit=50&type=plain|whatsapp_promo|money_giveaway
app.get('/api/admin/notifications/history', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const limit = Math.max(1, Math.min(200, parseInt(req.query.limit, 10) || 50));
    // Solo notificaciones MANUALES (compuestas desde el panel de
    // notificaciones). Se excluyen las del motor de estrategia automática
    // (strategyType), los avisos de línea caída y las campañas por lista.
    const filter = {
      strategyType: null,
      type: { $ne: 'line_down' },
      audienceType: { $ne: 'list' }
    };
    if (req.query.type && ['plain', 'whatsapp_promo', 'money_giveaway'].includes(req.query.type)) {
      filter.type = req.query.type;
    }
    const list = await NotificationHistory.find(filter)
      .sort({ sentAt: -1 })
      .limit(limit)
      .lean();
    res.json({ count: list.length, items: list });
  } catch (error) {
    logger.error(`/api/admin/notifications/history error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// POST admin: crear o reemplazar el promo activo.
// Body: { message, code, durationHours, prefix?, notificationHistoryId? }
// notificationHistoryId vincula la promo con el row del historial para
// que los waClicks que se trackeen sumen al row correcto.
app.post('/api/admin/promo-alert', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Solo el admin principal puede crear promos.' });
    }
    const { message, code, durationHours, prefix, notificationHistoryId } = req.body || {};
    const msg = String(message || '').trim().slice(0, 200);
    const codeNorm = _normalizePromoCode(code);
    const hours = Number(durationHours);
    if (!msg) return res.status(400).json({ error: 'Mensaje requerido' });
    if (!codeNorm) return res.status(400).json({ error: 'Código requerido (solo letras, números, _ y -)' });
    if (!isFinite(hours) || hours <= 0 || hours > 168) {
      return res.status(400).json({ error: 'Duración inválida (entre 1 y 168 horas)' });
    }
    const now = new Date();
    const expires = new Date(now.getTime() + hours * 3600 * 1000);
    const promo = {
      id: uuidv4(),
      message: msg,
      code: codeNorm,
      expiresAt: expires.toISOString(),
      createdAt: now.toISOString(),
      createdBy: req.user.username || null,
      prefix: prefix && typeof prefix === 'string' && prefix.trim() ? prefix.trim() : null,
      notificationHistoryId: notificationHistoryId || null
    };
    await setConfig(PROMO_ALERT_KEY, promo);
    res.json({ success: true, promo });
  } catch (error) {
    logger.error(`POST /api/admin/promo-alert error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// GET admin: ver el promo activo (sin filtro por prefix, ve todo).
app.get('/api/admin/promo-alert', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const promo = await getConfig(PROMO_ALERT_KEY, null);
    if (!promo) return res.json({ promo: null });
    const expiresAtMs = promo.expiresAt ? new Date(promo.expiresAt).getTime() : 0;
    const expired = !isFinite(expiresAtMs) || expiresAtMs <= Date.now();
    res.json({ promo, expired });
  } catch (error) {
    logger.error(`GET /api/admin/promo-alert error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// DELETE admin: cancelar el promo activo (lo borra del config).
app.delete('/api/admin/promo-alert', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Solo el admin principal puede cancelar promos.' });
    }
    await setConfig(PROMO_ALERT_KEY, null);
    res.json({ success: true });
  } catch (error) {
    logger.error(`DELETE /api/admin/promo-alert error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// ============================================
// CAÍDA DE LÍNEA — broadcast + reemplazo de número
// ============================================
// Cuando una línea de WhatsApp/teléfono se cae (suspendida, baneada,
// reemplazada), el admin entra acá:
//   1) Elige el equipo / sub-línea afectada (lineTeamName).
//   2) Pone el nuevo número que reemplaza al caído.
//   3) Opcional: define un % de bonus por X días para incentivar carga
//      de los clientes de esa línea mientras se acomodan al nuevo nro.
//   4) Mensaje del push (default: aviso genérico).
//
// El servidor:
//   - Resuelve el set de usernames afectados (User.lineTeamName == X).
//   - Bulk-actualiza User.linePhone y UserLineLookup.linePhone al nuevo nro.
//   - Actualiza el slot del config 'userLinesByPrefix' que tenga ese
//     teamName para que los registros futuros también vean el nuevo nro.
//   - Si hay promo, setea PROMO_ALERT_KEY con audienceWhitelist =
//     usernames afectados + lineDown:true para que solo ellos vean el
//     banner de "RECLAMÁ" sin filtrar por prefix.
//   - Manda push real solo a los usernames afectados (filter).
//   - Crea un row de NotificationHistory con type='line_down',
//     lineDownTeam, lineDownOldPhone, lineDownNewPhone para auditoría.
//
// Si la promo se setea pero el push falla totalmente (successCount=0,
// error), revertimos la promo (no queda banner activo "huérfano").
// ============================================

// GET preview: sin escribir, devuelve cuántos usuarios serán afectados
// y cuál es el teléfono actual del slot. Útil para mostrar confirmación
// en el frontend antes de apretar "Difundir".
app.get('/api/admin/line-down/preview', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const teamName = (req.query.teamName ? String(req.query.teamName) : '').trim();
    const teamMode = (req.query.teamMode === 'prefix') ? 'prefix' : 'exact';
    if (!teamName) return res.status(400).json({ error: 'Falta teamName' });

    const userFilter = teamMode === 'prefix'
      ? { lineTeamName: { $regex: '^' + teamName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), $options: '' } }
      : { lineTeamName: teamName };

    const [affected, withChannel, lookupPending] = await Promise.all([
      User.countDocuments({ ...userFilter, role: 'user' }),
      User.countDocuments({
        ...userFilter,
        role: 'user',
        $or: [
          { fcmTokenContext: 'standalone', notifPermission: 'granted' },
          { 'fcmTokens.context': 'standalone', 'fcmTokens.notifPermission': 'granted' }
        ]
      }),
      UserLineLookup.countDocuments(
        teamMode === 'prefix'
          ? { lineTeamName: { $regex: '^' + teamName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), $options: '' } }
          : { lineTeamName: teamName }
      )
    ]);

    // Snapshot del slot actual del config para mostrar el "antes/después".
    const linesCfg = (await getConfig('userLinesByPrefix')) || {};
    const slots = Array.isArray(linesCfg.slots) ? linesCfg.slots : [];
    const matchingSlots = slots
      .filter(s => {
        const tn = (s.teamName || '').trim();
        if (!tn) return false;
        return teamMode === 'prefix' ? tn.startsWith(teamName) : tn === teamName;
      })
      .map(s => ({ prefix: s.prefix, phone: s.phone, teamName: s.teamName }));

    res.json({
      success: true,
      teamName,
      teamMode,
      affected,
      withChannel,
      lookupPending,
      matchingSlots
    });
  } catch (error) {
    logger.error(`GET /api/admin/line-down/preview error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// POST broadcast: ejecuta el cambio de número + push + (opcional) promo.
app.post('/api/admin/line-down', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Solo el admin principal puede difundir caída de línea.' });
    }
    const {
      teamName,
      teamMode,
      newPhone,
      title,
      message,
      promo
    } = req.body || {};

    const tn = (teamName ? String(teamName) : '').trim();
    if (!tn) return res.status(400).json({ error: 'Falta teamName' });
    const mode = (teamMode === 'prefix') ? 'prefix' : 'exact';

    const newPhoneClean = (newPhone ? String(newPhone) : '').trim();
    if (!newPhoneClean) return res.status(400).json({ error: 'Falta el nuevo número' });
    if (newPhoneClean.length > 32) return res.status(400).json({ error: 'Nuevo número demasiado largo' });

    const titleClean = (title ? String(title) : '').trim() || '📵 Línea fuera de servicio';
    const messageClean = (message ? String(message) : '').trim();
    if (!messageClean) return res.status(400).json({ error: 'Falta el mensaje del push' });
    if (titleClean.length > 100) return res.status(400).json({ error: 'Título demasiado largo (máx 100)' });
    if (messageClean.length > 500) return res.status(400).json({ error: 'Mensaje demasiado largo (máx 500)' });

    let promoCfg = null;
    if (promo && promo.enabled) {
      const bonusPct = Number(promo.bonusPct);
      const durationDays = Number(promo.durationDays);
      if (!isFinite(bonusPct) || bonusPct <= 0 || bonusPct > 200) {
        return res.status(400).json({ error: 'Bonus inválido (1–200%)' });
      }
      if (!isFinite(durationDays) || durationDays <= 0 || durationDays > 30) {
        return res.status(400).json({ error: 'Duración inválida (1–30 días)' });
      }
      const promoMessage = (promo.promoMessage ? String(promo.promoMessage) : '').trim()
        || `🚨 Línea caída — reclamá ${bonusPct}% extra en tu carga por ${durationDays} día${durationDays > 1 ? 's' : ''}.`;
      const promoCode = _normalizePromoCode(promo.promoCode || `LINE${bonusPct}`);
      if (!promoCode) return res.status(400).json({ error: 'Código de promo inválido' });
      promoCfg = {
        bonusPct,
        durationDays,
        promoMessage,
        promoCode
      };
    }

    // Filtro para resolver audiencia.
    const escTn = tn.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const userFilter = mode === 'prefix'
      ? { lineTeamName: { $regex: '^' + escTn, $options: '' }, role: 'user' }
      : { lineTeamName: tn, role: 'user' };
    const lookupFilter = mode === 'prefix'
      ? { lineTeamName: { $regex: '^' + escTn, $options: '' } }
      : { lineTeamName: tn };

    // 1) Resolver usernames afectados.
    const affectedDocs = await User.find(userFilter, { username: 1, linePhone: 1, _id: 0 }).lean();
    const usernames = affectedDocs.map(u => u.username).filter(Boolean);
    const audienceCount = usernames.length;

    // Snapshot del teléfono "viejo" (mayoritario) para auditoría.
    const phoneCounts = new Map();
    for (const u of affectedDocs) {
      const p = (u.linePhone || '').trim();
      if (!p) continue;
      phoneCounts.set(p, (phoneCounts.get(p) || 0) + 1);
    }
    let oldPhone = null;
    let oldPhoneCount = 0;
    for (const [p, c] of phoneCounts) {
      if (c > oldPhoneCount) { oldPhone = p; oldPhoneCount = c; }
    }

    if (audienceCount === 0) {
      return res.status(400).json({
        error: `No hay usuarios registrados con equipo "${tn}". El cambio se aplicaría sólo a UserLineLookup y al slot del config; usá el panel "Números vigentes" para eso.`
      });
    }

    // 2) Bulk update User.linePhone.
    const userUpdate = await User.updateMany(
      userFilter,
      { $set: { linePhone: newPhoneClean, lineAssignedAt: new Date(), lineAssignedBy: req.user.username || null } }
    );

    // 3) Bulk update UserLineLookup.linePhone (para que los registros
    //    futuros / re-resolves también vean el nuevo número).
    const lookupUpdate = await UserLineLookup.updateMany(
      lookupFilter,
      { $set: { linePhone: newPhoneClean } }
    );

    // 4) Update slot(s) del config 'userLinesByPrefix'.
    let slotsUpdated = 0;
    try {
      const linesCfg = (await getConfig('userLinesByPrefix')) || {};
      const slots = Array.isArray(linesCfg.slots) ? linesCfg.slots : [];
      const newSlots = slots.map(s => {
        const stn = (s.teamName || '').trim();
        const matches = mode === 'prefix' ? stn.startsWith(tn) : stn === tn;
        if (matches) {
          slotsUpdated++;
          return { ...s, phone: newPhoneClean };
        }
        return s;
      });
      if (slotsUpdated > 0) {
        await setConfig('userLinesByPrefix', { ...linesCfg, slots: newSlots });
      }
    } catch (cfgErr) {
      logger.warn(`[line-down] no se pudo actualizar config de slots: ${cfgErr.message}`);
    }

    // 5) Si hay promo, setearla con audienceWhitelist + lineDown=true.
    let promoSet = null;
    if (promoCfg) {
      const now = new Date();
      const expires = new Date(now.getTime() + promoCfg.durationDays * 24 * 3600 * 1000);
      promoSet = {
        id: uuidv4(),
        message: promoCfg.promoMessage,
        code: promoCfg.promoCode,
        expiresAt: expires.toISOString(),
        createdAt: now.toISOString(),
        createdBy: req.user.username || null,
        prefix: null,
        audienceWhitelist: usernames.map(u => String(u).toLowerCase()),
        lineDown: true,
        lineDownTeam: tn,
        notificationHistoryId: null // se vincula abajo
      };
      await setConfig(PROMO_ALERT_KEY, promoSet);
    }

    // 6) Mandar push real.
    const data = {
      source: 'line-down',
      lineDownTeam: tn,
      newPhone: newPhoneClean,
      tag: 'line-down-' + Date.now()
    };
    if (promoCfg) {
      data.promoCode = promoCfg.promoCode;
      data.promoBonusPct = String(promoCfg.bonusPct);
      data.promoDurationDays = String(promoCfg.durationDays);
    }
    let sendResult = { successCount: 0, failureCount: 0, error: null };
    try {
      sendResult = await sendNotificationToAllUsers(
        User,
        titleClean,
        messageClean,
        data,
        { username: { $in: usernames } }
      );
    } catch (sendErr) {
      sendResult.error = sendErr.message;
    }

    // 6.5) Si se había seteado promo y el push fracasó por completo,
    // limpiar la promo (nadie iba a verla y sería falso engagement).
    if (promoSet && sendResult.error && (sendResult.successCount || 0) === 0) {
      await setConfig(PROMO_ALERT_KEY, null).catch(() => {});
      logger.error(`[line-down] promo CANCELADA porque el push falló totalmente: ${sendResult.error}`);
      promoSet = null;
    }

    // 7) NotificationHistory.
    const historyId = uuidv4();
    try {
      await NotificationHistory.create({
        id: historyId,
        sentAt: new Date(),
        audienceType: 'list',
        audienceCount,
        audiencePrefix: tn, // guardamos el equipo en este campo para reusar filtros
        title: titleClean,
        body: messageClean,
        type: 'line_down',
        promoMessage: promoCfg ? promoCfg.promoMessage : null,
        promoCode: promoCfg ? promoCfg.promoCode : null,
        promoExpiresAt: promoSet ? new Date(promoSet.expiresAt) : null,
        lineDownTeam: tn,
        lineDownOldPhone: oldPhone,
        lineDownNewPhone: newPhoneClean,
        totalUsers: audienceCount,
        successCount: sendResult.successCount || 0,
        failureCount: sendResult.failureCount || 0,
        sentBy: req.user.username || null
      });

      // Vincular el promo al historial para tracking de waClicks.
      if (promoSet) {
        const cur = await getConfig(PROMO_ALERT_KEY, null);
        if (cur && cur.id === promoSet.id) {
          await setConfig(PROMO_ALERT_KEY, { ...cur, notificationHistoryId: historyId });
        }
      }
    } catch (histErr) {
      logger.warn(`[line-down] no se pudo crear NotificationHistory: ${histErr.message}`);
    }

    res.json({
      success: true,
      historyId,
      teamName: tn,
      teamMode: mode,
      audienceCount,
      oldPhone,
      newPhone: newPhoneClean,
      usersUpdated: userUpdate.modifiedCount || 0,
      lookupUpdated: lookupUpdate.modifiedCount || 0,
      slotsUpdated,
      pushDelivered: sendResult.successCount || 0,
      pushFailed: sendResult.failureCount || 0,
      pushError: sendResult.error || null,
      promo: promoSet ? {
        id: promoSet.id,
        bonusPct: promoCfg.bonusPct,
        durationDays: promoCfg.durationDays,
        expiresAt: promoSet.expiresAt
      } : null
    });
  } catch (error) {
    logger.error(`POST /api/admin/line-down error: ${error.message}`);
    res.status(500).json({ error: error.message || 'Error del servidor' });
  }
});

// GET history: lista las últimas difusiones de caída de línea.
app.get('/api/admin/line-down/history', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const limit = Math.min(parseInt(req.query.limit) || 50, 200);
    const list = await NotificationHistory.find({ type: 'line_down' })
      .sort({ sentAt: -1 })
      .limit(limit)
      .lean();
    res.json({ success: true, items: list });
  } catch (error) {
    logger.error(`GET /api/admin/line-down/history error: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

