// Soft-block: el user puede LOGUEARSE pero NO puede reclamar bono de
// bienvenida ni códigos canjeables. Se usa cuando el admin desbloquea
// un fraudBlocked pero sospecha IP duplicada — lo deja jugar pero sin
// regalos hasta que confirme.
app.post('/api/admin/users/:id/bonus-restrict', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const user = await User.findOne({ id: req.params.id });
    if (!user) return res.status(404).json({ error: 'Usuario no encontrado.' });
    const reason = String((req.body && req.body.reason) || 'IP duplicada — bono ya reclamado bajo otra cuenta').slice(0, 250);
    // Saca el fraudBlocked (puede usar la app) pero mantiene bonusBlocked.
    user.fraudBlocked = false;
    user.fraudReason = null;
    user.bonusBlocked = true;
    user.bonusBlockedAt = new Date();
    user.bonusBlockedReason = reason;
    // También le mostramos el cartel — el user va a poder usar la app y
    // tenemos que asegurar que no cambie de sesión.
    user.unblockNoticePending = true;
    user.unblockNoticeAt = new Date();
    await user.save();
    logger.info(`Admin ${req.user.username} aplicó bonus-restrict a ${user.username}: ${reason}`);
    res.json({ success: true, message: `${user.username} con bono/códigos restringido.` });
  } catch (e) {
    logger.error(`POST /bonus-restrict: ${e.message}`);
    res.status(500).json({ error: 'Error del servidor.' });
  }
});

// Enviar chat a cargas (antes "pagos")
app.post('/api/admin/send-to-payments', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const { userId } = req.body;
    
    if (!userId) {
      return res.status(400).json({ error: 'Usuario no especificado' });
    }
    
    // Todos los admins (admin, depositor, withdrawer) pueden enviar a cargas
    
    // Actualizar estado del chat a CARGAS (antes "payments")
    await ChatStatus.findOneAndUpdate(
      { userId },
      { 
        status: 'payments',
        category: 'payments',
        assignedTo: null,
        updatedAt: new Date()
      },
      { upsert: true }
    );
    
    // Enviar mensaje al usuario
    await Message.create({
      id: uuidv4(),
      senderId: req.user.userId,
      senderUsername: req.user.username,
      senderRole: 'admin',
      receiverId: userId,
      receiverRole: 'user',
      content: '💳 Tu chat ha sido transferido al departamento de PAGOS. Un agente especializado te atenderá pronto.\n\nPor favor para agilizar el tiempo envie monto a retirar y cvu por favor!',
      type: 'text',
      timestamp: new Date(),
      read: false
    });
    
    // Notificar a admins
    notifyAdmins('chat_moved', { userId, to: 'payments', by: req.user.username });
    
    res.json({ success: true, message: 'Chat enviado a cargas' });
  } catch (error) {
    console.error('Error enviando a cargas:', error);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// Enviar chat de vuelta a Abiertos (desde Pagos o Cerrados)
app.post('/api/admin/send-to-open', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const { userId } = req.body;

    if (!userId) {
      return res.status(400).json({ error: 'Usuario no especificado' });
    }

    // Withdrawer no puede enviar a abiertos
    if (req.user.role === 'withdrawer') {
      return res.status(403).json({ error: 'No tienes permisos para esta acción' });
    }

    // Al mover a Abiertos: resetear categoría a 'cargas' (pool general)
    // y liberar asignación para que cualquier agente pueda tomar el chat
    await ChatStatus.findOneAndUpdate(
      { userId },
      {
        status: 'open',
        category: 'cargas',
        assignedTo: null,
        closedAt: null,
        closedBy: null,
        updatedAt: new Date()
      },
      { upsert: true }
    );

    notifyAdmins('chat_moved', { userId, to: 'open', by: req.user.username });

    res.json({ success: true, message: 'Chat enviado a abiertos' });
  } catch (error) {
    console.error('Error enviando a abiertos:', error);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

